                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    b.speed = base_s * 1.1
                    b.hp = min(getattr(b, "max_hp", 100.0), getattr(b, "hp", 100.0) + (5.0 * delta))

