class VoidTilesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Void Tiles"
        self.description = "The edges of the arena break down into void tiles. Touching them slows you down and randomly rewinds your movement, forcing fights to the center."
        self.history = {}
        self.tick_timer = 0.0
        self.safe_radius = 1000.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.history = {}
        for b in balls:
            self.history[getattr(b, 'id', 0)] = []

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        self.tick_timer += delta
        self.safe_radius = max(0.0, 1000.0 - self.tick_timer * 10.0)

        import math
        import random

        valid_balls = [b for b in balls if getattr(b, "alive", False)]

        # Center of arena is usually 500,500 if arena size is 1000,
        # let's assume world.arena.width/2 if available.
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        cx = arena_width / 2.0
        cy = arena_height / 2.0

        for b in valid_balls:
            b_id = getattr(b, 'id', 0)
            if b_id not in self.history:
                self.history[b_id] = []

            # Keep history to last 3 seconds
            self.history[b_id].append((self.tick_timer, getattr(b, 'x', 0.0), getattr(b, 'y', 0.0)))
            self.history[b_id] = [h for h in self.history[b_id] if self.tick_timer - h[0] <= 3.0]

            dx = getattr(b, 'x', 0.0) - cx
            dy = getattr(b, 'y', 0.0) - cy
            dist = math.hypot(dx, dy)

            if dist > self.safe_radius:
                # Apply slow
                b.speed_multiplier = getattr(b, 'speed_multiplier', 1.0) * 0.5

                # Random rewind
                if random.random() < 0.05 and len(self.history[b_id]) > 0:
                    past_state = random.choice(self.history[b_id])
                    b.x = past_state[1]
                    b.y = past_state[2]

class ExplosiveMeteorsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Explosive Meteors"
        self.description = "Randomly drops explosive meteors from the sky that damage any players caught in their blast radius."
        self.meteor_timer = 0.0
        self.meteors = []

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        if getattr(world, "arena", None) is not None and getattr(world.arena, "hazards", None) is None:
            world.arena.hazards = []
        self.meteor_timer = 0.0
        self.meteors = []

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random
        import math

        self.meteor_timer += delta

        if self.meteor_timer >= 5.0:
            self.meteor_timer = 0.0
            arena_width = getattr(world.arena, "width", 1000) if getattr(world, "arena", None) is not None else 1000
            arena_height = getattr(world.arena, "height", 1000) if getattr(world, "arena", None) is not None else 1000

            x = random.uniform(50, arena_width - 50)
            y = random.uniform(50, arena_height - 50)

            self.meteors.append({
                "id": f"meteor_{random.randint(10000, 99999)}",
                "x": x,
                "y": y,
                "delay": 3.0,
                "radius": 40.0
            })

        still_active = []
        for m in self.meteors:
            m["delay"] -= delta
            if m["delay"] <= 0:
                for b in balls:
                    if getattr(b, "alive", False):
                        dx = getattr(b, "x", 0.0) - m["x"]
                        dy = getattr(b, "y", 0.0) - m["y"]
                        dist = math.hypot(dx, dy)
                        if dist <= m["radius"]:
                            if hasattr(b, "take_damage"):
                                b.take_damage(50.0)
                            else:
                                b.hp = getattr(b, "hp", 100) - 50.0
                            if dist > 0.0001:
                                push_force = 1000.0
                                b.vx = getattr(b, "vx", 0.0) + (dx / dist) * push_force
                                b.vy = getattr(b, "vy", 0.0) + (dy / dist) * push_force
            else:
                still_active.append(m)

        self.meteors = still_active

        if getattr(world, "arena", None) is not None and getattr(world.arena, "hazards", None) is not None:
            world.arena.hazards = [h for h in world.arena.hazards if getattr(h, "kind", "") != "meteor_indicator"]

            from arena.procedural_arena import Hazard
            for m in self.meteors:
                world.arena.hazards.append(Hazard(m["id"], m["x"], m["y"], m["radius"], "meteor_indicator", 0))

class ToxicFloodRoyaleMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Toxic Flood Royale"
        self.description = "The floor periodically floods with toxic poison. Players must fight for control of the limited elevated platforms to survive."
        self.state = "dry" # 'dry', 'warning', 'flooded'
        self.state_timer = 10.0
        self.platforms = []
        self.damage_per_second = 30.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.world = world
        self.platforms = []
        self.state = "dry"
        self.state_timer = 10.0

    def spawn_platforms(self, count=3):
        import random
        from arena.procedural_arena import Hazard
        arena_width = getattr(self.world.arena, "width", 1000) if hasattr(self.world, "arena") and self.world.arena else 1000
        arena_height = getattr(self.world.arena, "height", 1000) if hasattr(self.world, "arena") and self.world.arena else 1000

        self.platforms = []
        for _ in range(int(count)):
            x = random.uniform(200, arena_width - 200)
            y = random.uniform(200, arena_height - 200)
            radius = random.uniform(80.0, 150.0)
            self.platforms.append({
                "x": x,
                "y": y,
                "radius": radius
            })
            if hasattr(self.world, "arena") and hasattr(self.world.arena, "hazards"):
                hazard_id = len(self.world.arena.hazards) + random.randint(1000, 9999)
                hazard = Hazard(id=hazard_id, x=x, y=y, radius=radius, kind="elevated_platform", damage=0.0)
                self.world.arena.hazards.append(hazard)

    def tick(self, world, balls, delta=0.016):
        import math

        self.state_timer -= delta

        if self.state == "dry" and self.state_timer <= 0:
            self.state = "warning"
            self.state_timer = 5.0
            num_balls = len([b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"])
            num_platforms = max(1, num_balls // 2)
            self.spawn_platforms(count=num_platforms)
            if hasattr(world, "add_event"):
                world.add_event("visual_effect", {"type": "toxic_warning", "duration": 5.0})
        elif self.state == "warning" and self.state_timer <= 0:
            self.state = "flooded"
            self.state_timer = 10.0
            if hasattr(world, "add_event"):
                world.add_event("visual_effect", {"type": "toxic_flood_start", "duration": 10.0})
        elif self.state == "flooded" and self.state_timer <= 0:
            self.state = "dry"
            self.state_timer = 10.0
            self.platforms = []
            if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                world.arena.hazards = [h for h in world.arena.hazards if getattr(h, "kind", "") != "elevated_platform"]
            if hasattr(world, "add_event"):
                world.add_event("visual_effect", {"type": "toxic_flood_end"})

        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            on_platform = False
            for p in self.platforms:
                dx = b.x - p["x"]
                dy = b.y - p["y"]
                if math.sqrt(dx*dx + dy*dy) <= p["radius"]:
                    on_platform = True
                    break

            if self.state == "flooded" and not on_platform:
                b.hp -= self.damage_per_second * delta
                b.speed = getattr(b, "base_speed", getattr(b, "speed", 100.0)) * 0.7
                if b.hp <= 0:
                    b.alive = False
                    b.hp = 0
                    b.killer = "Toxic Flood"

class SlimeBossMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Slime Boss"
        self.description = "A giant slime boss that leaves a massive trail of slime and shoots slime balls. Splits into two smaller slimes when destroyed."
        self.boss_id = None

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        # Spawn the boss
        import random
        try:
            from ai.action import base_class_map
        except ImportError:
            base_class_map = {}

        boss_x = random.uniform(200, getattr(world.arena, "width", 1000) - 200)
        boss_y = random.uniform(200, getattr(world.arena, "height", 1000) - 200)

        # Create a mock ball for the boss to ensure compatibility with MockBall
        # We will dynamically create a mock class based on the first ball if possible
        if balls:
            base_ball = balls[0]
            boss_class = type(base_ball)
        else:
            boss_class = type('MockBoss', (object,), {})

        boss = boss_class()

        # Initialize necessary attributes based on what balls usually have
        if balls:
            for attr in dir(balls[0]):
                if not attr.startswith('__') and not callable(getattr(balls[0], attr)):
                    try:
                        setattr(boss, attr, getattr(balls[0], attr))
                    except AttributeError:
                        pass

        boss.id = getattr(world, "next_id", random.randint(10000, 99999))
        self.boss_id = boss.id
        boss.x = boss_x
        boss.y = boss_y
        boss.ball_type = "juggernaut"
        boss.team = "boss"
        boss.max_hp = 3000.0
        boss.hp = 3000.0
        boss.damage = 30.0
        boss.radius = 40.0
        boss.speed = 80.0
        boss.alive = True

        boss.slime_trail_timer = 0.0
        boss.slime_shoot_timer = 3.0
        boss.is_slime_boss = True

        balls.append(boss)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        # Update slime projectiles
        projectiles_to_remove = []
        patches_to_add = []
        for h in world.arena.hazards:
            if getattr(h, "kind", "") == "slime_projectile":
                h.x += getattr(h, "vx", 0) * delta
                h.y += getattr(h, "vy", 0) * delta
                h.duration -= delta

                # Check collision with players
                hit = False
                for b in balls:
                    if getattr(b, "alive", False) and getattr(b, "team", "") != "boss":
                        dx = b.x - h.x
                        dy = b.y - h.y
                        if dx*dx + dy*dy <= (b.radius + h.radius)**2:
                            b.hp -= getattr(h, "damage", 10)
                            b.slow_timer = max(getattr(b, "slow_timer", 0.0), 3.0)
                            hit = True
                            break

                if hit or h.duration <= 0:
                    projectiles_to_remove.append(h)
                    try:
                        from arena.procedural_arena import Hazard
                        patch = Hazard(id=len(world.arena.hazards) + 9000, x=h.x, y=h.y, radius=30.0, kind="slime", damage=0.0)
                        patch.active = True
                        patch.duration = 10.0
                        patches_to_add.append(patch)
                    except ImportError:
                        class Hazard:
                            def __init__(self, id, x, y, radius, kind, damage):
                                self.id = id
                                self.x = x
                                self.y = y
                                self.radius = radius
                                self.kind = kind
                                self.damage = damage
                                self.active = True
                        patch = Hazard(id=len(world.arena.hazards) + 9000, x=h.x, y=h.y, radius=30.0, kind="slime", damage=0.0)
                        patch.duration = 10.0
                        patches_to_add.append(patch)

        # Apply slow from slime patches
        for h in world.arena.hazards:
            if getattr(h, "kind", "") == "slime":
                for b in balls:
                    if getattr(b, "alive", False) and getattr(b, "team", "") != "boss":
                        dx = b.x - h.x
                        dy = b.y - h.y
                        if dx*dx + dy*dy <= (b.radius + h.radius)**2:
                            b.slow_timer = max(getattr(b, "slow_timer", 0.0), 1.0)

        for p in projectiles_to_remove:
            if p in world.arena.hazards:
                world.arena.hazards.remove(p)
        for p in patches_to_add:
            world.arena.hazards.append(p)

        # Find boss and minions
        boss = None
        for b in balls:
            if getattr(b, "id", None) == self.boss_id:
                boss = b
                break

        if boss:
            if boss.hp <= 0 or not boss.alive:
                boss.alive = False
                if boss in balls:
                    balls.remove(boss)

                # Split into two smaller slimes
                if not getattr(boss, "is_slime_minion", False):
                    import random
                    for i in range(2):
                        boss_class = type(boss)
                        minion = boss_class()

                        for attr in dir(boss):
                            if not attr.startswith('__') and not callable(getattr(boss, attr)):
                                try:
                                    setattr(minion, attr, getattr(boss, attr))
                                except AttributeError:
                                    pass

                        minion.id = getattr(world, "next_id", random.randint(10000, 99999)) + i + 1
                        minion.x = boss.x + random.choice([-20, 20])
                        minion.y = boss.y + random.choice([-20, 20])
                        minion.max_hp = boss.max_hp * 0.4
                        minion.hp = minion.max_hp
                        minion.radius = boss.radius * 0.6
                        minion.speed = boss.speed * 1.5
                        minion.damage = boss.damage * 0.6
                        minion.alive = True
                        minion.is_slime_minion = True
                        minion.slime_trail_timer = 0.0

                        balls.append(minion)
            else:
                # Trail logic
                boss.slime_trail_timer = getattr(boss, "slime_trail_timer", 0.0) - delta
                if boss.slime_trail_timer <= 0:
                    boss.slime_trail_timer = 0.2

                    try:
                        from arena.procedural_arena import Hazard
                        trail = Hazard(id=len(world.arena.hazards) + 9000, x=boss.x, y=boss.y, radius=25.0, kind="slime", damage=0.0)
                        trail.active = True
                        trail.duration = 10.0
                        world.arena.hazards.append(trail)
                    except ImportError:
                        class Hazard:
                            def __init__(self, id, x, y, radius, kind, damage):
                                self.id = id
                                self.x = x
                                self.y = y
                                self.radius = radius
                                self.kind = kind
                                self.damage = damage
                                self.active = True
                        trail = Hazard(id=len(world.arena.hazards) + 9000, x=boss.x, y=boss.y, radius=25.0, kind="slime", damage=0.0)
                        trail.duration = 10.0
                        world.arena.hazards.append(trail)

                # Shooting logic
                if not getattr(boss, "is_slime_minion", False):
                    boss.slime_shoot_timer = getattr(boss, "slime_shoot_timer", 3.0) - delta
                    if boss.slime_shoot_timer <= 0:
                        boss.slime_shoot_timer = 3.0

                        # Find closest enemy
                        closest_enemy = None
                        min_dist = 999999
                        for b in balls:
                            if b != boss and getattr(b, "alive", False) and getattr(b, "team", "") != boss.team:
                                dist = (b.x - boss.x)**2 + (b.y - boss.y)**2
                                if dist < min_dist:
                                    min_dist = dist
                                    closest_enemy = b

                        if closest_enemy:
                            import math
                            dx = closest_enemy.x - boss.x
                            dy = closest_enemy.y - boss.y
                            mag = math.sqrt(dx*dx + dy*dy)
                            if mag > 0:
                                vx = (dx / mag) * 300.0
                                vy = (dy / mag) * 300.0

                                try:
                                    from arena.procedural_arena import Hazard
                                    proj = Hazard(id=len(world.arena.hazards) + 9000, x=boss.x, y=boss.y, radius=15.0, kind="slime_projectile", damage=20.0)
                                    proj.active = True
                                    proj.vx = vx
                                    proj.vy = vy
                                    proj.duration = 2.0
                                    world.arena.hazards.append(proj)
                                except ImportError:
                                    class Hazard:
                                        def __init__(self, id, x, y, radius, kind, damage):
                                            self.id = id
                                            self.x = x
                                            self.y = y
                                            self.radius = radius
                                            self.kind = kind
                                            self.damage = damage
                                            self.active = True
                                    proj = Hazard(id=len(world.arena.hazards) + 9000, x=boss.x, y=boss.y, radius=15.0, kind="slime_projectile", damage=20.0)
                                    proj.vx = vx
                                    proj.vy = vy
                                    proj.duration = 2.0
                                    world.arena.hazards.append(proj)

class DecayingProjectilesMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Decaying Projectiles Mutator"
        self.description = "Projectiles become smaller and deal less damage over time, forcing players to hit enemies at closer ranges to maximize effect."

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)

        for proj in getattr(world, "projectiles", []) + getattr(world.arena, "hazards", []):
            if not getattr(proj, "alive", True) and not getattr(proj, "hp", 1.0) > 0:
                continue

            b_type = getattr(proj, "ball_type", getattr(proj, "kind", ""))
            is_proj = b_type in ["projectile", "spell", "fireball", "bullet", "snipe", "laser_beam"] or getattr(proj, "is_projectile", False) or getattr(proj, "is_spell", False)

            if not is_proj:
                continue

            if not hasattr(proj, "_original_radius"):
                proj._original_radius = getattr(proj, "radius", 5.0)
            if not hasattr(proj, "_original_damage"):
                proj._original_damage = getattr(proj, "damage", 10.0)

            decay_rate = 0.5  # Decay per second
            decay_factor = 1.0 - (decay_rate * delta)

            if decay_factor < 0:
                decay_factor = 0

            proj.radius = max(1.0, getattr(proj, "radius", 5.0) * decay_factor)

            # For damage we decay linearly based on the new radius ratio to original
            ratio = proj.radius / proj._original_radius
            proj.damage = max(0.0, proj._original_damage * ratio)


class BouncingProjectilesMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Bouncing Projectiles Mutator"
        self.description = "All projectiles (bullets, fireballs, snipes) bounce off walls and hazards infinitely until they hit a player or lose all their velocity."

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)

        arena_width = getattr(getattr(world, "arena", None), "width", 1000)
        arena_height = getattr(getattr(world, "arena", None), "height", 1000)

        for proj in getattr(world, "projectiles", []) + getattr(world.arena, "hazards", []):
            if not getattr(proj, "alive", True) and not getattr(proj, "hp", 1.0) > 0:
                continue

            b_type = getattr(proj, "ball_type", getattr(proj, "kind", ""))
            is_proj = b_type in ["projectile", "spell", "fireball", "bullet", "snipe", "laser_beam"] or getattr(proj, "is_projectile", False) or getattr(proj, "is_spell", False)

            if not is_proj:
                continue

            bounces = getattr(proj, "bounces", 0)

            x = getattr(proj, "x", 0)
            y = getattr(proj, "y", 0)
            radius = getattr(proj, "radius", 5.0)
            vx = getattr(proj, "vx", 0)
            vy = getattr(proj, "vy", 0)

            bounced = False
            if x - radius < 0 and vx < 0:
                proj.vx = -vx
                proj.x = radius
                bounced = True
            elif x + radius > arena_width and vx > 0:
                proj.vx = -vx
                proj.x = arena_width - radius
                bounced = True

            if y - radius < 0 and vy < 0:
                proj.vy = -vy
                proj.y = radius
                bounced = True
            elif y + radius > arena_height and vy > 0:
                proj.vy = -vy
                proj.y = arena_height - radius
                bounced = True

            # Hazards collisions (just simple AABB or circle for hazards that aren't this projectile)
            for h in getattr(world.arena, "hazards", []):
                if h == proj:
                    continue
                # For hazards, if they collide, bounce
                hx = getattr(h, "x", 0)
                hy = getattr(h, "y", 0)
                hradius = getattr(h, "radius", 5.0)
                dist_sq = (x - hx)**2 + (y - hy)**2
                if dist_sq < (radius + hradius)**2:
                    # Simple reflection normal
                    nx = x - hx
                    ny = y - hy
                    length = (nx**2 + ny**2)**0.5
                    if length > 0:
                        nx /= length
                        ny /= length
                        # dot product
                        dot = vx * nx + vy * ny
                        if dot < 0: # moving towards each other
                            proj.vx = vx - 2 * dot * nx
                            proj.vy = vy - 2 * dot * ny
                            vx = proj.vx
                            vy = proj.vy
                            bounced = True

            if bounced:
                proj.bounces = bounces + 1
                if hasattr(proj, "bounces_left"):
                    proj.bounces_left += 1

class WrapAroundMode(GameMode):
    """
    An arena mode where hitting a map boundary doesn't just bounce you, but teleports you to the opposite side of the map with inverted velocity.
    """
    def __init__(self):
        super().__init__()
        self.name = "Wrap Around Arena"
        self.description = "Hitting a map boundary teleports you to the opposite side with inverted velocity instead of bouncing."

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        if not hasattr(world, "arena") or world.arena is None:
            return

        arena_width = getattr(world.arena, "width", 800.0)
        arena_height = getattr(world.arena, "height", 600.0)

        for b in balls:
            if not getattr(b, "alive", False):
                continue

            radius = getattr(b, "radius", 15.0)

            x = getattr(b, "x", 0.0)
            y = getattr(b, "y", 0.0)

            teleported = False

            def is_blocked(target_x, target_y):
                if hasattr(world.arena, "hazards"):
                    for h in world.arena.hazards:
                        if getattr(h, "kind", "") == "stabilizer_field":
                            hr = getattr(h, "radius", 40.0)
                            hx = getattr(h, "x", 0.0)
                            hy = getattr(h, "y", 0.0)
                            dist_sq = (target_x - hx)**2 + (target_y - hy)**2
                            if dist_sq < (radius + hr)**2:
                                return True
                return False

            # Check horizontal boundaries
            if x - radius <= 0:
                target_x = arena_width - radius - 1.0
                if is_blocked(target_x, y):
                    b.x = radius + 1.0
                    b.vx = -getattr(b, "vx", 0.0)
                else:
                    b.x = target_x
                    b.vx = -getattr(b, "vx", 0.0)
                    teleported = True
            elif x + radius >= arena_width:
                target_x = radius + 1.0
                if is_blocked(target_x, y):
                    b.x = arena_width - radius - 1.0
                    b.vx = -getattr(b, "vx", 0.0)
                else:
                    b.x = target_x
                    b.vx = -getattr(b, "vx", 0.0)
                    teleported = True

            # Check vertical boundaries
            if y - radius <= 0:
                target_y = arena_height - radius - 1.0
                if is_blocked(x, target_y):
                    b.y = radius + 1.0
                    b.vy = -getattr(b, "vy", 0.0)
                else:
                    b.y = target_y
                    b.vy = -getattr(b, "vy", 0.0)
                    teleported = True
            elif y + radius >= arena_height:
                target_y = radius + 1.0
                if is_blocked(x, target_y):
                    b.y = arena_height - radius - 1.0
                    b.vy = -getattr(b, "vy", 0.0)
                else:
                    b.y = target_y
                    b.vy = -getattr(b, "vy", 0.0)
                    teleported = True

            if teleported and hasattr(world, "add_event"):
                world.add_event("boundary_wrap", {"message": "Wrapped around the arena!", "ball_id": getattr(b, "id", None)})



class EntangledHazardsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Entangled Hazards"
        self.description = "Hazards spawn in pairs. Damage or status effects taken by a ball near one hazard are partially duplicated to balls near its paired hazard."
        self.status_effects = ["stun_timer", "burn_timer", "poison_timer", "blindness_timer", "confusion_timer", "slow_timer", "frozen_timer", "silence_timer"]
        self.prev_state = {}
        self.hazard_pairs = []

    class BallState:
        def __init__(self, hp):
            self.hp = hp

    def _init_prev_state(self, b):
        state = self.BallState(getattr(b, "hp", 100.0))
        for eff in self.status_effects:
            setattr(state, eff, getattr(b, eff, 0.0))
        self.prev_state[b.id] = state

    def setup(self, world, balls):
        super().setup(world, balls)
        self.prev_state = {}
        for b in balls:
            if getattr(b, "ball_type", None) != "spectator":
                self._init_prev_state(b)

        if not hasattr(world, "arena") or not world.arena:
            return
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        try:
            from arena.procedural_arena import Hazard
        except ImportError:
            class Hazard:
                def __init__(self, id, x, y, radius, kind, damage):
                    self.id = id
                    self.x = x
                    self.y = y
                    self.radius = radius
                    self.target_radius = radius
                    self.kind = kind
                    self.damage = damage
                    self.active = True

        import random
        arena_w = getattr(world.arena, "width", 800)
        arena_h = getattr(world.arena, "height", 600)

        self.hazard_pairs = []
        for i in range(3):
            h1_id = 98000 + len(world.arena.hazards) * 2
            h2_id = h1_id + 1

            x1 = random.uniform(100, arena_w - 100)
            y1 = random.uniform(100, arena_h - 100)
            h1 = Hazard(id=h1_id, x=x1, y=y1, radius=100.0, kind="entangled_hazard", damage=0.0)
            h1.partner_id = h2_id

            x2 = random.uniform(100, arena_w - 100)
            y2 = random.uniform(100, arena_h - 100)
            h2 = Hazard(id=h2_id, x=x2, y=y2, radius=100.0, kind="entangled_hazard", damage=0.0)
            h2.partner_id = h1_id

            world.arena.hazards.extend([h1, h2])
            self.hazard_pairs.append((h1_id, h2_id))

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        if not hasattr(world, "arena") or not world.arena:
            return

        import math

        hazards_by_id = {h.id: h for h in getattr(world.arena, "hazards", []) if getattr(h, "kind", "") == "entangled_hazard"}
        balls_near_hazard = {h_id: [] for h_id in hazards_by_id}

        deltas = {}
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue
            deltas[b.id] = {"hp_loss": 0.0, "status": {eff: 0.0 for eff in self.status_effects}}
            bx, by = getattr(b, "x", 0.0), getattr(b, "y", 0.0)
            for h_id, h in hazards_by_id.items():
                hx, hy, hr = getattr(h, "x", 0.0), getattr(h, "y", 0.0), getattr(h, "radius", 100.0)
                dist = math.hypot(bx - hx, by - hy)
                if dist <= hr:
                    balls_near_hazard[h_id].append(b)

        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            if getattr(b, "id", None) not in self.prev_state:
                self._init_prev_state(b)

            state = self.prev_state[b.id]

            bx, by = getattr(b, "x", 0.0), getattr(b, "y", 0.0)
            nearby_h_id = None
            for h_id, h in hazards_by_id.items():
                hx, hy, hr = getattr(h, "x", 0.0), getattr(h, "y", 0.0), getattr(h, "radius", 100.0)
                if math.hypot(bx - hx, by - hy) <= hr:
                    nearby_h_id = h_id
                    break

            if nearby_h_id:
                partner_h_id = getattr(hazards_by_id[nearby_h_id], "partner_id", None)
                if partner_h_id and partner_h_id in balls_near_hazard:
                    targets = [tb for tb in balls_near_hazard[partner_h_id] if getattr(tb, "alive", False) and tb.id != b.id]

                    curr_hp = getattr(b, "hp", 100.0)
                    if curr_hp < state.hp:
                        damage_taken = state.hp - curr_hp
                        shared_damage = damage_taken * 0.5
                        for t in targets:
                            if t.id in deltas:
                                deltas[t.id]["hp_loss"] += shared_damage

                    for eff in self.status_effects:
                        curr_eff = getattr(b, eff, 0.0)
                        state_eff = getattr(state, eff, 0.0)
                        if curr_eff > state_eff:
                            delta_eff = (curr_eff - state_eff) * 0.5
                            for t in targets:
                                if t.id in deltas:
                                    deltas[t.id]["status"][eff] += delta_eff

        # Apply deltas
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            d = deltas.get(b.id)
            if d:
                if d["hp_loss"] > 0:
                    if hasattr(b, "take_damage"):
                        b.take_damage(d["hp_loss"])
                    else:
                        b.hp = getattr(b, "hp", 100.0) - d["hp_loss"]
                        if b.hp <= 0:
                            b.hp = 0
                            b.alive = False

                for eff, val in d["status"].items():
                    if val > 0:
                        setattr(b, eff, getattr(b, eff, 0.0) + val)

            self._init_prev_state(b)


class ElasticTetherMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Elastic Tether"
        self.description = "Pairs of players are tethered together. If they move too far apart, they are snapped back towards each other, dealing collision damage."
        self.max_distance = 250.0
        self.snap_force = 800.0
        self.collision_damage = 30.0
        self.collision_cooldown = 1.0

    def setup(self, world, balls):
        super().setup(world, balls)
        import random
        alive_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator" and getattr(b, "alive", False)]
        random.shuffle(alive_balls)

        # Clear existing
        for b in balls:
            b.tether_target = None
            b.tether_cooldown = 0.0

        for i in range(0, len(alive_balls) - 1, 2):
            b1 = alive_balls[i]
            b2 = alive_balls[i+1]
            b1.tether_target = b2
            b2.tether_target = b1
            b1.tether_cooldown = 0.0
            b2.tether_cooldown = 0.0

    def tick(self, world, balls, delta: float = 0.016):
        super().tick(world, balls, delta)
        import math

        for b in balls:
            if not getattr(b, "alive", False):
                continue

            b.tether_cooldown = max(0.0, getattr(b, "tether_cooldown", 0.0) - delta)

            target = getattr(b, "tether_target", None)
            # Only process if b is the "first" in the pair by ID to avoid double-processing
            if target and getattr(target, "alive", False) and getattr(b, "id", 0) < getattr(target, "id", 0):
                dx = target.x - b.x
                dy = target.y - b.y
                dist = math.hypot(dx, dy)

                if dist > self.max_distance:
                    excess = dist - self.max_distance
                    pull = (excess / self.max_distance) * self.snap_force

                    nx = dx / dist
                    ny = dy / dist

                    b.vx = getattr(b, "vx", 0.0) + nx * pull * delta
                    b.vy = getattr(b, "vy", 0.0) + ny * pull * delta

                    target.vx = getattr(target, "vx", 0.0) - nx * pull * delta
                    target.vy = getattr(target, "vy", 0.0) - ny * pull * delta

                # Collision damage
                b_radius = getattr(b, "radius", 15.0)
                t_radius = getattr(target, "radius", 15.0)

                if dist < b_radius + t_radius + 5.0:
                    if getattr(b, "tether_cooldown", 0.0) <= 0.0 and getattr(target, "tether_cooldown", 0.0) <= 0.0:
                        b.tether_cooldown = self.collision_cooldown
                        target.tether_cooldown = self.collision_cooldown

                        if hasattr(world, "_deal_damage"):
                            world._deal_damage(target, b, self.collision_damage)
                            world._deal_damage(b, target, self.collision_damage)
                        else:
                            b.hp = getattr(b, "hp", 100.0) - self.collision_damage
                            target.hp = getattr(target, "hp", 100.0) - self.collision_damage


class PersonalDoppelgangerMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Personal Doppelganger"
        self.description = "Every player spawns with an AI-controlled doppelganger that mimics their attacks but moves randomly. If a player dies, they take over their doppelganger."
        self.doppelgangers = {}

    def setup(self, world, balls):
        super().setup(world, balls)
        import copy
        self.doppelgangers.clear()

        class Doppelganger:
            def __init__(self, owner, new_id):
                self.id = new_id
                self.owner_id = getattr(owner, "id", 0)
                self.is_personal_doppelganger = True
                self.x = getattr(owner, "x", 0.0)
                self.y = getattr(owner, "y", 0.0)
                self.vx = 0.0
                self.vy = 0.0
                self.radius = getattr(owner, "radius", 20.0)
                self.hp = getattr(owner, "hp", 100.0)
                self.max_hp = getattr(owner, "max_hp", 100.0)
                self.alive = True
                self.ball_type = getattr(owner, "ball_type", "basic")
                self.team = getattr(owner, "team", "neutral")
                self.speed = getattr(owner, "speed", 100.0)
                self.base_speed = getattr(owner, "base_speed", 100.0)
                self.damage = getattr(owner, "damage", 25.0)
                self.base_damage = getattr(owner, "base_damage", 25.0)
                self.skills = copy.deepcopy(getattr(owner, "skills", []))
                self.inventory = copy.deepcopy(getattr(owner, "inventory", []))

                self.active_skill = None
                self.skill_timer = 0.0

                self.move_timer = 0.0
                self.target_angle = 0.0

        new_balls = []
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                b_id = getattr(b, "id", 0)
                d_id = 1000000 + b_id
                d = Doppelganger(b, d_id)
                new_balls.append(d)
                self.doppelgangers[b_id] = d_id

                b._prev_active_skill = getattr(b, "active_skill", None)

        if hasattr(world, "balls"):
            world.balls.extend(new_balls)

    def tick(self, world, balls, delta=0.016):
        import math
        import random
        super().tick(world, balls, delta)

        balls_by_id = {getattr(b, "id", None): b for b in balls}

        to_remove = []

        for owner_id, dop_id in self.doppelgangers.items():
            owner = balls_by_id.get(owner_id)
            dop = balls_by_id.get(dop_id)

            if not owner or not dop:
                continue

            if not getattr(owner, "alive", False) and getattr(dop, "alive", True):
                owner.alive = True
                owner.x = getattr(dop, "x", 0.0)
                owner.y = getattr(dop, "y", 0.0)
                owner.hp = getattr(dop, "hp", 100.0)
                owner.vx = getattr(dop, "vx", 0.0)
                owner.vy = getattr(dop, "vy", 0.0)

                dop.alive = False
                to_remove.append(owner_id)
                continue

            if not getattr(dop, "alive", False):
                to_remove.append(owner_id)
                continue

            if getattr(owner, "alive", False) and getattr(dop, "alive", True):
                dop.move_timer -= delta
                if dop.move_timer <= 0:
                    dop.move_timer = random.uniform(0.5, 2.0)
                    dop.target_angle = random.uniform(0, math.pi * 2)

                dop.vx = math.cos(dop.target_angle) * dop.speed
                dop.vy = math.sin(dop.target_angle) * dop.speed

                cur_skill = getattr(owner, "active_skill", None)
                prev_skill = getattr(owner, "_prev_active_skill", None)

                if cur_skill and cur_skill != prev_skill:
                    dop.active_skill = cur_skill
                    if hasattr(owner, "skill_timer"):
                        dop.skill_timer = getattr(owner, "skill_timer", 0.0)

                owner._prev_active_skill = cur_skill

        for id in to_remove:
            if id in self.doppelgangers:
                del self.doppelgangers[id]

class RoamingDoppelgangerMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Roaming Doppelganger"
        self.description = "A rare elite hazard roams the map. When it spots a player, it perfectly mimics their stats, buffs, and loadout for 30 seconds. Players must outrun their doppelganger or fight an equally matched mirror."

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import math
        import copy
        import random

        if not hasattr(world, "doppelganger_spawned"):
            world.doppelganger_spawned = True
            class DoppelgangerHazard:
                def __init__(self, id_val, x, y):
                    self.id = id_val
                    self.x = x
                    self.y = y
                    self.vx = 0.0
                    self.vy = 0.0
                    self.radius = 40.0
                    self.hp = 1000.0
                    self.max_hp = 1000.0
                    self.alive = True
                    self.ball_type = "elite_doppelganger"
                    self.team = "Hazard"
                    self.speed = 100.0
                    self.base_speed = 100.0
                    self.damage = 25.0
                    self.base_damage = 25.0
                    self.perception_radius = 500.0
                    self.base_perception_radius = 500.0

                    self.mimic_target_id = None
                    self.mimic_timer = 0.0
                    self.is_doppelganger = True

            arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
            arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

            boss = DoppelgangerHazard(
                99999 + random.randint(1, 1000),
                random.uniform(0, arena_width),
                random.uniform(0, arena_height)
            )
            world.doppelganger_boss = boss

            if hasattr(world, "balls"):
                world.balls.append(boss)

        if hasattr(world, "doppelganger_boss"):
            boss = world.doppelganger_boss
            if not getattr(boss, "alive", False):
                return

            # If currently mimicking
            if boss.mimic_timer > 0:
                boss.mimic_timer = max(0.0, boss.mimic_timer - delta)
                if boss.mimic_timer <= 0:
                    boss.mimic_target_id = None
                    # Revert to base stats
                    boss.radius = 40.0
                    boss.speed = 100.0
                    boss.damage = 25.0
                    boss.ball_type = "elite_doppelganger"
                    # Reset skills/buffs if necessary
                    if hasattr(boss, "inventory"):
                        boss.inventory = []
                    if hasattr(boss, "skills"):
                        boss.skills = []

            if boss.mimic_timer <= 0:
                # Look for a target to mimic
                closest_dist = boss.perception_radius
                closest_target = None

                for b in balls:
                    if not getattr(b, "alive", False) or getattr(b, "is_doppelganger", False) or getattr(b, "ball_type", "") == "spectator" or getattr(b, "team", "") == "Hazard":
                        continue

                    dx = b.x - boss.x
                    dy = b.y - boss.y
                    dist = math.sqrt(dx*dx + dy*dy)

                    if dist <= closest_dist:
                        closest_dist = dist
                        closest_target = b

                if closest_target is not None:
                    boss.mimic_target_id = closest_target.id
                    boss.mimic_timer = 30.0

                    # Mimic stats perfectly
                    boss.radius = getattr(closest_target, "radius", 40.0)
                    boss.speed = getattr(closest_target, "speed", 100.0)
                    boss.base_speed = getattr(closest_target, "base_speed", boss.speed)
                    boss.damage = getattr(closest_target, "damage", 25.0)
                    boss.base_damage = getattr(closest_target, "base_damage", boss.damage)
                    boss.max_hp = getattr(closest_target, "max_hp", 100.0)
                    boss.hp = boss.max_hp
                    boss.ball_type = getattr(closest_target, "ball_type", "basic")

                    if hasattr(closest_target, "inventory"):
                        boss.inventory = copy.deepcopy(closest_target.inventory)
                    if hasattr(closest_target, "skills"):
                        boss.skills = copy.deepcopy(closest_target.skills)

            # Simple roaming logic if not mimicking, or chase target if mimicking
            if boss.mimic_timer > 0 and boss.mimic_target_id is not None:
                target = None
                for b in balls:
                    if getattr(b, "id", None) == boss.mimic_target_id:
                        target = b
                        break

                if target and getattr(target, "alive", False):
                    # Chase target
                    dx = target.x - boss.x
                    dy = target.y - boss.y
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist > 0:
                        boss.vx = (dx / dist) * boss.speed
                        boss.vy = (dy / dist) * boss.speed
                else:
                    boss.mimic_timer = 0.0 # Target dead or missing, stop mimicking
            else:
                # Roam
                if random.random() < 0.05 * delta:
                    angle = random.uniform(0, 2 * math.pi)
                    boss.vx = math.cos(angle) * boss.speed
                    boss.vy = math.sin(angle) * boss.speed


class RandomTeleportDashMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Random Teleport Dash"
        self.description = "A rare game mode modifier where instead of standard dashes, ball abilities have a chance to trigger a randomized, short-range teleport around the arena. This creates high-stakes, unpredictable positioning during engagements, making both escapes and chases thrilling."

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random
        import math

        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            is_dashing = getattr(b, "is_dashing", False)
            skill_timer = getattr(b, "skill_timer", 0.0)
            dash_cooldown = getattr(b, "dash_cooldown", 0.0)

            prev_skill_timer = getattr(b, "_prev_teleport_skill_timer", 0.0)
            prev_dash_cooldown = getattr(b, "_prev_teleport_dash_cooldown", 0.0)

            just_used_skill = False
            if skill_timer > prev_skill_timer + 1.0:
                just_used_skill = True
            if dash_cooldown > prev_dash_cooldown + 1.0:
                just_used_skill = True

            b._prev_teleport_skill_timer = skill_timer
            b._prev_teleport_dash_cooldown = dash_cooldown

            if is_dashing or just_used_skill:
                if getattr(b, "random_teleport_cooldown", 0.0) <= 0.0:
                    if random.random() < 0.3:
                        teleport_radius = random.uniform(150.0, 300.0)
                        angle = random.uniform(0, 2 * math.pi)

                        new_x = b.x + math.cos(angle) * teleport_radius
                        new_y = b.y + math.sin(angle) * teleport_radius

                        b.x = max(getattr(b, "radius", 15.0), min(arena_width - getattr(b, "radius", 15.0), new_x))
                        b.y = max(getattr(b, "radius", 15.0), min(arena_height - getattr(b, "radius", 15.0), new_y))

                        b.vx = 0.0
                        b.vy = 0.0

                        if hasattr(world, "add_event"):
                            world.add_event("visual_effect", {"type": "teleport", "x": b.x, "y": b.y})

                    b.random_teleport_cooldown = 2.0

            if hasattr(b, "random_teleport_cooldown") and b.random_teleport_cooldown > 0:
                b.random_teleport_cooldown -= delta



class TeleportDashMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Teleport Dash Mutator"
        self.description = "Replaces the dash skill with a short-range instantaneous teleport that can pass through thin walls but has a longer cooldown."
        self.mutators_active = True
        self.mutators = ["teleport_dash"]

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        if not hasattr(world, "dead_balls"):
            world.dead_balls = []
        self.apply_dynamic_traits(world, balls, delta)
        for b in balls:
            if not getattr(b, "alive", False):
                if b not in world.dead_balls:
                    b.time_since_death = 0.0
                    world.dead_balls.append(b)
                else:
                    b.time_since_death = getattr(b, "time_since_death", 0.0) + delta
                continue


class TimeRewindAltarMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Time Rewind Altar"
        self.description = "An altar that, when captured by a team, rewinds the positions and health of all enemy balls by 5 seconds, allowing the capturing team to regain a lost advantage or punish an aggressive push."
        self.altar = None
        self.ball_history = {}
        self.time_elapsed = 0.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        arena_w = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_h = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        self.altar = {
            "x": arena_w * 0.5,
            "y": arena_h * 0.5,
            "radius": 150.0,
            "capture_progress": 0.0,
            "owner": None,
            "cooldown": 0.0
        }
        self.ball_history = {}
        self.time_elapsed = 0.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        self.time_elapsed += delta

        # Record history for 5 seconds
        for b in balls:
            bid = getattr(b, "id", id(b))
            if bid not in self.ball_history:
                self.ball_history[bid] = []

            # Record state
            state = {
                "t": self.time_elapsed,
                "x": getattr(b, "x", 0.0),
                "y": getattr(b, "y", 0.0),
                "hp": getattr(b, "hp", 0.0),
                "alive": getattr(b, "alive", False)
            }
            self.ball_history[bid].append(state)

            # Prune old states (older than 5 seconds)
            while self.ball_history[bid] and self.time_elapsed - self.ball_history[bid][0]["t"] > 5.0:
                self.ball_history[bid].pop(0)

        if not self.altar:
            return

        # Cooldown management
        if self.altar["cooldown"] > 0:
            self.altar["cooldown"] -= delta
            return

        teams_present = {}
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                bx = getattr(b, "x", 0.0)
                by = getattr(b, "y", 0.0)
                dist_sq = (bx - self.altar["x"])**2 + (by - self.altar["y"])**2
                if dist_sq <= self.altar["radius"]**2:
                    team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                    teams_present[team] = teams_present.get(team, 0) + 1

                    if hasattr(b, "inventory") and "negative_modifier" in b.inventory:
                        b.inventory.remove("negative_modifier")
                        self.altar["sabotaged_by"] = team
                        if hasattr(world, "add_event"):
                            world.add_event("altar_sabotaged", {"team": team})

                    saboteur = self.altar.get("sabotaged_by")
                    if saboteur and saboteur != team:
                        b.hp = max(0.0, getattr(b, "hp", 100.0) - 15.0 * delta)

        if teams_present:
            max_team = max(teams_present, key=teams_present.get)
            is_tie = sum(1 for t, v in teams_present.items() if v == teams_present[max_team]) > 1
            if not is_tie:
                if self.altar["owner"] == max_team:
                    if self.altar["capture_progress"] < 100.0:
                        self.altar["capture_progress"] = min(100.0, self.altar["capture_progress"] + 20.0 * delta)
                        if self.altar["capture_progress"] == 100.0:
                            # TRIGGER REWIND!
                            self.trigger_rewind(max_team, balls, world)
                            self.altar["capture_progress"] = 0.0
                            self.altar["owner"] = None
                            self.altar["cooldown"] = 30.0 # 30s cooldown after use
                else:
                    self.altar["capture_progress"] -= 20.0 * delta
                    if self.altar["capture_progress"] <= 0:
                        self.altar["owner"] = max_team
                        self.altar["capture_progress"] = 0.0
        else:
            self.altar["capture_progress"] = max(0.0, self.altar["capture_progress"] - 10.0 * delta)
            if self.altar["capture_progress"] == 0.0:
                self.altar["owner"] = None

    def trigger_rewind(self, capturing_team, balls, world):
        if hasattr(world, "add_event"):
            world.add_event("altar_rewind_triggered", {"team": capturing_team})

        for b in balls:
            team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
            # Rewind only enemy balls
            if team != capturing_team and getattr(b, "ball_type", None) != "spectator":
                bid = getattr(b, "id", id(b))
                if bid in self.ball_history and self.ball_history[bid]:
                    # The oldest state is the one closest to 5 seconds ago
                    old_state = self.ball_history[bid][0]
                    b.x = old_state["x"]
                    b.y = old_state["y"]
                    if old_state["alive"]:
                        b.hp = old_state["hp"]
                        b.alive = True
                    # If they were dead 5 seconds ago, they stay dead or die
                    else:
                        b.hp = 0.0
                        b.alive = False

class RisingLavaMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Rising Lava"
        self.description = "Lava rises from the bottom of the screen, destroying low platforms and damaging balls."
        self.lava_y = 10000.0  # arbitrary high value, updated on first tick
        self.initialized = False

    def apply_dynamic_traits(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        super().apply_dynamic_traits(world, balls, delta)
        if not self.initialized:
            if hasattr(world, 'arena') and hasattr(world.arena, 'height'):
                self.lava_y = world.arena.height
            else:
                self.lava_y = 2000.0
            self.initialized = True

        self.lava_y -= 10.0 * delta

        if hasattr(world, 'arena') and hasattr(world.arena, 'platforms'):
            world.arena.platforms = [p for p in world.arena.platforms if getattr(p, 'y', 0.0) < self.lava_y]

        for b in balls:
            if getattr(b, 'alive', False):
                if getattr(b, 'y', 0.0) > self.lava_y:
                    b.hp -= 50.0 * delta
                    if b.hp <= 0:
                        b.hp = 0
                        b.alive = False
                        b.killer = "lava"

class ChromaBossMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Chroma Boss"
        self.description = "A new boss ball type that rapidly cycles through aura colors. Hitting the boss while its aura matches your own heals you instead of damaging the boss, making timing crucial for takedowns."
        self.boss_id = None
        self.boss_aura_timer = 0.0
        self.boss_aura_index = 0
        self.aura_colors = [(0.0, 1.0, 0.0, 0.5), (0.0, 0.0, 1.0, 0.6), (1.0, 0.0, 1.0, 0.7), (1.0, 0.0, 0.0, 0.8), (1.0, 1.0, 0.0, 1.0)]

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        import random
        boss_x = random.uniform(200, getattr(world.arena, "width", 1000) - 200) if hasattr(world, "arena") else 500
        boss_y = random.uniform(200, getattr(world.arena, "height", 1000) - 200) if hasattr(world, "arena") else 500

        boss_class = type('MockBoss', (object,), {})
        if balls:
            base_ball = balls[0]
            boss_class = type(base_ball)

        boss = boss_class()

        if balls:
            for attr in dir(balls[0]):
                if not attr.startswith('__') and not callable(getattr(balls[0], attr)):
                    try:
                        setattr(boss, attr, getattr(balls[0], attr))
                    except AttributeError:
                        pass

        boss.id = getattr(world, "next_id", random.randint(10000, 99999))
        self.boss_id = boss.id
        boss.x = boss_x
        boss.y = boss_y
        boss.ball_type = "chroma_boss"
        boss.team = "boss"
        boss.max_hp = 5000.0
        boss.hp = 5000.0
        boss.damage = 30.0
        boss.radius = 40.0
        boss.speed = 80.0
        boss.alive = True
        boss.cosmetic_aura_color = self.aura_colors[0]

        balls.append(boss)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        boss = None
        for b in balls:
            if getattr(b, "id", None) == self.boss_id:
                boss = b
                break

        if boss and getattr(boss, "alive", False):
            self.boss_aura_timer += delta
            if self.boss_aura_timer >= 1.0:
                self.boss_aura_timer = 0.0
                self.boss_aura_index = (self.boss_aura_index + 1) % len(self.aura_colors)
                boss.cosmetic_aura_color = self.aura_colors[self.boss_aura_index]
                if hasattr(world, "add_event"):
                    world.add_event("chroma_boss_aura_change", {"color": boss.cosmetic_aura_color})


class RandomQuantumTunnelsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Random Quantum Tunnels"
        self.description = "Random quantum tunnels occasionally spawn. Entering one instantly teleports the ball to the opposite side of the map with inverted velocity."
        self.tunnels = []
        self.tunnel_radius = 40.0
        self.spawn_timer = 0.0

    class Tunnel:
        def __init__(self, x, y):
            self.x = x
            self.y = y

    def setup(self, world, balls):
        super().setup(world, balls)
        self.tunnels = []
        import random
        if hasattr(world, "arena"):
            w, h = getattr(world.arena, "width", 2000.0), getattr(world.arena, "height", 2000.0)
            for _ in range(3):
                self.tunnels.append(self.Tunnel(random.uniform(100, w-100), random.uniform(100, h-100)))

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random
        import math

        self.spawn_timer += delta
        if self.spawn_timer > 10.0:
            self.spawn_timer = 0.0
            if hasattr(world, "arena"):
                w, h = getattr(world.arena, "width", 2000.0), getattr(world.arena, "height", 2000.0)
                if len(self.tunnels) > 0:
                    self.tunnels.pop(0)
                self.tunnels.append(self.Tunnel(random.uniform(100, w-100), random.uniform(100, h-100)))

        for b in balls:
            if not getattr(b, "alive", False):
                continue

            cd = getattr(b, "quantum_tunnel_cooldown", 0.0)
            if cd > 0:
                b.quantum_tunnel_cooldown = max(0.0, cd - delta)
                continue

            for t in self.tunnels:
                dist = math.sqrt((b.x - t.x)**2 + (b.y - t.y)**2)
                if dist < self.tunnel_radius:
                    w = 2000.0
                    h = 2000.0
                    if hasattr(world, "arena"):
                        w = getattr(world.arena, "width", 2000.0)
                        h = getattr(world.arena, "height", 2000.0)

                    b.x = w - b.x
                    b.y = h - b.y
                    b.vx = -getattr(b, "vx", 0.0)
                    b.vy = -getattr(b, "vy", 0.0)
                    b.quantum_tunnel_cooldown = 1.0

                    if hasattr(world, "add_event"):
                        world.add_event("quantum_tunnel_teleport", {"ball_id": getattr(b, "id", 0)})
                    break



class GuildWarMode(GameMode):
    def __init__(self, attacker_guild=None, defender_guild=None):
        super().__init__()
        self.name = "Guild War"
        self.description = "Attack the enemy guild's HQ and destroy their defenses."
        self.attacker_guild = attacker_guild
        self.defender_guild = defender_guild
        self.hq_hp = 5000
        self.hq_max_hp = 5000
        self.defenses_spawned = False
        self.attacker_balls = []
        self.defender_balls = []
        self.hq_x = 400
        self.hq_y = 300
        self.hq_radius = 50

    def setup(self, world, balls):
        super().setup(world, balls)
        self.attacker_balls = []
        self.defender_balls = []

        # Split balls mock
        half = len(balls) // 2
        for i, b in enumerate(balls):
            if i < half:
                self.attacker_balls.append(b.id)
            else:
                self.defender_balls.append(b.id)

        try:
            from system.guild import GuildManager
            gm = GuildManager()
            if self.defender_guild and hasattr(world, 'arena'):
                if hasattr(gm, 'get_hq_status'):
                    hq_status = gm.get_hq_status(self.defender_guild)
                    if hq_status:
                        defenses = hq_status.get("defenses", {})
                        # Add defensive hazards
                        import math
                        angle_step = 2 * math.pi / max(1, sum(defenses.values()))
                        current_angle = 0
                        for d_type, amount in defenses.items():
                            for _ in range(amount):
                                distance = 100 + (hash(current_angle) % 50)
                                world.arena.hazards.append({
                                    "type": "hazard",
                                    "kind": d_type,
                                    "x": self.hq_x + math.cos(current_angle) * distance,
                                    "y": self.hq_y + math.sin(current_angle) * distance,
                                    "radius": 15,
                                    "damage": 10 if d_type == "turret" else 20,
                                    "active": True,
                                    "is_defense": True,
                                    "owner_guild": self.defender_guild
                                })
                                current_angle += angle_step
        except (ImportError, AttributeError):
            pass

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        # Check attackers in range of HQ
        attackers_in_range = []
        for b in world.balls:
            if b.id in self.attacker_balls:
                dist = ((b.x - self.hq_x)**2 + (b.y - self.hq_y)**2)**0.5
                if dist < self.hq_radius + b.radius + 20:
                    attackers_in_range.append(b)

        if attackers_in_range:
            damage = len(attackers_in_range) * 10 * delta
            self.hq_hp -= damage
            if self.hq_hp <= 0:
                self.hq_hp = 0
                world.add_event('guild_war_over', {
                    'type': 'guild_war_over',
                    'winner': self.attacker_guild,
                    'message': f"{self.attacker_guild} destroyed {self.defender_guild}'s HQ!"
                })
                # Attempt to steal resources
                try:
                    from system.guild import GuildManager
                    gm = GuildManager()
                    if self.attacker_guild and self.defender_guild and hasattr(gm, 'record_siege_defense_broken'):
                        stolen = gm.record_siege_defense_broken(self.attacker_guild, self.defender_guild, 1000)
                        world.add_event('siege_success', {'attacker': self.attacker_guild, 'defender': self.defender_guild, 'stolen': stolen})
                except (ImportError, AttributeError):
                    pass

        # Defenses deal damage
        if hasattr(world, 'arena'):
            for h in world.arena.hazards:
                if h.get("is_defense") and h.get("active"):
                    for b in world.balls:
                        if b.id in self.attacker_balls:
                            dist = ((b.x - h["x"])**2 + (b.y - h["y"])**2)**0.5
                            if dist < h["radius"] + b.radius:
                                b.hp -= h.get("damage", 5) * delta


class GuildStormMode(GameMode):
    def __init__(self, guild_name=None, cost=500):
        super().__init__()
        self.name = "Guild Storm"
        self.description = "A powerful storm summoned by pooling guild resources. Guild members gain speed and damage buffs, while non-members take periodic damage."
        self.guild_name = guild_name
        self.cost = cost
        self.storm_active = False
        self.storm_duration = 30.0
        self.timer = 0.0
        self.guild_members_cache = []

    def setup(self, world, balls):
        super().setup(world, balls)

        self.guild_members_cache = []
        # Check if we can activate it
        if self.guild_name:
            from system.guild import GuildManager
            guild_manager = GuildManager()
            guild = guild_manager.get_guild(self.guild_name)
            if guild and guild.get("resources", 0) >= self.cost:
                guild["resources"] -= self.cost
                guild_manager.save()
                self.storm_active = True
                self.guild_members_cache = guild.get("members", [])

                if hasattr(world, 'add_event'):
                    world.add_event('guild_storm', {
                        'type': 'guild_storm',
                        'message': f"Guild Storm activated by {self.guild_name}!"
                    })

        for b in balls:
            if not getattr(b, 'base_speed', None):
                b.base_speed = getattr(b, 'speed', 100.0)
            if not getattr(b, 'base_damage', None):
                b.base_damage = getattr(b, 'damage', 10.0)

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        if not self.storm_active:
            return

        self.timer += delta
        if self.timer >= self.storm_duration:
            self.storm_active = False

            # Reset buffs
            for b in balls:
                b.speed = b.base_speed
                b.damage = b.base_damage

            if hasattr(world, 'add_event'):
                world.add_event('guild_storm_end', {
                    'type': 'guild_storm_end',
                    'message': "The Guild Storm has dissipated."
                })
            return

        for b in balls:
            player_id = getattr(b, 'player_id', None)
            is_member = False

            if self.guild_name and player_id and player_id in self.guild_members_cache:
                is_member = True

            if is_member:
                b.speed = b.base_speed * 1.5
                b.damage = b.base_damage * 1.5
            else:
                b.speed = b.base_speed
                b.damage = b.base_damage
                # Periodic damage to non-members
                b.hp -= 5.0 * delta

class PinballMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Pinball Mutator"
        self.description = "Balls are forced to move continuously and taking damage from walls is disabled. Hitting walls instead provides massive momentum boosts and recharges dash abilities, encouraging a pinball-like playstyle."
        self._base_speed_mult = 1.5
        self._dash_recharge = 1.0

    def setup(self, world, balls):
        super().setup(world, balls)
        for ball in balls:
            if hasattr(ball, 'speed'):
                ball.speed *= self._base_speed_mult

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        for ball in balls:
            if not getattr(ball, "is_alive", True):
                continue

            # Disable wall damage by clamping position before the physics engine applies it (if applicable) or setting a flag
            # Note: A real implementation might need to hook into the wall collision event, but here we can simulate it
            # by detecting proximity to walls and reversing velocity + boosting

            radius = getattr(ball, "radius", 20)
            hit_wall = False

            # Predict or detect wall hits
            if getattr(ball, "x", 0) <= radius:
                ball.x = radius
                if hasattr(ball, "vx") and ball.vx < 0:
                    ball.vx = -ball.vx * 1.5
                    hit_wall = True
            elif getattr(ball, "x", 0) >= arena_width - radius:
                ball.x = arena_width - radius
                if hasattr(ball, "vx") and ball.vx > 0:
                    ball.vx = -ball.vx * 1.5
                    hit_wall = True

            if getattr(ball, "y", 0) <= radius:
                ball.y = radius
                if hasattr(ball, "vy") and ball.vy < 0:
                    ball.vy = -ball.vy * 1.5
                    hit_wall = True
            elif getattr(ball, "y", 0) >= arena_height - radius:
                ball.y = arena_height - radius
                if hasattr(ball, "vy") and ball.vy > 0:
                    ball.vy = -ball.vy * 1.5
                    hit_wall = True

            if hit_wall:
                # Provide momentum boost and recharge dash
                if hasattr(ball, 'cooldown'):
                    ball.cooldown = max(0, ball.cooldown - self._dash_recharge)
                ball.wall_damage_immunity = True

                # We can't easily disable wall damage if it's processed elsewhere,
                # but we can try to heal the ball if it just took wall damage, or prevent it
                # by adding an invulnerability frame, or ensuring we bounce before the wall logic
                if hasattr(ball, 'wall_damage_immunity'):
                    ball.wall_damage_immunity = True


class BiomeSafeZonesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Biome Safe Zones"
        self.description = "Each shrinking safe zone acts as a unique biome, granting different passive abilities, allowing for multiple tactical advantages."
        self.zones = [] # list of {"x": float, "y": float, "radius": float, "target_x": float, "target_y": float, "biome": string}
        self.min_zone_radius = 50.0
        self.biomes = ["speed", "damage", "heal", "shield", "low_gravity"]

    def setup(self, world, balls):
        super().setup(world, balls)
        self.world = world
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        import random
        self.zones = []
        for i in range(4):
            r = min(arena_width, arena_height) / 4.0
            x = random.uniform(r, arena_width - r)
            y = random.uniform(r, arena_height - r)
            self.zones.append({
                "x": x,
                "y": y,
                "radius": r,
                "target_x": random.uniform(r, arena_width - r),
                "target_y": random.uniform(r, arena_height - r),
                "biome": self.biomes[i % len(self.biomes)]
            })

    def tick(self, world, balls, delta=0.016):
        import math
        import random

        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        # Update zones
        for zone in self.zones:
            # shrink
            if zone["radius"] > self.min_zone_radius:
                zone["radius"] -= 2.0 * delta
                if zone["radius"] < self.min_zone_radius:
                    zone["radius"] = self.min_zone_radius

            # move towards target
            dx = zone["target_x"] - zone["x"]
            dy = zone["target_y"] - zone["y"]
            dist = math.sqrt(dx*dx + dy*dy)
            speed = 10.0 * delta
            if dist > speed:
                zone["x"] += (dx/dist) * speed
                zone["y"] += (dy/dist) * speed
            else:
                zone["x"] = zone["target_x"]
                zone["y"] = zone["target_y"]
                zone["target_x"] = random.uniform(200, arena_width - 200)
                zone["target_y"] = random.uniform(200, arena_height - 200)

        for b in balls:
            w_timer = getattr(b, 'weather_immunity_timer', 0.0)
            is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
            if not getattr(b, "alive", False):
                continue

            if not hasattr(b, "base_speed"):
                b.base_speed = getattr(b, "speed", 100.0)
            if not hasattr(b, "base_damage"):
                b.base_damage = getattr(b, "damage", 10.0)

            in_any_zone = False
            active_biome = None
            closest_dist = float('inf')

            for zone in self.zones:
                dx = b.x - zone["x"]
                dy = b.y - zone["y"]
                dist = math.sqrt(dx*dx + dy*dy)
                if dist <= zone["radius"]:
                    in_any_zone = True
                    if dist < closest_dist:
                        closest_dist = dist
                        active_biome = zone["biome"]

            # Remove previous modifiers if biome changed or outside zone
            if getattr(b, "biome_modifier_speed", False) and active_biome != "speed":
                b.speed = b.base_speed
                delattr(b, "biome_modifier_speed")

            if getattr(b, "biome_modifier_damage", False) and active_biome != "damage":
                b.damage = b.base_damage
                delattr(b, "biome_modifier_damage")

            if getattr(b, "biome_modifier_low_gravity", False) and active_biome != "low_gravity":
                if hasattr(b, "base_mass"):
                    b.mass = b.base_mass
                delattr(b, "biome_modifier_low_gravity")

            if in_any_zone and active_biome:
                if active_biome == "speed":
                    if not getattr(b, "biome_modifier_speed", False):
                        b.speed = b.base_speed * 1.5
                        b.biome_modifier_speed = True
                elif active_biome == "damage":
                    if not getattr(b, "biome_modifier_damage", False):
                        b.damage = b.base_damage * 1.5
                        b.biome_modifier_damage = True
                elif active_biome == "heal":
                    if hasattr(b, "hp") and hasattr(b, "max_hp"):
                        b.hp = min(getattr(b, "max_hp", 100.0), b.hp + 10.0 * delta)
                elif active_biome == "shield":
                    b.energy_shield_active = True
                    b.energy_shield_hp = getattr(b, "energy_shield_hp", 0.0) + 15.0 * delta
                    if getattr(b, "energy_shield_hp", 0.0) > 50.0:
                        b.energy_shield_hp = 50.0
                elif active_biome == "low_gravity":
                    if not getattr(b, "biome_modifier_low_gravity", False):
                        if not hasattr(b, "base_mass"):
                            b.base_mass = getattr(b, "mass", 1.0)
                        b.mass = b.base_mass * 0.1
                        b.biome_modifier_low_gravity = True
            else:
                if not is_immune:
                    damage = 10.0 * delta
                    b.hp -= damage
                    if b.hp <= 0:
                        b.hp = 0
                        b.alive = False
                        if hasattr(b, "id") and b.id not in world.dead_balls:
                            world.dead_balls.append(b.id)
                            world.add_event("ball_died", {"id": b.id, "reason": "biome_safe_zones_storm", "killer_id": -1})


class ElementalChainReactionMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Elemental Chain Reactions"
        self.description = "A game mode where elemental attacks trigger chain reactions. Hitting a burning ball with a water attack creates a massive steam explosion that blinds everyone nearby, while hitting a frozen ball with a fire attack instantly shatters their ice for massive burst damage."


class CollapsingCeilingMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Collapsing Ceiling"
        self.description = "The ceiling is collapsing! Safe zones appear, and their vertical height shrinks over time. Balls caught under falling debris are briefly stunned and take massive damage."
        self.zones = []
        self.collapse_timer = 0.0
        self.max_collapse_timer = 10.0
        self.zone_width = 200.0
        self.zone_height = 800.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.collapse_timer = self.max_collapse_timer
        self._spawn_zones(world)

    def _spawn_zones(self, world):
        import random
        self.zones = []
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        # Initial safe zones
        self.zone_height = arena_height
        for _ in range(3):
            x = random.uniform(self.zone_width / 2, arena_width - self.zone_width / 2)
            y = arena_height / 2
            self.zones.append({"x": x, "y": y, "width": self.zone_width, "height": self.zone_height})

    def tick(self, world, balls, delta=0.016):
        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        self.collapse_timer -= delta

        # Shrink the vertical height
        shrink_rate = 50.0
        self.zone_height = max(100.0, self.zone_height - shrink_rate * delta)

        for z in self.zones:
            z["height"] = self.zone_height

        if self.collapse_timer <= 0:
            self.collapse_timer = self.max_collapse_timer
            # Drop the ceiling (damage anyone outside the safe zones vertically or horizontally)
            for b in balls:
                if not getattr(b, "alive", False):
                    continue
                w_timer = getattr(b, 'weather_immunity_timer', 0.0)
                is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
                if is_immune:
                    continue

                in_safe_zone = False
                for z in self.zones:
                    # check if inside the rectangular safe zone
                    dx = abs(b.x - z["x"])
                    dy = abs(b.y - z["y"])
                    if dx <= z["width"] / 2 and dy <= z["height"] / 2:
                        in_safe_zone = True
                        break

                if not in_safe_zone:
                    # Stun and massive damage
                    if not getattr(b, "is_stunned", False):
                        b.is_stunned = True
                    b.stun_timer = max(getattr(b, "stun_timer", 0.0), 2.0)

                    damage = 300.0
                    if hasattr(b, "take_damage"):
                        b.take_damage(damage)
                    elif hasattr(b, "hp"):
                        b.hp -= damage
                        if b.hp <= 0:
                            b.hp = 0
                            b.alive = False
                            if hasattr(b, "id") and b.id not in world.dead_balls:
                                world.dead_balls.append(b.id)
                                if hasattr(world, "add_event"):
                                    world.add_event("ball_died", {"id": b.id, "reason": "collapsing_ceiling", "killer_id": -1})

            self._spawn_zones(world)





class TiltingPlatformMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Tilting Platform"
        self.description = "The arena periodically tilts, causing balls to drift slowly towards the edge or center."
        self.tilt_timer = 0.0
        self.tilt_duration = 10.0
        self.tilt_direction = "center"
        self.drift_speed = 100.0

    def apply_dynamic_traits(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        pass

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        if not hasattr(world, "dead_balls"):
            world.dead_balls = []
        self.tilt_timer = 0.0
        import random
        self.tilt_duration = random.uniform(8.0, 12.0)
        self.tilt_direction = random.choice(["center", "edge"])

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        self.tilt_timer += delta
        if self.tilt_timer >= self.tilt_duration:
            self.tilt_timer = 0.0
            import random
            self.tilt_duration = random.uniform(8.0, 12.0)
            self.tilt_direction = random.choice(["center", "edge"])
            if hasattr(world, "add_event"):
                world.add_event("platform_tilt", {"direction": self.tilt_direction})

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        center_x = arena_width / 2.0
        center_y = arena_height / 2.0

        import math
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                dx = center_x - b.x
                dy = center_y - b.y
                dist = math.hypot(dx, dy)

                if dist > 0.1:
                    nx = dx / dist
                    ny = dy / dist
                    drift = self.drift_speed * delta

                    if self.tilt_direction == "center":
                        b.x += nx * drift
                        b.y += ny * drift
                    elif self.tilt_direction == "edge":
                        b.x -= nx * drift
                        b.y -= ny * drift



class CurrencyBurdenMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Risk Reward Currency"
        self.description = "Currency pickups grant damage but slow you down and increase your size. Deposit at altars for permanent buffs."
        self.currency_spawn_timer = 0.0

    def setup(self, world: Any, balls: List[Any]) -> None:
        super().setup(world, balls)
        if getattr(world, "currency_pickups", None) is None:
            world.currency_pickups = []
        if not hasattr(world, "altars"):
            world.altars = []

        # Clear generic boosters
        if hasattr(world, "boosters"):
            world.boosters = []

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        import random
        # Spawn some altars
        for _ in range(3):
            world.altars.append({
                "x": random.uniform(100, arena_width - 100),
                "y": random.uniform(100, arena_height - 100),
                "radius": 50.0
            })

        # Initial currency
        for _ in range(15):
            world.currency_pickups.append({
                "x": random.uniform(50, arena_width - 50),
                "y": random.uniform(50, arena_height - 50),
                "type": "currency"
            })

        for b in balls:
            if getattr(b, "ball_type", None) != "spectator":
                b.currency = getattr(b, "currency", 0)

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random
        import math

        # Suppress generic boosters
        if hasattr(world, "boosters"):
            world.boosters = []

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        self.currency_spawn_timer += delta
        if self.currency_spawn_timer >= 1.5:
            self.currency_spawn_timer = 0.0
            if len(world.currency_pickups) < 40:
                world.currency_pickups.append({
                    "x": random.uniform(50, arena_width - 50),
                    "y": random.uniform(50, arena_height - 50),
                    "type": "currency"
                })

        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            # Initialize base stats if not present
            if not hasattr(b, "base_speed"):
                b.base_speed = getattr(b, "speed", 100.0)
            if not hasattr(b, "base_damage"):
                b.base_damage = getattr(b, "damage", 10.0)
            if not hasattr(b, "base_radius"):
                b.base_radius = getattr(b, "radius", 10.0)

            # Collect currency
            pickups_to_remove = []
            for c in world.currency_pickups:
                dx = b.x - c["x"]
                dy = b.y - c["y"]
                dist = math.sqrt(dx*dx + dy*dy)
                if dist <= b.radius + 15.0:
                    b.currency = getattr(b, "currency", 0) + 1
                    pickups_to_remove.append(c)

            for c in pickups_to_remove:
                if c in world.currency_pickups:
                    world.currency_pickups.remove(c)

            curr = getattr(b, "currency", 0)

            # Apply Burden / Risk-Reward
            # Slower speed (min 0.2x)
            b.speed = b.base_speed * max(0.2, 1.0 - (curr * 0.05))
            # Higher damage (up to whatever)
            b.damage = b.base_damage * (1.0 + (curr * 0.1))
            # Larger radius
            b.radius = b.base_radius * (1.0 + (curr * 0.02))

            # Deposit at altars
            for altar in getattr(world, "altars", []):
                dx = b.x - altar["x"]
                dy = b.y - altar["y"]
                dist = math.sqrt(dx*dx + dy*dy)
                if dist <= b.radius + altar["radius"]:
                    team = getattr(b, "team", getattr(b, "ball_type", "unknown"))

                    if hasattr(b, "inventory") and "negative_modifier" in b.inventory:
                        b.inventory.remove("negative_modifier")
                        altar["sabotaged_by"] = team
                        if hasattr(world, "add_event"):
                            world.add_event("altar_sabotaged", {"team": team})

                    saboteur = altar.get("sabotaged_by")
                    if saboteur and saboteur != team:
                        b.hp = max(0.0, getattr(b, "hp", 100.0) - 15.0 * delta)

            if curr > 0:
                for altar in getattr(world, "altars", []):
                    dx = b.x - altar["x"]
                    dy = b.y - altar["y"]
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist <= b.radius + altar["radius"]:
                        # Buy buff using all currency
                        buff_amount = curr
                        b.currency = 0

                        # Apply permanent buff based on amount deposited
                        upgrade_type = random.choice(["max_hp", "base_speed", "base_damage", "reflect_shield_duration"])
                        if upgrade_type == "max_hp":
                            if not hasattr(b, "base_max_hp"):
                                b.base_max_hp = getattr(b, "max_hp", 100.0)
                            b.base_max_hp += 5.0 * buff_amount
                            b.max_hp = b.base_max_hp
                            b.hp = min(getattr(b, "hp", 100.0) + 5.0 * buff_amount, b.max_hp)
                        elif upgrade_type == "base_speed":
                            b.base_speed += 2.0 * buff_amount
                        elif upgrade_type == "base_damage":
                            b.base_damage += 1.0 * buff_amount
                        elif upgrade_type == "reflect_shield_duration":
                            if not hasattr(b, "bonus_reflect_shield_duration"):
                                b.bonus_reflect_shield_duration = 0.0
                            b.bonus_reflect_shield_duration += 0.5 * buff_amount

                        # Reset dynamic stats calculation
                        b.speed = b.base_speed
                        b.damage = b.base_damage
                        b.radius = b.base_radius

                        if hasattr(world, "add_event"):
                            world.add_event("altar_deposit", {"ball": b, "amount": buff_amount, "upgrade": upgrade_type})
                        break


class TricksterEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Trickster Event"
        self.description = "An arena event where all players are turned into Tricksters for 30 seconds."
        self.duration = 30.0
        self.timer = 0.0
        self.applied = False
        self.finished = False

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        if self.finished:
            return

        if not self.applied:
            self.applied = True
            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "team", "") == "spectator":
                    continue
                b.original_ball_type_trickster_event = getattr(b, "ball_type", None)
                b.ball_type = "trickster"
                if hasattr(b, "traits") and "trickster" not in getattr(b, "traits", []):
                    b.traits.append("trickster")
                    b.trickster_event_added_trait = True
                else:
                    b.trickster_event_added_trait = False

        self.timer += delta

        if self.timer >= self.duration:
            self.finished = True
            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "team", "") == "spectator":
                    continue
                if hasattr(b, "original_ball_type_trickster_event"):
                    b.ball_type = b.original_ball_type_trickster_event
                if getattr(b, "trickster_event_added_trait", False):
                    if hasattr(b, "traits") and "trickster" in b.traits:
                        b.traits.remove("trickster")

class AuraPulseEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Aura Pulse Event"
        self.description = "A global event where stacking auras pulse outward globally every 15 seconds. During a pulse, all players with active aura buffs grant those buffs to random friendly players anywhere on the map for 5 seconds. If a player with a reversed aura (via the Aura Inverter Trap) pulses, it debuffs enemies map-wide instead."
        self.pulse_timer = 0.0

    def tick(self, world, balls, delta=0.016):
        import random
        self.pulse_timer += delta
        if self.pulse_timer >= 15.0:
            self.pulse_timer = 0.0

            aura_buff_keys = ["vampiric_aura_timer", "decoy_aura_timer", "cosmetic_aura_scale"]

            for b in balls:
                if not getattr(b, "alive", True) or getattr(b, "is_decoy", False):
                    continue

                has_aura = False
                active_auras = {}
                for key in aura_buff_keys:
                    val = getattr(b, key, 0.0)
                    if isinstance(val, (int, float)) and val > (1.0 if key == "cosmetic_aura_scale" else 0.0):
                        has_aura = True
                        active_auras[key] = val

                if has_aura:
                    is_reversed = getattr(b, "aura_inversion_timer", 0.0) > 0.0

                    if is_reversed:
                        enemies = [e for e in balls if e != b and getattr(e, "alive", True) and getattr(e, "team", getattr(e, "ball_type", "")) != getattr(b, "team", getattr(b, "ball_type", ""))]
                        for e in enemies:
                            e.aura_disruption_timer = max(getattr(e, "aura_disruption_timer", 0.0), 5.0)
                            e.aura_inversion_timer = max(getattr(e, "aura_inversion_timer", 0.0), 5.0)
                    else:
                        friendlies = [f for f in balls if f != b and getattr(f, "alive", True) and getattr(f, "team", getattr(f, "ball_type", "")) == getattr(b, "team", getattr(b, "ball_type", ""))]
                        if friendlies:
                            target = random.choice(friendlies)
                            for key in active_auras:
                                if key == "cosmetic_aura_scale":
                                    target.cosmetic_aura_scale = max(getattr(target, key, 1.0), active_auras[key])
                                else:
                                    setattr(target, key, max(getattr(target, key, 0.0), 5.0))


class ExpandingArenaMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Expanding Arena"
        self.description = "Every 30 seconds the arena size increases by 10%, giving players more space but making it harder to find resources and forcing ranged encounters."
        self.expand_timer = 0.0
        self.max_size = 2000.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        if hasattr(world, "arena"):
            world.arena.width = min(getattr(world.arena, "width", 500.0), 500.0)
            world.arena.height = min(getattr(world.arena, "height", 500.0), 500.0)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.apply_dynamic_traits(world, balls, delta)

        if not hasattr(self, "expand_timer"):
            self.expand_timer = 0.0

        self.expand_timer += delta

        if self.expand_timer >= 30.0:
            self.expand_timer -= 30.0

            if hasattr(world, "arena"):
                old_w = getattr(world.arena, "width", 500.0)
                old_h = getattr(world.arena, "height", 500.0)

                new_w = min(self.max_size, old_w * 1.1)
                new_h = min(self.max_size, old_h * 1.1)

                world.arena.width = new_w
                world.arena.height = new_h

                if hasattr(world, "add_event"):
                    world.add_event("arena_expanded", {"width": new_w, "height": new_h})

class ShrinkingArenaMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Shrinking Arena"
        self.description = "Every 30 seconds the arena size is reduced by 10%, forcing players into closer combat."
        self.shrink_timer = 0.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.apply_dynamic_traits(world, balls, delta)

        if not hasattr(self, "shrink_timer"):
            self.shrink_timer = 0.0

        self.shrink_timer += delta

        if self.shrink_timer >= 30.0:
            self.shrink_timer -= 30.0

            if hasattr(world, "arena"):
                old_w = getattr(world.arena, "width", 1000.0)
                old_h = getattr(world.arena, "height", 1000.0)

                new_w = max(200.0, old_w * 0.9)
                new_h = max(200.0, old_h * 0.9)

                world.arena.width = new_w
                world.arena.height = new_h

                for b in balls:
                    radius = getattr(b, "radius", 15.0)
                    bx = getattr(b, "x", 0.0)
                    by = getattr(b, "y", 0.0)

                    if bx > new_w - radius:
                        b.x = new_w - radius
                    if by > new_h - radius:
                        b.y = new_h - radius

                if hasattr(world.arena, "hazards"):
                    for h in world.arena.hazards:
                        radius = getattr(h, "radius", 0.0)
                        hx = getattr(h, "x", 0.0)
                        hy = getattr(h, "y", 0.0)
                        if hx > new_w - radius:
                            h.x = new_w - radius
                        if hy > new_h - radius:
                            h.y = new_h - radius

                if hasattr(world, "add_event"):
                    world.add_event("arena_shrunk", {"width": new_w, "height": new_h})


class ExpandingLavaRoyaleMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Expanding Lava Royale"
        self.description = "A battle royale variation where the center is lava and expands outwards, forcing players to eventually fight on the very edges of the map while dodging environmental hazards."
        self.zone_x = 500.0
        self.zone_y = 500.0
        self.danger_radius = 0.0
        self.max_danger_radius = 500.0
        self.expand_rate = 15.0
        self.inside_damage_per_second = 25.0
        self.hazard_timer = 0.0
        import random
        self.random = random

    def setup(self, world, balls):
        super().setup(world, balls)
        self.world = world
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        self.zone_x = arena_width / 2.0
        self.zone_y = arena_height / 2.0
        self.danger_radius = 50.0
        self.max_danger_radius = max(arena_width, arena_height) / 1.5
        self.hazard_timer = 3.0

        valid_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator"]
        for i, b in enumerate(valid_balls):
            if i >= 20:
                b.ball_type = "spectator"
                b.alive = False
            else:
                b.team = getattr(b, "team", b.ball_type)

        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

    def tick(self, world, balls, delta=0.016):
        import math

        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        for b in balls:
            w_timer = getattr(b, 'weather_immunity_timer', 0.0)
            is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
            if not getattr(b, "alive", False):
                if b not in world.dead_balls:
                    b.time_since_death = 0.0
                    world.dead_balls.append(b)
                else:
                    b.time_since_death = getattr(b, "time_since_death", 0.0) + delta

        if self.danger_radius < self.max_danger_radius:
            self.danger_radius += self.expand_rate * delta
            if self.danger_radius > self.max_danger_radius:
                self.danger_radius = self.max_danger_radius

        damage_this_tick = self.inside_damage_per_second * delta

        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                bx = getattr(b, "x", 0.0)
                by = getattr(b, "y", 0.0)
                dx = bx - self.zone_x
                dy = by - self.zone_y
                dist = math.sqrt(dx*dx + dy*dy)

                if dist <= self.danger_radius:
                    b.hp -= damage_this_tick
                    # Apply burn effect like Lava Royale
                    if not getattr(b, "weather_immunity_timer", 0) > 0:
                        b.burn_timer = getattr(b, "burn_timer", 0.0) + delta
                    if b.hp <= 0:
                        b.alive = False
                        b.hp = 0
                        b.killer = "lava"

                # Push players out so they feel the expansion (optional but fits the description)
                if dist > 0.1 and dist <= self.danger_radius + 20.0:
                    push_strength = 200.0
                    if not hasattr(b, "vx"): b.vx = 0.0
                    if not hasattr(b, "vy"): b.vy = 0.0
                    b.vx += (dx / dist) * push_strength * delta
                    b.vy += (dy / dist) * push_strength * delta

        # Rain fireballs from above
        self.hazard_timer -= delta
        if self.hazard_timer <= 0.0 and hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            self.hazard_timer = 0.5  # Spawn frequently!
            angle = self.random.uniform(0, math.pi * 2.0)
            dist = self.random.uniform(0.0, max(arena_width, arena_height))
            hx = self.zone_x + math.cos(angle) * dist
            hy = self.zone_y + math.sin(angle) * dist

            hx = max(50.0, min(arena_width - 50.0, hx))
            hy = max(50.0, min(arena_height - 50.0, hy))

            h_id = len(world.arena.hazards) + self.random.randint(10000, 99999)

            try:
                from arena.procedural_arena import Hazard
                hazard = Hazard(id=h_id, x=hx, y=hy, radius=40.0, kind="lava_projectile", damage=15.0)
                hazard.duration = 10.0
                hazard.active = True
                world.arena.hazards.append(hazard)
            except ImportError:
                class TempHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                        self.duration = 10.0
                        self.active = True
                hazard = TempHazard(h_id, hx, hy, 40.0, "lava_projectile", 15.0)
                world.arena.hazards.append(hazard)

    def check_winner(self, world, balls):
        alive = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator"]
        if len(alive) == 0:
            if hasattr(self, "_award_skill_points"):
                self._award_skill_points()
            return "Draw"

        teams_alive = set(getattr(b, "team", getattr(b, "ball_type", None)) for b in alive)
        if len(teams_alive) == 1:
            if hasattr(self, "_award_skill_points"):
                self._award_skill_points()
            return list(teams_alive)[0]

        if len(alive) == 1:
            if hasattr(self, "_award_skill_points"):
                self._award_skill_points()
            return getattr(alive[0], "team", getattr(alive[0], "ball_type", None))

        return None



