class ChainLightningEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Chain Lightning Event"
        self.description = "Chain lightning periodically strikes the center, turning entities into conduits that spread smaller, low-damage arcs to nearby balls for 10 seconds."
        self.strike_timer = 0.0
        self.strike_interval = 20.0
        self.conduit_duration = 10.0
        self.arc_damage = 5.0
        self.arc_radius = 150.0
        self.arc_cooldown_duration = 1.0

    def tick(self, world, balls, delta=0.016):
        import math
        import random

        self.strike_timer += delta

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        center_x = arena_width / 2.0
        center_y = arena_height / 2.0

        if self.strike_timer >= self.strike_interval:
            self.strike_timer = 0.0
            strike_radius = 200.0

            if hasattr(world, "add_event"):
                world.add_event("chain_lightning_strike", {"x": center_x, "y": center_y, "radius": strike_radius})

            for b in balls:
                if not getattr(b, "alive", True):
                    continue
                dist = math.hypot(b.x - center_x, b.y - center_y)
                if dist <= strike_radius + getattr(b, "radius", 15.0):
                    b.chain_lightning_conduit_timer = self.conduit_duration
                    b.chain_lightning_arc_timer = 0.0
                    if hasattr(world, "add_event"):
                        world.add_event("status_effect", {"id": getattr(b, "id", "unknown"), "effect": "conduit", "duration": self.conduit_duration})

        # Process conduits
        for b in balls:
            if not getattr(b, "alive", True):
                continue
            conduit_timer = getattr(b, "chain_lightning_conduit_timer", 0.0)
            if conduit_timer > 0:
                b.chain_lightning_conduit_timer = conduit_timer - delta
                arc_timer = getattr(b, "chain_lightning_arc_timer", 0.0)
                arc_timer -= delta
                if arc_timer <= 0:
                    arc_timer = self.arc_cooldown_duration

                    # Find nearby targets to zap
                    targets = []
                    for target in balls:
                        if target == b or not getattr(target, "alive", True):
                            continue
                        dist = math.hypot(target.x - b.x, target.y - b.y)
                        if dist <= self.arc_radius + getattr(b, "radius", 15.0) + getattr(target, "radius", 15.0):
                            targets.append(target)

                    if targets:
                        target = random.choice(targets)
                        if hasattr(world, "_deal_damage"):
                            world._deal_damage(b, target, self.arc_damage)
                        if hasattr(world, "add_event"):
                            world.add_event("visual_effect", {
                                "type": "line",
                                "x": b.x, "y": b.y,
                                "tx": target.x, "ty": target.y,
                                "color": "cyan"
                            })
                            world.add_event("chain_lightning_arc", {
                                "source": getattr(b, "id", "unknown"),
                                "target": getattr(target, "id", "unknown")
                            })
                b.chain_lightning_arc_timer = arc_timer


class BlackHoleWeatherMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Black Hole Weather"
        self.description = "A weather event that slowly pulls everyone towards the center of the arena."
        self.weather = "black_hole_storm"
        self.pull_strength = 20.0

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import math

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        center_x = arena_width / 2.0
        center_y = arena_height / 2.0

        for b in balls:
            if getattr(b, "alive", True) and getattr(b, "ball_type", "") != "spectator":
                # Do not pull if immune to weather
                w_timer = getattr(b, 'weather_immunity_timer', 0.0)
                is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
                if is_immune:
                    continue

                dx = center_x - b.x
                dy = center_y - b.y
                dist_sq = dx*dx + dy*dy
                if dist_sq > 0.0001:
                    dist = math.sqrt(dist_sq)
                    nx = dx / dist
                    ny = dy / dist

                    pull_x = nx * self.pull_strength * delta
                    pull_y = ny * self.pull_strength * delta

                    b.x += pull_x
                    b.y += pull_y

                    if hasattr(b, 'vx'):
                        b.vx += pull_x * 5
                    if hasattr(b, 'vy'):
                        b.vy += pull_y * 5

class PeriodicGravityFlipMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Periodic Gravity Flip"
        self.description = "Periodically flips the gravity of the arena, sending heavy objects flying and altering player momentum."
        self.flip_timer = 0.0
        self.flip_interval = 5.0
        self.gravity_direction = 1.0
        self.gravity_strength = 200.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.apply_dynamic_traits(world, balls, delta)
        self.flip_timer += delta
        if self.flip_timer >= self.flip_interval:
            self.flip_timer = 0.0
            self.gravity_direction *= -1.0
            dir_str = "Up" if self.gravity_direction < 0 else "Down"
            if hasattr(world, 'add_event'):
                world.add_event("gravity_flip", {"message": f"Gravity flipped {dir_str}!"})

        # Apply global gravity force
        for b in balls:
            if getattr(b, "alive", False):
                mass = getattr(b, "mass", 1.0)
                if not hasattr(b, "vy"):
                    b.vy = 0.0
                gravity_mult = -1.0 if getattr(b, "in_reverse_physics_zone", False) else 1.0
                b.vy += self.gravity_strength * self.gravity_direction * mass * delta * gravity_mult

        if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
            for h in world.arena.hazards:
                mass = getattr(h, "mass", 3.0)  # Heavy objects
                if not hasattr(h, "vy"):
                    h.vy = 0.0
                if not hasattr(h, "vx"):
                    h.vx = 0.0
                h.vy += self.gravity_strength * self.gravity_direction * mass * delta
                if hasattr(h, "y"):
                    h.y += h.vy * delta

