class MovingWallsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Moving Walls"
        self.description = "Random walls spawn and slowly move across the arena. Players must dodge them to avoid being crushed or taking damage."
        self.spawn_timer = 0.0

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random

        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        self.spawn_timer -= delta
        if self.spawn_timer <= 0:
            self.spawn_timer = 5.0
            wall_types = ["horizontal", "vertical"]
            wall_type = random.choice(wall_types)
            speed = 50.0

            if wall_type == "horizontal":
                if random.random() < 0.5:
                    x = 0
                    vx = speed
                else:
                    x = world.arena.width
                    vx = -speed
                y = random.uniform(0, world.arena.height)
                w = 20
                h = random.uniform(100, 300)
                vy = 0.0
            else:
                if random.random() < 0.5:
                    y = 0
                    vy = speed
                else:
                    y = world.arena.height
                    vy = -speed
                x = random.uniform(0, world.arena.width)
                w = random.uniform(100, 300)
                h = 20
                vx = 0.0

            wall_hazard = {
                "kind": "moving_wall",
                "x": x,
                "y": y,
                "width": w,
                "height": h,
                "vx": vx,
                "vy": vy,
                "damage": 20.0,
                "duration": 15.0,
                "id": f"moving_wall_{getattr(world, 'tick_count', random.randint(0, 10000))}"
            }
            if isinstance(world.arena.hazards, list):
                world.arena.hazards.append(wall_hazard)

        to_remove = []
        for hazard in world.arena.hazards:
            if isinstance(hazard, dict) and hazard.get("kind") == "moving_wall":
                hazard["duration"] -= delta
                if hazard["duration"] <= 0:
                    to_remove.append(hazard)
                    continue

                hazard["x"] += hazard.get("vx", 0) * delta
                hazard["y"] += hazard.get("vy", 0) * delta

                hx = hazard["x"]
                hy = hazard["y"]
                hw = hazard["width"]
                hh = hazard["height"]
                hdmg = hazard.get("damage", 20.0)

                for b in balls:
                    if getattr(b, "alive", True) and not getattr(b, "is_intangible", False):
                        bx = b.x
                        by = b.y
                        br = getattr(b, "radius", 20.0)

                        closest_x = max(hx - hw/2, min(bx, hx + hw/2))
                        closest_y = max(hy - hh/2, min(by, hy + hh/2))

                        dist_sq = (bx - closest_x)**2 + (by - closest_y)**2
                        if dist_sq <= br*br:
                            if hasattr(b, "take_damage"):
                                b.take_damage(hdmg * delta)
                            else:
                                b.hp -= hdmg * delta
                                if b.hp <= 0:
                                    b.alive = False

                            b.x += hazard.get("vx", 0) * delta * 1.5
                            b.y += hazard.get("vy", 0) * delta * 1.5
                            b.vx = hazard.get("vx", 0) * 1.5
                            b.vy = hazard.get("vy", 0) * 1.5

                            if hasattr(world, "events"):
                                if getattr(world, "tick_count", 0) % 10 == 0:
                                    world.events.append({'type': 'visual_effect', 'data': {'type': 'explosion', 'x': bx, 'y': by, 'radius': 10.0, 'color': 'gray'}})

        if hasattr(world.arena.hazards, "remove"):
            for r in to_remove:
                if r in world.arena.hazards:
                    world.arena.hazards.remove(r)


class CaptureZonesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Capture Zones"
        self.description = "Players capture sections of the map by remaining inside them. Captured sections periodically drop boosters or spawn defensive hazards against enemies."
        self.zones = []
        self.spawn_timer = 0.0

    def apply_dynamic_traits(self, world, balls, delta):
        # Initialize zones if none exist
        if not self.zones:
            import random
            random.seed(int(getattr(world, "tick_timer", 0.0) * 1000) + 123)
            # Spawn 3 random zones
            for _ in range(3):
                self.zones.append({
                    "x": random.uniform(200, 800),
                    "y": random.uniform(200, 800),
                    "radius": 150.0,
                    "owner": None,
                    "capture_progress": 0.0,
                    "capturing_team": None,
                    "reward_timer": 5.0
                })
            random.seed()

        # Update capture progress
        for zone in self.zones:
            # Determine who is inside the zone
            occupants = []
            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "ball_type", "") == "spectator":
                    continue
                bx = getattr(b, "x", 0.0)
                by = getattr(b, "y", 0.0)
                br = getattr(b, "radius", 20.0)
                dx = bx - zone["x"]
                dy = by - zone["y"]
                if dx*dx + dy*dy <= (zone["radius"] + br)**2:
                    occupants.append(b)

            if not occupants:
                # Decay progress if no one is in
                if zone["capture_progress"] > 0 and zone["owner"] is None:
                    zone["capture_progress"] = max(0.0, zone["capture_progress"] - delta * 10.0)
            else:
                # Only progress if all occupants are from the same team/owner (assuming free-for-all -> owner is ball_type or id, but team is better. Actually, balls don't always have teams. Let's use ball.id or ball_type)
                # Let's use ball_type for ownership/team
                first_occupant_team = getattr(occupants[0], "team", getattr(occupants[0], "ball_type", "unknown"))
                same_team = all(getattr(b, "team", getattr(b, "ball_type", "unknown")) == first_occupant_team for b in occupants)

                if same_team:
                    if zone["owner"] != first_occupant_team:
                        if zone["capturing_team"] == first_occupant_team:
                            zone["capture_progress"] += delta * 20.0
                            if zone["capture_progress"] >= 100.0:
                                zone["capture_progress"] = 100.0
                                zone["owner"] = first_occupant_team
                                if hasattr(world, "add_event"):
                                    world.add_event("zone_captured", {"team": first_occupant_team, "zone": zone})
                        else:
                            # Contested by another team, decay first
                            zone["capture_progress"] -= delta * 20.0
                            if zone["capture_progress"] <= 0:
                                # Start capturing for the new team immediately
                                excess = abs(zone["capture_progress"])
                                zone["capture_progress"] = excess
                                zone["capturing_team"] = first_occupant_team

            # If owned, tick reward timer
            if zone["owner"] is not None:
                zone["reward_timer"] -= delta
                if zone["reward_timer"] <= 0:
                    zone["reward_timer"] = 10.0
                    import random
                    if random.random() < 0.5:
                        # Spawn booster
                        booster = {
                            "type": random.choice(["hp", "speed", "damage"]),
                            "x": zone["x"] + random.uniform(-50, 50),
                            "y": zone["y"] + random.uniform(-50, 50)
                        }
                        if hasattr(world, "boosters"):
                            world.boosters.append(booster)
                        if hasattr(world, "add_event"):
                            world.add_event("zone_spawned_booster", {"zone": zone})
                    else:
                        # Spawn defensive hazard
                        hazard = {
                            "type": "zone_defense",
                            "x": zone["x"] + random.uniform(-50, 50),
                            "y": zone["y"] + random.uniform(-50, 50),
                            "radius": 40.0,
                            "damage": 15.0,
                            "owner_team": zone["owner"],
                            "duration": 8.0
                        }
                        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                            world.arena.hazards.append(hazard)
                        if hasattr(world, "add_event"):
                            world.add_event("zone_spawned_hazard", {"zone": zone})


class ExpandingHazardBubblesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Expanding Hazard Bubbles"
        self.description = "The entire map is safe initially, but expanding hazard bubbles randomly spawn. Players must avoid the growing hazard zones."
        self.bubbles = []
        self.bubble_spawn_timer = 0.0
        self.bubble_spawn_interval = 6.0
        self.max_radius = 250.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.bubbles = []
        self.bubble_spawn_timer = 2.0

    def tick(self, world, balls, delta=0.016):
        import math
        import random
        super().tick(world, balls, delta)
        self.bubble_spawn_timer -= delta

        if self.bubble_spawn_timer <= 0:
            self.bubble_spawn_timer = self.bubble_spawn_interval

            arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") else 1000.0
            arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") else 1000.0

            x = random.uniform(50.0, arena_width - 50.0)
            y = random.uniform(50.0, arena_height - 50.0)

            self.bubbles.append({
                "x": x,
                "y": y,
                "radius": 20.0,
                "timer": 15.0 # Max lifespan
            })

            if hasattr(world, "add_event"):
                world.add_event("hazard_bubble_spawned", {"x": x, "y": y, "message": "Hazard bubble spawned!"})

        active_bubbles = []
        for bubble in self.bubbles:
            bubble["timer"] -= delta
            if bubble["timer"] > 0:
                if bubble["radius"] < self.max_radius:
                    bubble["radius"] += 15.0 * delta
                active_bubbles.append(bubble)

                for b in balls:
                    if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                        dist = math.hypot(b.x - bubble["x"], b.y - bubble["y"])
                        if dist <= bubble["radius"]:
                            damage = 25.0 * delta
                            if hasattr(b, "take_damage"):
                                b.take_damage(damage)
                            else:
                                b.hp = getattr(b, "hp", 100) - damage
                                if b.hp <= 0:
                                    b.alive = False

        self.bubbles = active_bubbles


class HighSpeedReflectiveBarriersMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "High Speed Reflective Barriers"
        self.description = "Barriers spawn in the arena that reflect projectiles and players at high speeds."
        self.barrier_timer = 0.0

    def setup(self, world, balls):
        super().setup(world, balls)
        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            try:
                from arena.procedural_arena import Hazard
                hazard_class = Hazard
            except ImportError:
                class FallbackHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                        self.active = True
                hazard_class = FallbackHazard

            import random
            arena_width = getattr(world.arena, "width", 1000.0)
            arena_height = getattr(world.arena, "height", 1000.0)

            for i in range(3):
                hx = random.uniform(200, arena_width - 200)
                hy = random.uniform(200, arena_height - 200)
                hazard = hazard_class(f"reflect_barrier_{i}", hx, hy, 40.0, "high_speed_reflect_barrier", 0.0)
                world.arena.hazards.append(hazard)

    def apply_dynamic_traits(self, world, balls, delta=0.016):
        import math

        entities = list(balls)
        if hasattr(world, "projectiles"):
            entities.extend(world.projectiles)

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            barriers = [h for h in world.arena.hazards if getattr(h, "kind", "") == "high_speed_reflect_barrier"]

            for entity in entities:
                if not getattr(entity, "alive", True) and not (getattr(entity, "hp", 1.0) > 0 and getattr(entity, "is_projectile", False)):
                    continue

                if hasattr(entity, "reflect_barrier_cooldown") and entity.reflect_barrier_cooldown > 0:
                    entity.reflect_barrier_cooldown -= delta
                    if entity.reflect_barrier_cooldown <= 0:
                        delattr(entity, "reflect_barrier_cooldown")
                    continue

                for barrier in barriers:
                    bx = getattr(barrier, "x", 0.0)
                    by = getattr(barrier, "y", 0.0)
                    br = getattr(barrier, "radius", 40.0)

                    dx = entity.x - bx
                    dy = entity.y - by
                    dist_sq = dx * dx + dy * dy

                    er = getattr(entity, "radius", 10.0)
                    min_dist = br + er

                    if dist_sq < min_dist * min_dist and dist_sq > 0.0001:
                        dist = math.sqrt(dist_sq)
                        nx = dx / dist
                        ny = dy / dist

                        vx = getattr(entity, "vx", 0.0)
                        vy = getattr(entity, "vy", 0.0)

                        dot = vx * nx + vy * ny
                        if dot < 0:
                            # Reflect velocity and increase speed
                            new_vx = (vx - 2 * dot * nx) * 1.5
                            new_vy = (vy - 2 * dot * ny) * 1.5

                            entity.vx = new_vx
                            entity.vy = new_vy

                            # Update positions slightly to avoid getting stuck
                            overlap = min_dist - dist
                            entity.x += nx * overlap
                            entity.y += ny * overlap

                            entity.reflect_barrier_cooldown = 0.5



class ImplosionBombEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Implosion Bomb Event"
        self.description = "A hazard that slowly pulls entities toward its center. When it expires, it violently explodes, pushing everyone away."
        self.event_timer = 0.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.event_timer += delta

        if not hasattr(world, "arena"):
            return

        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        if self.event_timer >= 20.0:
            self.event_timer = 0.0
            import random
            arena_width = getattr(world.arena, "width", 1000)
            arena_height = getattr(world.arena, "height", 1000)
            cx = random.uniform(200, arena_width - 200)
            cy = random.uniform(200, arena_height - 200)

            try:
                from arena.procedural_arena import Hazard
                h = Hazard(id=len(world.arena.hazards) + 91000 + random.randint(0, 1000), x=cx, y=cy, radius=80.0, kind="implosion_bomb", damage=0.0)
            except ImportError:
                class DummyHazardIB:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                h = DummyHazardIB(len(world.arena.hazards) + 91000 + random.randint(0, 1000), cx, cy, 80.0, "implosion_bomb", 0.0)

            setattr(h, "duration", 10.0)
            setattr(h, "pull_radius", 500.0)
            setattr(h, "pull_strength", 150.0)

            world.arena.hazards.append(h)

            if hasattr(world, "add_event"):
                world.add_event("implosion_bomb_spawned", {"x": cx, "y": cy})

        hazards_to_remove = []
        for h in world.arena.hazards:
            if getattr(h, "kind", "") == "implosion_bomb":
                hx = getattr(h, "x", 0.0)
                hy = getattr(h, "y", 0.0)
                pull_radius = getattr(h, "pull_radius", 500.0)
                pull_strength = getattr(h, "pull_strength", 150.0)

                # Decrease duration
                h.duration = getattr(h, "duration", 10.0) - delta

                import math
                # Pull balls
                for b in balls:
                    if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                        dx = hx - b.x
                        dy = hy - b.y
                        dist = math.sqrt(dx*dx + dy*dy)

                        if dist < pull_radius and dist > 0.0001:
                            nx = dx / dist
                            ny = dy / dist
                            b.x += nx * pull_strength * delta
                            b.y += ny * pull_strength * delta

                            if hasattr(b, "vx"):
                                b.vx = getattr(b, "vx", 0.0) + nx * pull_strength * delta * 0.5
                            if hasattr(b, "vy"):
                                b.vy = getattr(b, "vy", 0.0) + ny * pull_strength * delta * 0.5

                if getattr(h, "duration", 0.0) <= 0.0:
                    hazards_to_remove.append(h)

        for h in hazards_to_remove:
            if h in world.arena.hazards:
                world.arena.hazards.remove(h)

            if hasattr(world, "add_event"):
                world.add_event("visual_effect", {"type": "implosion_bomb_explosion", "x": h.x, "y": h.y, "radius": 400.0})

            # Explode and push everyone away
            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                    import math
                    dx = b.x - h.x
                    dy = b.y - h.y
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist <= 400.0:
                        damage = 50.0 * (1.0 - dist / 400.0)
                        b.hp = getattr(b, "hp", 100.0) - damage
                        if b.hp <= 0:
                            b.hp = 0
                            b.alive = False
                            b.killer = "implosion_bomb"

                        if dist > 0.0001:
                            nx = dx / dist
                            ny = dy / dist
                            knockback = 800.0 * (1.0 - dist / 400.0)
                            b.vx = getattr(b, "vx", 0.0) + nx * knockback
                            b.vy = getattr(b, "vy", 0.0) + ny * knockback



class SingularityBombEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Singularity Bomb Event"
        self.description = "A massive singularity bomb spawns periodically. It slowly pulls in all nearby projectiles. If it absorbs enough projectiles or takes enough damage, it detonates in a massive AoE blast!"
        self.event_timer = 0.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.event_timer += delta

        if not hasattr(world, "arena"):
            return

        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        if self.event_timer >= 20.0:
            self.event_timer = 0.0
            import random
            arena_width = getattr(world.arena, "width", 1000)
            arena_height = getattr(world.arena, "height", 1000)
            cx = random.uniform(200, arena_width - 200)
            cy = random.uniform(200, arena_height - 200)

            try:
                from arena.procedural_arena import Hazard
                h = Hazard(id=len(world.arena.hazards) + 90000 + random.randint(0, 1000), x=cx, y=cy, radius=80.0, kind="singularity_bomb", damage=0.0)
            except ImportError:
                class DummyHazardSB:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                h = DummyHazardSB(len(world.arena.hazards) + 90000 + random.randint(0, 1000), cx, cy, 80.0, "singularity_bomb", 0.0)

            setattr(h, "hp", 150.0)
            setattr(h, "max_hp", 150.0)
            setattr(h, "pull_radius", 400.0)
            setattr(h, "pull_strength", 200.0)

            world.arena.hazards.append(h)

            if hasattr(world, "add_event"):
                world.add_event("singularity_bomb_spawned", {"x": cx, "y": cy})

        hazards_to_remove = []
        for h in world.arena.hazards:
            if getattr(h, "kind", "") == "singularity_bomb":
                hx = getattr(h, "x", 0.0)
                hy = getattr(h, "y", 0.0)
                pull_radius = getattr(h, "pull_radius", 400.0)
                pull_strength = getattr(h, "pull_strength", 200.0)

                # Pull projectiles
                if hasattr(world, "projectiles"):
                    import math
                    projs_to_remove = []
                    for p in world.projectiles:
                        px = getattr(p, "x", 0.0)
                        py = getattr(p, "y", 0.0)
                        dx = hx - px
                        dy = hy - py
                        dist = math.sqrt(dx*dx + dy*dy)

                        if dist < pull_radius:
                            if dist < getattr(h, "radius", 80.0):
                                projs_to_remove.append(p)
                            elif dist > 0.0001:
                                nx = dx / dist
                                ny = dy / dist

                                p.vx = getattr(p, "vx", 0.0) + nx * pull_strength * delta
                                p.vy = getattr(p, "vy", 0.0) + ny * pull_strength * delta
                                p.x += nx * (pull_strength * 0.5) * delta
                                p.y += ny * (pull_strength * 0.5) * delta

                    for p in projs_to_remove:
                        if p in world.projectiles:
                            world.projectiles.remove(p)
                        h.hp = getattr(h, "hp", 150.0) - getattr(p, "damage", 10.0)

                if getattr(h, "hp", 150.0) <= 0.0:
                    hazards_to_remove.append(h)

        for h in hazards_to_remove:
            if h in world.arena.hazards:
                world.arena.hazards.remove(h)

            # Explode
            if hasattr(world, "add_event"):
                world.add_event("visual_effect", {"type": "singularity_bomb_explosion", "x": h.x, "y": h.y, "radius": 300.0})

            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                    import math
                    dx = b.x - h.x
                    dy = b.y - h.y
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist <= 300.0:
                        damage = 100.0 * (1.0 - dist / 300.0)
                        b.hp = getattr(b, "hp", 100.0) - damage
                        if b.hp <= 0:
                            b.hp = 0
                            b.alive = False
                            b.killer = "singularity_bomb"

                        if dist > 0.0001:
                            nx = dx / dist
                            ny = dy / dist
                            knockback = 500.0 * (1.0 - dist / 300.0)
                            b.vx = getattr(b, "vx", 0.0) + nx * knockback
                            b.vy = getattr(b, "vy", 0.0) + ny * knockback



class GravityInversionMode(GameMode):
    def __init__(self):
        super().__init__()
        self.id = "Gravity Inversion"
        self.name = "Gravity Inversion"
        self.description = "Periodically, gravity flips, pulling players to the walls instead of the ground or sending them flying."
        self.inversion_timer = 0.0
        self.inversion_duration = 0.0
        self.inversion_strength = 300.0

    def setup(self, world: 'Any', balls: 'List[Any]'):
        super().setup(world, balls)
        self.inversion_timer = getattr(self, "random", __import__("random")).uniform(10.0, 20.0)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        if self.inversion_duration > 0:
            self.inversion_duration -= delta

            for b in balls:
                if not getattr(b, 'alive', True) or not getattr(b, 'active', True): continue
                if getattr(b, 'ball_type', None) == 'spectator': continue

                # Push outwards from center (simulating pulling to walls)
                arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
                arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
                cx, cy = arena_width / 2.0, arena_height / 2.0

                dx = b.x - cx
                dy = b.y - cy
                dist = (dx**2 + dy**2)**0.5
                if dist > 0:
                    # Give them some upwards lift as well to simulate "flying"
                    b.vx += (dx/dist) * self.inversion_strength * delta
                    b.vy += (dy/dist) * self.inversion_strength * delta
                    # Added lift to simulate flying to the ceiling if no walls
                    b.vy -= self.inversion_strength * 0.5 * delta
        else:
            self.inversion_timer -= delta
            if self.inversion_timer <= 0:
                self.inversion_duration = getattr(self, "random", __import__("random")).uniform(4.0, 8.0)
                self.inversion_timer = getattr(self, "random", __import__("random")).uniform(15.0, 25.0)
                if hasattr(world, 'add_event'):
                    world.add_event("gravity_inversion", {"duration": self.inversion_duration})


class RandomGravityShiftMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Random Gravity Shift"
        self.description = "A mode where gravity periodically shifts in random directions."
        self.shift_timer = 0.0
        self.shift_interval = 15.0
        self.gravity_dir_x = 0.0
        self.gravity_dir_y = 1.0
        self.gravity_strength = 300.0
        import random
        self.random = random

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.apply_dynamic_traits(world, balls, delta)
        self.shift_timer -= delta
        if self.shift_timer <= 0:
            self.shift_timer = self.shift_interval
            import math
            angle = self.random.uniform(0, 2 * math.pi)
            self.gravity_dir_x = math.cos(angle)
            self.gravity_dir_y = math.sin(angle)
            if hasattr(world, 'add_event'):
                world.add_event("gravity_shift", {"message": "Gravity shifted!"})

        for b in balls:
            if not getattr(b, 'alive', True) or not getattr(b, 'active', True):
                continue
            if getattr(b, 'ball_type', None) == 'spectator':
                continue

            mass = getattr(b, 'mass', 1.0)
            gravity_mult = -1.0 if getattr(b, "in_reverse_physics_zone", False) else 1.0

            # Lower mass is affected more strongly.
            mass_effect = 1.0 / max(mass, 0.1)

            is_juggernaut = getattr(b, 'ball_type', None) == 'juggernaut' or getattr(b, 'juggernaut_booster_timer', 0.0) > 0 or mass >= 2.0
            if is_juggernaut:
                mass_effect *= 0.5  # more resistant
                if hasattr(b, 'stamina'):
                    b.stamina = max(0.0, b.stamina - 40.0 * delta)

            if hasattr(b, 'vx'):
                b.vx += self.gravity_strength * self.gravity_dir_x * mass_effect * delta * gravity_mult
            if hasattr(b, 'vy'):
                b.vy += self.gravity_strength * self.gravity_dir_y * mass_effect * delta * gravity_mult

        if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
            for h in world.arena.hazards:
                mass = getattr(h, 'mass', 1.0)
                if hasattr(h, 'vx'):
                    h.vx += self.gravity_strength * self.gravity_dir_x * mass * delta
                if hasattr(h, 'vy'):
                    h.vy += self.gravity_strength * self.gravity_dir_y * mass * delta

class VulnerabilitySafeZoneMode(SafeZoneMode):
    def __init__(self):
        super().__init__()
        self.name = "Vulnerability Safe Zone"
        self.description = "The safe zone shrinks as usual, but instead of straight damage, balls outside the zone take increasing damage multipliers from all sources based on how far out they are."

    def tick(self, world, balls, delta=0.016):
        import math
        import random

        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        for b in balls:
            w_timer = getattr(b, 'weather_immunity_timer', 0.0)
            is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
            if not getattr(b, "alive", False):
                if b not in world.dead_balls:
                    b.time_since_death = 0.0
                    world.dead_balls.append(b)
                else:
                    b.time_since_death = getattr(b, "time_since_death", 0.0) + delta

        # Move the safe zone
        dx = self.zone_target_x - self.zone_x
        dy = self.zone_target_y - self.zone_y
        dist = math.sqrt(dx*dx + dy*dy)
        if dist > 5.0:
            move_speed = 15.0 # pixels per second
            self.zone_x += (dx / dist) * move_speed * delta
            self.zone_y += (dy / dist) * move_speed * delta
        else:
            arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
            arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
            buffer = max(100.0, self.zone_radius * 0.5)
            self.zone_target_x = random.uniform(buffer, arena_width - buffer)
            self.zone_target_y = random.uniform(buffer, arena_height - buffer)

        paused_this_tick = self.shrink_pause_timer > 0
        if self.shrink_pause_timer > 0:
            self.shrink_pause_timer -= delta
            if self.shrink_pause_timer < 0:
                self.shrink_pause_timer = 0.0

        players_in_zone = 0
        for b in balls:
            w_timer = getattr(b, 'weather_immunity_timer', 0.0)
            is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
            if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                dx_b = b.x - self.zone_x
                dy_b = b.y - self.zone_y
                dist_b = math.sqrt(dx_b*dx_b + dy_b*dy_b)
                if dist_b <= self.zone_radius:
                    players_in_zone += 1

        shrink_multiplier = max(1.0, float(players_in_zone))

        # Shrink the safe zone
        if not paused_this_tick and self.zone_radius > self.min_zone_radius:
            self.zone_radius -= self.shrink_rate * shrink_multiplier * delta
            if self.zone_radius <= self.min_zone_radius:
                self.zone_radius = self.min_zone_radius
                if not self.collapse_triggered:
                    self.collapse_triggered = True
                    if hasattr(world, "add_event"):
                        world.add_event("collapse_event", {"type": "collapse_event", "message": "COLLAPSE EVENT! The zone collapses!"})
        elif getattr(self, "collapse_triggered", False):
            if not paused_this_tick and self.zone_radius > 0:
                self.zone_radius -= self.shrink_rate * shrink_multiplier * delta
                if self.zone_radius < 0:
                    self.zone_radius = 0.0

            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                    dx = self.zone_x - b.x
                    dy = self.zone_y - b.y
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist > 0:
                        pull_strength = 2000.0
                        if not hasattr(b, "vx"): b.vx = 0.0
                        if not hasattr(b, "vy"): b.vy = 0.0
                        b.vx += (dx / dist) * pull_strength * delta
                        b.vy += (dy / dist) * pull_strength * delta

        # Apply vulnerability multiplier instead of flat damage
        for b in balls:
            w_timer = getattr(b, 'weather_immunity_timer', 0.0)
            is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
            if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                dx = b.x - self.zone_x
                dy = b.y - self.zone_y
                distance_to_center = math.sqrt(dx*dx + dy*dy)

                if distance_to_center > self.zone_radius:
                    # Apply significant speed penalty for being outside safe zone
                    b.slow_timer = max(getattr(b, "slow_timer", 0.0), 0.5)
                    # Calculate multiplier based on how far outside they are
                    extra_dist = distance_to_center - self.zone_radius
                    multiplier = 1.0 + (extra_dist / 100.0)
                    if getattr(self, 'collapse_triggered', False):
                        multiplier *= 2.0
                    b.vulnerability_multiplier = multiplier

                    if not getattr(b, "invisible_to_minimap", False):
                        ping_timer = getattr(b, "minimap_ping_timer", 0.0)
                        if ping_timer <= 1e-5:
                            if hasattr(world, "add_event"):
                                world.add_event("minimap_ping", {"x": b.x, "y": b.y, "color": "orange", "duration": 0.5})
                            b.minimap_ping_timer = 1.0
                        else:
                            b.minimap_ping_timer = ping_timer - delta
                else:
                    b.vulnerability_multiplier = 1.0


class ContinuousShrinkSafeZoneMode(SafeZoneMode):
    def __init__(self):
        super().__init__()
        self.name = "Continuous Shrink Safe Zone"
        self.description = "A game mode where the safe area continuously shrinks over time, forcing players into closer proximity and increasing the frequency of encounters."
        self.shrink_rate = 15.0

    def tick(self, world, balls, delta=0.016):
        self.shrink_pause_timer = 0.0
        super().tick(world, balls, delta)

class ReverseTimePenaltyMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Reverse Time Penalty"
        self.description = "Every 60 seconds, all balls are forcefully rewound to their positions 10 seconds ago. However, their health and cooldowns remain at current levels, leading to unpredictable resets and repositioning plays."
        self.timer = 0.0
        self.history = {}

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        self.timer += delta

        # Record position history
        for b in balls:
            if getattr(b, "ball_type", None) == "spectator":
                continue
            b_id = getattr(b, "id", id(b))
            if b_id not in self.history:
                self.history[b_id] = []

            # Save (timestamp, x, y)
            self.history[b_id].append((self.timer, b.x, b.y))

            # Prune history older than 10 seconds
            while self.history[b_id] and self.timer - self.history[b_id][0][0] > 10.0:
                self.history[b_id].pop(0)

        if self.timer >= 60.0:
            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                    continue
                b_id = getattr(b, "id", id(b))
                if b_id in self.history and len(self.history[b_id]) > 0:
                    # Rewind to oldest recorded state (around 10s ago)
                    oldest_state = self.history[b_id][0]
                    b.x = oldest_state[1]
                    b.y = oldest_state[2]

            # Reset timer and history
            self.timer = 0.0
            self.history = {}




class ExponentialControlPointMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Exponential Control Point"
        self.description = "A single control point grants increasing global buffs to the controlling player's faction, but they take exponentially more damage the longer they hold it."
        self.control_point = {"x": 500, "y": 500, "radius": 150, "owner": None, "capture_progress": 0.0}
        self.hold_time = 0.0

    def apply_dynamic_traits(self, world, balls, delta):
        # Update control point logic
        occupants = []
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", "") == "spectator":
                continue
            bx = getattr(b, "x", 0.0)
            by = getattr(b, "y", 0.0)
            br = getattr(b, "radius", 20.0)
            dx = bx - self.control_point["x"]
            dy = by - self.control_point["y"]
            if dx*dx + dy*dy <= (self.control_point["radius"] + br)**2:
                occupants.append(b)

        if not occupants:
            if self.control_point["capture_progress"] > 0 and self.control_point["owner"] is None:
                self.control_point["capture_progress"] = max(0.0, self.control_point["capture_progress"] - delta * 10.0)
        else:
            first_occupant_team = getattr(occupants[0], "team", getattr(occupants[0], "ball_type", "unknown"))
            same_team = all(getattr(b, "team", getattr(b, "ball_type", "unknown")) == first_occupant_team for b in occupants)

            if same_team:
                if self.control_point["owner"] != first_occupant_team:
                    if self.control_point["owner"] is not None:
                        # Contested by another team
                        self.control_point["capture_progress"] -= delta * 10.0
                        if self.control_point["capture_progress"] <= 0:
                            self.control_point["owner"] = None
                            self.control_point["capture_progress"] = 0
                            self.hold_time = 0.0
                    else:
                        self.control_point["capture_progress"] += delta * 10.0
                        if self.control_point["capture_progress"] >= 100.0:
                            self.control_point["capture_progress"] = 100.0
                            self.control_point["owner"] = first_occupant_team
                            self.hold_time = 0.0
                            if hasattr(world, "add_event"):
                                world.add_event("zone_captured", {"team": first_occupant_team})
            else:
                # Contested by multiple teams
                pass

        # Apply effects
        if self.control_point["owner"] is not None:
            self.hold_time += delta
            exponential_damage = (1.5 ** self.hold_time) * delta
            multiplier_buff = 1.0 + (0.1 * self.hold_time)

            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                    b_team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                    if b_team == self.control_point["owner"]:
                        b.hp -= exponential_damage
                        b.speed_multiplier = getattr(b, "speed_multiplier", 1.0) * multiplier_buff
                        b.damage_multiplier = getattr(b, "damage_multiplier", 1.0) * multiplier_buff


