        for b in balls:
            if getattr(b, "alive", False):
                b.hp = getattr(b, "hp", 100.0) - drain_amount
                if b.hp <= 0:
                    b.hp = 0
                    b.alive = False
                    if hasattr(world, "add_event"):
                        world.add_event("death", {"id": getattr(b, "id", None), "reason": "vampiric_drain"})

