class FrostbiteMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Frostbite"
        self.description = "Players must keep moving or stay near heat vents to avoid freezing to death."
        self.heat_vents = []
        self.vent_spawn_timer = 0.0
        self.vent_spawn_interval = 5.0
        self.vent_duration = 10.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        self.heat_vents = []
        self.vent_spawn_timer = 0.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random

        arena_w = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_h = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        self.vent_spawn_timer += delta
        if self.vent_spawn_timer >= self.vent_spawn_interval:
            self.vent_spawn_timer = 0.0
            self.heat_vents.append({
                "x": random.uniform(100, arena_w - 100),
                "y": random.uniform(100, arena_h - 100),
                "radius": 150.0,
                "timer": self.vent_duration
            })

        active_vents = []
        for vent in self.heat_vents:
            vent["timer"] -= delta
            if vent["timer"] > 0:
                active_vents.append(vent)
        self.heat_vents = active_vents

        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            near_vent = False
            bx = getattr(b, "x", 0.0)
            by = getattr(b, "y", 0.0)
            for vent in self.heat_vents:
                dist_sq = (bx - vent["x"])**2 + (by - vent["y"])**2
                if dist_sq <= vent["radius"]**2:
                    near_vent = True
                    break

            vx = getattr(b, "vx", 0.0)
            vy = getattr(b, "vy", 0.0)
            speed = (vx**2 + vy**2)**0.5

            frostbite_stack = getattr(b, "frostbite_stack", 0.0)

            if near_vent:
                frostbite_stack = max(0.0, frostbite_stack - 20.0 * delta)
            elif speed < 50.0:
                frostbite_stack = min(100.0, frostbite_stack + 10.0 * delta)
            else:
                frostbite_stack = max(0.0, frostbite_stack - 5.0 * delta)

            b.frostbite_stack = frostbite_stack

            base_speed = getattr(b, "base_speed", getattr(b, "speed", 100.0))
            if frostbite_stack > 50.0:
                # Apply speed debuff and damage
                b.speed_debuff_timer = max(getattr(b, "speed_debuff_timer", 0.0), 0.1)
                b.speed_debuff_multiplier = min(getattr(b, "speed_debuff_multiplier", 1.0), max(0.2, 1.0 - (frostbite_stack - 50.0) / 50.0 * 0.8))

                if frostbite_stack >= 100.0:
                    b.hp -= 5.0 * delta
                    if b.hp <= 0:
                        b.alive = False




class CurrencyBountyMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Currency Bounty"
        self.description = "Whenever a ball hits a certain currency threshold, a bounty is placed on them and other balls gain bonus stats when moving towards them."
        self.currency_spawn_timer = 0.0

    def setup(self, world: Any, balls: List[Any]) -> None:
        super().setup(world, balls)
        if getattr(world, "currency_pickups", None) is None:
            world.currency_pickups = []

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        import random
        # Initial currency
        for _ in range(15):
            world.currency_pickups.append({
                "x": random.uniform(50, arena_width - 50),
                "y": random.uniform(50, arena_height - 50),
                "type": "currency"
            })

        for b in balls:
            if getattr(b, "ball_type", None) != "spectator":
                b.currency = getattr(b, "currency", 0)

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random
        import math

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        self.currency_spawn_timer += delta
        if self.currency_spawn_timer >= 1.5:
            self.currency_spawn_timer = 0.0
            if len(world.currency_pickups) < 40:
                world.currency_pickups.append({
                    "x": random.uniform(50, arena_width - 50),
                    "y": random.uniform(50, arena_height - 50),
                    "type": "currency"
                })

        bounty_target = None
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            if not hasattr(b, "base_speed"):
                b.base_speed = getattr(b, "speed", 100.0)
            if not hasattr(b, "base_damage"):
                b.base_damage = getattr(b, "damage", 10.0)

            # Reset stats to base first
            b.speed = b.base_speed
            b.damage = b.base_damage

            # Collect currency
            pickups_to_remove = []
            for c in world.currency_pickups:
                dx = b.x - c["x"]
                dy = b.y - c["y"]
                dist = math.sqrt(dx*dx + dy*dy)
                if dist <= getattr(b, "radius", 15.0) + 15.0:
                    b.currency = getattr(b, "currency", 0) + 1
                    pickups_to_remove.append(c)

            for c in pickups_to_remove:
                if c in world.currency_pickups:
                    world.currency_pickups.remove(c)

            if getattr(b, "currency", 0) >= 10:
                bounty_target = b

        if bounty_target:
            if int(getattr(world, "tick", 0)) % 30 == 0:
                if hasattr(world, "add_event"):
                    world.add_event("bounty_compass", {"target_x": float(bounty_target.x), "target_y": float(bounty_target.y), "owner_id": getattr(bounty_target, "id", None)})
                elif hasattr(world, "events"):
                    world.events.append({"type": "bounty_compass", "data": {"target_x": float(bounty_target.x), "target_y": float(bounty_target.y), "owner_id": getattr(bounty_target, "id", None)}})

            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator" or b == bounty_target:
                    continue

                dx = bounty_target.x - b.x
                dy = bounty_target.y - b.y
                dist = math.sqrt(dx*dx + dy*dy)

                vx = getattr(b, "vx", 0.0)
                vy = getattr(b, "vy", 0.0)
                v_mag = math.sqrt(vx*vx + vy*vy)

                if dist > 0 and v_mag > 0:
                    dot_product = (dx * vx + dy * vy) / (dist * v_mag)
                    # If moving generally towards the target
                    if dot_product > 0.5:
                        b.speed = getattr(b, "base_speed", 100.0) * 1.5
                        b.damage = getattr(b, "base_damage", 10.0) * 1.5



class IrradiationSurvivalMode(GameMode):
    def __init__(self):
        super().__init__()
        self.irradiation_zones = []
        self.zone_timer = 0.0
        self.booster_timer = 0.0

    def setup(self, world: Any, balls: List[Any]) -> None:
        super().setup(world, balls)
        self.irradiation_zones = []
        self.zone_timer = 5.0
        self.booster_timer = 10.0

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        import random
        import math

        class Hazard:
            def __init__(self, id, x, y, radius, kind, damage):
                self.id = id
                self.x = x
                self.y = y
                self.radius = radius
                self.kind = kind
                self.damage = damage
                self.active = True

        self.zone_timer -= delta
        if self.zone_timer <= 0:
            self.zone_timer = random.uniform(8.0, 15.0)
            x = random.uniform(50, 950)
            y = random.uniform(50, 950)
            z_id = world.next_id() if callable(getattr(world, "next_id", None)) else (world.next_id if isinstance(getattr(world, "next_id", None), int) else random.randint(100000, 999999))
            zone = {
                'id': z_id,
                'x': x,
                'y': y,
                'radius': 30.0,
                'kind': 'irradiation_zone',
                'active': True
            }
            if not hasattr(self, "irradiation_zones"):
                self.irradiation_zones = []
            self.irradiation_zones.append(zone)

        self.booster_timer -= delta
        if self.booster_timer <= 0:
            self.booster_timer = random.uniform(10.0, 20.0)
            if hasattr(world, 'boosters') and hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
                b_id = world.next_id() if callable(getattr(world, "next_id", None)) else (world.next_id if isinstance(getattr(world, "next_id", None), int) else random.randint(100000, 999999))
                booster = Hazard(b_id, random.uniform(50, 950), random.uniform(50, 950), 15.0, 'anti_radiation_booster', 0.0)
                world.boosters.append(booster)
                world.arena.hazards.append(booster)

        if not hasattr(self, "irradiation_zones"):
            self.irradiation_zones = []

        for z in self.irradiation_zones:
            if not z.get('active', True):
                continue
            z['radius'] = min(250.0, z['radius'] + 4.0 * delta)

            for b in balls:
                if not getattr(b, 'alive', True) or getattr(b, 'ball_type', '') == 'spectator':
                    continue
                dx = getattr(b, 'x', 0) - z['x']
                dy = getattr(b, 'y', 0) - z['y']
                dist = math.hypot(dx, dy)
                if dist < z['radius'] + getattr(b, 'radius', 15.0):
                    b.mutation_level = getattr(b, 'mutation_level', 0.0) + 1.0 * delta
                    b.max_stamina = max(20.0, getattr(b, 'max_stamina', 100.0) - 2.0 * delta)
                    if getattr(b, 'mutation_level', 0.0) > 5.0:
                        b.mutant = True


class CursedRelicsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Cursed Relics"
        self.description = "Scattered across the map are cursed relics that, when picked up, provide huge temporary stat buffs (like double damage) but drain the ball's health continually over time. A ball can drop the relic by bumping into another ball, passing the curse along in a deadly game of hot potato."

    def setup(self, world, balls):
        super().setup(world, balls)
        if not hasattr(world, "arena") or not hasattr(world.arena, "hazards"):
            return

        arena_w = getattr(world.arena, "width", 2000.0)
        arena_h = getattr(world.arena, "height", 2000.0)

        import random
        from arena.procedural_arena import Hazard

        for _ in range(5):
            x = random.uniform(100.0, arena_w - 100.0)
            y = random.uniform(100.0, arena_h - 100.0)
            relic = Hazard(len(world.arena.hazards) + 50000 + random.randint(1, 9999), x, y, 25.0, "cursed_relic", 0.0)
            setattr(relic, "attached_id", None)
            setattr(relic, "transfer_cooldown", 0.0)
            world.arena.hazards.append(relic)

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        for b in balls:
            if hasattr(b, "base_damage_cursed"):
                b.damage = b.base_damage_cursed
                delattr(b, "base_damage_cursed")

        if not hasattr(world, "arena") or not hasattr(world.arena, "hazards"):
            return

        import math

        for hazard in world.arena.hazards:
            if getattr(hazard, "kind", "") == "cursed_relic":
                if hasattr(hazard, "transfer_cooldown"):
                    hazard.transfer_cooldown -= delta
                    if hazard.transfer_cooldown < 0.0:
                        hazard.transfer_cooldown = 0.0
                else:
                    hazard.transfer_cooldown = 0.0

                attached_id = getattr(hazard, "attached_id", None)
                if attached_id is not None:
                    owner = next((b for b in balls if getattr(b, "id", None) == attached_id), None)
                    if owner and getattr(owner, "alive", True):
                        hazard.x = owner.x
                        hazard.y = owner.y

                        if not hasattr(owner, "base_damage_cursed"):
                            owner.base_damage_cursed = getattr(owner, "damage", 10.0)

                        owner.damage = owner.base_damage_cursed * 2.0

                        if hasattr(owner, "hp"):
                            owner.hp -= 15.0 * delta

                        if hazard.transfer_cooldown <= 0.0:
                            owner_r = getattr(owner, "radius", 20.0)
                            for other in balls:
                                if other.id != owner.id and getattr(other, "alive", True):
                                    dx = other.x - owner.x
                                    dy = other.y - owner.y
                                    dist = math.hypot(dx, dy)
                                    other_r = getattr(other, "radius", 20.0)
                                    if dist < owner_r + other_r + 2.0:
                                        hazard.attached_id = other.id
                                        hazard.transfer_cooldown = 1.0

                                        owner.damage = owner.base_damage_cursed
                                        delattr(owner, "base_damage_cursed")
                                        break
                    else:
                        hazard.attached_id = None
                        hazard.transfer_cooldown = 1.0
                else:
                    h_r = getattr(hazard, "radius", 25.0)
                    for b in balls:
                        if getattr(b, "alive", True):
                            dx = b.x - hazard.x
                            dy = b.y - hazard.y
                            dist = math.hypot(dx, dy)
                            b_r = getattr(b, "radius", 20.0)
                            if dist < b_r + h_r:
                                hazard.attached_id = b.id
                                hazard.transfer_cooldown = 1.0
                                break

class WeatherAltarsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Weather Altars"
        self.description = "Special altars that only appear during specific weather conditions. They offer extremely rare and powerful items, but purchasing them permanently reduces a player's max health or base speed for the rest of the match."
        self.altars = []

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random, math

        current_weather = getattr(world.arena, "weather", "clear") if hasattr(world, "arena") else "clear"
        intense_weathers = ["thunderstorm", "blizzard", "hurricane", "storm", "heatwave", "sandstorm", "heavy_rain"]

        if current_weather in intense_weathers:
            if not self.altars:
                # spawn an altar
                arena_w = getattr(world.arena, "width", 1000) if hasattr(world, "arena") else 1000
                arena_h = getattr(world.arena, "height", 1000) if hasattr(world, "arena") else 1000
                self.altars.append({
                    "x": random.uniform(100, arena_w - 100),
                    "y": random.uniform(100, arena_h - 100),
                    "radius": 100.0,
                    "purchases": {},
                    "purchased_by": set()
                })
        else:
            self.altars.clear()

        # Process altars
        for altar in self.altars:
            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "ball_type", "") == "spectator":
                    continue

                bid = getattr(b, "id", None)
                if bid is None or bid in altar["purchased_by"]:
                    continue

                dx = getattr(b, "x", 0) - altar["x"]
                dy = getattr(b, "y", 0) - altar["y"]
                dist = math.sqrt(dx*dx + dy*dy)

                if dist < altar["radius"]:
                    altar["purchases"][bid] = altar["purchases"].get(bid, 0.0) + delta
                    if altar["purchases"][bid] >= 2.0:
                        altar["purchased_by"].add(bid)

                        if random.choice([True, False]):
                            b.max_hp = max(10.0, getattr(b, "max_hp", 100.0) - 30.0)
                            b.hp = min(getattr(b, "hp", 100.0), b.max_hp)
                            penalty = "Max HP Reduced"
                        else:
                            b.base_speed = max(20.0, getattr(b, "base_speed", 100.0) - 30.0)
                            if hasattr(b, "speed"):
                                b.speed = min(b.speed, b.base_speed)
                            penalty = "Base Speed Reduced"

                        items = ["time_stop_booster", "death_defy_booster", "invulnerability_booster", "quantum_relay_booster", "chronosphere_booster", "overclock_booster"]
                        chosen_item = random.choice(items)
                        if not hasattr(b, "inventory"):
                            b.inventory = []
                        b.inventory.append(chosen_item)

                        if hasattr(world, "add_event"):
                            world.add_event("weather_altar_purchase", {"ball_id": bid, "item": chosen_item, "penalty": penalty})
                else:
                    if bid in altar["purchases"]:
                        altar["purchases"][bid] = max(0.0, altar["purchases"][bid] - delta)


class DeepFreezeMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Deep Freeze Mutator"
        self.description = "The arena slowly freezes! Ice patches expand continuously. Stay near thermal vents to thaw your movement speed penalty, or take gradual freezing damage."
        self.ice_expansion_rate = 10.0
        self.freeze_damage_rate = 5.0
        self.max_speed_penalty = 0.5
        self.thaw_rate = 5.0 # Time to fully thaw
        self.freeze_rate = 15.0 # Time to fully freeze

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)

        # Initialize freeze level for balls
        for b in balls:
            b.freeze_level = 0.0

        # Spawn some initial ice patches and thermal vents
        if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
            import random

            # Find an unused ID range
            max_id = 80000
            for h in world.arena.hazards:
                if hasattr(h, 'id') and h.id > max_id:
                    max_id = h.id

            # Add thermal vents
            for i in range(5):
                vent_id = max_id + i + 1
                x = random.uniform(100, world.arena.width - 100)
                y = random.uniform(100, world.arena.height - 100)

                # Check for Hazard definition
                from arena.procedural_arena import Hazard
                vent = Hazard(id=vent_id, x=x, y=y, radius=150.0, kind="thermal_vent", damage=0.0)
                world.arena.hazards.append(vent)

            # Add ice patches
            for i in range(5):
                ice_id = max_id + i + 6
                x = random.uniform(100, world.arena.width - 100)
                y = random.uniform(100, world.arena.height - 100)

                from arena.procedural_arena import Hazard
                ice = Hazard(id=ice_id, x=x, y=y, radius=50.0, kind="ice_patches", damage=0.0)
                world.arena.hazards.append(ice)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        import math

        # Expand ice patches
        if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
            for h in world.arena.hazards:
                if getattr(h, 'kind', '') == 'ice_patches' or getattr(h, 'kind', '') == 'ice_patch':
                    h.radius = getattr(h, 'radius', 30.0) + self.ice_expansion_rate * delta
                    if h.radius > 800.0:
                        h.radius = 800.0 # Cap radius

        for b in balls:
            if not getattr(b, 'alive', False):
                continue

            bx = getattr(b, 'x', 0)
            by = getattr(b, 'y', 0)
            brad = getattr(b, 'radius', 0)

            # Check proximity to thermal vents
            near_vent = False
            if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
                for h in world.arena.hazards:
                    if getattr(h, 'kind', '') == 'thermal_vent':
                        hx = getattr(h, 'x', 0)
                        hy = getattr(h, 'y', 0)
                        hrad = getattr(h, 'radius', 0)

                        dist_sq = (bx - hx)**2 + (by - hy)**2
                        if dist_sq <= (hrad + brad)**2:
                            near_vent = True
                            break

            current_freeze = getattr(b, 'freeze_level', 0.0)

            if near_vent:
                # Thaw
                current_freeze -= (1.0 / self.thaw_rate) * delta
                if current_freeze < 0.0:
                    current_freeze = 0.0
            else:
                # Freeze
                current_freeze += (1.0 / self.freeze_rate) * delta
                if current_freeze > 1.0:
                    current_freeze = 1.0

            b.freeze_level = current_freeze

            # Apply speed penalty and damage
            if current_freeze > 0:
                # Avoid overriding speed if it's 0 (e.g., from other stuns/freezes)
                # Check if it's a mock object first to prevent MagicMock comparison issues
                try:
                    is_mock_speed = b.speed.__class__.__name__ == 'MagicMock'
                except:
                    is_mock_speed = False

                if not is_mock_speed:
                    current_speed = getattr(b, 'speed', None)
                    if current_speed is not None and current_speed > 0:
                        speed_mult = 1.0 - (current_freeze * self.max_speed_penalty)
                        try:
                            base_speed = getattr(b, 'base_speed', 100.0)
                            if base_speed.__class__.__name__ != 'MagicMock':
                                b.speed = base_speed * speed_mult
                        except:
                            pass

                if current_freeze >= 1.0:
                    # Take freeze damage
                    if hasattr(b, 'hp'):
                        b.hp -= self.freeze_damage_rate * delta
                        if b.hp <= 0:
                            b.hp = 0
                            b.alive = False
                            if hasattr(world, 'add_event'):
                                world.add_event('death', {'id': getattr(b, 'id', None), 'reason': 'frozen'})


