class RollingBouldersMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Rolling Boulders"
        self.description = "Periodically spawn massive boulders that roll linearly across the arena, crushing balls and shattering into rocks upon hitting boundaries."
        self.spawn_timer = 0.0

    def apply_dynamic_traits(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        for b in balls:
            sb_timer = getattr(b, "soul_boost_timer", 0.0)
            if getattr(b, "alive", True) and isinstance(sb_timer, (int, float)) and sb_timer > 0:
                b.soul_boost_timer -= delta
                if b.soul_boost_timer <= 0:
                    b.soul_boost_timer = 0
                    if hasattr(b, "base_damage"):
                        b.damage = b.base_damage
                    if hasattr(b, "base_speed"):
                        b.speed = b.base_speed

        if getattr(world, "weekly_mutator", "") == "gravity_reversal" or getattr(world, "mutators_active", False) and "gravity_reversal" in getattr(world, "mutators", []) or getattr(self, "name", "") == "Gravity Reversal Mutator":
            timer = getattr(world, "gravity_reversal_timer", 0.0)
            if isinstance(timer, (int, float)):
                timer += delta
            else:
                timer = delta
            if timer > 10.0:
                timer -= 10.0
                current = getattr(world, "gravity_reversal_active", False)
                world.gravity_reversal_active = not current
                if hasattr(world, "add_event") and getattr(self, "name", "") == "Gravity Reversal Mutator":
                    msg = "Gravity Reversed!" if world.gravity_reversal_active else "Gravity Restored!"
                    world.add_event("gravity_reversal", {"message": msg, "reversed": world.gravity_reversal_active})
            world.gravity_reversal_timer = timer

        weather = getattr(self, "weather", "")
        if not weather and hasattr(world, "arena"):
            weather = getattr(world.arena, "weather", "")

        if hasattr(world, "boosters") and hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            for b in world.boosters:
                if not getattr(b, "mutated_env", None):
                    bx = b.get("x", 0) if isinstance(b, dict) else getattr(b, "x", 0)
                    by = b.get("y", 0) if isinstance(b, dict) else getattr(b, "y", 0)
                    for h in world.arena.hazards:
                        hk = h.get("kind", "") if isinstance(h, dict) else getattr(h, "kind", "")
                        if hk in ["mud_puddle", "quicksand", "lava", "flood_zone", "poison_cloud"]:
                            hx = h.get("x", 0) if isinstance(h, dict) else getattr(h, "x", 0)
                            hy = h.get("y", 0) if isinstance(h, dict) else getattr(h, "y", 0)
                            hr = h.get("radius", 0) if isinstance(h, dict) else getattr(h, "radius", 0)
                            dx = bx - hx
                            dy = by - hy
                            if dx*dx + dy*dy <= hr*hr:
                                if isinstance(b, dict):
                                    b["mutated_env"] = hk
                                else:
                                    setattr(b, "mutated_env", hk)
                                break

        arena_type = getattr(world.arena, "name", "unknown").lower() if hasattr(world, "arena") else "unknown"

        for b in balls:
            if not getattr(b, "alive", False):
                continue

            traits = getattr(b, "traits", [])
            b_type = getattr(b, "ball_type", "").lower()

            # Trait: Fire
            is_fire = "fire" in b_type or "fire" in traits
            if is_fire:
                if weather in ["heatwave", "lava"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    base_d = getattr(b, "base_damage", getattr(b, "damage", 10.0))
                    b.speed = base_s * 1.2
                    b.damage = base_d * 1.2
                elif weather in ["rain", "blizzard", "heavy_rain"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    base_d = getattr(b, "base_damage", getattr(b, "damage", 10.0))
                    b.speed = base_s * 0.8
                    b.damage = base_d * 0.8

            # Trait: Earth
            is_earth = "earth" in b_type or "rock" in b_type or "earth" in traits or "rock" in traits
            if is_earth:
                if weather == "sandstorm":
                    b.weather_immunity_timer = getattr(b, "weather_immunity_timer", 0.0) + delta * 2.0

                if "dirt" in arena_type or "earth" in arena_type:
                    b.defense_multiplier = 0.8

            # Trait: Wind
            is_wind = "wind" in b_type or "wind" in traits
            if is_wind:
                if weather in ["slight_breeze", "storm"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    b.speed = base_s * 1.2
                elif weather == "hurricane":
                    # Blown away by hurricane
                    b.x = getattr(b, "x", 0.0) + (100.0 * delta)
                    b.y = getattr(b, "y", 0.0) + (100.0 * delta)
                    b.defense_multiplier = getattr(b, "defense_multiplier", 1.0) * 1.5

            # Trait: Water
            is_water = "water" in b_type or "water" in traits
            if is_water:
                if weather in ["light_rain", "heavy_rain", "rain"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    b.speed = base_s * 1.1
                    b.hp = min(getattr(b, "max_hp", 100.0), getattr(b, "hp", 100.0) + (5.0 * delta))

            # Trait: Elementalist
            is_elemental = "elemental" in b_type or "elemental" in traits
            if is_elemental:
                if weather in ["sandstorm"]:
                    # Elementalist in sandstorm gains a passive shield/defense boost
                    b.defense_multiplier = getattr(b, "defense_multiplier", 1.0) * 0.7
                    b.speed = getattr(b, "base_speed", getattr(b, "speed", 100.0)) * 1.15

    def setup(self, world: Any, balls: List[Any]) -> None:
        super().setup(world, balls)
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []
        self.spawn_timer = 0.0

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random
        import math

        self.spawn_timer += delta

        arena_width = getattr(world.arena, "width", 1000)
        arena_height = getattr(world.arena, "height", 1000)

        try:
            from arena.procedural_arena import Hazard
        except ImportError:
            class Hazard:
                def __init__(self, id, x, y, radius, kind, damage):
                    self.id = id
                    self.x = x
                    self.y = y
                    self.radius = radius
                    self.kind = kind
                    self.damage = damage
                    self.active = True
                    self.target_radius = 0.0

        if self.spawn_timer >= 5.0:
            self.spawn_timer = 0.0

            side = random.choice(["top", "bottom", "left", "right"])

            x, y = 0.0, 0.0
            vx, vy = 0.0, 0.0
            speed = random.uniform(150.0, 250.0)

            if side == "top":
                x = random.uniform(100, arena_width - 100)
                y = 0.0
                vx = random.uniform(-50.0, 50.0)
                vy = speed
            elif side == "bottom":
                x = random.uniform(100, arena_width - 100)
                y = arena_height
                vx = random.uniform(-50.0, 50.0)
                vy = -speed
            elif side == "left":
                x = 0.0
                y = random.uniform(100, arena_height - 100)
                vx = speed
                vy = random.uniform(-50.0, 50.0)
            elif side == "right":
                x = arena_width
                y = random.uniform(100, arena_height - 100)
                vx = -speed
                vy = random.uniform(-50.0, 50.0)

            h_id = 30000 + len(world.arena.hazards) + random.randint(0, 10000)
            boulder = Hazard(id=h_id, x=x, y=y, radius=60.0, kind="rolling_boulder", damage=300.0)
            setattr(boulder, "vx", vx)
            setattr(boulder, "vy", vy)
            setattr(boulder, "duration", 20.0)  # Should hit a wall before expiring

            world.arena.hazards.append(boulder)

        hazards_to_remove = []
        new_hazards = []

        for h in getattr(world.arena, "hazards", []):
            if getattr(h, "kind", "") == "rolling_boulder":
                # Update position
                vx = getattr(h, "vx", 0.0)
                vy = getattr(h, "vy", 0.0)
                h.x += vx * delta
                h.y += vy * delta

                # Check ball collisions
                boulder_radius = getattr(h, "radius", 60.0)
                boulder_damage = getattr(h, "damage", 300.0)

                for b in balls:
                    if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                        ball_radius = getattr(b, "radius", 15.0)
                        dist_sq = (b.x - h.x)**2 + (b.y - h.y)**2
                        if dist_sq <= (boulder_radius + ball_radius)**2:
                            b.hp -= boulder_damage
                            if b.hp <= 0:
                                b.hp = 0
                                b.alive = False
                                b.killer = "rolling_boulder"

                # Check interactions with other hazards
                for other_h in getattr(world.arena, "hazards", []):
                    if other_h != h and getattr(other_h, "kind", "") in ["spikes", "trap", "pull_trap"]:
                        dist_sq = (h.x - other_h.x)**2 + (h.y - other_h.y)**2
                        if dist_sq <= (boulder_radius + getattr(other_h, "radius", 15.0))**2:
                            hazards_to_remove.append(other_h)

                # Check wall/bounds collisions
                hit_wall = False
                if h.x + boulder_radius < -50 or h.x - boulder_radius > arena_width + 50 or h.y + boulder_radius < -50 or h.y - boulder_radius > arena_height + 50:
                    hit_wall = True

                if not hit_wall and hasattr(world.arena, "walls"):
                    for wall in world.arena.walls:
                        # Simple AABB check vs circle
                        wx, wy, ww, wh = getattr(wall, "x", 0), getattr(wall, "y", 0), getattr(wall, "width", 0), getattr(wall, "height", 0)

                        test_x = h.x
                        test_y = h.y

                        if h.x < wx: test_x = wx
                        elif h.x > wx + ww: test_x = wx + ww

                        if h.y < wy: test_y = wy
                        elif h.y > wy + wh: test_y = wy + wh

                        dist_x = h.x - test_x
                        dist_y = h.y - test_y
                        if dist_x*dist_x + dist_y*dist_y <= boulder_radius*boulder_radius:
                            hit_wall = True
                            break

                if hit_wall:
                    hazards_to_remove.append(h)

                    # Shatter into rocks
                    for i in range(3):
                        rock_id = 40000 + len(world.arena.hazards) + len(new_hazards) + random.randint(0, 10000)
                        rock = Hazard(id=rock_id, x=h.x, y=h.y, radius=15.0, kind="rock", damage=30.0)
                        setattr(rock, "duration", 5.0)

                        import random
                        import math
                        angle = random.uniform(0, 2 * math.pi)
                        rock_speed = random.uniform(50.0, 150.0)
                        setattr(rock, "vx", math.cos(angle) * rock_speed)
                        setattr(rock, "vy", math.sin(angle) * rock_speed)

                        new_hazards.append(rock)

            elif getattr(h, "kind", "") == "rock":
                # Rocks also roll a bit
                vx = getattr(h, "vx", 0.0)
                vy = getattr(h, "vy", 0.0)
                if vx != 0.0 or vy != 0.0:
                    h.x += vx * delta
                    h.y += vy * delta
                    # Decelerate
                    setattr(h, "vx", vx * 0.95)
                    setattr(h, "vy", vy * 0.95)

                # Check ball collisions
                rock_radius = getattr(h, "radius", 15.0)
                rock_damage = getattr(h, "damage", 30.0)

                for b in balls:
                    if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                        ball_radius = getattr(b, "radius", 15.0)
                        dist_sq = (b.x - h.x)**2 + (b.y - h.y)**2
                        if dist_sq <= (rock_radius + ball_radius)**2:
                            b.hp -= rock_damage
                            if b.hp <= 0:
                                b.hp = 0
                                b.alive = False
                                b.killer = "rock"
                            if h not in hazards_to_remove:
                                hazards_to_remove.append(h)

        for h in hazards_to_remove:
            if h in world.arena.hazards:
                world.arena.hazards.remove(h)

        world.arena.hazards.extend(new_hazards)

class SoulLinkMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Soul Link"
        self.description = "Players are randomly paired. Damage and status effects taken by one are shared with the other."
        self.prev_state = {}
        self.status_effects = ["stun_timer", "burn_timer", "poison_timer", "blindness_timer", "confusion_timer", "slow_timer", "frozen_timer"]

    class BallState:
        def __init__(self, hp):
            self.hp = hp

    def _init_prev_state(self, b):
        state = self.BallState(getattr(b, "hp", 100.0))
        for eff in self.status_effects:
            setattr(state, eff, getattr(b, eff, 0.0))
        self.prev_state[b.id] = state

    def apply_dynamic_traits(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        for b in balls:
            sb_timer = getattr(b, "soul_boost_timer", 0.0)
            if getattr(b, "alive", True) and isinstance(sb_timer, (int, float)) and sb_timer > 0:
                b.soul_boost_timer -= delta
                if b.soul_boost_timer <= 0:
                    b.soul_boost_timer = 0
                    if hasattr(b, "base_damage"):
                        b.damage = b.base_damage
                    if hasattr(b, "base_speed"):
                        b.speed = b.base_speed

        if getattr(world, "weekly_mutator", "") == "gravity_reversal" or getattr(world, "mutators_active", False) and "gravity_reversal" in getattr(world, "mutators", []) or getattr(self, "name", "") == "Gravity Reversal Mutator":
            timer = getattr(world, "gravity_reversal_timer", 0.0)
            if isinstance(timer, (int, float)):
                timer += delta
            else:
                timer = delta
            if timer > 10.0:
                timer -= 10.0
                current = getattr(world, "gravity_reversal_active", False)
                world.gravity_reversal_active = not current
                if hasattr(world, "add_event") and getattr(self, "name", "") == "Gravity Reversal Mutator":
                    msg = "Gravity Reversed!" if world.gravity_reversal_active else "Gravity Restored!"
                    world.add_event("gravity_reversal", {"message": msg, "reversed": world.gravity_reversal_active})
            world.gravity_reversal_timer = timer

        weather = getattr(self, "weather", "")
        if not weather and hasattr(world, "arena"):
            weather = getattr(world.arena, "weather", "")

        if hasattr(world, "boosters") and hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            for b in world.boosters:
                if not getattr(b, "mutated_env", None):
                    bx = b.get("x", 0) if isinstance(b, dict) else getattr(b, "x", 0)
                    by = b.get("y", 0) if isinstance(b, dict) else getattr(b, "y", 0)
                    for h in world.arena.hazards:
                        hk = h.get("kind", "") if isinstance(h, dict) else getattr(h, "kind", "")
                        if hk in ["mud_puddle", "quicksand", "lava", "flood_zone", "poison_cloud"]:
                            hx = h.get("x", 0) if isinstance(h, dict) else getattr(h, "x", 0)
                            hy = h.get("y", 0) if isinstance(h, dict) else getattr(h, "y", 0)
                            hr = h.get("radius", 0) if isinstance(h, dict) else getattr(h, "radius", 0)
                            dx = bx - hx
                            dy = by - hy
                            if dx*dx + dy*dy <= hr*hr:
                                if isinstance(b, dict):
                                    b["mutated_env"] = hk
                                else:
                                    setattr(b, "mutated_env", hk)
                                break

        arena_type = getattr(world.arena, "name", "unknown").lower() if hasattr(world, "arena") else "unknown"

        for b in balls:
            if not getattr(b, "alive", False):
                continue

            traits = getattr(b, "traits", [])
            b_type = getattr(b, "ball_type", "").lower()

            # Trait: Fire
            is_fire = "fire" in b_type or "fire" in traits
            if is_fire:
                if weather in ["heatwave", "lava"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    base_d = getattr(b, "base_damage", getattr(b, "damage", 10.0))
                    b.speed = base_s * 1.2
                    b.damage = base_d * 1.2
                elif weather in ["rain", "blizzard", "heavy_rain"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    base_d = getattr(b, "base_damage", getattr(b, "damage", 10.0))
                    b.speed = base_s * 0.8
                    b.damage = base_d * 0.8

            # Trait: Earth
            is_earth = "earth" in b_type or "rock" in b_type or "earth" in traits or "rock" in traits
            if is_earth:
                if weather == "sandstorm":
                    b.weather_immunity_timer = getattr(b, "weather_immunity_timer", 0.0) + delta * 2.0

                if "dirt" in arena_type or "earth" in arena_type:
                    b.defense_multiplier = 0.8

            # Trait: Wind
            is_wind = "wind" in b_type or "wind" in traits
            if is_wind:
                if weather in ["slight_breeze", "storm"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    b.speed = base_s * 1.2
                elif weather == "hurricane":
                    # Blown away by hurricane
                    b.x = getattr(b, "x", 0.0) + (100.0 * delta)
                    b.y = getattr(b, "y", 0.0) + (100.0 * delta)
                    b.defense_multiplier = getattr(b, "defense_multiplier", 1.0) * 1.5

            # Trait: Water
            is_water = "water" in b_type or "water" in traits
            if is_water:
                if weather in ["light_rain", "heavy_rain", "rain"]:
                    base_s = getattr(b, "base_speed", getattr(b, "speed", 100.0))
                    b.speed = base_s * 1.1
                    b.hp = min(getattr(b, "max_hp", 100.0), getattr(b, "hp", 100.0) + (5.0 * delta))

            # Trait: Elementalist
            is_elemental = "elemental" in b_type or "elemental" in traits
            if is_elemental:
                if weather in ["sandstorm"]:
                    # Elementalist in sandstorm gains a passive shield/defense boost
                    b.defense_multiplier = getattr(b, "defense_multiplier", 1.0) * 0.7
                    b.speed = getattr(b, "base_speed", getattr(b, "speed", 100.0)) * 1.15

    def setup(self, world: Any, balls: List[Any]) -> None:
        super().setup(world, balls)
        self.swap_timer = 0.0
        import random
        alive_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator"]
        random.shuffle(alive_balls)

        for i in range(0, len(alive_balls) - 1, 2):
            b1 = alive_balls[i]
            b2 = alive_balls[i+1]
            b1.soul_link_target = b2
            b2.soul_link_target = b1

        if len(alive_balls) % 2 != 0:
            alive_balls[-1].soul_link_target = None

        self.prev_state = {}
        for b in balls:

            self._init_prev_state(b)

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        hp_diffs = {}
        eff_diffs = {}

        for b in balls:
            w_timer = getattr(b, 'weather_immunity_timer', 0.0)
            is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
            if not getattr(b, "alive", False):
                continue

            if getattr(b, "id", None) not in self.prev_state:
                self._init_prev_state(b)

            state = self.prev_state[b.id]

            curr_hp = getattr(b, "hp", 100.0)
            if curr_hp < state.hp:
                hp_diffs[b.id] = state.hp - curr_hp

            eff_diffs[b.id] = {}
            for eff in self.status_effects:
                prev_val = getattr(state, eff, 0.0)
                curr_val = getattr(b, eff, 0.0)
                if curr_val > prev_val:
                    eff_diffs[b.id][eff] = curr_val - prev_val

        for b in balls:
            if not getattr(b, "alive", False):
                continue

            target = getattr(b, "soul_link_target", None)
            if target and getattr(target, "alive", False):
                if b.id in hp_diffs:
                    damage = hp_diffs[b.id]
                    target_curr_hp = getattr(target, "hp", 100.0)
                    if target_curr_hp > 0:
                        target.hp = target_curr_hp - damage
                        if target.hp <= 0:
                            target.hp = 0
                            target.alive = False
                            target.killer = getattr(b, "killer", "soul_link")

                if b.id in eff_diffs:
                    for eff, diff in eff_diffs[b.id].items():
                        target_val = getattr(target, eff, 0.0)
                        setattr(target, eff, target_val + diff)

        for b in balls:
            if not getattr(b, "alive", False):
                continue
            if getattr(b, "id", None) in self.prev_state:
                state = self.prev_state[b.id]
                state.hp = getattr(b, "hp", 100.0)
                for eff in self.status_effects:
                    setattr(state, eff, getattr(b, eff, 0.0))


class AllianceTournamentMode(GameMode):
    """Two alliances (groups of partnered guilds) face off in a multi-round tournament. Winning yields unique cosmetics and high resource rewards shared among all allied guilds."""
    def __init__(self):
        super().__init__()
        self.name = "alliance_tournament"
        self.desc = "Multi-round alliance tournament between combined teams"
        self.alliances = {}
        self.alliance_clans = {}
        self.scores = {}
        self.current_round = 1
        self.max_wins_needed = 2  # Best of 3
        self.tournament_over = False
        self.winner_alliance = None
        self.survival_points = {"AllianceA": 0.0, "AllianceB": 0.0}
        self.elimination_points = {"AllianceA": 0, "AllianceB": 0}
        self.prev_alive = {}

    def setup(self, world, balls):
        super().setup(world, balls)
        self.world = world
        self.alliances = {}
        self.scores = {"AllianceA": 0, "AllianceB": 0}
        self.current_round = 1
        self.tournament_over = False
        self.winner_alliance = None
        self.survival_points = {"AllianceA": 0.0, "AllianceB": 0.0}
        self.elimination_points = {"AllianceA": 0, "AllianceB": 0}
        self.prev_alive = {}

        self.alliance_clans = {
            "AllianceA": ["Guild1", "Guild2"],
            "AllianceB": ["Guild3", "Guild4"]
        }

        if len(balls) >= 2:
            mid = len(balls) // 2
            alliance1_balls = balls[:mid]
            alliance2_balls = balls[mid:]
            self.alliances["AllianceA"] = [b.id for b in alliance1_balls]
            self.alliances["AllianceB"] = [b.id for b in alliance2_balls]

    def _tick(self, delta):
        if self.tournament_over:
            return

        alive_counts = {"AllianceA": 0, "AllianceB": 0}
        for alliance, members in self.alliances.items():
            for ball in self.world.balls:
                if ball.id in members:
                    is_alive = getattr(ball, "alive", False)
                    was_alive = self.prev_alive.get(ball.id, True)

                    if is_alive:
                        alive_counts[alliance] += 1
                        self.survival_points[alliance] += delta
                    elif was_alive and not is_alive:
                        # Ball died this tick
                        opp_alliance = "AllianceB" if alliance == "AllianceA" else "AllianceA"
                        self.elimination_points[opp_alliance] += 1

                    self.prev_alive[ball.id] = is_alive

        # Check if a round has ended
        round_winner = None
        if alive_counts["AllianceA"] > 0 and alive_counts["AllianceB"] == 0:
            round_winner = "AllianceA"
        elif alive_counts["AllianceB"] > 0 and alive_counts["AllianceA"] == 0:
            round_winner = "AllianceB"
        elif alive_counts["AllianceA"] == 0 and alive_counts["AllianceB"] == 0:
            round_winner = "Draw"

        if round_winner:
            if round_winner != "Draw":
                self.scores[round_winner] += 1

            if self.scores.get("AllianceA", 0) >= self.max_wins_needed:
                self._end_tournament("AllianceA")
            elif self.scores.get("AllianceB", 0) >= self.max_wins_needed:
                self._end_tournament("AllianceB")
            else:
                self.current_round += 1
                self._reset_round()

    def _reset_round(self):
        for ball in self.world.balls:
            ball.alive = True
            ball.hp = getattr(ball, "max_hp", 100.0)

    def _end_tournament(self, winner_alliance):
        self.tournament_over = True
        self.winner_alliance = winner_alliance
        try:
            from system.clan import ClanManager
            cm = ClanManager()
            total_points = 1000 + int(self.survival_points[winner_alliance] * 0.2) + (self.elimination_points[winner_alliance] * 100)
            winning_clans = self.alliance_clans.get(winner_alliance, [])
            for clan in winning_clans:
                if clan not in cm.data["clans"]:
                    cm.create_clan(clan, "system")
                cm.add_clan_points(clan, total_points)
                cm.unlock_cosmetic(clan, "Alliance_Champion_Aura")
                cm.unlock_cosmetic(clan, "Alliance_Victory_Banner")
                if "stash" not in cm.data["clans"][clan]:
                    cm.data["clans"][clan]["stash"] = {}
                cm.data["clans"][clan]["stash"]["alliance_tokens"] = cm.data["clans"][clan]["stash"].get("alliance_tokens", 0) + 50
            cm.save()
        except Exception:
            pass


