class RubberBandMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Rubber Band"
        self.description = "Teams are tethered by invisible rubber bands. If they move too far apart, they snap back together with massive force, dealing damage to anything in their path."
        self.max_distance = 300.0
        self.snap_force = 1500.0
        self.damage = 50.0

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import math
        import itertools

        teams = {}
        for b in balls:
            if not getattr(b, "alive", False):
                continue
            team = getattr(b, "team", None)
            if team is not None:
                if team not in teams:
                    teams[team] = []
                teams[team].append(b)

        for team, tballs in teams.items():
            if len(tballs) < 2:
                continue

            for b1, b2 in itertools.combinations(tballs, 2):
                dx = b2.x - b1.x
                dy = b2.y - b1.y
                dist = math.hypot(dx, dy)

                if dist > self.max_distance:
                    excess = dist - self.max_distance
                    # Add proportional snap force
                    pull = (excess / self.max_distance) * self.snap_force

                    nx = dx / dist
                    ny = dy / dist

                    # Apply velocity to pull them together
                    b1.vx = getattr(b1, "vx", 0.0) + nx * pull * delta
                    b1.vy = getattr(b1, "vy", 0.0) + ny * pull * delta

                    b2.vx = getattr(b2, "vx", 0.0) - nx * pull * delta
                    b2.vy = getattr(b2, "vy", 0.0) - ny * pull * delta

                    # Check for entities between them to deal damage
                    for other in balls:
                        if not getattr(other, "alive", False) or other == b1 or other == b2 or getattr(other, "team", None) == getattr(b1, "team", None):
                            continue

                        # Line segment check: b1 to b2
                        # Project other onto the line segment
                        px = other.x - b1.x
                        py = other.y - b1.y

                        dot = px * nx + py * ny

                        if 0 <= dot <= dist:
                            # Closest point on the segment
                            cx = b1.x + dot * nx
                            cy = b1.y + dot * ny

                            cdx = other.x - cx
                            cdy = other.y - cy
                            cdist = math.hypot(cdx, cdy)

                            radius = getattr(other, "radius", 15.0)

                            if cdist <= radius + 5.0:  # add a small buffer for the rubber band thickness
                                if hasattr(world, "_deal_damage"):
                                    # Deal damage. Use one of the team balls as the attacker for kill credit if needed
                                    world._deal_damage(b1, other, self.damage * delta * 60) # Scaled to frame rate
                                else:
                                    other.hp = getattr(other, "hp", 100.0) - self.damage * delta * 60

class TetheredRoyaleMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Tethered Royale"
        self.description = "Players are paired and permanently tethered. The tether limits distance but also deals damage to any other ball that passes through it. The chained players must coordinate to move, and they share damage taken but gain a unified health pool until the chain breaks."
        self.tethers = {}
        self.prev_alive = {}
        self.prev_hp = {}
        self.max_distance = 300.0
        self.pull_force = 800.0
        self.chain_damage = 25.0

    def setup(self, world, balls):
        super().setup(world, balls)
        import random
        alive_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator"]
        random.shuffle(alive_balls)

        self.tethers = {}
        self.prev_alive = {}
        self.prev_hp = {}

        for i in range(0, len(alive_balls) - 1, 2):
            b1 = alive_balls[i]
            b2 = alive_balls[i+1]
            b1.tether_target = b2
            b2.tether_target = b1
            self.tethers[b1.id] = b2
            self.tethers[b2.id] = b1

            # Unified health pool
            total_hp = getattr(b1, "hp", 100.0) + getattr(b2, "hp", 100.0)
            b1.max_hp = getattr(b1, "max_hp", 100.0) + getattr(b2, "max_hp", 100.0)
            b2.max_hp = b1.max_hp
            b1.hp = total_hp
            b2.hp = total_hp

        if len(alive_balls) % 2 != 0:
            alive_balls[-1].tether_target = None

        for b in balls:
            self.prev_alive[b.id] = getattr(b, "alive", False)
            self.prev_hp[b.id] = getattr(b, "hp", 100.0)

    def tick(self, world, balls, delta: float = 0.016):
        super().tick(world, balls, delta)
        import math

        processed_pairs = set()

        for b in balls:
            was_alive = self.prev_alive.get(b.id, False)
            is_alive = getattr(b, "alive", False)

            # Detect elimination
            if was_alive and not is_alive:
                # Trigger explosive recoil
                from arena.procedural_arena import Hazard
                h = Hazard(id="recoil_" + str(b.id), x=getattr(b, "x", 0.0), y=getattr(b, "y", 0.0), kind="recoil_explosion", radius=100.0, damage=50.0)
                h.duration = 0.2
                h.damage = 50.0
                if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                    world.arena.hazards.append(h)

                # Unlink partner
                target = getattr(b, "tether_target", None)
                if target:
                    target.tether_target = None
                    # Revert max hp
                    target.max_hp = getattr(target, "base_max_hp", 100.0)
                    target.hp = min(target.hp, target.max_hp)

            self.prev_alive[b.id] = is_alive

            if not is_alive:
                continue

            target = getattr(b, "tether_target", None)
            if target and getattr(target, "alive", False):
                pair_id = tuple(sorted([b.id, target.id]))
                if pair_id not in processed_pairs:
                    processed_pairs.add(pair_id)

                    # Sync HP correctly (sum of damage taken)
                    b_prev_hp = self.prev_hp.get(b.id, getattr(b, "hp", 100.0))
                    t_prev_hp = self.prev_hp.get(target.id, getattr(target, "hp", 100.0))

                    b_dmg = b_prev_hp - getattr(b, "hp", 100.0)
                    t_dmg = t_prev_hp - getattr(target, "hp", 100.0)
                    total_dmg = max(0.0, b_dmg) + max(0.0, t_dmg)

                    # Assume they share the same hp pool at the start of tick, so b_prev_hp == t_prev_hp ideally,
                    # but if there are small sync errors, we just take the max previous hp.
                    new_hp = max(b_prev_hp, t_prev_hp) - total_dmg

                    b.hp = new_hp
                    target.hp = new_hp

                    self.prev_hp[b.id] = new_hp
                    self.prev_hp[target.id] = new_hp

                    # Distance limit and pull
                    dx = target.x - b.x
                    dy = target.y - b.y
                    dist = math.hypot(dx, dy)

                    if dist > 0:
                        nx = dx / dist
                        ny = dy / dist

                        if dist > self.max_distance:
                            excess = dist - self.max_distance
                            pull = min((excess / 50.0) * self.pull_force, self.pull_force * 2.0)

                            b.vx = getattr(b, "vx", 0.0) + nx * pull * delta
                            b.vy = getattr(b, "vy", 0.0) + ny * pull * delta

                            target.vx = getattr(target, "vx", 0.0) - nx * pull * delta
                            target.vy = getattr(target, "vy", 0.0) - ny * pull * delta

                        # Check chain damage
                        for other in balls:
                            if not getattr(other, "alive", False) or other == b or other == target:
                                continue

                            # Project other onto the line segment
                            px = other.x - b.x
                            py = other.y - b.y
                            dot = px * nx + py * ny

                            if 0 <= dot <= dist:
                                cx = b.x + dot * nx
                                cy = b.y + dot * ny
                                cdx = other.x - cx
                                cdy = other.y - cy
                                cdist = math.hypot(cdx, cdy)

                                radius = getattr(other, "radius", 15.0)
                                if cdist <= radius + 5.0:
                                    if hasattr(world, "_deal_damage"):
                                        world._deal_damage(b, other, self.chain_damage * delta * 60)
                                    else:
                                        other.hp = getattr(other, "hp", 100.0) - self.chain_damage * delta * 60
            else:
                self.prev_hp[b.id] = getattr(b, "hp", 100.0)


GAME_MODES["tethered_royale"] = TetheredRoyaleMode()
