class OrbitalMinesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Orbital Mines"
        self.description = "Orbital mines constantly revolve around the center of the arena."
        self.id = "orbital_mines"
        self.orbit_speed = 1.0 # radians per second
        self.orbit_distance = 300.0

    def tick(self, world, balls, delta=0.016):
        import math
        import random
        super().tick(world, balls, delta)

        if not (hasattr(world, 'arena') and hasattr(world.arena, 'hazards')):
            return

        cx = getattr(world, 'width', 1000) / 2.0
        cy = getattr(world, 'height', 1000) / 2.0

        # Count existing orbital mines
        mines = [h for h in world.arena.hazards if getattr(h, 'kind', '') == 'orbital_mine']

        # Spawn mines if fewer than 5
        if len(mines) < 5:
            from arena.procedural_arena import Hazard
            num_to_spawn = 5 - len(mines)
            for _ in range(num_to_spawn):
                mine_id = len(world.arena.hazards) + random.randint(10000, 99999)
                mine = Hazard(mine_id, cx, cy, 20.0, "orbital_mine", 30.0)
                setattr(mine, 'active', True)
                setattr(mine, 'duration', 9999.0)
                setattr(mine, 'angle', random.uniform(0, 2 * math.pi))
                # Add random orbital distance offset per mine
                setattr(mine, 'orbit_dist', random.uniform(150.0, 450.0))
                # Randomize speed slightly per mine
                setattr(mine, 'speed_mult', random.choice([-1, 1]) * random.uniform(0.8, 1.5))
                world.arena.hazards.append(mine)
                mines.append(mine)

        # Update mine positions
        for m in mines:
            if getattr(m, 'active', True):
                ang = getattr(m, 'angle', 0.0)
                spd = self.orbit_speed * getattr(m, 'speed_mult', 1.0)
                ang += spd * delta
                setattr(m, 'angle', ang)

                dist = getattr(m, 'orbit_dist', self.orbit_distance)
                m.x = cx + math.cos(ang) * dist
                m.y = cy + math.sin(ang) * dist

GAME_MODES["orbital_mines"] = OrbitalMinesMode()

class PerfectReflectorHazardMode(GameMode):
    """
    A dynamic hazard that spawns and expands across the arena. Any projectile or moving entity
    that hits its boundary gets reflected perfectly but with 2x velocity and increased damage potential.
    """
    def __init__(self):
        super().__init__()
        self.name = "Perfect Reflector Hazard"
        self.description = "An expanding hazard that reflects balls and doubles their velocity upon hitting its boundary."
        self.hazard_x = 500.0
        self.hazard_y = 500.0
        self.hazard_radius = 10.0
        self.expansion_rate = 30.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        self.hazard_x = arena_width / 2.0
        self.hazard_y = arena_height / 2.0
        self.hazard_radius = 10.0

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            try:
                from arena.procedural_arena import Hazard
                hazard_class = Hazard
            except ImportError:
                class FallbackHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                        self.active = True
                hazard_class = FallbackHazard

            self.hazard_obj = hazard_class("perfect_reflector_zone", self.hazard_x, self.hazard_y, self.hazard_radius, "perfect_reflector", 0.0)
            if not hasattr(self.hazard_obj, "active"):
                self.hazard_obj.active = True
            world.arena.hazards.append(self.hazard_obj)

    def tick(self, world, balls, delta=0.016):
        import math
        self.hazard_radius += self.expansion_rate * delta

        if hasattr(self, "hazard_obj"):
            self.hazard_obj.radius = self.hazard_radius

        for b in balls:
            if getattr(b, "ball_type", None) == "spectator" or not getattr(b, "alive", True):
                continue

            if hasattr(b, "reflector_cooldown"):
                b.reflector_cooldown -= delta
                if b.reflector_cooldown <= 0:
                    delattr(b, "reflector_cooldown")

            if hasattr(b, "reflector_cooldown"):
                continue

            dx = b.x - self.hazard_x
            dy = b.y - self.hazard_y
            dist = math.hypot(dx, dy)

            # Check if ball hits the boundary (within a 15px thickness threshold)
            if abs(dist - self.hazard_radius) < 15.0:
                # Normal vector from center to boundary
                nx, ny = 0.0, 0.0
                if dist > 0.001:
                    nx = dx / dist
                    ny = dy / dist

                vx = getattr(b, "vx", 0.0)
                vy = getattr(b, "vy", 0.0)

                # Perfect reflection: v' = v - 2(v \cdot n)n
                dot_product = vx * nx + vy * ny
                # Only reflect if it's moving towards the boundary (from inside out or outside in)
                # Actually, we reflect regardless, or maybe only if it's hitting the boundary.
                # Let's just do perfect reflection if dot_product isn't 0.

                new_vx = vx - 2 * dot_product * nx
                new_vy = vy - 2 * dot_product * ny

                # Double velocity
                new_vx *= 2.0
                new_vy *= 2.0

                b.vx = new_vx
                b.vy = new_vy

                # Double speed
                if hasattr(b, "speed"):
                    b.speed *= 2.0
                if hasattr(b, "base_speed"):
                    b.base_speed *= 2.0

                # Increase base damage potential
                if hasattr(b, "base_damage"):
                    b.base_damage *= 1.5
                if hasattr(b, "damage"):
                    b.damage *= 1.5

                # Set cooldown to avoid multiple reflections in subsequent ticks
                b.reflector_cooldown = 1.0

GAME_MODES["perfect_reflector"] = PerfectReflectorHazardMode()

class ChronosphereEventMode(GameMode):
    """
    An arena-wide event where a massive chronosphere spawns. Entering it drastically
    increases cooldown recovery, but moving outside of it slows all animations,
    physics, and movement by 50% until the sphere collapses.
    """
    def __init__(self):
        super().__init__()
        self.name = "Chronosphere Event"
        self.description = "A massive chronosphere speeds up cooldowns inside, but slows everything else outside."
        self.zone_x = 500.0
        self.zone_y = 500.0
        self.zone_radius = 300.0
        self.collapse_timer = 20.0
        self.hazard_obj = None

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        self.zone_x = arena_width / 2.0
        self.zone_y = arena_height / 2.0
        self.collapse_timer = 20.0

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            try:
                from arena.procedural_arena import Hazard
                hazard_class = Hazard
            except ImportError:
                class FallbackHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                        self.active = True
                hazard_class = FallbackHazard

            self.hazard_obj = hazard_class("chronosphere", self.zone_x, self.zone_y, self.zone_radius, "chronosphere", 0.0)
            if not hasattr(self.hazard_obj, "active"):
                self.hazard_obj.active = True
            world.arena.hazards.append(self.hazard_obj)

    def tick(self, world, balls, delta=0.016):
        import math

        if self.collapse_timer > 0.0:
            self.collapse_timer -= delta
            if self.collapse_timer <= 0.0:
                if self.hazard_obj and hasattr(self.hazard_obj, "active"):
                    self.hazard_obj.active = False
                return

        if self.collapse_timer <= 0.0:
            return

        for b in balls:
            if not getattr(b, "alive", True):
                continue

            dx = getattr(b, "x", 0.0) - self.zone_x
            dy = getattr(b, "y", 0.0) - self.zone_y
            dist = math.hypot(dx, dy)

            vx = getattr(b, "vx", getattr(b, "velocity_x", 0.0))
            vy = getattr(b, "vy", getattr(b, "velocity_y", 0.0))

            if dist <= self.zone_radius:
                # Inside the sphere: rapidly decrease cooldowns
                if hasattr(b, "skill_cooldown"):
                    b.skill_cooldown = max(0.0, b.skill_cooldown - delta * 3.0)
                if hasattr(b, "dash_cooldown"):
                    b.dash_cooldown = max(0.0, b.dash_cooldown - delta * 3.0)
                if hasattr(b, "attack_cooldown"):
                    b.attack_cooldown = max(0.0, b.attack_cooldown - delta * 3.0)
            else:
                # Outside the sphere: counter-act movement by 50%
                b.x = getattr(b, "x", 0.0) - vx * delta * 0.5
                b.y = getattr(b, "y", 0.0) - vy * delta * 0.5

                # Slow down animations/timers by increasing them by 50% of delta
                if hasattr(b, "skill_cooldown"):
                    b.skill_cooldown = getattr(b, "skill_cooldown", 0.0) + delta * 0.5
                if hasattr(b, "dash_cooldown"):
                    b.dash_cooldown = getattr(b, "dash_cooldown", 0.0) + delta * 0.5
                if hasattr(b, "attack_cooldown"):
                    b.attack_cooldown = getattr(b, "attack_cooldown", 0.0) + delta * 0.5

class TimeDilationZoneMode(GameMode):
    """
    An anomalous zone in the arena where the flow of time slows down drastically.
    Entities and status effects within the field move and expire at half their normal rate.
    Projectiles and balls moving through these zones lose half their speed and delta multipliers are halved.
    """
    def __init__(self):
        super().__init__()
        self.name = "Time Dilation Zone"
        self.description = "Areas in the arena where time flows slower. Projectiles and balls moving through these zones lose half their speed and delta multipliers are halved."
        self.zone_x = 500.0
        self.zone_y = 500.0
        self.zone_radius = 200.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        self.zone_x = arena_width / 2.0
        self.zone_y = arena_height / 2.0

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            try:
                from arena.procedural_arena import Hazard
                hazard_class = Hazard
            except ImportError:
                class FallbackHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                        self.active = True
                hazard_class = FallbackHazard

            self.hazard_obj = hazard_class("time_dilation_zone", self.zone_x, self.zone_y, self.zone_radius, "time_dilation_zone", 0.0)
            if not hasattr(self.hazard_obj, "active"):
                self.hazard_obj.active = True
            world.arena.hazards.append(self.hazard_obj)

    def tick(self, world, balls, delta=0.016):
        import math
        for b in balls:
            if not getattr(b, "alive", True):
                continue

            dx = b.x - self.zone_x
            dy = b.y - self.zone_y
            dist = math.hypot(dx, dy)

            if dist <= self.zone_radius:
                vx = getattr(b, "vx", getattr(b, "velocity_x", 0.0))
                vy = getattr(b, "vy", getattr(b, "velocity_y", 0.0))

                # Apply counter-movement to simulate half speed
                b.x -= vx * delta * 0.5
                b.y -= vy * delta * 0.5

                for attr in dir(b):
                    if attr.endswith("_timer") or attr.endswith("_duration") or attr.endswith("_cooldown"):
                        val = getattr(b, attr)
                        if isinstance(val, (int, float)) and not isinstance(val, bool):
                            if attr == "confusion_zone_timer": continue
                            setattr(b, attr, val + delta * 0.5)

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            for h in world.arena.hazards:
                if not getattr(h, "active", True):
                    continue

                h_x = getattr(h, "x", 0.0)
                h_y = getattr(h, "y", 0.0)

                dx = h_x - self.zone_x
                dy = h_y - self.zone_y
                dist = math.hypot(dx, dy)

                if dist <= self.zone_radius:
                    h_vx = getattr(h, "vx", 0.0)
                    h_vy = getattr(h, "vy", 0.0)

                    # Slow down hazards
                    if hasattr(h, "x"): h.x -= h_vx * delta * 0.5
                    if hasattr(h, "y"): h.y -= h_vy * delta * 0.5

                    for attr in dir(h):
                        if attr.endswith("_timer") or attr.endswith("_duration") or attr.endswith("_cooldown") or attr == "duration" or attr == "lifetime":
                            val = getattr(h, attr)
                            if isinstance(val, (int, float)) and not isinstance(val, bool):
                                setattr(h, attr, val + delta * 0.5)

        if hasattr(world, "projectiles"):
            for p in world.projectiles:
                if not getattr(p, "active", True):
                    continue

                p_x = getattr(p, "x", 0.0)
                p_y = getattr(p, "y", 0.0)

                dx = p_x - self.zone_x
                dy = p_y - self.zone_y
                dist = math.hypot(dx, dy)

                if dist <= self.zone_radius:
                    p_vx = getattr(p, "vx", 0.0)
                    p_vy = getattr(p, "vy", 0.0)

                    # Slow down projectiles
                    if hasattr(p, "x"): p.x -= p_vx * delta * 0.5
                    if hasattr(p, "y"): p.y -= p_vy * delta * 0.5

                    for attr in dir(p):
                        if attr.endswith("_timer") or attr.endswith("_duration") or attr.endswith("_cooldown") or attr == "duration":
                            val = getattr(p, attr)
                            if isinstance(val, (int, float)) and not isinstance(val, bool):
                                setattr(p, attr, val + delta * 0.5)

