class SponsorDropMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Sponsor Drop"
        self.description = "During the match, special drop boxes appear periodically. Destroying them grants a permanent sponsor buff to the ball that lands the final hit."
        self.drop_timer = 0.0
        self.drop_interval = 15.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.drop_timer = 0.0

    def tick(self, world, balls, delta=0.016):
        import random
        self.drop_timer += delta
        if self.drop_timer >= self.drop_interval:
            self.drop_timer = 0.0
            arena_width = 1000.0
            arena_height = 1000.0
            if getattr(world, "arena", None) is not None:
                arena_width = getattr(world.arena, "width", 1000.0)
                arena_height = getattr(world.arena, "height", 1000.0)

            drop_x = random.uniform(100.0, arena_width - 100.0)
            drop_y = random.uniform(100.0, arena_height - 100.0)

            box_id = random.randint(100000, 999999)
            if hasattr(world, "next_id"):
                box_id = world.next_id
                world.next_id += 1

            box = SponsorDropBox(box_id, drop_x, drop_y)
            if hasattr(world, "balls"):
                world.balls.append(box)

            if hasattr(world, "add_event"):
                world.add_event("drop_box_spawned", {"message": "A Sponsor Drop Box has landed!"})

        to_remove = []
        for b in balls:
            if getattr(b, "ball_type", "") == "sponsor_drop_box" and not getattr(b, "alive", True):
                last_hit_id = getattr(b, "_last_hit_by_id", None)
                if last_hit_id is not None:
                    for ball in balls:
                        if getattr(ball, "id", None) == last_hit_id:
                            setattr(ball, "has_sponsor_buff", True)
                            ball.base_speed = getattr(ball, "base_speed", 100.0) * 1.2
                            ball.speed = getattr(ball, "speed", 100.0) * 1.2
                            ball.base_damage = getattr(ball, "base_damage", 10.0) * 1.2
                            ball.damage = getattr(ball, "damage", 10.0) * 1.2

                            if hasattr(world, "add_event"):
                                world.add_event("sponsor_buff", {"message": "A player claimed the Sponsor Buff!"})
                            break
                to_remove.append(b)

        if hasattr(world, "balls"):
            for b in to_remove:
                if b in world.balls:
                    world.balls.remove(b)

GAME_MODES["sponsor_drop"] = SponsorDropMode()

class EyeOfTheStormMode(SafeZoneMode):
    def __init__(self):
        super().__init__()
        self.name = "Eye of the Storm"
        self.description = "The safe zone has a fast-moving 'eye'. Inside the eye, health regenerates rapidly, but the outer safe zone acts normally. This encourages high-risk fights for the very center."
        self.eye_x = 500.0
        self.eye_y = 500.0
        self.eye_target_x = 500.0
        self.eye_target_y = 500.0
        self.eye_radius = 100.0
        self.eye_speed = 100.0
        self.heal_rate = 50.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.eye_x = self.zone_x
        self.eye_y = self.zone_y
        self.eye_target_x = self.zone_x
        self.eye_target_y = self.zone_y

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import math
        import random

        dx = self.eye_target_x - self.eye_x
        dy = self.eye_target_y - self.eye_y
        dist = math.sqrt(dx*dx + dy*dy)

        if dist > 5.0:
            self.eye_x += (dx / dist) * self.eye_speed * delta
            self.eye_y += (dy / dist) * self.eye_speed * delta
        else:
            angle = random.uniform(0, 2 * math.pi)
            r = random.uniform(0, max(0.0, self.zone_radius * 0.8))
            self.eye_target_x = self.zone_x + math.cos(angle) * r
            self.eye_target_y = self.zone_y + math.sin(angle) * r

        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                dist_to_eye = math.sqrt((b.x - self.eye_x)**2 + (b.y - self.eye_y)**2)
                if dist_to_eye <= self.eye_radius:
                    max_hp = getattr(b, "max_hp", 100.0)
                    b.hp = min(b.hp + self.heal_rate * delta, max_hp)

GAME_MODES["eye_of_the_storm"] = EyeOfTheStormMode()

class FakeBall:
    def __init__(self, id_val, start_x, start_y):
        self.id = id_val
        self.x = start_x
        self.y = start_y
        self.vx = 0.0
        self.vy = 0.0
        self.radius = 15.0
        self.hp = 1.0
        self.max_hp = 1.0
        self.alive = True
        self.ball_type = "basic"
        self.team = "neutral"
        self.speed = 150.0
        self.base_speed = 150.0
        self.damage = 0.0
        self.base_damage = 0.0
        self.perception_radius = 0.0
        self.is_fake = True
        self.target_x = start_x
        self.target_y = start_y
        self.move_timer = 0.0

    def update(self, delta, arena_width, arena_height):
        import math
        import random
        self.move_timer -= delta
        if self.move_timer <= 0.0:
            self.move_timer = random.uniform(1.0, 3.0)
            self.target_x = self.x + random.uniform(-200.0, 200.0)
            self.target_y = self.y + random.uniform(-200.0, 200.0)
            self.target_x = max(15.0, min(arena_width - 15.0, self.target_x))
            self.target_y = max(15.0, min(arena_height - 15.0, self.target_y))

        dx = self.target_x - self.x
        dy = self.target_y - self.y
        dist = math.sqrt(dx*dx + dy*dy)
        if dist > 5.0:
            self.vx = (dx / dist) * self.speed
            self.vy = (dy / dist) * self.speed
        else:
            self.vx = 0.0
            self.vy = 0.0

        self.x += self.vx * delta
        self.y += self.vy * delta
        self.x = max(15.0, min(arena_width - 15.0, self.x))
        self.y = max(15.0, min(arena_height - 15.0, self.y))

    def take_damage(self, amount, source=None):
        self.hp -= amount
        if self.hp <= 0:
            self.alive = False


