class FactionWarMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Faction War"
        self.description = "Players align with Light or Dark factions. Completing nemesis revenge kills earns points for the chosen faction."
        self.light_points = 0
        self.dark_points = 0
        self.season_ended = False
        self.winning_faction = None
        self.season_timer = 300.0
        self.superweapon_spawned = False
        self.superweapon_pos = None
        self.superweapon_faction = None
        self.superweapon_radius = 20.0

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        if not self.season_ended:
            self.season_timer -= delta
            if self.season_timer <= 0:
                self.end_season(world)

        if not self.superweapon_spawned:
            diff = self.light_points - self.dark_points
            if diff >= 5:
                self.superweapon_spawned = True
                self.superweapon_faction = "Dark"
                self.superweapon_pos = (0.0, 0.0)
            elif diff <= -5:
                self.superweapon_spawned = True
                self.superweapon_faction = "Light"
                self.superweapon_pos = (0.0, 0.0)

        if self.superweapon_spawned and self.superweapon_pos:
            import math
            for b in balls:
                if isinstance(b, dict):
                    if not b.get("active", True) or not b.get("alive", True): continue
                    b_x, b_y = b.get("x", 0.0), b.get("y", 0.0)
                    b_type = b.get("ball_type", "")
                    faction = b.get("faction")
                    b_radius = b.get("radius", 15.0)
                else:
                    if not getattr(b, "active", True) or not getattr(b, "alive", True): continue
                    b_x, b_y = b.x, b.y
                    b_type = getattr(b, "ball_type", "")
                    faction = getattr(b, "faction", None)
                    b_radius = getattr(b, "radius", 15.0)

                pm = getattr(world, "profile_manager", None)
                if pm and b_type == "local_player" and hasattr(pm, "get_faction"):
                    faction = pm.get_faction()

                if not faction:
                    faction = "Light" if hash(b_type) % 2 == 0 else "Dark"

                if faction == self.superweapon_faction:
                    dx = b_x - self.superweapon_pos[0]
                    dy = b_y - self.superweapon_pos[1]
                    if math.hypot(dx, dy) <= self.superweapon_radius + b_radius:
                        self.trigger_superweapon(world, balls, self.superweapon_faction)
                        self.superweapon_pos = None
                        break

    def trigger_superweapon(self, world, balls, triggering_faction):
        import random
        enemy_faction = "Light" if triggering_faction == "Dark" else "Dark"
        enemy_balls = []
        for b in balls:
            if isinstance(b, dict):
                if not b.get("active", True) or not b.get("alive", True): continue
                b_type = b.get("ball_type", "")
                faction = b.get("faction")
            else:
                if not getattr(b, "active", True) or not getattr(b, "alive", True): continue
                b_type = getattr(b, "ball_type", "")
                faction = getattr(b, "faction", None)

            pm = getattr(world, "profile_manager", None)
            if pm and b_type == "local_player" and hasattr(pm, "get_faction"):
                faction = pm.get_faction()

            if not faction:
                faction = "Light" if hash(b_type) % 2 == 0 else "Dark"

            if faction == enemy_faction:
                enemy_balls.append(b)

        if enemy_balls:
            num_to_eliminate = max(1, len(enemy_balls) // 2)
            targets = random.sample(enemy_balls, num_to_eliminate)
            for t in targets:
                if hasattr(world, "_deal_damage"):
                    hp = t.get("hp", 100) if isinstance(t, dict) else getattr(t, "hp", 100)
                    world._deal_damage(None, t, hp + 9999)
                else:
                    if isinstance(t, dict):
                        t["hp"] = -1
                        t["active"] = False
                        t["alive"] = False
                    else:
                        t.hp = -1
                        t.active = False
                        t.alive = False

    def on_ball_died(self, world, ball, killer):
        if hasattr(super(), "on_ball_died"):
            super().on_ball_died(world, ball, killer)

        if not killer or self.season_ended: return
        pm = getattr(world, "profile_manager", None)
        if pm and hasattr(pm, "is_nemesis"):
            k_type = getattr(killer, "ball_type", "")
            v_type = getattr(ball, "ball_type", "")

            if pm.is_nemesis(v_type, k_type):
                faction = pm.get_faction() if k_type == "local_player" else getattr(killer, "faction", None)
                if not faction:
                    faction = "Light" if hash(k_type) % 2 == 0 else "Dark"

                if faction == "Light":
                    self.light_points += 1
                elif faction == "Dark":
                    self.dark_points += 1

    def end_season(self, world):
        self.season_ended = True
        pm = getattr(world, "profile_manager", None)

        if self.light_points > self.dark_points:
            self.winning_faction = "Light"
        elif self.dark_points > self.light_points:
            self.winning_faction = "Dark"
        else:
            self.winning_faction = "Tie"

        if pm and self.winning_faction != "Tie":
            player_faction = pm.get_faction() if hasattr(pm, "get_faction") else None
            if player_faction == self.winning_faction:
                ball_to_unlock = f"{self.winning_faction.lower()}_champion"
                if "unlocked_balls" not in pm.data:
                    pm.data["unlocked_balls"] = []
                if ball_to_unlock not in pm.data["unlocked_balls"]:
                    pm.data["unlocked_balls"].append(ball_to_unlock)
                    pm.save()

class ChainReactionMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Chain Reaction"
        self.description = "Every elimination sets off a delayed explosion around the eliminated player. Surviving players can chain these explosions to eliminate multiple enemies."
        self.pending_explosions = []

    def on_ball_died(self, world, ball, killer):
        if hasattr(super(), "on_ball_died"):
            super().on_ball_died(world, ball, killer)

        if isinstance(ball, dict):
            ex_x = ball.get("x", 0.0)
            ex_y = ball.get("y", 0.0)
        else:
            ex_x = ball.x
            ex_y = ball.y

        self.pending_explosions.append({
            "x": ex_x,
            "y": ex_y,
            "timer": 1.5,
            "radius": 150.0,
            "damage": 50.0
        })

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        remaining_explosions = []
        new_explosions = [] # explosions added during this tick

        # Save current length to avoid iterating over newly added ones this tick
        current_explosions = list(self.pending_explosions)
        self.pending_explosions = [] # Clear so on_ball_died appends to empty

        for explosion in current_explosions:
            explosion["timer"] -= delta
            if explosion["timer"] <= 0.0:
                # Trigger explosion
                if not isinstance(world, dict) and hasattr(world, "add_event"):
                    world.add_event("chain_explosion", {
                        "x": explosion["x"],
                        "y": explosion["y"],
                        "radius": explosion["radius"]
                    })

                import math
                # Apply damage
                for b in balls:
                    b_alive = b.get("alive", True) if isinstance(b, dict) else getattr(b, "alive", True)
                    if b_alive:
                        b_x = b.get("x", 0.0) if isinstance(b, dict) else b.x
                        b_y = b.get("y", 0.0) if isinstance(b, dict) else b.y
                        dist = math.hypot(b_x - explosion["x"], b_y - explosion["y"])
                        if dist <= explosion["radius"]:
                            if isinstance(b, dict):
                                b["hp"] = b.get("hp", 100.0) - explosion["damage"]
                                if b["hp"] <= 0:
                                    b["alive"] = False
                                    self.on_ball_died(world, b, None)
                            else:
                                if hasattr(b, "take_damage"):
                                    # Fix: Don't pass `source=None` as many `take_damage` methods only accept `amount`
                                    try:
                                        b.take_damage(explosion["damage"], source=None)
                                    except TypeError:
                                        b.take_damage(explosion["damage"])
                                else:
                                    b.hp = getattr(b, "hp", 100) - explosion["damage"]
                                    if b.hp <= 0:
                                        b.alive = False
                                        self.on_ball_died(world, b, None)
            else:
                remaining_explosions.append(explosion)

        # self.pending_explosions now contains explosions from deaths this tick
        self.pending_explosions = remaining_explosions + self.pending_explosions

GAME_MODES['chain_reaction'] = ChainReactionMode()

GAME_MODES['faction_war'] = FactionWarMode()

class KillstreakExplosionMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Killstreak Explosion"
        self.description = "Every kill triggers an explosion that scales in radius and damage based on the killed ball's current killstreak."
        self.pending_explosions = []

    def on_ball_died(self, world, ball, killer):
        if hasattr(super(), "on_ball_died"):
            super().on_ball_died(world, ball, killer)

        if isinstance(ball, dict):
            ex_x = ball.get("x", 0.0)
            ex_y = ball.get("y", 0.0)
            killstreak = ball.get("kills", 0)
        else:
            ex_x = ball.x
            ex_y = ball.y
            killstreak = getattr(ball, "kills", 0)

        # Scale explosion based on killstreak
        radius = 100.0 + (killstreak * 20.0)
        damage = 30.0 + (killstreak * 15.0)

        killer_id = None
        if killer:
            killer_id = killer.get("id") if isinstance(killer, dict) else getattr(killer, "id", None)

        self.pending_explosions.append({
            "x": ex_x,
            "y": ex_y,
            "timer": 0.5,
            "radius": radius,
            "damage": damage,
            "killer": killer_id
        })

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        remaining_explosions = []
        current_explosions = list(self.pending_explosions)
        self.pending_explosions = []

        for explosion in current_explosions:
            explosion["timer"] -= delta
            if explosion["timer"] <= 0.0:
                if not isinstance(world, dict) and hasattr(world, "add_event"):
                    world.add_event("killstreak_explosion", {
                        "x": explosion["x"],
                        "y": explosion["y"],
                        "radius": explosion["radius"]
                    })

                import math
                for b in balls:
                    b_alive = b.get("alive", True) if isinstance(b, dict) else getattr(b, "alive", True)
                    if b_alive:
                        b_x = b.get("x", 0.0) if isinstance(b, dict) else b.x
                        b_y = b.get("y", 0.0) if isinstance(b, dict) else b.y
                        dist = math.hypot(b_x - explosion["x"], b_y - explosion["y"])
                        if dist <= explosion["radius"]:
                            if isinstance(b, dict):
                                b["hp"] = b.get("hp", 100.0) - explosion["damage"]
                                if b["hp"] <= 0:
                                    b["alive"] = False
                                    self.on_ball_died(world, b, None)
                            else:
                                if hasattr(b, "take_damage"):
                                    try:
                                        b.take_damage(explosion["damage"])
                                    except TypeError:
                                        try:
                                            b.take_damage(explosion["damage"], source=None)
                                        except Exception:
                                            pass
                                else:
                                    b.hp = getattr(b, "hp", 100) - explosion["damage"]
                                    if b.hp <= 0:
                                        b.alive = False
                                        self.on_ball_died(world, b, None)
            else:
                remaining_explosions.append(explosion)

        self.pending_explosions = remaining_explosions + self.pending_explosions

class MimicCloneSwapMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Mimic Clone Swap"
        self.description = "Every player spawns with a clone that perfectly mimics inputs, deals half damage, and takes double damage. Dying swaps the player into their clone but with halved stats."

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import copy
        import random

        # Ensure balls have clones
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "is_mimic_clone", False) or getattr(b, "ball_type", "") == "spectator":
                continue

            if not hasattr(b, "my_mimic_clone") or not getattr(b.my_mimic_clone, "alive", False):
                if not getattr(b, "has_used_mimic_revive", False):
                    clone = copy.copy(b)
                    clone.id = getattr(world, "next_id", random.randint(10000, 99999))
                    if hasattr(world, "next_id"):
                        world.next_id += 1

                    clone.x += random.uniform(-50, 50)
                    clone.y += random.uniform(-50, 50)
                    clone.hp = getattr(b, "hp", 100.0)
                    clone.max_hp = getattr(b, "max_hp", 100.0)
                    clone.is_mimic_clone = True
                    clone.mimic_owner_id = b.id
                    clone.base_damage_multiplier = getattr(b, "base_damage_multiplier", 1.0) * 0.5
                    clone.prev_hp = clone.hp

                    b.my_mimic_clone = clone

                    if hasattr(world, "balls"):
                        world.balls.append(clone)
            else:
                # Mimic inputs
                c = b.my_mimic_clone
                c.vx = getattr(b, "vx", 0.0)
                c.vy = getattr(b, "vy", 0.0)
                c.target_x = getattr(b, "target_x", c.x)
                c.target_y = getattr(b, "target_y", c.y)

                # Double damage logic
                c_hp = getattr(c, "hp", 100.0)
                c_prev = getattr(c, "prev_hp", 100.0)
                if c_hp < c_prev:
                    damage_taken = c_prev - c_hp
                    c.hp = c_hp - damage_taken
                    if c.hp <= 0:
                        c.alive = False
                    c.prev_hp = c.hp
                elif c_hp > c_prev: # Healed
                    c.prev_hp = c_hp

    def on_ball_died(self, world, ball, killer):
        if hasattr(super(), "on_ball_died"):
            super().on_ball_died(world, ball, killer)

        if getattr(ball, "is_mimic_clone", False):
            return

        if getattr(ball, "has_used_mimic_revive", False):
            return

        clone = getattr(ball, "my_mimic_clone", None)
        if clone and getattr(clone, "alive", False):
            # Revive
            ball.alive = True
            ball.x = clone.x
            ball.y = clone.y

            # Halve stats permanently
            ball.max_hp = getattr(ball, "max_hp", 100.0) / 2.0
            ball.hp = ball.max_hp
            ball.base_speed = getattr(ball, "base_speed", 100.0) / 2.0
            ball.base_damage_multiplier = getattr(ball, "base_damage_multiplier", 1.0) / 2.0
            ball.has_used_mimic_revive = True

            clone.alive = False
            clone.hp = 0

GAME_MODES['mimic_clone_swap'] = MimicCloneSwapMode()

GAME_MODES['killstreak_explosion'] = KillstreakExplosionMode()

class TornadoSwarmEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Tornado Swarm Event"
        self.description = "An arena-wide event where miniature tornadoes spawn periodically across the map for a limited time. They last 10 seconds and have high velocity, causing utter chaos. These miniature tornadoes can also combine with elemental hazards to become mini-firenados, mini-poison tornadoes, or mini-blizzards that slow down players."
        self.tornado_spawn_timer = 0.0
        self.tornado_spawn_interval = 2.0
        self.active_event = False
        self.event_timer = 15.0

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        self.event_timer -= delta
        if self.event_timer <= 0.0:
            self.active_event = not self.active_event
            if self.active_event:
                self.event_timer = 20.0
            else:
                self.event_timer = 40.0

        if self.active_event:
            self.tornado_spawn_timer -= delta
            if self.tornado_spawn_timer <= 0.0:
                self.tornado_spawn_timer = self.tornado_spawn_interval

                arena_width = getattr(world.arena, "width", 2000.0) if hasattr(world, "arena") else 2000.0
                arena_height = getattr(world.arena, "height", 2000.0) if hasattr(world, "arena") else 2000.0

                import random
                x = random.uniform(50.0, arena_width - 50.0)
                y = random.uniform(50.0, arena_height - 50.0)

                try:
                    from arena.procedural_arena import Hazard
                    HazardClass = Hazard
                except ImportError:
                    class FallbackHazard:
                        def __init__(self, id, x, y, radius, kind, damage):
                            self.id = id
                            self.x = x
                            self.y = y
                            self.radius = radius
                            self.kind = kind
                            self.damage = damage
                            self.active = True
                            self.target_radius = 0.0
                    HazardClass = FallbackHazard

                hazards = getattr(getattr(world, "arena", None), "hazards", [])
                t_id = len(hazards) + random.randint(10000, 99999)
                tornado = HazardClass(id=t_id, x=x, y=y, radius=30.0, kind="mini_tornado", damage=15.0)
                setattr(tornado, "duration", 10.0)
                setattr(tornado, "vx", random.uniform(-300.0, 300.0))
                setattr(tornado, "vy", random.uniform(-300.0, 300.0))

                if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                    world.arena.hazards.append(tornado)

        # Handle tornado logic (movement, combination with elements, expiration)
        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            to_remove = []
            for h in list(world.arena.hazards):  # Iterate over copy just in case
                kind = getattr(h, "kind", "")
                if kind in ("mini_tornado", "mini_firenado", "mini_poison_tornado", "mini_blizzard"):
                    # Move
                    h.x += getattr(h, "vx", 0.0) * delta
                    h.y += getattr(h, "vy", 0.0) * delta

                    # Bounce off walls
                    arena_width = getattr(world.arena, "width", 2000.0) if hasattr(world, "arena") else 2000.0
                    arena_height = getattr(world.arena, "height", 2000.0) if hasattr(world, "arena") else 2000.0

                    if h.x < getattr(h, "radius", 30.0):
                        h.x = getattr(h, "radius", 30.0)
                        setattr(h, "vx", getattr(h, "vx", 0.0) * -1.0)
                    elif h.x > arena_width - getattr(h, "radius", 30.0):
                        h.x = arena_width - getattr(h, "radius", 30.0)
                        setattr(h, "vx", getattr(h, "vx", 0.0) * -1.0)

                    if h.y < getattr(h, "radius", 30.0):
                        h.y = getattr(h, "radius", 30.0)
                        setattr(h, "vy", getattr(h, "vy", 0.0) * -1.0)
                    elif h.y > arena_height - getattr(h, "radius", 30.0):
                        h.y = arena_height - getattr(h, "radius", 30.0)
                        setattr(h, "vy", getattr(h, "vy", 0.0) * -1.0)

                    # Expiration
                    if hasattr(h, "duration"):
                        h.duration -= delta
                        if h.duration <= 0.0:
                            to_remove.append(h)
                            continue

                    # Combination with elements
                    if kind == "mini_tornado":
                        for other in world.arena.hazards:
                            if other is h or not getattr(other, "active", True): continue

                            other_kind = getattr(other, "kind", "")
                            if other_kind in ("fire_zone", "lava", "poison_cloud", "poison_nova", "fire_ring", "ice_patch", "ice_patches"):
                                import math
                                dist = math.hypot(h.x - other.x, h.y - other.y)
                                if dist < getattr(h, "radius", 30.0) + getattr(other, "radius", 50.0):
                                    if other_kind in ("fire_zone", "lava", "fire_ring"):
                                        h.kind = "mini_firenado"
                                        h.damage = 30.0
                                    elif other_kind in ("poison_cloud", "poison_nova"):
                                        h.kind = "mini_poison_tornado"
                                        h.damage = 25.0
                                    elif other_kind in ("ice_patch", "ice_patches"):
                                        h.kind = "mini_blizzard"
                                        h.damage = 10.0
                                    break

            for h in to_remove:
                if h in world.arena.hazards:
                    world.arena.hazards.remove(h)

GAME_MODES['tornado_swarm_event'] = TornadoSwarmEventMode()

class DynamicDangerZonesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Dynamic Danger Zones"
        self.description = "A dynamic procedural arena element where circular 'danger zones' periodically appear on the map. After a warning delay, any balls caught within the zone take heavy damage. The zones gradually shrink in size over the course of the match, forcing close-quarters combat."
        self.zones = []
        self.zone_spawn_timer = 0.0
        self.zone_spawn_interval = 15.0
        self.match_time = 0.0
        self.max_match_time = 300.0 # 5 minutes to shrink fully
        self.base_zone_radius = 200.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.zones = []
        self.zone_spawn_timer = 5.0
        self.match_time = 0.0

    def tick(self, world, balls, delta=0.016):
        import math
        import random
        super().tick(world, balls, delta)
        self.match_time += delta
        self.zone_spawn_timer -= delta

        # Calculate current max radius based on match time
        shrink_factor = max(0.2, 1.0 - (self.match_time / self.max_match_time))
        current_max_radius = self.base_zone_radius * shrink_factor

        if self.zone_spawn_timer <= 0:
            self.zone_spawn_timer = self.zone_spawn_interval

            arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") else 1000.0
            arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") else 1000.0

            x = random.uniform(current_max_radius, arena_width - current_max_radius)
            y = random.uniform(current_max_radius, arena_height - current_max_radius)

            self.zones.append({
                "x": x,
                "y": y,
                "radius": current_max_radius,
                "timer": 5.0, # Warning delay
                "active": False,
                "duration": 10.0 # Active duration
            })

            if hasattr(world, "add_event"):
                world.add_event("danger_zone_warning", {"x": x, "y": y, "radius": current_max_radius, "message": "Danger zone appearing!"})

        active_zones = []
        for zone in self.zones:
            zone["timer"] -= delta
            if not zone["active"]:
                if zone["timer"] <= 0:
                    zone["active"] = True
                    zone["timer"] = zone["duration"]
                    if hasattr(world, "add_event"):
                        world.add_event("danger_zone_active", {"x": zone["x"], "y": zone["y"], "radius": zone["radius"], "message": "Danger zone active!"})

                    # Spawn hazard
                    if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                        try:
                            from arena.procedural_arena import Hazard
                            HazardClass = Hazard
                        except ImportError:
                            class FallbackHazard:
                                def __init__(self, id, x, y, radius, kind, damage):
                                    self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                                    self.active = True
                            HazardClass = FallbackHazard

                        zone_hazard = HazardClass(
                            id=getattr(world, "next_id", random.randint(100000, 999999)),
                            x=zone["x"],
                            y=zone["y"],
                            radius=zone["radius"],
                            kind="danger_zone",
                            damage=50.0
                        )
                        setattr(zone_hazard, "duration", zone["duration"])
                        world.arena.hazards.append(zone_hazard)
                        zone["hazard"] = zone_hazard
                        if hasattr(world, "next_id"):
                            world.next_id += 1
                active_zones.append(zone)
            else:
                if zone["timer"] > 0:
                    active_zones.append(zone)

                    # Shrink the active zone gradually
                    shrink_rate = 10.0 * delta
                    zone["radius"] = max(10.0, zone["radius"] - shrink_rate)
                    if "hazard" in zone and hasattr(zone["hazard"], "radius"):
                        zone["hazard"].radius = zone["radius"]

                    # Apply heavy damage
                    for b in balls:
                        if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                            dist = math.hypot(b.x - zone["x"], b.y - zone["y"])
                            if dist <= zone["radius"]:
                                damage = 50.0 * delta
                                if hasattr(b, "take_damage"):
                                    b.take_damage(damage)
                                else:
                                    b.hp = getattr(b, "hp", 100) - damage
                                    if b.hp <= 0:
                                        b.alive = False
                else:
                    if "hazard" in zone and hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                        if zone["hazard"] in world.arena.hazards:
                            world.arena.hazards.remove(zone["hazard"])

        self.zones = active_zones

GAME_MODES['dynamic_danger_zones'] = DynamicDangerZonesMode()

class RepulsionFieldMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Repulsion Field"
        self.description = "All balls naturally repel each other slightly. The strength of repulsion increases as they get closer, making it difficult to land melee attacks and creating a pinball-like arena effect during high-speed collisions."

    def tick(self, world, balls, delta=0.016):
        import math
        super().tick(world, balls, delta)

        # Apply repulsion between all pairs of alive balls
        for i in range(len(balls)):
            b1 = balls[i]
            if not getattr(b1, "alive", False) or getattr(b1, "ball_type", None) == "spectator":
                continue

            for j in range(i + 1, len(balls)):
                b2 = balls[j]
                if not getattr(b2, "alive", False) or getattr(b2, "ball_type", None) == "spectator":
                    continue

                dx = b1.x - b2.x
                dy = b1.y - b2.y
                dist = math.hypot(dx, dy)

                # Minimum distance to prevent division by zero
                if dist < 1.0:
                    dx = 1.0
                    dy = 0.0
                    dist = 1.0

                # Calculate repulsion force
                # Strength increases as distance decreases
                max_dist = 300.0
                if dist < max_dist:
                    # Inverse relationship, capped to prevent insane velocities at point-blank
                    force = (max_dist - dist) / max_dist
                    force = force * force * 1000.0 * delta # base strength

                    nx = dx / dist
                    ny = dy / dist

                    b1.vx += nx * force
                    b1.vy += ny * force

                    b2.vx -= nx * force
                    b2.vy -= ny * force

GAME_MODES['repulsion_field'] = RepulsionFieldMode()

class MagneticShockwaveEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Magnetic Shockwave Event"
        self.description = "A new heavy hazard type that drops in the arena and periodically unleashes a massive magnetic shockwave that pulls players toward it while dealing damage. If a player touches the center of the anchor, they are completely stunned for 2 seconds."
        self.anchor = None
        self.spawn_timer = 0.0
        self.shockwave_timer = 0.0
        self.active_shockwave = False
        self.shockwave_duration = 0.0
        self.anchor_radius = 20.0
        self.pull_radius = 400.0

    class AnchorHazard:
        def __init__(self, x, y, radius):
            self.x = x
            self.y = y
            self.radius = radius
            self.kind = "magnetic_anchor"
            self.active = True
            self.duration = 9999.0

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        if getattr(world, "arena", None) is None:
            return

        if self.anchor is None:
            self.spawn_timer += delta
            if self.spawn_timer > 5.0:
                # Spawn anchor in the center
                x = getattr(world.arena, "width", 800) / 2
                y = getattr(world.arena, "height", 800) / 2
                self.anchor = self.AnchorHazard(x, y, self.anchor_radius)
                if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
                    world.arena.hazards = []
                world.arena.hazards.append(self.anchor)
                self.spawn_timer = 0.0
                if hasattr(world, "add_event"):
                    world.add_event("magnetic_anchor_spawn", {"x": x, "y": y})
        else:
            if not self.anchor.active or self.anchor not in getattr(world.arena, "hazards", []):
                self.anchor = None
                self.spawn_timer = 0.0
                return

            self.shockwave_timer += delta
            if self.active_shockwave:
                self.shockwave_duration += delta
                if self.shockwave_duration > 1.0:
                    self.active_shockwave = False
                    self.shockwave_duration = 0.0
                    self.shockwave_timer = 0.0
                else:
                    # Apply pull and damage
                    import math
                    for b in balls:
                        if not getattr(b, "alive", False):
                            continue
                        dx = self.anchor.x - b.x
                        dy = self.anchor.y - b.y
                        dist = math.hypot(dx, dy)
                        if dist < self.pull_radius and dist > 0:
                            pull_strength = 200.0 * (1.0 - dist / self.pull_radius)
                            b.vx += (dx / dist) * pull_strength * delta
                            b.vy += (dy / dist) * pull_strength * delta

                            # Damage over time during shockwave
                            b.hp -= 5.0 * delta

            elif self.shockwave_timer > 4.0:
                self.active_shockwave = True
                self.shockwave_duration = 0.0
                if hasattr(world, "add_event"):
                    world.add_event("magnetic_shockwave", {"x": self.anchor.x, "y": self.anchor.y, "radius": self.pull_radius})

            # Check for direct contact with anchor
            import math
            for b in balls:
                if not getattr(b, "alive", False):
                    continue
                dx = self.anchor.x - b.x
                dy = self.anchor.y - b.y
                dist = math.hypot(dx, dy)
                if dist < (self.anchor.radius + getattr(b, "radius", 10.0)):
                    # Stun
                    b.stun_timer = max(getattr(b, "stun_timer", 0.0), 2.0)

GAME_MODES['magnetic_shockwave'] = MagneticShockwaveEventMode()
class OrbitalCrosshairMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Orbital Crosshair"
        self.description = "A satellite crosshair slowly tracks players. Upon locking on, it fires an orbital beam creating an irradiated zone."
        self.crosshairs = []
        self.spawn_timer = 0.0
        self.spawn_interval = 20.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.crosshairs = []
        self.spawn_timer = 3.0

    def tick(self, world, balls, delta=0.016):
        import math
        import random
        super().tick(world, balls, delta)

        self.spawn_timer -= delta
        if self.spawn_timer <= 0:
            self.spawn_timer = self.spawn_interval

            valid_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]
            if valid_balls:
                target = max(valid_balls, key=lambda b: getattr(b, "score", 0))
                arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") else 1000.0
                arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") else 1000.0
                cx = random.uniform(100, arena_width - 100)
                cy = random.uniform(100, arena_height - 100)
                self.crosshairs.append({
                    "x": cx,
                    "y": cy,
                    "target_id": getattr(target, "id", None),
                    "state": "hunting", # hunting, locking, firing
                    "timer": 0.0,
                    "radius": 50.0,
                    "speed": 80.0
                })
                if hasattr(world, "add_event"):
                    world.add_event("crosshair_spawn", {"message": "An orbital crosshair is tracking a target!"})

        active_crosshairs = []
        for ch in self.crosshairs:
            if ch["state"] == "hunting":
                target = next((b for b in balls if getattr(b, "id", None) == ch["target_id"]), None)

                valid_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]
                if valid_balls:
                    highest_scoring_ball = max(valid_balls, key=lambda b: getattr(b, "score", 0))
                    if target != highest_scoring_ball:
                        target = highest_scoring_ball
                        ch["target_id"] = getattr(target, "id", None)


                ol_t = getattr(target, "orbital_link_timer", 0.0)
                if target and getattr(target, "orbital_strike_reflector_timer", 0.0) > 0.0:
                    enemies = [b for b in balls if getattr(b, "alive", False) and getattr(b, "team", "") != getattr(target, "team", "") and getattr(b, "ball_type", "") != "spectator"]
                    if enemies:
                        closest_enemy = min(enemies, key=lambda e: (e.x - target.x)**2 + (e.y - target.y)**2)
                        target = closest_enemy
                        ch["target_id"] = getattr(target, "id", None)
                    else:
                        ch["state"] = "hunting"
                        ch["target_id"] = None

                ol_t = getattr(target, "orbital_link_timer", 0.0)
                if target and isinstance(ol_t, (int, float)) and ol_t > 0.0:
                    # orbital link redirects
                    enemies = [b for b in balls if getattr(b, "alive", False) and getattr(b, "team", "") != getattr(target, "team", "") and getattr(b, "ball_type", "") != "spectator"]
                    if enemies:
                        closest_enemy = min(enemies, key=lambda e: (e.x - target.x)**2 + (e.y - target.y)**2)
                        target = closest_enemy
                        ch["target_id"] = getattr(target, "id", None)
                if not target or not getattr(target, "alive", False):
                    if not valid_balls:
                        continue # No targets left

                dx = target.x - ch["x"]
                dy = target.y - ch["y"]
                dist = math.hypot(dx, dy)

                if dist > 5.0:
                    ch["x"] += (dx / dist) * ch["speed"] * delta
                    ch["y"] += (dy / dist) * ch["speed"] * delta

                if dist < 20.0:
                    ch["timer"] += delta
                    if ch["timer"] >= 2.0:
                        ch["state"] = "locking"
                        ch["timer"] = 3.0 # Lock on duration
                        if hasattr(world, "add_event"):
                            world.add_event("crosshair_locking", {"x": ch["x"], "y": ch["y"], "message": "Orbital strike locking on!"})
                else:
                    ch["timer"] = max(0.0, ch["timer"] - delta)
                active_crosshairs.append(ch)

            elif ch["state"] == "locking":
                ch["timer"] -= delta
                if ch["timer"] <= 0:
                    ch["state"] = "firing"
                    # Spawn irradiated zone
                    if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                        try:
                            from arena.procedural_arena import Hazard
                            HazardClass = Hazard
                        except ImportError:
                            class FallbackHazard:
                                def __init__(self, id, x, y, radius, kind, damage):
                                    self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                                    self.active = True
                            HazardClass = FallbackHazard

                        h_id = getattr(world, "next_id", random.randint(100000, 999999))
                        h = HazardClass(id=h_id, x=ch["x"], y=ch["y"], radius=80.0, kind="irradiated_zone", damage=0.0)
                        setattr(h, "duration", 15.0)
                        world.arena.hazards.append(h)
                        if hasattr(world, "next_id"):
                            world.next_id += 1

                        # Chance to spawn meteorite debris
                        if random.random() < 0.5:
                            num_debris = random.randint(1, 3)
                            for i in range(num_debris):
                                d_id = getattr(world, "next_id", random.randint(100000, 999999)) + i
                                dx = ch["x"] + random.uniform(-40, 40)
                                dy = ch["y"] + random.uniform(-40, 40)
                                debris = HazardClass(id=d_id, x=dx, y=dy, radius=random.uniform(20.0, 40.0), kind="orbital_debris", damage=0.0)
                                setattr(debris, "duration", 10.0)
                                setattr(debris, "indestructible", True)
                                setattr(debris, "blocks_projectiles", True)
                                # Crucial: make it a physical obstacle
                                setattr(debris, "is_solid", True)
                                world.arena.hazards.append(debris)
                            if hasattr(world, "next_id"):
                                world.next_id += num_debris

                        if hasattr(world, "add_event"):
                            world.add_event("orbital_strike_fired", {"x": ch["x"], "y": ch["y"], "message": "Orbital strike fired!"})
                else:
                    active_crosshairs.append(ch)
            # if firing, we don't append it to active, it just disappears after firing

        self.crosshairs = active_crosshairs


        # Process irradiated_zone hazards
        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            for h in world.arena.hazards:
                if getattr(h, "kind", "") == "irradiated_zone" and getattr(h, "active", True):
                    for b in balls:
                        osr_t = getattr(b, "orbital_strike_reflector_timer", 0.0)
                        if isinstance(osr_t, (int, float)) and osr_t > 0.0:
                            continue
                        ol_t = getattr(b, "orbital_link_timer", 0.0)
                        if isinstance(ol_t, (int, float)) and ol_t > 0.0:
                            continue
                        if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":

                            dist = math.hypot(b.x - h.x, b.y - h.y)
                            if dist <= getattr(h, "radius", 80.0):
                                # Drain stamina regen (set to 0 or drain)
                                if hasattr(b, "stamina"):
                                    b.stamina = max(0.0, b.stamina - 20.0 * delta)
                                # Heavily slow
                                base_speed_multiplier = getattr(b, "base_speed_multiplier", 1.0)
                                b.speed_multiplier = base_speed_multiplier * 0.5
                                # Deal slight damage
                                damage = 10.0 * delta
                                if hasattr(b, "take_damage"):
                                    b.take_damage(damage, source="irradiated_zone")
                                else:
                                    b.hp -= damage
                                    if b.hp <= 0:
                                        b.hp = 0
                                        b.alive = False

GAME_MODES['orbital_crosshair'] = OrbitalCrosshairMode()

class SiphonBeamMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Siphon Beam"
        self.description = "A satellite crosshair slowly tracks players. Upon locking on, it fires an orbital beam creating a siphon zone that damages enemies and heals the lowest HP ball."
        self.crosshairs = []
        self.spawn_timer = 0.0
        self.spawn_interval = 20.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.crosshairs = []
        self.spawn_timer = 3.0

    def tick(self, world, balls, delta=0.016):
        import math
        import random
        super().tick(world, balls, delta)

        self.spawn_timer -= delta
        if self.spawn_timer <= 0:
            self.spawn_timer = self.spawn_interval

            valid_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]
            if valid_balls:
                target = max(valid_balls, key=lambda b: getattr(b, "score", 0))
                arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") else 1000.0
                arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") else 1000.0
                cx = random.uniform(100, arena_width - 100)
                cy = random.uniform(100, arena_height - 100)

                # Determine caller: lowest HP ball if randomly spawned
                caller = min(valid_balls, key=lambda b: getattr(b, "hp", 100.0))

                self.crosshairs.append({
                    "x": cx,
                    "y": cy,
                    "target_id": getattr(target, "id", None),
                    "caller_id": getattr(caller, "id", None),
                    "state": "hunting",
                    "timer": 0.0,
                    "radius": 50.0,
                    "speed": 80.0
                })
                if hasattr(world, "add_event"):
                    world.add_event("crosshair_spawn", {"message": "A siphon crosshair is tracking a target!"})

        active_crosshairs = []
        for ch in self.crosshairs:
            if ch["state"] == "hunting":
                target = next((b for b in balls if getattr(b, "id", None) == ch["target_id"]), None)

                valid_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]
                if valid_balls:
                    highest_scoring_ball = max(valid_balls, key=lambda b: getattr(b, "score", 0))
                    if target != highest_scoring_ball:
                        target = highest_scoring_ball
                        ch["target_id"] = getattr(target, "id", None)

                if target and getattr(target, "orbital_strike_reflector_timer", 0.0) > 0.0:
                    enemies = [b for b in balls if getattr(b, "alive", False) and getattr(b, "team", "") != getattr(target, "team", "") and getattr(b, "ball_type", "") != "spectator"]
                    if enemies:
                        closest_enemy = min(enemies, key=lambda e: (e.x - target.x)**2 + (e.y - target.y)**2)
                        target = closest_enemy
                        ch["target_id"] = getattr(target, "id", None)
                    else:
                        ch["state"] = "hunting"
                        ch["target_id"] = None

                ol_t = getattr(target, "orbital_link_timer", 0.0)
                if target and isinstance(ol_t, (int, float)) and ol_t > 0.0:
                    enemies = [b for b in balls if getattr(b, "alive", False) and getattr(b, "team", "") != getattr(target, "team", "") and getattr(b, "ball_type", "") != "spectator"]
                    if enemies:
                        closest_enemy = min(enemies, key=lambda e: (e.x - target.x)**2 + (e.y - target.y)**2)
                        target = closest_enemy
                        ch["target_id"] = getattr(target, "id", None)
                if not target or not getattr(target, "alive", False):
                    if not valid_balls:
                        continue

                dx = target.x - ch["x"]
                dy = target.y - ch["y"]
                dist = math.hypot(dx, dy)

                if dist > 5.0:
                    ch["x"] += (dx / dist) * ch["speed"] * delta
                    ch["y"] += (dy / dist) * ch["speed"] * delta

                if dist < 20.0:
                    ch["timer"] += delta
                    if ch["timer"] >= 2.0:
                        ch["state"] = "locking"
                        ch["timer"] = 3.0
                        if hasattr(world, "add_event"):
                            world.add_event("crosshair_locking", {"x": ch["x"], "y": ch["y"], "message": "Siphon beam locking on!"})
                else:
                    ch["timer"] = max(0.0, ch["timer"] - delta)
                active_crosshairs.append(ch)

            elif ch["state"] == "locking":
                ch["timer"] -= delta
                if ch["timer"] <= 0:
                    ch["state"] = "firing"
                    if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                        try:
                            from arena.procedural_arena import Hazard
                            HazardClass = Hazard
                        except ImportError:
                            class FallbackHazard:
                                def __init__(self, id, x, y, radius, kind, damage):
                                    self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                                    self.active = True
                            HazardClass = FallbackHazard

                        h_id = getattr(world, "next_id", random.randint(100000, 999999))
                        h = HazardClass(id=h_id, x=ch["x"], y=ch["y"], radius=80.0, kind="siphon_zone", damage=0.0)
                        setattr(h, "duration", 15.0)
                        setattr(h, "caller_id", ch.get("caller_id", None))
                        world.arena.hazards.append(h)
                        if hasattr(world, "next_id"):
                            world.next_id += 1
                        if hasattr(world, "add_event"):
                            world.add_event("orbital_strike_fired", {"x": ch["x"], "y": ch["y"], "message": "Siphon beam fired!"})
                else:
                    active_crosshairs.append(ch)

        self.crosshairs = active_crosshairs

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            for h in world.arena.hazards:
                if getattr(h, "kind", "") == "siphon_zone" and getattr(h, "active", True):
                    total_siphoned = 0.0
                    for b in balls:
                        osr_t = getattr(b, "orbital_strike_reflector_timer", 0.0)
                        if isinstance(osr_t, (int, float)) and osr_t > 0.0:
                            continue
                        ol_t = getattr(b, "orbital_link_timer", 0.0)
                        if isinstance(ol_t, (int, float)) and ol_t > 0.0:
                            continue
                        if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                            dist = math.hypot(b.x - h.x, b.y - h.y)
                            if dist <= getattr(h, "radius", 80.0):
                                if hasattr(b, "stamina"):
                                    b.stamina = max(0.0, b.stamina - 20.0 * delta)
                                base_speed_multiplier = getattr(b, "base_speed_multiplier", 1.0)
                                b.speed_multiplier = base_speed_multiplier * 0.5
                                damage = 10.0 * delta
                                if hasattr(b, "take_damage"):
                                    b.take_damage(damage, source="siphon_zone")
                                else:
                                    b.hp -= damage
                                    if b.hp <= 0:
                                        b.hp = 0
                                        b.alive = False
                                total_siphoned += damage

                    if total_siphoned > 0:
                        caller_id = getattr(h, "caller_id", None)
                        caller = next((b for b in balls if getattr(b, "id", None) == caller_id), None)
                        if caller and getattr(caller, "alive", False) and getattr(caller, "ball_type", "") != "spectator":
                            max_hp = getattr(caller, "max_hp", 100.0)
                            caller.hp = min(max_hp, caller.hp + total_siphoned)
                        else:
                            valid_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]
                            if valid_balls:
                                lowest_hp_ball = min(valid_balls, key=lambda b: getattr(b, "hp", 100.0))
                                max_hp = getattr(lowest_hp_ball, "max_hp", 100.0)
                                lowest_hp_ball.hp = min(max_hp, lowest_hp_ball.hp + total_siphoned)

GAME_MODES['siphon_beam'] = SiphonBeamMode()


GAME_MODES['spectator_holograms'] = SpectatorHologramsMode()

GAME_MODES['decoy_network'] = DecoyNetworkMode()

