class HealerFreezeTagMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Healer Freeze Tag"
        self.description = "One Healer per team. Healers must dodge hazards and quickly unfreeze their entire team before the other healer does."

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        # Split into two teams
        playing_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator"]
        mid = len(playing_balls) // 2
        for i, b in enumerate(playing_balls):
            b.team = "Red" if i < mid else "Blue"

        # Pick a healer for each team
        teams = {}
        for b in playing_balls:
            if b.team not in teams:
                teams[b.team] = []
            teams[b.team].append(b)

        for t, members in teams.items():
            for i, b in enumerate(members):
                if i == 0:
                    b.is_healer = True
                    b.is_frozen = False
                else:
                    b.is_healer = False
                    self._freeze_ball(b)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        alive_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator"]

        n = len(alive_balls)
        for i in range(n):
            for j in range(i + 1, n):
                b1 = alive_balls[i]
                b2 = alive_balls[j]

                b1_x = getattr(b1, "x", 0.0)
                b1_y = getattr(b1, "y", 0.0)
                b1_r = getattr(b1, "radius", 10.0)

                b2_x = getattr(b2, "x", 0.0)
                b2_y = getattr(b2, "y", 0.0)
                b2_r = getattr(b2, "radius", 10.0)

                dist_sq = (b1_x - b2_x) ** 2 + (b1_y - b2_y) ** 2
                min_dist = b1_r + b2_r

                if dist_sq < min_dist ** 2:
                    team1 = getattr(b1, "team", None)
                    team2 = getattr(b2, "team", None)

                    if team1 and team2 and team1 == team2:
                        # Ally collision
                        b1_frozen = getattr(b1, "is_frozen", False)
                        b2_frozen = getattr(b2, "is_frozen", False)

                        # If one is frozen and the other is NOT frozen (i.e. is the healer or an unfrozen ally)
                        if b1_frozen and not b2_frozen:
                            self._unfreeze_ball(b1)
                        elif not b1_frozen and b2_frozen:
                            self._unfreeze_ball(b2)

    def _freeze_ball(self, b: 'Any') -> None:
        b.is_frozen = True
        b.stun_timer = 9999.0
        b.frozen_timer = 9999.0
        b.vx = 0.0
        b.vy = 0.0

    def _unfreeze_ball(self, b: 'Any') -> None:
        b.is_frozen = False
        b.stun_timer = 0.0
        b.frozen_timer = 0.0

    def check_winner(self, world: 'Any', balls: 'List[Any]') -> 'Optional[str]':
        playing_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator"]
        if not playing_balls:
            return "Draw"

        team_status = {}
        for b in playing_balls:
            team = getattr(b, "team", None)
            if team:
                if team not in team_status:
                    team_status[team] = {"total": 0, "frozen": 0}
                team_status[team]["total"] += 1
                if getattr(b, "is_frozen", False):
                    team_status[team]["frozen"] += 1

        # A team wins if they have 0 frozen players across all their initial members
        winners = []
        for team, stats in team_status.items():
            if stats["frozen"] == 0 and stats["total"] > 0:
                winners.append(team)

        if len(winners) == 1:
            return winners[0]
        elif len(winners) > 1:
            return "Draw"

        return None

GAME_MODES['healer_freeze_tag'] = HealerFreezeTagMode()

class InvisibleGravityWellsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Invisible Gravity Wells"
        self.description = "Invisible gravity wells spawn randomly in the arena. If a player approaches within a certain radius, they are pulled towards the center, altering their movement vector continuously."
        self.spawn_timer = 0.0

    def tick(self, world, balls, delta=0.016):
        import random
        import math

        if not hasattr(world, "arena") or not hasattr(world.arena, "hazards"):
            return

        # Handle spawning invisible gravity wells
        self.spawn_timer += delta
        if self.spawn_timer >= 5.0: # spawn every 5 seconds
            self.spawn_timer = 0.0
            arena_width = getattr(world.arena, "width", 1000.0)
            arena_height = getattr(world.arena, "height", 1000.0)

            x = random.uniform(100.0, arena_width - 100.0)
            y = random.uniform(100.0, arena_height - 100.0)
            h_id = len(world.arena.hazards) + random.randint(10000, 99999)

            try:
                from arena.procedural_arena import Hazard
                well = Hazard(id=h_id, x=x, y=y, radius=200.0, kind="invisible_gravity_well", damage=0.0)
                well.duration = 15.0
                well.active = True
            except ImportError:
                class FallbackHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                        self.duration = 15.0
                        self.active = True
                well = FallbackHazard(id=h_id, x=x, y=y, radius=200.0, kind="invisible_gravity_well", damage=0.0)

            world.arena.hazards.append(well)

        to_remove = []
        for h in world.arena.hazards:
            if getattr(h, "kind", "") == "invisible_gravity_well":
                if hasattr(h, "duration"):
                    h.duration -= delta
                    if h.duration <= 0:
                        to_remove.append(h)
                        continue

                for b in balls:
                    if not getattr(b, "alive", False):
                        continue

                    bx = getattr(b, "x", 0.0)
                    by = getattr(b, "y", 0.0)
                    dx = h.x - bx
                    dy = h.y - by
                    dist = math.hypot(dx, dy)
                    h_radius = getattr(h, "radius", 200.0)

                    if dist <= h_radius:
                        if dist > 0.0001:
                            pull_strength = 200.0 * (1.0 - (dist / h_radius))
                            if not hasattr(b, "vx"): b.vx = 0.0
                            if not hasattr(b, "vy"): b.vy = 0.0
                            b.vx += (dx / dist) * pull_strength * delta
                            b.vy += (dy / dist) * pull_strength * delta

        for h in to_remove:
            if h in world.arena.hazards:
                world.arena.hazards.remove(h)

GAME_MODES['invisible_gravity_wells'] = InvisibleGravityWellsMode()


class IceWallsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Ice Walls"
        self.description = "The arena is surrounded by fragile ice walls. Hitting them at high speed shatters them, creating an abyss, but they regenerate over time."
        self.regeneration_timer = 0.0

    def start(self, world, balls):
        if not hasattr(world, "arena"):
            return
        if not hasattr(world.arena, "boundary_states"):
            world.arena.boundary_states = {}
        if not hasattr(world.arena, "boundary_health"):
            world.arena.boundary_health = {}
        for wall in ["top", "bottom", "left", "right"]:
            world.arena.boundary_states[wall] = "ice"
            world.arena.boundary_health[wall] = 2000.0

    def tick(self, world, balls, delta):
        if not hasattr(world, "arena"):
            return

        self.regeneration_timer += delta
        if self.regeneration_timer >= 5.0:  # Regenerate every 5 seconds
            self.regeneration_timer = 0.0

            if hasattr(world.arena, "boundary_health") and hasattr(world.arena, "boundary_states"):
                for wall in ["top", "bottom", "left", "right"]:
                    current_health = world.arena.boundary_health.get(wall, 2000.0)
                    current_state = world.arena.boundary_states.get(wall, "ice")

                    if current_state == "ice":
                        # Regenerate health slowly
                        if current_health < 2000.0:
                            world.arena.boundary_health[wall] = min(2000.0, current_health + 250.0)
                    else:
                        # Regenerate back to ice
                        world.arena.boundary_states[wall] = "ice"
                        world.arena.boundary_health[wall] = 1000.0 # Starts weaker when regenerating

                        # Shrink the hazard zone if it was expanded
                        if hasattr(world.arena, "boundary_offsets"):
                            world.arena.boundary_offsets[wall] = max(0.0, world.arena.boundary_offsets.get(wall, 0.0) - 50.0)


class LinkedPortalsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Linked Portals"
        self.description = "Pairs of teleportation pads that can be deployed across the map. Players or hazards passing over them instantly jump to the linked pad, keeping momentum intact for creative ambushes or escapes."
        self.portals = []
        self.spawn_timer = 0.0
        self.spawn_interval = 5.0

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        arena_w = getattr(world.arena, "width", 800) if hasattr(world, "arena") and world.arena else 800
        arena_h = getattr(world.arena, "height", 600) if hasattr(world, "arena") and world.arena else 600

        self.spawn_timer += delta
        if self.spawn_timer >= self.spawn_interval:
            self.spawn_timer -= self.spawn_interval

            import random
            p1 = {
                "x": random.uniform(50, max(50, arena_w - 50)),
                "y": random.uniform(50, max(50, arena_h - 50)),
                "radius": 30.0,
                "lifetime": 10.0,
                "linked_id": 1
            }
            p2 = {
                "x": random.uniform(50, max(50, arena_w - 50)),
                "y": random.uniform(50, max(50, arena_h - 50)),
                "radius": 30.0,
                "lifetime": 10.0,
                "linked_id": 0
            }
            p1["link"] = p2
            p2["link"] = p1
            self.portals.extend([p1, p2])
            if hasattr(world, "add_event"):
                world.add_event("portal_spawn", {"message": "A linked portal pair appeared!", "x": p1["x"], "y": p1["y"]})

        active_portals = []
        for portal in self.portals:
            portal["lifetime"] -= delta
            if portal["lifetime"] > 0:
                active_portals.append(portal)
        self.portals = active_portals

        # Check for teleportation
        for portal in self.portals:
            if portal.get("cooldown", 0) > 0:
                portal["cooldown"] -= delta
                continue

            px, py, pr = portal["x"], portal["y"], portal["radius"]
            for b in balls:
                if getattr(b, "alive", False):
                    dx = getattr(b, "x", 0.0) - px
                    dy = getattr(b, "y", 0.0) - py
                    import math
                    dist = math.sqrt(dx * dx + dy * dy)
                    if dist < pr + getattr(b, "radius", 10.0):
                        linked = portal["link"]

                        if hasattr(world, "add_event"):
                            world.add_event("teleport_out", {"message": "Teleported!", "x": getattr(b, "x", 0.0), "y": getattr(b, "y", 0.0)})

                        b.x = linked["x"]
                        b.y = linked["y"]
                        # Keep momentum intact

                        linked["cooldown"] = 0.5
                        portal["cooldown"] = 0.5

                        if hasattr(world, "add_event"):
                            world.add_event("teleport_in", {"message": "Arrived!", "x": getattr(b, "x", 0.0), "y": getattr(b, "y", 0.0)})
                        break

            if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                for h in world.arena.hazards:
                    dx = getattr(h, "x", 0.0) - px
                    dy = getattr(h, "y", 0.0) - py
                    import math
                    dist = math.sqrt(dx * dx + dy * dy)
                    if dist < pr + getattr(h, "radius", 10.0):
                        linked = portal["link"]
                        h.x = linked["x"]
                        h.y = linked["y"]
                        linked["cooldown"] = 0.5
                        portal["cooldown"] = 0.5
                        break

            if hasattr(world, "projectiles"):
                for p in world.projectiles:
                    if getattr(p, "alive", False) or getattr(p, "active", False):
                        dx = getattr(p, "x", 0.0) - px
                        dy = getattr(p, "y", 0.0) - py
                        import math
                        dist = math.sqrt(dx * dx + dy * dy)
                        if dist < pr + getattr(p, "radius", 5.0):
                            linked = portal["link"]
                            if hasattr(p, "x"):
                                p.x = linked["x"]
                            if hasattr(p, "y"):
                                p.y = linked["y"]
                            linked["cooldown"] = 0.5
                            portal["cooldown"] = 0.5
                            break


class WeatherCombinationsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Weather Combinations"
        self.description = "Capturing altars of different weather types combines their effects. E.g. Rain + Heatwave = Steam (obscures vision, drains stamina)."
        self.active_weathers = set()
        self.combined_weather = None
        self.altars = []

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        arena_w = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_h = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        self.altars = [
            {"x": arena_w * 0.25, "y": arena_h * 0.25, "radius": 150.0, "capture_progress": 0.0, "weather": "rain", "owner": None},
            {"x": arena_w * 0.75, "y": arena_h * 0.75, "radius": 150.0, "capture_progress": 0.0, "weather": "heatwave", "owner": None}
        ]

        self.active_weathers = set()
        self.combined_weather = None

        valid_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator"]
        for b in valid_balls:
            b.base_speed = getattr(b, "base_speed", getattr(b, "speed", 100.0))
            if not hasattr(b, "stamina"):
                b.stamina = 100.0
            if not hasattr(b, "max_stamina"):
                b.max_stamina = 100.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        if not hasattr(self, "altars"):
            return

        current_weathers = set()

        for altar in self.altars:
            teams_present = {}
            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                    bx = getattr(b, "x", 0.0)
                    by = getattr(b, "y", 0.0)
                    if not isinstance(bx, (int, float)): bx = 0.0
                    if not isinstance(by, (int, float)): by = 0.0
                    dist_sq = (bx - altar["x"])**2 + (by - altar["y"])**2
                    if dist_sq <= altar["radius"]**2:
                        team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                        teams_present[team] = teams_present.get(team, 0) + 1

                        if hasattr(b, "inventory") and "negative_modifier" in b.inventory:
                            b.inventory.remove("negative_modifier")
                            altar["sabotaged_by"] = team
                            if hasattr(world, "add_event"):
                                world.add_event("altar_sabotaged", {"team": team})

                        saboteur = altar.get("sabotaged_by")
                        if saboteur and saboteur != team:
                            b.hp = max(0.0, getattr(b, "hp", 100.0) - 15.0 * delta)

            if teams_present:
                max_team = max(teams_present, key=teams_present.get)
                is_tie = sum(1 for t, v in teams_present.items() if v == teams_present[max_team]) > 1
                if not is_tie:
                    if altar["owner"] == max_team:
                        if altar["capture_progress"] < 100.0:
                            altar["capture_progress"] = min(100.0, altar["capture_progress"] + 20.0 * delta)
                    else:
                        altar["capture_progress"] -= 20.0 * delta
                        if altar["capture_progress"] <= 0:
                            altar["owner"] = max_team
                            altar["capture_progress"] = 0.0

            else:
                altar["capture_progress"] = max(0.0, altar["capture_progress"] - 10.0 * delta)
                if altar["capture_progress"] == 0.0:
                    altar["owner"] = None

            if altar["capture_progress"] >= 100.0:
                current_weathers.add(altar["weather"])

        if current_weathers != self.active_weathers:
            self.active_weathers = current_weathers

            if "rain" in self.active_weathers and "heatwave" in self.active_weathers:
                self.combined_weather = "steam"
                if hasattr(world, "add_event"):
                    world.add_event("weather_change", {"weather": "steam", "message": "Steam obscures the arena!"})
            else:
                self.combined_weather = None

        # apply effects
        for b in balls:
            if not getattr(b, "alive", False):
                continue

            if not hasattr(b, "stamina"):
                b.stamina = 100.0
                b.max_stamina = 100.0

            base_speed = getattr(b, "base_speed", 100.0)

            if self.combined_weather == "steam":
                # Drain stamina
                b.stamina = max(0.0, b.stamina - 5.0 * delta)
                if b.stamina <= 0.0:
                    b.speed = base_speed * 0.5
                else:
                    b.speed = base_speed * 0.8 # reduced vision/speed
            else:
                # Recover stamina if no steam
                b.stamina = min(b.max_stamina, b.stamina + 10.0 * delta)

                # Apply single weather effects if any
                if "heatwave" in self.active_weathers and "rain" not in self.active_weathers:
                    b.speed = base_speed * 1.2
                elif "rain" in self.active_weathers and "heatwave" not in self.active_weathers:
                    b.speed = base_speed * 0.9
                else:
                    b.speed = base_speed

GAME_MODES['weather_combinations'] = WeatherCombinationsMode()

GAME_MODES['ice_walls'] = IceWallsMode()
GAME_MODES['pinball_mutator'] = PinballMutatorMode()
GAME_MODES['linked_portals'] = LinkedPortalsMode()


class VIPProtectionMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Spectral VIP Protection"
        self.description = "One player per team becomes a Spectral VIP. They cannot attack, are highly vulnerable, but emit a constant healing aura for teammates."
        self.vips = {}
        self.heal_radius = 200.0
        self.heal_rate = 15.0  # HP per second
        self.vip_setup_done = False

    def setup(self, world, balls):
        super().setup(world, balls)
        self.vips = {}
        self.vip_setup_done = False

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        # Group balls by team
        teams = {}
        active_balls = [b for b in balls if getattr(b, 'alive', False)]
        for b in active_balls:
            t = getattr(b, 'team', 0)
            if t not in teams:
                teams[t] = []
            teams[t].append(b)

        if not self.vip_setup_done and active_balls:
            import random
            for t, team_balls in teams.items():
                if team_balls:
                    # Pick a random VIP for each team
                    vip = random.choice(team_balls)
                    self.vips[t] = getattr(vip, 'id', id(vip))
                    vip.is_vip = True
                    # VIP traits: no attack, vulnerable
                    vip.damage = 0.0
                    vip.base_damage = 0.0
                    if hasattr(world, "add_event"):
                        world.add_event("visual_effect", {"type": "vip_aura", "x": vip.x, "y": vip.y, "team": t})
            self.vip_setup_done = True

        # Process healing aura and vulnerability
        # Collect HP deltas
        hp_deltas = {}
        import random
        for t, team_balls in teams.items():
            if t not in self.vips:
                continue

            vip_id = self.vips[t]
            vip_ball = None
            for b in team_balls:
                if getattr(b, 'id', id(b)) == vip_id:
                    vip_ball = b
                    break

            if vip_ball and getattr(vip_ball, 'alive', False):
                # Ensure VIP cannot attack
                vip_ball.damage = 0.0
                vip_ball.base_damage = 0.0
                vip_ball.energy_shield_active = False # VIP is vulnerable
                vip_ball.energy_shield_hp = 0.0

                # Heal teammates
                for b in team_balls:
                    if b == vip_ball:
                        continue
                    if not getattr(b, 'alive', False):
                        continue

                    dist_sq = (b.x - vip_ball.x)**2 + (b.y - vip_ball.y)**2
                    if dist_sq < (self.heal_radius + getattr(b, 'radius', 10.0) + getattr(vip_ball, 'radius', 10.0))**2:
                        heal_amount = self.heal_rate * delta
                        hp_deltas[getattr(b, 'id', id(b))] = hp_deltas.get(getattr(b, 'id', id(b)), 0.0) + heal_amount

                        if hasattr(world, "add_event"):
                            if random.random() < 0.1:
                                world.add_event("visual_effect", {"type": "heal_tick", "x": b.x, "y": b.y})

        # Apply healing
        for b in active_balls:
            b_id = getattr(b, 'id', id(b))
            if b_id in hp_deltas:
                # IMPORTANT: ensure we apply heal up to max_hp, but max_hp is 100 default
                b.hp = min(getattr(b, 'max_hp', 100.0), b.hp + hp_deltas[b_id])

GAME_MODES['vip_protection'] = VIPProtectionMode()

GAME_MODES['elemental_chain_reactions'] = ElementalChainReactionMode()


class GravityShiftMode(GameMode):
    def __init__(self):
        super().__init__()
        self.id = "Gravity Shift"
        self.name = "Gravity Shift"
        self.description = "Gravity occasionally shifts, pulling balls towards the edges or a random point. High prestige players can deploy anchors."
        self.shift_timer = 0.0
        self.shift_duration = 0.0
        self.shift_type = None
        self.shift_point = (0.0, 0.0)
        self.shift_strength = 200.0
        self.anchor_duration = 5.0
        self.anchors = []

    def setup(self, world: Any, balls: List[Any]):
        super().setup(world, balls)
        self.shift_timer = getattr(self, "random", __import__("random")).uniform(5.0, 15.0)

    def tick(self, world: Any, balls: List[Any], delta: float):
        super().tick(world, balls, delta)

        # Manage anchors
        for anchor in self.anchors[:]:
            anchor['timer'] -= delta
            if anchor['timer'] <= 0:
                self.anchors.remove(anchor)

        if self.shift_duration > 0:
            self.shift_duration -= delta

            for b in balls:
                if not getattr(b, 'alive', True) or not getattr(b, 'active', True): continue
                if getattr(b, 'ball_type', None) == 'spectator': continue

                # Check for anchor
                is_anchored = False
                for anchor in self.anchors:
                    if anchor['owner_id'] == getattr(b, 'id', None):
                        is_anchored = True
                        break

                if is_anchored: continue

                # Apply gravity
                if self.shift_type == 'point':
                    dx = self.shift_point[0] - b.x
                    dy = self.shift_point[1] - b.y
                    dist = (dx**2 + dy**2)**0.5
                    if dist > 0:
                        gravity_mult = -1.0 if getattr(b, "in_reverse_physics_zone", False) else 1.0
                        b.vx += (dx/dist) * self.shift_strength * delta * gravity_mult
                        b.vy += (dy/dist) * self.shift_strength * delta * gravity_mult
                elif self.shift_type == 'edges':
                    # Push towards nearest edge (assuming standard arena bounds [-300, 300])
                    # We'll just push outwards from center
                    dist = (b.x**2 + b.y**2)**0.5
                    if dist > 0:
                        gravity_mult = -1.0 if getattr(b, "in_reverse_physics_zone", False) else 1.0
                        b.vx += (b.x/dist) * self.shift_strength * delta * gravity_mult
                        b.vy += (b.y/dist) * self.shift_strength * delta * gravity_mult

        else:
            self.shift_timer -= delta
            if self.shift_timer <= 0:
                self.shift_duration = getattr(self, "random", __import__("random")).uniform(3.0, 8.0)
                self.shift_timer = getattr(self, "random", __import__("random")).uniform(10.0, 20.0)
                self.shift_type = getattr(self, "random", __import__("random")).choice(['point', 'edges'])
                if self.shift_type == 'point':
                    self.shift_point = (getattr(self, "random", __import__("random")).uniform(-200, 200), getattr(self, "random", __import__("random")).uniform(-200, 200))
                if hasattr(world, 'add_event'):
                    world.add_event("gravity_shift", {"type": self.shift_type, "duration": self.shift_duration})

        # Player input for anchor
        for b in balls:
            if not getattr(b, 'alive', True) or not getattr(b, 'active', True): continue

            # Simulated player input checking (action or key press)
            # In AI script context, we might check an action flag
            if getattr(b, 'prestige', 0) >= 3 and getattr(b, 'action_deploy_anchor', False):
                b.action_deploy_anchor = False # Consume intent

                # Check cooldown
                if getattr(b, 'anchor_cooldown', 0) <= 0:
                    b.anchor_cooldown = 15.0
                    self.anchors.append({'owner_id': getattr(b, 'id', None), 'x': b.x, 'y': b.y, 'timer': self.anchor_duration})
                    if hasattr(world, 'add_event'):
                        world.add_event("anchor_deployed", {"owner": getattr(b, 'id', None)})

            if hasattr(b, 'anchor_cooldown'):
                b.anchor_cooldown -= delta


class RandomGravityShiftMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Random Gravity Shift"
        self.description = "A mode where gravity periodically shifts in random directions."
        self.shift_timer = 0.0
        self.shift_interval = 15.0
        self.gravity_dir_x = 0.0
        self.gravity_dir_y = 1.0
        self.gravity_strength = 300.0
        import random
        self.random = random

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.apply_dynamic_traits(world, balls, delta)
        self.shift_timer -= delta
        if self.shift_timer <= 0:
            self.shift_timer = self.shift_interval
            import math
            angle = self.random.uniform(0, 2 * math.pi)
            self.gravity_dir_x = math.cos(angle)
            self.gravity_dir_y = math.sin(angle)
            if hasattr(world, 'add_event'):
                world.add_event("gravity_shift", {"message": "Gravity shifted!"})

        for b in balls:
            if not getattr(b, 'alive', True) or not getattr(b, 'active', True):
                continue
            if getattr(b, 'ball_type', None) == 'spectator':
                continue

            mass = getattr(b, 'mass', 1.0)
            gravity_mult = -1.0 if getattr(b, "in_reverse_physics_zone", False) else 1.0

            # Lower mass is affected more strongly.
            mass_effect = 1.0 / max(mass, 0.1)

            is_juggernaut = getattr(b, 'ball_type', None) == 'juggernaut' or getattr(b, 'juggernaut_booster_timer', 0.0) > 0 or mass >= 2.0
            if is_juggernaut:
                mass_effect *= 0.5  # more resistant
                if hasattr(b, 'stamina'):
                    b.stamina = max(0.0, b.stamina - 40.0 * delta)

            if hasattr(b, 'vx'):
                b.vx += self.gravity_strength * self.gravity_dir_x * mass_effect * delta * gravity_mult
            if hasattr(b, 'vy'):
                b.vy += self.gravity_strength * self.gravity_dir_y * mass_effect * delta * gravity_mult

        if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
            for h in world.arena.hazards:
                mass = getattr(h, 'mass', 1.0)
                if hasattr(h, 'vx'):
                    h.vx += self.gravity_strength * self.gravity_dir_x * mass * delta
                if hasattr(h, 'vy'):
                    h.vy += self.gravity_strength * self.gravity_dir_y * mass * delta


GAME_MODES['gravity_shift'] = GravityShiftMode()
GAME_MODES['random_gravity_shift'] = RandomGravityShiftMode()



class WaterfallsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Waterfalls"
        self.description = "A waterfall hazard periodically appears. Balls caught in it are pulled to the center and then dropped to a lower arena layer, briefly disabling their attacks while they fall."
        self.spawn_timer = 5.0
        import random
        self.random = random

    def setup(self, world, balls):
        super().setup(world, balls)
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)
        self.spawn_timer -= delta
        if self.spawn_timer <= 0:
            self.spawn_timer = self.random.uniform(10.0, 20.0)
            if hasattr(world, "arena"):
                aw = getattr(world.arena, "width", 1000)
                ah = getattr(world.arena, "height", 1000)
                class Hazard:
                    def __init__(self, id, x, y, radius, kind, damage, duration):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                        self.duration = duration
                        self.vx = 0.0
                        self.vy = 0.0
                        self.active = True
                hz = Hazard(id=len(getattr(world.arena, "hazards", [])) + self.random.randint(1000, 9999), x=self.random.uniform(200, aw-200), y=self.random.uniform(200, ah-200), radius=120.0, kind="waterfall", damage=0.0, duration=15.0)
                if hasattr(world.arena, "hazards"):
                    world.arena.hazards.append(hz)
                    if hasattr(world, "add_event"):
                        world.add_event("hazard_spawned", {"kind": "waterfall", "x": hz.x, "y": hz.y})

        # Process waterfalls and falling state
        for b in balls:
            if not getattr(b, "alive", False): continue

            # Decrease falling timer and prevent attacks
            if getattr(b, "waterfall_fall_timer", 0.0) > 0.0:
                if not hasattr(b, "waterfall_cached_damage"):
                    b.waterfall_cached_damage = getattr(b, "damage", 10.0)
                    b.waterfall_cached_base_damage = getattr(b, "base_damage", 10.0)
                b.waterfall_fall_timer -= delta
                b.damage = 0.0
                b.base_damage = 0.0
                if b.waterfall_fall_timer <= 0.0:
                    b.waterfall_fall_timer = 0.0
                    b.damage = getattr(b, "waterfall_cached_damage", 10.0)
                    b.base_damage = getattr(b, "waterfall_cached_base_damage", 10.0)

            if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                for hz in world.arena.hazards:
                    if getattr(hz, "kind", "") == "waterfall":
                        hx, hy = getattr(hz, "x", 0.0), getattr(hz, "y", 0.0)
                        hr = getattr(hz, "radius", 0.0)
                        dx = hx - b.x
                        dy = hy - b.y
                        dist_sq = dx*dx + dy*dy
                        if dist_sq < hr*hr:
                            dist = dist_sq**0.5
                            if dist > 0:
                                nx = dx / dist
                                ny = dy / dist
                                pull = 80.0 * delta
                                # Pull logic
                                if getattr(b, "anchor_booster_timer", 0.0) <= 0:
                                    b.x += nx * pull
                                    b.y += ny * pull

                                # Drop logic if close to center
                                if dist < 15.0 and getattr(b, "waterfall_fall_timer", 0.0) <= 0.0:
                                    b.z_layer = getattr(b, "z_layer", 0) - 1
                                    b.waterfall_fall_timer = 2.0

class FallingTilesRoyaleMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Falling Tiles Royale"
        self.description = "A battle royale variant where the arena is made up of a grid of tiles. Every few seconds, some tiles light up and then fall away, turning into bottomless pits."
        self.grid_size = 50.0
        self.tiles = {}
        self.timer = 0.0
        self.phase = "wait"
        self.warning_duration = 2.0
        self.fall_duration = 3.0
        self.active_tiles = []
        self.falling_tiles = []
        self.is_falling_tiles_royale = True
        import random
        self.random = random

    def setup(self, world, balls):
        super().setup(world, balls)
        self.tiles = {}
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        self.cols = int(arena_width / self.grid_size)
        self.rows = int(arena_height / self.grid_size)

        for c in range(self.cols):
            for r in range(self.rows):
                self.tiles[(c, r)] = {"state": "normal"} # normal, warning, falling, pit

        self.timer = 5.0
        self.phase = "wait"

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        self.timer -= delta

        if self.phase == "wait":
            if self.timer <= 0:
                self.phase = "warning"
                self.timer = self.warning_duration
                # Pick some tiles to light up
                normal_tiles = [k for k, v in self.tiles.items() if v["state"] == "normal"]
                num_to_fall = max(1, int(len(normal_tiles) * 0.1))
                if num_to_fall > len(normal_tiles) - 4:
                    num_to_fall = max(1, len(normal_tiles) - 4) # leave some

                self.falling_tiles = self.random.sample(normal_tiles, min(num_to_fall, len(normal_tiles)))
                for k in self.falling_tiles:
                    self.tiles[k]["state"] = "warning"

                if hasattr(world, "add_event"):
                    world.add_event("tiles_warning", {"message": "Some tiles are lighting up!", "tiles": self.falling_tiles})

        elif self.phase == "warning":
            if self.timer <= 0:
                self.phase = "falling"
                self.timer = self.fall_duration
                for k in self.falling_tiles:
                    self.tiles[k]["state"] = "falling"
                if hasattr(world, "add_event"):
                    world.add_event("tiles_falling", {"message": "Tiles are falling!", "tiles": self.falling_tiles})

        elif self.phase == "falling":
            if self.timer <= 0:
                self.phase = "wait"
                self.timer = getattr(self.random, "uniform", lambda a,b: 5.0)(4.0, 8.0)
                if hasattr(world, "add_event"):
                    world.add_event("tiles_pit", {"message": "Tiles have fallen!", "tiles": self.falling_tiles})
                for k in self.falling_tiles:
                    self.tiles[k]["state"] = "pit"
                self.falling_tiles = []

        # Handle balls over pits
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            bx, by = getattr(b, "x", 0.0), getattr(b, "y", 0.0)
            c = int(bx / self.grid_size)
            r = int(by / self.grid_size)

            if (c, r) in self.tiles:
                state = self.tiles[(c, r)]["state"]
                if state == "pit":
                    # Instant death or massive damage
                    if hasattr(b, "take_damage"):
                        b.take_damage(9999.0)
                    else:
                        b.hp = 0.0
                        b.alive = False

                    if not getattr(b, "alive", False) and hasattr(world, "add_event"):
                        world.add_event("ball_fell", {"id": getattr(b, "id", None)})


class QuadrantRoyaleMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Quadrant Royale"
        self.description = "The arena is divided into four quadrants, each with its own shrinking safe zone. Portals periodically appear to allow travel between quadrants."
        self.quadrants = {}
        self.portals = []
        self.portal_spawn_timer = 0.0
        self.damage_per_second = 20.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        self.quadrants = {
            0: {"x": arena_width * 0.25, "y": arena_height * 0.25, "radius": min(arena_width, arena_height) * 0.25, "shrink_rate": 5.0},
            1: {"x": arena_width * 0.75, "y": arena_height * 0.25, "radius": min(arena_width, arena_height) * 0.25, "shrink_rate": 7.0},
            2: {"x": arena_width * 0.25, "y": arena_height * 0.75, "radius": min(arena_width, arena_height) * 0.25, "shrink_rate": 6.0},
            3: {"x": arena_width * 0.75, "y": arena_height * 0.75, "radius": min(arena_width, arena_height) * 0.25, "shrink_rate": 8.0}
        }
        self.portals = []
        self.portal_spawn_timer = 0.0

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random
        import math

        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        for q_id, q_data in self.quadrants.items():
            if q_data["radius"] > 30.0:
                q_data["radius"] -= q_data["shrink_rate"] * delta
                if q_data["radius"] < 30.0:
                    q_data["radius"] = 30.0

        self.portal_spawn_timer += delta
        if self.portal_spawn_timer > 10.0:
            self.portal_spawn_timer = 0.0
            if len(self.portals) < 8:
                keys = list(self.quadrants.keys())
                random.shuffle(keys)
                q1_id = keys[0]
                q2_id = keys[1]
                q1 = self.quadrants[q1_id]
                q2 = self.quadrants[q2_id]

                p1_x = q1["x"]
                p1_y = q1["y"]
                p2_x = q2["x"]
                p2_y = q2["y"]

                portal_id_1 = len(self.portals) + 1
                portal_id_2 = len(self.portals) + 2

                self.portals.append({
                    "id": portal_id_1, "x": p1_x, "y": p1_y, "radius": 30.0, "target_x": p2_x, "target_y": p2_y, "cooldown": 0.0
                })
                self.portals.append({
                    "id": portal_id_2, "x": p2_x, "y": p2_y, "radius": 30.0, "target_x": p1_x, "target_y": p1_y, "cooldown": 0.0
                })

                if hasattr(world, "add_event"):
                    world.add_event("portal_spawned", {"x": p1_x, "y": p1_y})
                    world.add_event("portal_spawned", {"x": p2_x, "y": p2_y})

        for p in self.portals:
            if p["cooldown"] > 0:
                p["cooldown"] -= delta

        for b in balls:
            if not getattr(b, "alive", True) or getattr(b, "ball_type", None) == "spectator":
                continue

            bx = getattr(b, "x", 0.0)
            by = getattr(b, "y", 0.0)
            radius = getattr(b, "radius", 15.0)

            teleported = False
            for p in self.portals:
                if p["cooldown"] <= 0.0:
                    dist_sq = (bx - p["x"])**2 + (by - p["y"])**2
                    if dist_sq < (radius + p["radius"])**2:
                        b.x = p["target_x"]
                        b.y = p["target_y"]
                        p["cooldown"] = 2.0

                        for twin in self.portals:
                            if twin["x"] == p["target_x"] and twin["y"] == p["target_y"]:
                                twin["cooldown"] = 2.0
                                break

                        teleported = True
                        if hasattr(world, "add_event"):
                            world.add_event("teleported", {"ball_id": getattr(b, "id", None)})
                        break

            if teleported:
                bx = b.x
                by = b.y
                # Add a brief invulnerability/cooldown to the ball to prevent chain-teleporting
                if hasattr(world, "add_event"):
                    # Give it a small offset so it's not perfectly centered on the portal
                    import random
                    b.x += random.uniform(-10.0, 10.0)
                    b.y += random.uniform(-10.0, 10.0)
                    bx = b.x
                    by = b.y

            q_id = 0
            if bx > arena_width / 2.0: q_id += 1
            if by > arena_height / 2.0: q_id += 2

            q_data = self.quadrants.get(q_id)
            if q_data:
                dist = math.hypot(bx - q_data["x"], by - q_data["y"])
                if dist > q_data["radius"]:
                    if hasattr(b, "take_damage"):
                        b.take_damage(self.damage_per_second * delta)
                    else:
                        b.hp = getattr(b, "hp", 100.0) - self.damage_per_second * delta
                        if b.hp <= 0.0:
                            b.alive = False

GAME_MODES['waterfalls_mode'] = WaterfallsMode()
GAME_MODES['falling_tiles_royale'] = FallingTilesRoyaleMode()
GAME_MODES['tilting_platform'] = TiltingPlatformMode()

