class WindstormEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Windstorm Event"
        self.description = "A global event that causes a massive windstorm, periodically knocking all balls back in a specific direction and increasing chaotic movement."
        self.push_timer = 3.0
        self.push_duration = 0.0
        self.push_dir_x = 0.0
        self.push_dir_y = 0.0
        self.push_strength = 800.0

        self.event_timer = 20.0
        self.event_duration = 10.0
        self.is_active = False
        import random
        self.random = random

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        if not self.is_active:
            self.event_timer -= delta
            if self.event_timer <= 0.0:
                self.is_active = True
                self.event_duration = 10.0
                if hasattr(world, "add_event"):
                    world.add_event("windstorm_event_start", {"message": "A massive windstorm is blowing through the arena!"})
                # Immediately start a push
                self.push_timer = 0.0
        else:
            self.event_duration -= delta
            if self.event_duration <= 0.0:
                self.is_active = False
                self.event_timer = 20.0
                self.push_duration = 0.0
                if hasattr(world, "add_event"):
                    world.add_event("windstorm_event_end", {"message": "The windstorm has passed."})
            else:
                self.push_timer -= delta
                if self.push_timer <= 0.0:
                    if self.push_duration <= 0.0:
                        import math
                        angle = self.random.uniform(0, 2 * math.pi)
                        self.push_dir_x = math.cos(angle)
                        self.push_dir_y = math.sin(angle)
                        self.push_duration = self.random.uniform(1.5, 2.5)
                        if hasattr(world, "add_event"):
                            world.add_event("windstorm_gust", {"message": "A strong gust of wind hits!"})
                    else:
                        self.push_duration -= delta
                        if self.push_duration <= 0.0:
                            self.push_timer = self.random.uniform(2.0, 4.0)

                if self.push_duration > 0.0:
                    for b in balls:
                        if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                            if not hasattr(b, "vx"):
                                b.vx = 0.0
                            if not hasattr(b, "vy"):
                                b.vy = 0.0
                            b.vx += self.push_dir_x * self.push_strength * delta
                            b.vy += self.push_dir_y * self.push_strength * delta

                            import math
                            v_mag = math.hypot(b.vx, b.vy)
                            if v_mag > 0.01:
                                dot = (b.vx / v_mag) * self.push_dir_x + (b.vy / v_mag) * self.push_dir_y
                                if dot > 0.3:
                                    b.vx += self.push_dir_x * self.push_strength * dot * 2.0 * delta
                                    b.vy += self.push_dir_y * self.push_strength * dot * 2.0 * delta
                                    b.speed_boost_timer = getattr(b, "speed_boost_timer", 0.0) + delta * 2.0

                    if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
                        for h in world.arena.hazards:
                            if hasattr(h, 'vx') and hasattr(h, 'vy'):
                                h.vx += self.push_dir_x * self.push_strength * delta
                                h.vy += self.push_dir_y * self.push_strength * delta
                            elif hasattr(h, 'x') and hasattr(h, 'y'):
                                h.x += self.push_dir_x * self.push_strength * delta
                                h.y += self.push_dir_y * self.push_strength * delta

class SolarWindstormEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Solar Windstorm Event"
        self.description = "A weather event that randomly applies push forces across the entire arena while drastically increasing the effectiveness of all solar-powered abilities and boosting energy regeneration. Movement against the wind costs extra stamina."
        self.push_timer = 3.0
        self.push_duration = 0.0
        self.push_dir_x = 0.0
        self.push_dir_y = 0.0
        self.push_strength = 700.0

        self.event_timer = 20.0
        self.event_duration = 15.0
        self.is_active = False
        import random
        self.random = random

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        if not self.is_active:
            self.event_timer -= delta
            if self.event_timer <= 0.0:
                self.is_active = True
                self.event_duration = 15.0
                if hasattr(world, "add_event"):
                    world.add_event("solar_windstorm_event_start", {"message": "A solar windstorm is blowing through the arena! Solar abilities are boosted!"})
                # Immediately start a push
                self.push_timer = 0.0
        else:
            self.event_duration -= delta
            if self.event_duration <= 0.0:
                self.is_active = False
                self.event_timer = 20.0
                self.push_duration = 0.0
                if hasattr(world, "add_event"):
                    world.add_event("solar_windstorm_event_end", {"message": "The solar windstorm has passed."})
            else:
                self.push_timer -= delta
                if self.push_timer <= 0.0:
                    if self.push_duration <= 0.0:
                        import math
                        angle = self.random.uniform(0, 2 * math.pi)
                        self.push_dir_x = math.cos(angle)
                        self.push_dir_y = math.sin(angle)
                        self.push_duration = self.random.uniform(1.5, 3.0)
                        if hasattr(world, "add_event"):
                            world.add_event("solar_wind_gust", {"message": "A strong gust of solar wind hits!"})
                    else:
                        self.push_duration -= delta
                        if self.push_duration <= 0.0:
                            self.push_timer = self.random.uniform(2.0, 4.0)

                if self.push_duration > 0.0:
                    import math
                    for b in balls:
                        if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                            if not hasattr(b, "vx"):
                                b.vx = 0.0
                            if not hasattr(b, "vy"):
                                b.vy = 0.0

                            # Push force
                            b.vx += self.push_dir_x * self.push_strength * delta
                            b.vy += self.push_dir_y * self.push_strength * delta

                            v_mag = math.hypot(b.vx, b.vy)
                            if v_mag > 0.01:
                                # Dot product of current velocity with wind direction
                                dot = (b.vx / v_mag) * self.push_dir_x + (b.vy / v_mag) * self.push_dir_y

                                # Extra stamina cost for moving against the wind
                                if dot < -0.3:
                                    if hasattr(b, "stamina"):
                                        stamina_drain = 20.0 * abs(dot) * delta
                                        b.stamina = max(0.0, b.stamina - stamina_drain)

                                # Increase speed if moving with the wind
                                if dot > 0.3:
                                    b.vx += self.push_dir_x * self.push_strength * dot * 1.5 * delta
                                    b.vy += self.push_dir_y * self.push_strength * dot * 1.5 * delta

                        # Boost energy regeneration for everyone in the solar wind
                        if getattr(b, "alive", False):
                            if hasattr(b, "stamina"):
                                b.stamina = min(getattr(b, "max_stamina", 100.0), b.stamina + 10.0 * delta)

                            if hasattr(b, "energy"):
                                b.energy = min(getattr(b, "max_energy", 100.0), b.energy + 10.0 * delta)

                            # Drastically boost solar-powered abilities
                            if getattr(b, "ball_type", "") == "solar_bot":
                                b.hp = min(getattr(b, "max_hp", 100.0), getattr(b, "hp", 100.0) + 15.0 * delta)
                                b.speed_multiplier = max(getattr(b, "speed_multiplier", 1.0), 1.5)

                    if hasattr(world, 'arena') and hasattr(world.arena, 'hazards'):
                        for h in world.arena.hazards:
                            if hasattr(h, 'vx') and hasattr(h, 'vy'):
                                h.vx += self.push_dir_x * self.push_strength * delta
                                h.vy += self.push_dir_y * self.push_strength * delta
                            elif hasattr(h, 'x') and hasattr(h, 'y'):
                                h.x += self.push_dir_x * self.push_strength * delta
                                h.y += self.push_dir_y * self.push_strength * delta


class VolcanicEruptionEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Volcanic Eruption Event"
        self.description = "A global event that causes the center of the arena to periodically erupt, showering random locations across the map with burning projectiles that leave lingering lava puddles. Provides chaotic area denial."
        self.eruption_timer = 20.0
        self.eruption_duration = 5.0
        self.is_erupting = False

        self.projectile_spawn_timer = 0.0
        self.projectile_spawn_interval = 0.5

        self.center_x = 1000.0
        self.center_y = 1000.0

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        arena_width = getattr(world.arena, "width", 2000.0) if hasattr(world, "arena") else 2000.0
        arena_height = getattr(world.arena, "height", 2000.0) if hasattr(world, "arena") else 2000.0

        self.center_x = arena_width / 2.0
        self.center_y = arena_height / 2.0

        if not self.is_erupting:
            self.eruption_timer -= delta
            if self.eruption_timer <= 0.0:
                self.is_erupting = True
                self.eruption_duration = 5.0
                if hasattr(world, "add_event"):
                    world.add_event("volcanic_eruption_start", {"message": "The arena center is erupting!"})
        else:
            self.eruption_duration -= delta
            if self.eruption_duration <= 0.0:
                self.is_erupting = False
                self.eruption_timer = 20.0
                if hasattr(world, "add_event"):
                    world.add_event("volcanic_eruption_end", {"message": "The eruption has subsided."})
            else:
                self.projectile_spawn_timer -= delta
                if self.projectile_spawn_timer <= 0.0:
                    self.projectile_spawn_timer = self.projectile_spawn_interval

                    import random
                    target_x = random.uniform(50.0, arena_width - 50.0)
                    target_y = random.uniform(50.0, arena_height - 50.0)

                    try:
                        from arena.procedural_arena import Hazard
                        HazardClass = Hazard
                    except ImportError:
                        class FallbackHazard:
                            def __init__(self, id, x, y, radius, kind, damage):
                                self.id = id
                                self.x = x
                                self.y = y
                                self.radius = radius
                                self.kind = kind
                                self.damage = damage
                                self.active = True
                        HazardClass = FallbackHazard

                    if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                        t_id = len(world.arena.hazards) + random.randint(10000, 99999)
                        projectile = HazardClass(id=t_id, x=self.center_x, y=self.center_y, radius=15.0, kind="lava_projectile", damage=25.0)
                        setattr(projectile, "target_x", target_x)
                        setattr(projectile, "target_y", target_y)

                        import math
                        dx = target_x - self.center_x
                        dy = target_y - self.center_y
                        dist = math.hypot(dx, dy)
                        speed = 800.0
                        setattr(projectile, "vx", (dx/dist)*speed if dist > 0 else 0.0)
                        setattr(projectile, "vy", (dy/dist)*speed if dist > 0 else 0.0)
                        setattr(projectile, "duration", dist / speed if speed > 0 else 1.0)

                        world.arena.hazards.append(projectile)

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            to_remove = []
            to_add = []
            for h in list(world.arena.hazards):
                kind = getattr(h, "kind", "")
                if kind == "lava_projectile":
                    h.x += getattr(h, "vx", 0.0) * delta
                    h.y += getattr(h, "vy", 0.0) * delta

                    if hasattr(h, "duration"):
                        h.duration -= delta
                        if h.duration <= 0.0:
                            to_remove.append(h)
                            try:
                                from arena.procedural_arena import Hazard
                                HazardClass = Hazard
                            except ImportError:
                                class FallbackHazard:
                                    def __init__(self, id, x, y, radius, kind, damage):
                                        self.id = id
                                        self.x = x
                                        self.y = y
                                        self.radius = radius
                                        self.kind = kind
                                        self.damage = damage
                                        self.active = True
                                HazardClass = FallbackHazard

                            import random
                            t_id = len(world.arena.hazards) + random.randint(10000, 99999)
                            lava = HazardClass(id=t_id, x=h.x, y=h.y, radius=40.0, kind="lava", damage=20.0)
                            setattr(lava, "duration", 10.0)
                            to_add.append(lava)

                elif kind == "lava":
                    if hasattr(h, "duration"):
                        h.duration -= delta
                        if h.duration <= 0.0:
                            to_remove.append(h)

            for h in to_remove:
                if h in world.arena.hazards:
                    world.arena.hazards.remove(h)
            for h in to_add:
                world.arena.hazards.append(h)

GAME_MODES['windstorm_event'] = WindstormEventMode()
