class AuctionEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Hidden Item Auction"
        self.description = "Periodically, a hidden artifact goes up for auction among alive players. They can bid their gold to win the artifact, which grants permanent buffs."
        self.auction_timer = 20.0
        self.auction_active = False
        self.auction_duration = 5.0
        self.current_bid = 0
        self.highest_bidder = None
        self.artifact_stats = {"max_hp": 50.0, "base_speed": 20.0, "base_damage": 10.0}

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random

        alive_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]
        if not alive_balls:
            return

        if not self.auction_active:
            self.auction_timer -= delta
            if self.auction_timer <= 0:
                self.auction_active = True
                self.auction_duration = 5.0
                self.current_bid = 10
                self.highest_bidder = None
                # Create random stats for the artifact
                self.artifact_stats = {
                    "max_hp": random.randint(20, 100),
                    "base_speed": random.randint(10, 40),
                    "base_damage": random.randint(5, 25)
                }
                if hasattr(world, "add_event"):
                    world.add_event("auction_started", {"starting_bid": self.current_bid})
        else:
            self.auction_duration -= delta

            # Simulated AI bidding logic: balls bid if they have enough gold
            for b in alive_balls:
                gold = getattr(b, "gold", 0)
                if gold > self.current_bid and self.highest_bidder != b and random.random() < 2.0 * delta:
                    bid_amount = self.current_bid + max(1, int((gold - self.current_bid) * random.random() * 0.5))
                    self.current_bid = bid_amount
                    self.highest_bidder = b
                    if hasattr(world, "add_event"):
                        world.add_event("auction_bid", {"bidder_id": getattr(b, "id", None), "amount": bid_amount})

            if self.auction_duration <= 0:
                self.auction_active = False
                self.auction_timer = random.uniform(20.0, 40.0)
                if self.highest_bidder:
                    # Deduct gold and award stats
                    self.highest_bidder.gold -= self.current_bid
                    self.highest_bidder.max_hp = getattr(self.highest_bidder, "max_hp", 100.0) + self.artifact_stats["max_hp"]
                    self.highest_bidder.hp = getattr(self.highest_bidder, "hp", 100.0) + self.artifact_stats["max_hp"]
                    self.highest_bidder.base_speed = getattr(self.highest_bidder, "base_speed", 100.0) + self.artifact_stats["base_speed"]
                    self.highest_bidder.base_damage = getattr(self.highest_bidder, "base_damage", 10.0) + self.artifact_stats["base_damage"]
                    if hasattr(world, "add_event"):
                        world.add_event("auction_won", {
                            "winner_id": getattr(self.highest_bidder, "id", None),
                            "cost": self.current_bid,
                            "stats": self.artifact_stats
                        })
                else:
                    if hasattr(world, "add_event"):
                        world.add_event("auction_failed", {})

GAME_MODES['auction_event'] = AuctionEventMode()


class BountyExtractionMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Bounty Extraction"
        self.description = "Players collect bounty tags from fallen enemies. Bringing bounty tags to safe extraction zones gives currency that can be spent on persistent upgrades during the match."
        self.extraction_zone_x = 500.0
        self.extraction_zone_y = 500.0
        self.extraction_zone_radius = 200.0
        self.extraction_timer = 0.0
        self.bounty_tags = []

    def on_ball_died(self, world, ball, killer=None):
        if hasattr(super(), "on_ball_died"):
            super().on_ball_died(world, ball, killer)

        # Spawn a bounty tag where the ball died
        tag = {
            "x": getattr(ball, "x", 0.0),
            "y": getattr(ball, "y", 0.0),
            "type": "bounty_tag",
            "value": getattr(ball, "currency", 0) + 1  # Drop held currency + 1 for themselves
        }
        self.bounty_tags.append(tag)
        if hasattr(world, "boosters"):
            world.boosters.append(tag)
        if hasattr(world, "add_event"):
            world.add_event("tag_spawned", {"x": tag["x"], "y": tag["y"], "value": tag["value"]})

    def apply_dynamic_traits(self, world, balls, delta):
        # Move extraction zone occasionally
        self.extraction_timer -= delta
        if self.extraction_timer <= 0:
            self.extraction_timer = 30.0
            import random
            random.seed(int(getattr(world, "tick_timer", 0.0) * 1000) + len(self.bounty_tags))
            # Just simple bounds for extraction zone
            self.extraction_zone_x = random.uniform(200, 800)
            self.extraction_zone_y = random.uniform(200, 800)
            random.seed() # reset seed
            if hasattr(world, "add_event"):
                world.add_event("extraction_zone_moved", {"x": self.extraction_zone_x, "y": self.extraction_zone_y})

        # Process tags and extraction for alive balls
        for b in balls:
            if not getattr(b, "alive", False):
                continue

            # Decrement cooldown
            cd = getattr(b, "purchase_cooldown", 0.0)
            if cd > 0.0:
                b.purchase_cooldown = cd - delta

            # 1. Collect tags
            b_x = getattr(b, "x", 0.0)
            b_y = getattr(b, "y", 0.0)
            b_r = getattr(b, "radius", 20.0)

            remaining_tags = []
            for tag in self.bounty_tags:
                dx = tag["x"] - b_x
                dy = tag["y"] - b_y
                if dx*dx + dy*dy <= (b_r + 20.0)**2:  # 20.0 is tag pickup radius
                    # Pick up tag
                    b.currency = getattr(b, "currency", 0) + tag["value"]
                    if hasattr(world, "add_event"):
                        world.add_event("tag_collected", {"ball_id": getattr(b, "id", None), "value": tag["value"]})
                else:
                    remaining_tags.append(tag)
            self.bounty_tags = remaining_tags

            # 2. Extract and upgrade
            # Check if in extraction zone
            dist_sq = (self.extraction_zone_x - b_x)**2 + (self.extraction_zone_y - b_y)**2
            if dist_sq <= self.extraction_zone_radius**2:
                curr = getattr(b, "currency", 0)
                # Spend 5 currency for an upgrade
                if curr >= 5:
                    if getattr(b, "purchase_cooldown", 0.0) <= 0.0:
                        b.currency = curr - 5
                        b.purchase_cooldown = 1.0  # Cooldown between purchases

                        import random
                        upgrade = random.choice(["hp", "speed", "damage"])
                        if upgrade == "hp":
                            b.max_hp = getattr(b, "max_hp", 100.0) + 20.0
                            b.hp = getattr(b, "hp", 100.0) + 20.0
                        elif upgrade == "speed":
                            b.base_speed = getattr(b, "base_speed", 100.0) + 10.0
                            b.speed = getattr(b, "speed", 100.0) + 10.0
                        elif upgrade == "damage":
                            b.base_damage = getattr(b, "base_damage", 10.0) + 2.0
                            b.damage = getattr(b, "damage", 10.0) + 2.0

                        if hasattr(world, "add_event"):
                            world.add_event("upgrade_purchased", {"ball": b, "upgrade": upgrade})


GAME_MODES['bounty_extraction'] = BountyExtractionMode()

class FloorPaintMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Floor Paint"
        self.description = "Players shoot paint that stays on the floor, providing a movement speed boost to allies and a slow debuff to enemies traversing over it."
        self.splats = []

    class Splat:
        def __init__(self, x, y, team, radius=40.0):
            self.x = x
            self.y = y
            self.team = team
            self.radius = radius

    def setup(self, world, balls):
        super().setup(world, balls)
        self.splats = []
        for b in balls:
            if not hasattr(b, "base_speed"):
                b.base_speed = getattr(b, "speed", 100.0)
            b._paint_cd = 0.0

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)

        # Handle attacks and convert them to splats
        if hasattr(world, "attacks") and world.attacks:
            for atk, victim in list(world.attacks):
                atk_team = getattr(atk, "team", "Neutral")
                # Drop splat where the attack hit
                self.splats.append(self.Splat(victim.x, victim.y, atk_team))

        # Splats when moving/attacking
        for b in balls:
            if not getattr(b, "alive", False):
                continue

            b_team = getattr(b, "team", "Neutral")

            if not hasattr(b, "_paint_cd"):
                b._paint_cd = 0.0

            b._paint_cd -= delta
            if b._paint_cd <= 0.0:
                import random
                sx = getattr(b, "x", 0.0) + random.uniform(-50, 50)
                sy = getattr(b, "y", 0.0) + random.uniform(-50, 50)
                self.splats.append(self.Splat(sx, sy, b_team))
                b._paint_cd = random.uniform(0.5, 1.5)

            if len(self.splats) > 200:
                self.splats.pop(0)

            on_ally = False
            on_enemy = False

            for splat in self.splats:
                dx = getattr(b, "x", 0.0) - splat.x
                dy = getattr(b, "y", 0.0) - splat.y
                dist_sq = dx*dx + dy*dy
                if dist_sq < (getattr(b, "radius", 10.0) + splat.radius)**2:
                    if splat.team == b_team:
                        on_ally = True
                    elif splat.team != "Neutral":
                        on_enemy = True

            base = getattr(b, "base_speed", 100.0)
            if on_ally and not on_enemy:
                b.speed = base * 1.5
            elif on_enemy and not on_ally:
                b.speed = base * 0.5
            else:
                b.speed = base

GAME_MODES['floor_paint'] = FloorPaintMode()

class DynamicCaptureZonesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Dynamic Capture Zones"
        self.description = "Dynamic capture zones move around the arena. Earn points by staying inside, but they are contested if multiple teams are present. The zone shrinks over time."
        self.zone = None

    def apply_dynamic_traits(self, world, balls, delta):
        if not self.zone:
            self.zone = {
                "x": 500.0,
                "y": 500.0,
                "vx": 50.0,
                "vy": 30.0,
                "radius": 300.0,
                "min_radius": 50.0,
                "shrink_rate": 2.0
            }

        self.zone["radius"] = max(self.zone["min_radius"], self.zone["radius"] - self.zone["shrink_rate"] * delta)
        self.zone["x"] += self.zone["vx"] * delta
        self.zone["y"] += self.zone["vy"] * delta

        width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") else 1000
        height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") else 1000

        if self.zone["x"] - self.zone["radius"] < 0:
            self.zone["x"] = self.zone["radius"]
            self.zone["vx"] *= -1
        elif self.zone["x"] + self.zone["radius"] > width:
            self.zone["x"] = width - self.zone["radius"]
            self.zone["vx"] *= -1

        if self.zone["y"] - self.zone["radius"] < 0:
            self.zone["y"] = self.zone["radius"]
            self.zone["vy"] *= -1
        elif self.zone["y"] + self.zone["radius"] > height:
            self.zone["y"] = height - self.zone["radius"]
            self.zone["vy"] *= -1

        occupants_by_team = {}
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", "") == "spectator":
                continue

            bx = getattr(b, "x", 0.0)
            by = getattr(b, "y", 0.0)
            br = getattr(b, "radius", 20.0)

            dx = bx - self.zone["x"]
            dy = by - self.zone["y"]
            if dx*dx + dy*dy <= (self.zone["radius"] + br)**2:
                team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                if team not in occupants_by_team:
                    occupants_by_team[team] = []
                occupants_by_team[team].append(b)

        if len(occupants_by_team) == 1:
            team = list(occupants_by_team.keys())[0]
            for b in occupants_by_team[team]:
                b.score = getattr(b, "score", 0) + delta * 10.0
        elif len(occupants_by_team) > 1:
            timer = getattr(self, "contested_timer", 0.0) + delta
            if timer > 3.0:
                if hasattr(world, "add_event"):
                    world.add_event("zone_contested", {"message": "Zone is Contested!"})
                timer = 0.0
            self.contested_timer = timer

    def check_winner(self, world, balls):
        alive_teams = {}
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                alive_teams[team] = True

        if len(alive_teams) == 1:
            return list(alive_teams.keys())[0]

        best_score = -1
        best_team = None
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                score = getattr(b, "score", 0)
                if score >= 1000:
                    return team
                if score > best_score:
                    best_score = score
                    best_team = team

        return None


class TelegraphedSupplyDropMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Telegraphed Supply Drop"
        self.description = "Periodically, high-value supply packages are dropped via parachute into the arena. Their landing zone is telegraphed early."
        self.drop_timer = 0.0
        self.active_telegraphs = []
        self.high_tier_drops = []
        self.random = __import__("random").Random(12345)

    def setup(self, world: Any, balls: List[Any]) -> None:
        super().setup(world, balls)
        self.drop_timer = 0.0
        self.active_telegraphs = []
        self.high_tier_drops = []
        if hasattr(world, "tick_timer"):
            self.random = __import__("random").Random(int(world.tick_timer * 1000))

    def tick(self, world: Any, balls: List[Any], delta: float = 0.016) -> None:
        if not hasattr(world, "arena"):
            return

        self.drop_timer += delta
        if self.drop_timer >= 20.0:
            self.drop_timer = 0.0

            arena_width = getattr(world.arena, "width", 1000)
            arena_height = getattr(world.arena, "height", 1000)
            x = self.random.uniform(200, arena_width - 200)
            y = self.random.uniform(200, arena_height - 200)

            t_id = f"telegraph_{self.random.randint(1000, 9999)}"
            telegraph = {
                "id": t_id,
                "x": x,
                "y": y,
                "radius": 50.0,
                "kind": "supply_drop_telegraph",
                "timer": 5.0,
                "active": True
            }
            self.active_telegraphs.append(telegraph)

            if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
                world.arena.hazards = []

            try:
                from arena.procedural_arena import Hazard
                h = Hazard(id=t_id, x=x, y=y, radius=50.0, kind="supply_drop_telegraph", damage=0.0)
                setattr(h, "timer", 5.0)
            except ImportError:
                class DummyHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                        self.active = True
                h = DummyHazard(t_id, x, y, 50.0, "supply_drop_telegraph", 0.0)
                setattr(h, "timer", 5.0)

            world.arena.hazards.append(h)
            if hasattr(world, "add_event"):
                world.add_event("telegraph_spawn", {"message": "A high-value supply drop is incoming!"})

        # Process telegraphs
        for t in self.active_telegraphs[:]:
            if not t.get("active", True):
                continue

            t["timer"] -= delta

            # Synchronize with hazard
            sync_h = None
            if hasattr(world.arena, "hazards"):
                for h in world.arena.hazards:
                    if getattr(h, "id", "") == t["id"]:
                        setattr(h, "timer", t["timer"])
                        sync_h = h
                        break

            if t["timer"] <= 0:
                t["active"] = False
                if t in self.active_telegraphs:
                    self.active_telegraphs.remove(t)
                if sync_h and hasattr(world.arena, "hazards") and sync_h in world.arena.hazards:
                    world.arena.hazards.remove(sync_h)

                # Spawn high tier drop
                drop_id = f"ht_drop_{self.random.randint(1000, 9999)}"
                try:
                    from arena.procedural_arena import Hazard
                    drop = Hazard(id=drop_id, x=t["x"], y=t["y"], radius=60.0, kind="high_tier_drop", damage=0.0)
                except ImportError:
                    class DummyHazardHT:
                        def __init__(self, id, x, y, radius, kind, damage):
                            self.id = id
                            self.x = x
                            self.y = y
                            self.radius = radius
                            self.kind = kind
                            self.damage = damage
                            self.active = True
                    drop = DummyHazardHT(drop_id, t["x"], t["y"], 60.0, "high_tier_drop", 0.0)

                setattr(drop, "capture_progress", 0.0)
                setattr(drop, "capturing_team", None)

                if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
                    world.arena.hazards = []
                world.arena.hazards.append(drop)

                if not hasattr(self, "high_tier_drops"):
                    self.high_tier_drops = []
                self.high_tier_drops.append(drop)

                import math
                for b in balls:
                    if getattr(b, "alive", False):
                        dist = math.hypot(getattr(b, "x", 0) - t["x"], getattr(b, "y", 0) - t["y"])
                        if dist <= 60.0 + getattr(b, "radius", 15.0):
                            b.hp = getattr(b, "hp", 100.0) - 30.0
                            if getattr(b, "hp", 0) <= 0:
                                b.alive = False
                            if dist > 0:
                                dx = getattr(b, "x", 0) - t["x"]
                                dy = getattr(b, "y", 0) - t["y"]
                                b.vx = getattr(b, "vx", 0.0) + (dx / dist) * 800.0
                                b.vy = getattr(b, "vy", 0.0) + (dy / dist) * 800.0

                if hasattr(world, "add_event"):
                    world.add_event("supply_drop_shockwave", {"x": t["x"], "y": t["y"], "radius": 60.0})
                    world.add_event("high_tier_drop_landed", {"message": "Supply drop has landed! Capture it!"})

        # Process drops
        if hasattr(self, "high_tier_drops"):
            drops_to_remove = []
            import math
            for drop in self.high_tier_drops:
                if not getattr(drop, "active", True):
                    drops_to_remove.append(drop)
                    continue

                balls_inside = []
                for b in balls:
                    if not getattr(b, "alive", False): continue
                    bx = getattr(b, "x", 0.0)
                    by = getattr(b, "y", 0.0)
                    if math.hypot(bx - getattr(drop, "x", 0.0), by - getattr(drop, "y", 0.0)) < getattr(drop, "radius", 60.0):
                        balls_inside.append(b)

                if balls_inside:
                    teams_inside = list(set(getattr(b, "team", getattr(b, "ball_type", "")) for b in balls_inside))
                    if len(teams_inside) == 1:
                        team = teams_inside[0]
                        if getattr(drop, "capturing_team", None) == team:
                            drop.capture_progress = getattr(drop, "capture_progress", 0.0) + 20.0 * delta
                            if drop.capture_progress >= 100.0:
                                drop.active = False
                                drops_to_remove.append(drop)
                                if hasattr(world.arena, "hazards") and drop in world.arena.hazards:
                                    world.arena.hazards.remove(drop)

                                for b in balls:
                                    if getattr(b, "team", getattr(b, "ball_type", "")) == team and getattr(b, "alive", False):
                                        buff_type = self.random.choice(["invulnerability", "instant_ultimate", "mega_heal", "damage_boost", "speed_boost"])
                                        if buff_type == "invulnerability":
                                            b.invulnerable_timer = getattr(b, "invulnerable_timer", 0.0) + 15.0
                                        elif buff_type == "instant_ultimate":
                                            b.ultimate_charge = getattr(b, "max_ultimate_charge", 100.0)
                                        elif buff_type == "mega_heal":
                                            b.hp = getattr(b, "max_hp", 100.0)
                                            b.shield = getattr(b, "shield", 0.0) + 100.0
                                        elif buff_type == "damage_boost":
                                            b.damage = getattr(b, "base_damage", getattr(b, "damage", 10.0)) * 2.0
                                            b.soul_boost_timer = getattr(b, "soul_boost_timer", 0.0) + 20.0
                                        elif buff_type == "speed_boost":
                                            b.speed = getattr(b, "base_speed", getattr(b, "speed", 100.0)) * 1.5
                                            b.speed_boost_timer = getattr(b, "speed_boost_timer", 0.0) + 15.0

                                if hasattr(world, "add_event"):
                                    world.add_event("high_tier_drop_captured", {"team": team})
                        else:
                            drop.capturing_team = team
                            drop.capture_progress = 0.0
                    else:
                        # Contested
                        drop.capture_progress = max(0.0, getattr(drop, "capture_progress", 0.0) - 10.0 * delta)
                else:
                    drop.capture_progress = max(0.0, getattr(drop, "capture_progress", 0.0) - 5.0 * delta)
                    if drop.capture_progress == 0:
                        drop.capturing_team = None

            for d in drops_to_remove:
                if d in self.high_tier_drops:
                    self.high_tier_drops.remove(d)

    def check_winner(self, world, balls):
        alive_teams = {}
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                alive_teams[team] = True

        if len(alive_teams) == 1:
            return list(alive_teams.keys())[0]

        best_score = -1
        best_team = None
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                team = getattr(b, "team", getattr(b, "ball_type", "unknown"))
                score = getattr(b, "score", 0)
                if score >= 1000:
                    return team
                if score > best_score:
                    best_score = score
                    best_team = team

        return None

