class IndestructibleLaserCoreMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Indestructible Laser Core"
        self.description = "A single indestructible laser core spawns in the center of the map. It fires two continuous solid beam lasers in opposite directions and slowly rotates. Over time, the core bounces around the arena like a paddle ball, randomly changing direction when hitting a wall, making dodging extremely unpredictable."
        self.core_spawned = False

    def setup(self, world, balls):
        super().setup(world, balls)
        self.core_spawned = False
        if not hasattr(world, "arena"): return
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"): world.arena.hazards = []

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        if not hasattr(world, "arena"): return

        if not self.core_spawned:
            self.core_spawned = True
            aw = getattr(world.arena, "width", 1000.0)
            ah = getattr(world.arena, "height", 1000.0)

            import math
            import random
            try:
                from arena.procedural_arena import Hazard
            except ImportError:
                class Hazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                        self.active = True

            if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
                world.arena.hazards = []

            h_id = "indestructible_laser_core_0"
            h = Hazard(id=h_id, x=aw/2.0, y=ah/2.0, radius=500.0, kind="spinning_laser", damage=50.0)
            h.angle = random.uniform(0, math.pi * 2)
            h.duration = 9999.0

            # Start moving in a random direction
            speed = 300.0
            move_angle = random.uniform(0, math.pi * 2)
            h.vx = math.cos(move_angle) * speed
            h.vy = math.sin(move_angle) * speed

            # The core itself doesn't have a built-in visual radius in the hazard dictionary
            # for the ball part if it's purely a spinning laser, but let's add one just in case
            # for our own logic.
            h.core_radius = 40.0

            world.arena.hazards.append(h)

        # Update the core's position and handle wall bouncing
        aw = getattr(world.arena, "width", 1000.0)
        ah = getattr(world.arena, "height", 1000.0)
        import random

        for hazard in world.arena.hazards:
            if getattr(hazard, "id", "") == "indestructible_laser_core_0":
                # Update position
                vx = getattr(hazard, "vx", 0.0)
                vy = getattr(hazard, "vy", 0.0)

                hazard.x += vx * delta
                hazard.y += vy * delta

                core_radius = getattr(hazard, "core_radius", 40.0)

                bounced = False

                if hazard.x - core_radius < 0:
                    hazard.x = core_radius
                    hazard.vx = abs(hazard.vx)
                    bounced = True
                elif hazard.x + core_radius > aw:
                    hazard.x = aw - core_radius
                    hazard.vx = -abs(hazard.vx)
                    bounced = True

                if hazard.y - core_radius < 0:
                    hazard.y = core_radius
                    hazard.vy = abs(hazard.vy)
                    bounced = True
                elif hazard.y + core_radius > ah:
                    hazard.y = ah - core_radius
                    hazard.vy = -abs(hazard.vy)
                    bounced = True

                if bounced:
                    # Randomly changing direction when hitting a wall slightly
                    # but keep magnitude
                    import math
                    current_speed = math.hypot(hazard.vx, hazard.vy)
                    current_angle = math.atan2(hazard.vy, hazard.vx)

                    # add small random deviation between -15 and 15 degrees
                    angle_deviation = random.uniform(-0.26, 0.26)
                    new_angle = current_angle + angle_deviation

                    hazard.vx = math.cos(new_angle) * current_speed
                    hazard.vy = math.sin(new_angle) * current_speed

GAME_MODES["indestructible_laser_core"] = IndestructibleLaserCoreMode()


class UnstablePayloadMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Unstable Payload"
        self.description = "Periodically, an 'unstable payload' hazard spawns in the center of the arena. It slowly expands and deals increasing radiation damage. Players must attack it to push it towards enemy teams before it reaches critical mass and detonates, instantly eliminating anyone caught in its massive blast radius."
        self.spawn_timer = 10.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import math
        import random

        if not hasattr(world, "arena"):
            return
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        self.spawn_timer -= delta
        if self.spawn_timer <= 0:
            # Check if one already exists
            has_payload = any(getattr(h, "kind", "") == "unstable_payload" for h in world.arena.hazards)
            if not has_payload:
                self.spawn_timer = 30.0 # Next spawn
                arena_width = getattr(world.arena, "width", 1000)
                arena_height = getattr(world.arena, "height", 1000)
                cx = arena_width / 2.0
                cy = arena_height / 2.0

                try:
                    from arena.procedural_arena import Hazard
                    h = Hazard(id=len(world.arena.hazards) + 95000 + random.randint(0, 1000), x=cx, y=cy, radius=20.0, kind="unstable_payload", damage=0.0)
                except ImportError:
                    class DummyHazardUP:
                        def __init__(self, id, x, y, radius, kind, damage):
                            self.id = id
                            self.x = x
                            self.y = y
                            self.radius = radius
                            self.kind = kind
                            self.damage = damage
                    h = DummyHazardUP(len(world.arena.hazards) + 95000 + random.randint(0, 1000), cx, cy, 20.0, "unstable_payload", 0.0)

                # Add satellites to payload
                import math
                h.satellites = []
                for i in range(4):
                    class PayloadSatellite:
                        def __init__(self, cx, cy, idx):
                            self.id = random.randint(10000, 99999)
                            self.orbit_angle = (2 * math.pi / 4) * idx
                            self.orbit_radius = 40.0
                            self.orbit_speed = 1.5
                            self.is_orbiting = True
                            self.x = cx + math.cos(self.orbit_angle) * self.orbit_radius
                            self.y = cy + math.sin(self.orbit_angle) * self.orbit_radius
                            self.radius = 8.0
                    h.satellites.append(PayloadSatellite(h.x, h.y, i))

                setattr(h, "vx", 0.0)
                setattr(h, "vy", 0.0)
                setattr(h, "mass_timer", 0.0)
                setattr(h, "active", True)
                world.arena.hazards.append(h)

                if hasattr(world, "add_event"):
                    world.add_event("unstable_payload_spawned", {"x": cx, "y": cy})
            else:
                self.spawn_timer = 5.0 # Check again soon

        hazards_to_remove = []
        for h in world.arena.hazards:
            if getattr(h, "kind", "") == "unstable_payload" and getattr(h, "active", True):
                h.mass_timer = getattr(h, "mass_timer", 0.0) + delta

                # Expand payload over time (starts at 20, grows up to 100 over 15 seconds)
                progress = min(1.0, h.mass_timer / 15.0)
                h.radius = 20.0 + (80.0 * progress)

                # Update position based on velocity with friction
                h.vx = getattr(h, "vx", 0.0) * (1.0 - 1.5 * delta)
                h.vy = getattr(h, "vy", 0.0) * (1.0 - 1.5 * delta)
                h.x += h.vx * delta
                h.y += h.vy * delta

                # Update satellites position
                satellites = getattr(h, "satellites", [])
                import math
                for sat in satellites:
                    if getattr(sat, "is_orbiting", False):
                        sat.orbit_angle += sat.orbit_speed * delta
                        # Adjust orbit radius based on payload growth
                        current_orbit = h.radius + 20.0
                        sat.x = h.x + math.cos(sat.orbit_angle) * current_orbit
                        sat.y = h.y + math.sin(sat.orbit_angle) * current_orbit
                        sat.orbit_radius = current_orbit

                # Bounce off walls
                arena_width = getattr(world.arena, "width", 1000)
                arena_height = getattr(world.arena, "height", 1000)
                if h.x - h.radius < 0:
                    h.x = h.radius
                    h.vx = abs(h.vx) * 0.8
                elif h.x + h.radius > arena_width:
                    h.x = arena_width - h.radius
                    h.vx = -abs(h.vx) * 0.8

                if h.y - h.radius < 0:
                    h.y = h.radius
                    h.vy = abs(h.vy) * 0.8
                elif h.y + h.radius > arena_height:
                    h.y = arena_height - h.radius
                    h.vy = -abs(h.vy) * 0.8

                # Radiation damage to nearby players (scales with size)
                rad_radius = h.radius * 2.5
                base_dmg = 5.0 + (15.0 * progress)

                for b in balls:
                    if not getattr(b, "alive", False) or getattr(b, "ball_type", "") == "spectator":
                        continue

                    dx = b.x - h.x
                    dy = b.y - h.y
                    dist = math.sqrt(dx*dx + dy*dy)

                    if dist < rad_radius:
                        dmg = base_dmg * (1.0 - dist/rad_radius) * delta
                        b.hp = getattr(b, "hp", 100.0) - dmg
                        if b.hp <= 0:
                            b.hp = 0
                            b.alive = False

                    # Collision / Attack logic
                    # If player touches it, push it!
                    if dist <= h.radius + getattr(b, "radius", 15.0):
                        overlap = h.radius + getattr(b, "radius", 15.0) - dist
                        if dist > 0.001:
                            nx = dx / dist
                            ny = dy / dist

                            # push ball out
                            b.x += nx * overlap
                            b.y += ny * overlap

                            # transfer some momentum to payload based on relative velocity
                            rel_vx = getattr(b, "vx", 0.0) - h.vx
                            rel_vy = getattr(b, "vy", 0.0) - h.vy
                            impulse = (nx * rel_vx + ny * rel_vy)

                            if impulse < 0:
                                # Ball is moving towards payload
                                h.vx -= nx * abs(impulse) * 0.5
                                h.vy -= ny * abs(impulse) * 0.5
                                # Also deal tiny damage to player for touching
                                b.hp = getattr(b, "hp", 100.0) - 10.0 * delta
                                if b.hp <= 0:
                                    b.hp = 0
                                    b.alive = False

                # Explode at critical mass
                if h.mass_timer >= 15.0:
                    hazards_to_remove.append(h)

        for h in hazards_to_remove:
            world.arena.hazards.remove(h)

            # Satellites detach on explosion
            satellites = getattr(h, "satellites", [])
            import random
            import math
            for sat in satellites:
                # Detach and fly outward
                sat_angle = getattr(sat, "orbit_angle", 0.0)
                dir_x = math.cos(sat_angle)
                dir_y = math.sin(sat_angle)
                sat_speed = 400.0
                sat.vx = dir_x * sat_speed
                sat.vy = dir_y * sat_speed
                sat.is_orbiting = False

                # Add to projectiles
                if hasattr(world, "projectiles"):
                    p_id = getattr(sat, "id", random.randint(10000, 99999))
                    class SatProjectile:
                        def __init__(self, x, y, vx, vy, radius, damage, owner_id):
                            self.id = p_id
                            self.x = x
                            self.y = y
                            self.vx = vx
                            self.vy = vy
                            self.radius = radius
                            self.damage = damage
                            self.owner_id = owner_id
                            self.bounce_count = 0
                            self.max_bounces = 2
                            self.active = True
                            self.time_to_live = 4.0
                    p = SatProjectile(sat.x, sat.y, sat.vx, sat.vy, getattr(sat, "radius", 8.0), 25.0, None)
                    world.projectiles.append(p)

            h.satellites = []

            # Massive explosion
            blast_radius = 450.0
            if hasattr(world, "add_event"):
                world.add_event("visual_effect", {"type": "massive_explosion", "x": h.x, "y": h.y, "radius": blast_radius})
                world.add_event("unstable_payload_detonated", {"x": h.x, "y": h.y})

            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                    import math
                    dx = b.x - h.x
                    dy = b.y - h.y
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist <= blast_radius:
                        # Instant elimination if close, high damage if at edge
                        if dist < blast_radius * 0.6:
                            b.hp = 0
                            b.alive = False
                        else:
                            dmg = 200.0 * (1.0 - (dist - blast_radius*0.6)/(blast_radius*0.4))
                            b.hp = getattr(b, "hp", 100.0) - dmg
                            if b.hp <= 0:
                                b.hp = 0
                                b.alive = False

class BlindFragmentAuctionMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Blind Fragment Auction"
        self.description = "Players secretly wager their collected loadout fragments for an ultra-rare game-changing item or exclusive cosmetic."
        self.auction_timer = 30.0
        self.auction_active = False
        self.auction_duration = 10.0
        self.bids = {}
        self.auction_items = [
            {"type": "buff", "stat": "base_damage", "multiplier": 1.5, "name": "Ultra Rare Booster: Damage"},
            {"type": "buff", "stat": "base_speed", "multiplier": 1.5, "name": "Ultra Rare Booster: Speed"},
            {"type": "buff", "stat": "max_hp", "addition": 200.0, "name": "Omega Shield"},
            {"type": "cosmetic", "item": "golden_crown", "name": "Exclusive Cosmetic: Golden Crown"}
        ]
        import random
        self.current_item = random.choice(self.auction_items)

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random
        alive_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]
        if not alive_balls:
            return

        if not self.auction_active:
            self.auction_timer -= delta
            if self.auction_timer <= 0:
                self.auction_active = True
                self.auction_duration = 10.0
                self.bids = {}
                self.current_item = random.choice(self.auction_items)
                if hasattr(world, "add_event"):
                    world.add_event("blind_auction_started", {"item": self.current_item["name"]})
        else:
            self.auction_duration -= delta

            for b in alive_balls:
                b_id = getattr(b, "id", None)
                fragments = getattr(b, "collected_fragments", 0)
                if fragments > 0 and random.random() < 2.0 * delta:
                    current_bid = self.bids.get(b_id, 0)
                    if current_bid < fragments:
                        bid_increase = random.randint(1, fragments - current_bid)
                        self.bids[b_id] = current_bid + bid_increase

            if self.auction_duration <= 0:
                self.auction_active = False
                self.auction_timer = random.uniform(30.0, 50.0)

                if self.bids:
                    highest_bid = max(self.bids.values())
                    top_bidders = [b_id for b_id, bid in self.bids.items() if bid == highest_bid]
                    winner_id = random.choice(top_bidders)

                    winner = next((b for b in alive_balls if getattr(b, "id", None) == winner_id), None)
                    if winner:
                        winner.collected_fragments = getattr(winner, "collected_fragments", 0) - highest_bid

                        if self.current_item["type"] == "buff":
                            if "multiplier" in self.current_item:
                                stat = self.current_item["stat"]
                                current_val = getattr(winner, stat, 1.0)
                                setattr(winner, stat, current_val * self.current_item["multiplier"])
                                # Adjust non-base stat as well for immediate effect if applicable
                                if stat == "base_damage":
                                    winner.damage = getattr(winner, "damage", 10.0) * self.current_item["multiplier"]
                                elif stat == "base_speed":
                                    winner.speed = getattr(winner, "speed", 100.0) * self.current_item["multiplier"]
                            elif "addition" in self.current_item:
                                stat = self.current_item["stat"]
                                current_val = getattr(winner, stat, 100.0)
                                setattr(winner, stat, current_val + self.current_item["addition"])
                                if stat == "max_hp":
                                    winner.hp = getattr(winner, "hp", 100.0) + self.current_item["addition"]
                        elif self.current_item["type"] == "cosmetic":
                            cosmetics = getattr(winner, "cosmetics", [])
                            if self.current_item["item"] not in cosmetics:
                                cosmetics.append(self.current_item["item"])
                                winner.cosmetics = cosmetics

                        if hasattr(world, "add_event"):
                            world.add_event("blind_auction_ended", {
                                "winner_id": winner_id,
                                "winning_bid": highest_bid,
                                "item": self.current_item["name"]
                            })
                else:
                    if hasattr(world, "add_event"):
                        world.add_event("blind_auction_ended", {
                            "winner_id": None,
                            "winning_bid": 0,
                            "item": self.current_item["name"]
                        })

GAME_MODES["unstable_payload"] = UnstablePayloadMode()
GAME_MODES["blind_fragment_auction"] = BlindFragmentAuctionMode()
GAME_MODES["mobile_platform"] = MobilePlatformMode()

class AmmoDepotMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Ammo Depot"
        self.description = "Players start with extremely low attack speed and damage, and must pick up ammo packs to fight effectively."
        self.ammo_spawn_timer = 2.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        for b in balls:
            b.ammo_buff_timer = 0.0

            # Store original values if not already present
            if not hasattr(b, "original_base_damage"):
                b.original_base_damage = 10.0
            if not hasattr(b, "original_attack_speed"):
                b.original_attack_speed = 1.0

            b.base_damage = b.original_base_damage * 0.1
            b.attack_speed = b.original_attack_speed * 0.1

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random

        # Spawn ammo
        if hasattr(world, "boosters") and hasattr(world, "arena"):
            self.ammo_spawn_timer -= delta
            if self.ammo_spawn_timer <= 0:
                self.ammo_spawn_timer = random.uniform(1.5, 3.5)
                # Ensure maximum ammo packs on map to avoid clutter
                ammo_count = sum(1 for b in world.boosters if getattr(b, "kind", "") == "ammo_pack")
                if ammo_count < 15:
                    b_id = 9500 + len(world.boosters) + random.randint(0, 1000)
                    bx = random.uniform(100, world.arena.width - 100)
                    by = random.uniform(100, world.arena.height - 100)

                    class AmmoBooster:
                        def __init__(self, bid, x, y):
                            self.id = bid
                            self.x = x
                            self.y = y
                            self.kind = "ammo_pack"
                            self.radius = 15.0
                            self.ball_type = "booster"
                            self.active = True
                    world.boosters.append(AmmoBooster(b_id, bx, by))

        # Manage player stats and collisions
        for b in balls:
            if not getattr(b, "alive", False):
                continue

            # Decrement timer
            if hasattr(b, "ammo_buff_timer"):
                b.ammo_buff_timer -= delta
                if b.ammo_buff_timer <= 0:
                    b.ammo_buff_timer = 0.0
                    b.base_damage = getattr(b, "original_base_damage", 10.0) * 0.1
                    b.attack_speed = getattr(b, "original_attack_speed", 1.0) * 0.1
                else:
                    b.base_damage = getattr(b, "original_base_damage", 10.0) * 2.0
                    b.attack_speed = getattr(b, "original_attack_speed", 1.0) * 2.0

            # Check collisions with ammo
            if hasattr(world, "boosters"):
                b_x = getattr(b, "x", 0.0)
                b_y = getattr(b, "y", 0.0)
                b_r = getattr(b, "radius", 20.0)

                for booster in world.boosters:
                    if getattr(booster, "kind", "") == "ammo_pack" and getattr(booster, "active", False):
                        booster_x = getattr(booster, "x", 0.0)
                        booster_y = getattr(booster, "y", 0.0)
                        booster_r = getattr(booster, "radius", 15.0)

                        dx = b_x - booster_x
                        dy = b_y - booster_y
                        if dx*dx + dy*dy <= (b_r + booster_r)**2:
                            booster.active = False
                            b.ammo_buff_timer = 4.0
                            if hasattr(world, "add_event"):
                                world.add_event("ammo_pickup", {"ball_id": getattr(b, "id", 0)})

GAME_MODES["ammo_depot"] = AmmoDepotMode()


class CascadingStunMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Cascading Stun"
        self.description = "Colliding with any other ball automatically arms a Stun Explosion on both entities, creating an arena filled with constant bouncing and cascading stun effects."
        self.status_effects = ["stun_timer", "stun_arm_timer"]

    def setup(self, world):
        balls = getattr(world, "balls", []) if hasattr(world, "balls") else world.get("balls", []) if isinstance(world, dict) else []
        for b in balls:
            if isinstance(b, dict):
                b["stun_arm_timer"] = 0.0
                b["stun_timer"] = 0.0
            else:
                b.stun_arm_timer = 0.0
                b.stun_timer = 0.0
    def tick(self, world, delta):
        balls = getattr(world, "balls", []) if hasattr(world, "balls") else world.get("balls", []) if isinstance(world, dict) else []
        n = len(balls)

        # Handle explosions and timer
        for b in balls:
            if not getattr(b, "alive", False) and not (isinstance(b, dict) and b.get("alive", False)):
                continue

            arm_timer = getattr(b, "stun_arm_timer", 0.0) if hasattr(b, "stun_arm_timer") else b.get("stun_arm_timer", 0.0) if isinstance(b, dict) else 0.0
            if arm_timer > 0:
                arm_timer -= delta
                if arm_timer <= 0:
                    # Explode!
                    if isinstance(b, dict):
                        b["stun_arm_timer"] = 0.0
                    else:
                        b.stun_arm_timer = 0.0

                    b_x = getattr(b, "x", 0.0) if hasattr(b, "x") else b.get("x", 0.0) if isinstance(b, dict) else 0.0
                    b_y = getattr(b, "y", 0.0) if hasattr(b, "y") else b.get("y", 0.0) if isinstance(b, dict) else 0.0
                    explosion_radius = 150.0

                    if hasattr(world, "add_event"):
                        world.add_event("stun_explosion", {"x": b_x, "y": b_y, "radius": explosion_radius})

                    for other in balls:
                        if other is b or (not getattr(other, "alive", False) and not (isinstance(other, dict) and other.get("alive", False))):
                            continue
                        o_x = getattr(other, "x", 0.0) if hasattr(other, "x") else other.get("x", 0.0) if isinstance(other, dict) else 0.0
                        o_y = getattr(other, "y", 0.0) if hasattr(other, "y") else other.get("y", 0.0) if isinstance(other, dict) else 0.0
                        o_r = getattr(other, "radius", 20.0) if hasattr(other, "radius") else other.get("radius", 20.0) if isinstance(other, dict) else 20.0

                        dx = b_x - o_x
                        dy = b_y - o_y
                        dist_sq = dx*dx + dy*dy
                        if dist_sq <= (explosion_radius + o_r)**2:
                            # Apply stun
                            curr_stun = getattr(other, "stun_timer", 0.0) if hasattr(other, "stun_timer") else other.get("stun_timer", 0.0) if isinstance(other, dict) else 0.0
                            new_stun = max(curr_stun, 1.5)
                            if isinstance(other, dict):
                                other["stun_timer"] = new_stun
                            else:
                                other.stun_timer = new_stun
                else:
                    if isinstance(b, dict):
                        b["stun_arm_timer"] = arm_timer
                    else:
                        b.stun_arm_timer = arm_timer

        # Check collisions to arm
        for i in range(n):
            b1 = balls[i]
            if not getattr(b1, "alive", False) and not (isinstance(b1, dict) and b1.get("alive", False)): continue

            b1_x = getattr(b1, "x", 0.0) if hasattr(b1, "x") else b1.get("x", 0.0) if isinstance(b1, dict) else 0.0
            b1_y = getattr(b1, "y", 0.0) if hasattr(b1, "y") else b1.get("y", 0.0) if isinstance(b1, dict) else 0.0
            b1_r = getattr(b1, "radius", 20.0) if hasattr(b1, "radius") else b1.get("radius", 20.0) if isinstance(b1, dict) else 20.0

            for j in range(i + 1, n):
                b2 = balls[j]
                if not getattr(b2, "alive", False) and not (isinstance(b2, dict) and b2.get("alive", False)): continue

                b2_x = getattr(b2, "x", 0.0) if hasattr(b2, "x") else b2.get("x", 0.0) if isinstance(b2, dict) else 0.0
                b2_y = getattr(b2, "y", 0.0) if hasattr(b2, "y") else b2.get("y", 0.0) if isinstance(b2, dict) else 0.0
                b2_r = getattr(b2, "radius", 20.0) if hasattr(b2, "radius") else b2.get("radius", 20.0) if isinstance(b2, dict) else 20.0

                dx = b1_x - b2_x
                dy = b1_y - b2_y
                dist_sq = dx*dx + dy*dy

                if dist_sq <= (b1_r + b2_r)**2:
                    # They collided, arm them if not already armed
                    b1_arm = getattr(b1, "stun_arm_timer", 0.0) if hasattr(b1, "stun_arm_timer") else b1.get("stun_arm_timer", 0.0) if isinstance(b1, dict) else 0.0
                    b2_arm = getattr(b2, "stun_arm_timer", 0.0) if hasattr(b2, "stun_arm_timer") else b2.get("stun_arm_timer", 0.0) if isinstance(b2, dict) else 0.0

                    if b1_arm <= 0:
                        if isinstance(b1, dict):
                            b1["stun_arm_timer"] = 2.0
                        else:
                            b1.stun_arm_timer = 2.0
                    if b2_arm <= 0:
                        if isinstance(b2, dict):
                            b2["stun_arm_timer"] = 2.0
                        else:
                            b2.stun_arm_timer = 2.0

GAME_MODES["cascading_stun"] = CascadingStunMode()

class SquadRelayMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Squad Relay"
        self.description = "Players can only control one ball at a time in a squad. When the active ball dies, the next one spawns in with inherited speed and temporary invulnerability."
        self.spectator_queue = {}

    def apply_dynamic_traits(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        pass

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        self.spectator_queue = {}

        teams = {}
        for b in balls:
            if getattr(b, "ball_type", "") == "spectator":
                continue
            t = getattr(b, "team", "players")
            if t not in teams:
                teams[t] = []
            teams[t].append(b)

        for t, team_balls in teams.items():
            if len(team_balls) > 1:
                active_ball = team_balls[0]
                spectators = team_balls[1:]
                self.spectator_queue[t] = spectators

                for sb in spectators:
                    sb.original_ball_type = getattr(sb, "ball_type", "player")
                    sb.ball_type = "spectator"
                    sb.x = -1000.0
                    sb.y = -1000.0
                    sb.vx = 0.0
                    sb.vy = 0.0
            else:
                self.spectator_queue[t] = []

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        for t, queue in list(self.spectator_queue.items()):
            active = None
            dead_active = None
            for b in balls:
                if getattr(b, "team", "") == t and getattr(b, "ball_type", "") != "spectator":
                    if getattr(b, "hp", 100) > 0 and getattr(b, "alive", True):
                        active = b
                    else:
                        dead_active = b

            if active is None and dead_active is not None:
                dead_active.alive = False

                if queue:
                    next_ball = queue.pop(0)
                    next_ball.ball_type = getattr(next_ball, "original_ball_type", "player")
                    next_ball.x = dead_active.x
                    next_ball.y = dead_active.y
                    next_ball.vx = getattr(dead_active, "vx", 0.0)
                    next_ball.vy = getattr(dead_active, "vy", 0.0)

                    next_ball.intangible = True
                    next_ball.intangible_timer = 2.0

                    if hasattr(world, "add_event"):
                        world.add_event("squad_relay_spawn", {"message": f"Team {t} relay spawned!"})

GAME_MODES["squad_relay"] = SquadRelayMode()

class TeleportingSafeZoneMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Teleporting Safe Zone"
        self.description = "A safe zone that randomly teleports around the map every 10 seconds, forcing players to constantly adapt their positioning to stay alive."
        self.zone_x = 500.0
        self.zone_y = 500.0
        self.zone_radius = 200.0
        self.teleport_timer = 0.0
        self.teleport_interval = 10.0
        self.outside_damage_per_second = 15.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        self.zone_x = arena_width / 2.0
        self.zone_y = arena_height / 2.0
        self.teleport_timer = 0.0

    def tick(self, world, balls, delta=0.016):
        import math
        import random

        self.teleport_timer += delta
        if self.teleport_timer >= self.teleport_interval:
            self.teleport_timer = 0.0
            arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
            arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
            margin = self.zone_radius

            # Ensure margin isn't larger than half the arena
            safe_margin_x = min(margin, arena_width / 2.0)
            safe_margin_y = min(margin, arena_height / 2.0)

            self.zone_x = random.uniform(safe_margin_x, arena_width - safe_margin_x)
            self.zone_y = random.uniform(safe_margin_y, arena_height - safe_margin_y)

            if hasattr(world, "add_event"):
                world.add_event("zone_teleport", {"message": "The safe zone has teleported!"})

        damage = self.outside_damage_per_second * delta
        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            dx = b.x - self.zone_x
            dy = b.y - self.zone_y
            dist = math.sqrt(dx*dx + dy*dy)

            if dist > self.zone_radius:
                # Apply significant speed penalty for being outside safe zone
                b.slow_timer = max(getattr(b, "slow_timer", 0.0), 0.5)
                b.hp -= damage
                if b.hp <= 0:
                    b.hp = 0
                    b.alive = False
                    if hasattr(world, "add_event"):
                        world.add_event("kill", {"killer": "safe_zone", "victim": getattr(b, "id", "Unknown")})

GAME_MODES["teleporting_safe_zone"] = TeleportingSafeZoneMode()


class OrbitalDebrisMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Orbital Debris"
        self.description = "Indestructible debris clusters orbit the center gravity well. The debris blocks projectiles and damages entities upon high-speed collision, forcing players to time their approaches and manage their slingshot trajectories carefully."
        self.id = "orbital_debris"

        self.center_x = 500.0
        self.center_y = 500.0
        self.num_debris = 5
        self.orbit_speed = 0.5  # radians per second
        self.orbit_radius = 250.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.center_x = getattr(world.arena, "width", 1000.0) / 2.0
        self.center_y = getattr(world.arena, "height", 1000.0) / 2.0

        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        import math
        try:
            from arena.procedural_arena import Hazard
        except ImportError:
            class Hazard:
                def __init__(self, id, x, y, radius, kind, damage, **kwargs):
                    self.id = id
                    self.x = x
                    self.y = y
                    self.radius = radius
                    self.kind = kind
                    self.damage = damage
                    for k, v in kwargs.items():
                        setattr(self, k, v)

        # Central gravity well
        existing_well = next((h for h in world.arena.hazards if getattr(h, "kind", "") == "gravity_well" and getattr(h, "id", None) == 88888), None)
        if not existing_well:
            well = Hazard(
                id=88888,
                x=self.center_x,
                y=self.center_y,
                radius=100.0,
                kind="gravity_well",
                damage=10.0
            )
            setattr(well, "pull_strength", 150.0)
            world.arena.hazards.append(well)

        # Debris clusters
        for i in range(self.num_debris):
            d_id = 88890 + i
            existing = next((h for h in world.arena.hazards if getattr(h, "kind", "") == "orbital_debris" and getattr(h, "id", None) == d_id), None)
            if not existing:
                angle = (2 * math.pi / self.num_debris) * i
                dx = math.cos(angle) * self.orbit_radius
                dy = math.sin(angle) * self.orbit_radius

                debris = Hazard(
                    id=d_id,
                    x=self.center_x + dx,
                    y=self.center_y + dy,
                    radius=40.0,
                    kind="orbital_debris",
                    damage=0.0
                )
                setattr(debris, "indestructible", True)
                setattr(debris, "blocks_projectiles", True)
                setattr(debris, "orbit_angle", angle)
                world.arena.hazards.append(debris)

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import math

        # Update debris positions
        for h in getattr(world.arena, "hazards", []):
            if getattr(h, "kind", "") == "orbital_debris":
                angle = getattr(h, "orbit_angle", 0.0)
                angle += self.orbit_speed * delta
                setattr(h, "orbit_angle", angle)

                h.x = self.center_x + math.cos(angle) * self.orbit_radius
                h.y = self.center_y + math.sin(angle) * self.orbit_radius

        # Gravity well logic
        well = next((h for h in getattr(world.arena, "hazards", []) if getattr(h, "kind", "") == "gravity_well" and getattr(h, "id", None) == 88888), None)
        if well:
            pull_strength = getattr(well, "pull_strength", 150.0)
            for b in balls:
                if not getattr(b, "alive", False):
                    continue
                dx = well.x - b.x
                dy = well.y - b.y
                dist = math.hypot(dx, dy)
                if 10.0 < dist < 500.0:
                    force = (pull_strength * delta) / dist
                    b.vx += dx * force
                    b.vy += dy * force


        # Projectile blocking
        if hasattr(world, "projectiles"):
            projs_to_remove = []
            for p in world.projectiles:
                for h in getattr(world.arena, "hazards", []):
                    if getattr(h, "kind", "") == "orbital_debris":
                        dx = p.x - h.x
                        dy = p.y - h.y
                        if math.hypot(dx, dy) < h.radius:
                            projs_to_remove.append(p)
                            break
            for p in projs_to_remove:
                if p in world.projectiles:
                    world.projectiles.remove(p)

        # High-speed collision damage
        for b in balls:
            if not getattr(b, "alive", False):
                continue
            speed = math.hypot(getattr(b, "vx", 0.0), getattr(b, "vy", 0.0))
            for h in getattr(world.arena, "hazards", []):
                if getattr(h, "kind", "") == "orbital_debris":
                    dx = b.x - h.x
                    dy = b.y - h.y
                    dist = math.hypot(dx, dy)
                    if dist < (getattr(b, "radius", 10.0) + getattr(h, "radius", 40.0)):
                        if speed > 200.0:
                            b.hp -= 25.0  # Burst damage for high speed collision

                        # Physics deflection (bounce off)
                        if dist > 0.01:
                            nx, ny = dx / dist, dy / dist
                            # Push ball out of hazard to prevent sticking
                            overlap = (getattr(b, "radius", 10.0) + getattr(h, "radius", 40.0)) - dist
                            b.x += nx * overlap
                            b.y += ny * overlap

                            # Reflect velocity
                            dot = (b.vx * nx + b.vy * ny)
                            b.vx -= 2 * dot * nx
                            b.vy -= 2 * dot * ny

                            # Add some dampening so it doesn't infinite bounce
                            b.vx *= 0.8
                            b.vy *= 0.8


GAME_MODES['orbital_debris'] = OrbitalDebrisMode()


class QuantumWormholeMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Quantum Wormhole"
        self.description = "A hazard zone that instantly teleports a ball to a paired zone on the other side of the arena, maintaining their exact velocity and direction, which can be used defensively or aggressively."
        self.wormholes = []
        self.setup_done = False

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_w = getattr(world.arena, "width", 800) if hasattr(world, "arena") and world.arena else 800
        arena_h = getattr(world.arena, "height", 600) if hasattr(world, "arena") and world.arena else 600

        self.wormholes = []
        self.setup_done = False

        import random
        # We will create two wormholes randomly positioned in the arena
        pad = 50.0
        w1 = {
            "x": random.uniform(pad, arena_w - pad),
            "y": random.uniform(pad, arena_h - pad),
            "radius": 50.0,
            "cooldown": 0.0,
            "linked_idx": 1
        }
        w2 = {
            "x": random.uniform(pad, arena_w - pad),
            "y": random.uniform(pad, arena_h - pad),
            "radius": 50.0,
            "cooldown": 0.0,
            "linked_idx": 0
        }
        self.wormholes.extend([w1, w2])

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        if not self.setup_done:
            self.setup(world, balls)
            self.setup_done = True

        for w in self.wormholes:
            if w["cooldown"] > 0:
                w["cooldown"] -= delta

        for i, w in enumerate(self.wormholes):
            if w["cooldown"] > 0:
                continue

            wx, wy, wr = w["x"], w["y"], w["radius"]

            # Balls teleportation
            for b in balls:
                if getattr(b, "alive", False):
                    dx = getattr(b, "x", 0.0) - wx
                    dy = getattr(b, "y", 0.0) - wy
                    import math
                    dist = math.sqrt(dx * dx + dy * dy)

                    if dist < wr + getattr(b, "radius", 10.0):
                        linked = self.wormholes[w["linked_idx"]]

                        if hasattr(world, "add_event"):
                            world.add_event("teleport_out", {"message": "Teleported!", "x": getattr(b, "x", 0.0), "y": getattr(b, "y", 0.0)})

                        b.x = linked["x"]
                        b.y = linked["y"]
                        # We do NOT reset momentum! (exact velocity maintained)

                        linked["cooldown"] = 0.5
                        w["cooldown"] = 0.5

                        if hasattr(world, "add_event"):
                            world.add_event("teleport_in", {"message": "Arrived!", "x": getattr(b, "x", 0.0), "y": getattr(b, "y", 0.0)})

                        break # Only teleport once per tick per wormhole

            # Hazards/Projectiles teleportation
            if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                for h in world.arena.hazards:
                    dx = getattr(h, "x", 0.0) - wx
                    dy = getattr(h, "y", 0.0) - wy
                    import math
                    dist = math.sqrt(dx * dx + dy * dy)
                    if dist < wr + getattr(h, "radius", 10.0):
                        linked = self.wormholes[w["linked_idx"]]
                        h.x = linked["x"]
                        h.y = linked["y"]
                        linked["cooldown"] = 0.5
                        w["cooldown"] = 0.5
                        break

            if hasattr(world, "projectiles"):
                for p in world.projectiles:
                    if getattr(p, "alive", False) or getattr(p, "active", False):
                        dx = getattr(p, "x", 0.0) - wx
                        dy = getattr(p, "y", 0.0) - wy
                        import math
                        dist = math.sqrt(dx * dx + dy * dy)
                        if dist < wr + getattr(p, "radius", 5.0):
                            linked = self.wormholes[w["linked_idx"]]
                            if hasattr(p, "x"):
                                p.x = linked["x"]
                            if hasattr(p, "y"):
                                p.y = linked["y"]
                            linked["cooldown"] = 0.5
                            w["cooldown"] = 0.5
                            break

GAME_MODES['quantum_wormhole'] = QuantumWormholeMode()



class QuantumTunnelSafeZoneMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Quantum Tunnel Safe Zone"
        self.description = "A specific biome safe zone that periodically teleports entities inside it to another random quantum tunnel biome on the map, allowing for rapid escapes or surprise attacks, but making it hard to hold ground."
        self.biomes = []
        self.biome_radius = 150.0
        self.teleport_timer = 0.0
        self.teleport_interval = 8.0
        self.outside_damage_per_second = 10.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        # Create 4 biomes
        self.biomes = [
            {"x": arena_width * 0.25, "y": arena_height * 0.25},
            {"x": arena_width * 0.75, "y": arena_height * 0.25},
            {"x": arena_width * 0.25, "y": arena_height * 0.75},
            {"x": arena_width * 0.75, "y": arena_height * 0.75},
        ]
        self.teleport_timer = 0.0

    def tick(self, world, balls, delta=0.016):
        import math, random
        self.teleport_timer += delta
        teleport_now = False
        if self.teleport_timer >= self.teleport_interval:
            self.teleport_timer = 0.0
            teleport_now = True

        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            in_biome = False
            current_biome_index = -1
            for i, biome in enumerate(self.biomes):
                dist = math.hypot(b.x - biome["x"], b.y - biome["y"])
                if dist <= self.biome_radius:
                    in_biome = True
                    current_biome_index = i
                    break

            if not in_biome:
                b.slow_timer = max(getattr(b, "slow_timer", 0.0), 0.5)
                dmg = self.outside_damage_per_second * delta
                if hasattr(b, "take_damage"):
                    b.take_damage(dmg, "quantum_tunnel_safe_zone")
                elif hasattr(b, "hp"):
                    b.hp -= dmg
                    if b.hp <= 0:
                        b.hp = 0
                        b.alive = False
            else:
                if teleport_now:
                    other_biomes = [i for i in range(len(self.biomes)) if i != current_biome_index]
                    if other_biomes:
                        target_index = random.choice(other_biomes)
                        target_biome = self.biomes[target_index]

                        b.x = target_biome["x"] + random.uniform(-20, 20)
                        b.y = target_biome["y"] + random.uniform(-20, 20)

                        if hasattr(world, "add_event"):
                            world.add_event("quantum_teleport", {"ball_id": getattr(b, "id", -1), "target_biome": target_index})

class OrbitingChaosOrbsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Orbiting Chaos Orbs"
        self.description = "Players periodically spawn orbiting chaos orbs."
        self.spawn_timer = 5.0
        self.spawn_interval = 5.0

    class ChaosOrb:
        def __init__(self, owner, angle):
            import math
            self.kind = "chaos_orb"
            self.owner = owner
            self.angle = angle
            self.orbit_speed = 3.0
            self.orbit_radius = 60.0
            self.radius = 15.0
            self.x = getattr(owner, "x", 0.0) + self.orbit_radius * math.cos(self.angle)
            self.y = getattr(owner, "y", 0.0) + self.orbit_radius * math.sin(self.angle)
            self.damage = 25.0
            self.active = True

    def setup(self, world, balls):
        super().setup(world, balls)
        self.spawn_timer = 5.0
        self.orbs = []

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        self.spawn_timer -= delta
        if self.spawn_timer <= 0:
            self.spawn_timer = self.spawn_interval
            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator":
                    import math
                    import random
                    angle = random.uniform(0, 2 * math.pi)
                    orb = self.ChaosOrb(b, angle)
                    self.orbs.append(orb)
                    if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                        world.arena.hazards.append(orb)

        for orb in self.orbs[:]:
            if not getattr(orb.owner, "alive", False):
                orb.active = False

            if not orb.active:
                self.orbs.remove(orb)
                if hasattr(world, "arena") and hasattr(world.arena, "hazards") and orb in world.arena.hazards:
                    world.arena.hazards.remove(orb)
                continue

            import math
            orb.angle += orb.orbit_speed * delta
            orb.x = getattr(orb.owner, "x", 0.0) + orb.orbit_radius * math.cos(orb.angle)
            orb.y = getattr(orb.owner, "y", 0.0) + orb.orbit_radius * math.sin(orb.angle)

            for b in balls:
                if getattr(b, "alive", False) and b != orb.owner:
                    dx = getattr(b, "x", 0.0) - orb.x
                    dy = getattr(b, "y", 0.0) - orb.y
                    dist = math.sqrt(dx*dx + dy*dy)
                    if dist < orb.radius + getattr(b, "radius", 10.0):
                        if hasattr(b, "hp"):
                            b.hp -= orb.damage
                            if hasattr(world, "add_event"):
                                world.add_event("damage", {"target": getattr(b, "id", 0), "amount": orb.damage, "source": getattr(orb.owner, "id", 0)})
                        orb.active = False
                        break

GAME_MODES['orbiting_chaos_orbs'] = OrbitingChaosOrbsMode()

class DecoySwapMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Decoy Swap"
        self.description = "Periodically swaps every player's position with their nearest active decoy or clone. If a player lacks one, a decoy is spawned at their location moments before the swap."
        self.timer = 0.0
        self.swap_interval = 12.0
        self.pre_spawn_time = 11.5
        self.pre_spawn_triggered = False

    class ChaosSwapDecoy:
        def __init__(self, target_ball):
            self.owner_id = getattr(target_ball, "id", None)
            self.x = getattr(target_ball, "x", 0.0)
            self.y = getattr(target_ball, "y", 0.0)
            self.vx = getattr(target_ball, "vx", 0.0)
            self.vy = getattr(target_ball, "vy", 0.0)
            self.radius = getattr(target_ball, "radius", 15.0)
            self.hp = 10.0
            self.max_hp = 10.0
            self.alive = True
            self.team = getattr(target_ball, "team", "neutral")
            self.is_decoy = True
            self.decoy_type = "chaos_swap"
            self.kind = "chaos_swap_decoy"
            self.decoy_timer = 5.0 # Required timer for decoys

    def tick(self, world, balls, delta=0.016):
        import math
        self.timer += delta

        if self.timer >= self.pre_spawn_time and not self.pre_spawn_triggered:
            self.pre_spawn_triggered = True
            if hasattr(world, "add_event"):
                world.add_event("chaos_swap_warning", {"message": "Chaos Swap imminent!"})

            # Find players without decoys and spawn one for them
            for b in balls:
                if getattr(b, "alive", False) and not getattr(b, "is_decoy", False) and not getattr(b, "is_decoy_clone", False) and not getattr(b, "is_illusion", False) and getattr(b, "ball_type", "") != "spectator":
                    # Check if they have an active decoy
                    has_decoy = False
                    for other in balls:
                        if getattr(other, "alive", False) and (getattr(other, "is_decoy", False) or getattr(other, "is_decoy_clone", False) or getattr(other, "is_illusion", False)):
                            if getattr(other, "owner_id", None) == b.id:
                                has_decoy = True
                                break

                    if not has_decoy:
                        decoy = self.ChaosSwapDecoy(b)
                        if hasattr(world, "next_id"):
                            decoy.id = world.next_id
                            world.next_id += 1
                        else:
                            decoy.id = 99999 + b.id

                        if hasattr(world, "balls"):
                            world.balls.append(decoy)

        if self.timer >= self.swap_interval:
            self.timer = 0.0
            self.pre_spawn_triggered = False

            if hasattr(world, "add_event"):
                world.add_event("chaos_swap_execute", {"message": "Swapped!"})

            for b in balls:
                if getattr(b, "alive", False) and not getattr(b, "is_decoy", False) and not getattr(b, "is_decoy_clone", False) and not getattr(b, "is_illusion", False) and getattr(b, "ball_type", "") != "spectator":
                    # Find nearest decoy owned by this player
                    nearest_decoy = None
                    min_dist = float('inf')
                    for other in balls:
                        if getattr(other, "alive", False) and (getattr(other, "is_decoy", False) or getattr(other, "is_decoy_clone", False) or getattr(other, "is_illusion", False)):
                            if getattr(other, "owner_id", None) == b.id:
                                dist = math.hypot(b.x - other.x, b.y - other.y)
                                if dist < min_dist:
                                    min_dist = dist
                                    nearest_decoy = other

                    if nearest_decoy:
                        # Swap positions
                        temp_x, temp_y = b.x, b.y
                        b.x, b.y = nearest_decoy.x, nearest_decoy.y
                        nearest_decoy.x, nearest_decoy.y = temp_x, temp_y

                        if hasattr(world, "events"):
                            world.events.append({
                                'type': 'visual_effect',
                                'data': {
                                    'type': 'teleport_swap',
                                    'x1': b.x,
                                    'y1': b.y,
                                    'x2': nearest_decoy.x,
                                    'y2': nearest_decoy.y
                                }
                            })

GAME_MODES['decoy_swap'] = DecoySwapMode()

