class VerticalLavaPlatformerMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Vertical Lava Platformer"
        self.description = "A vertical-scrolling platformer where balls must outrun a rising lava pool using jump pads and low gravity to reach the top."
        self.mutators_active = True
        self.mutators = ["low_gravity"]
        self.lava_y = 10000.0
        self.initialized = False

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        self.initialized = False
        if not hasattr(world, "arena"):
            return
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        import random
        arena_width = getattr(world.arena, "width", 1000.0)
        arena_height = getattr(world.arena, "height", 1000.0)

        num_pads = 15
        for i in range(num_pads):
            y_pos = arena_height - (i * (arena_height / num_pads))
            x_pos = random.uniform(100.0, arena_width - 100.0)
            bp = type("Hazard", (), {"id": 190000 + i, "x": x_pos, "y": y_pos, "radius": 40.0, "kind": "jump_pad", "damage": 0.0, "active": True})
            world.arena.hazards.append(bp)

    def apply_dynamic_traits(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        super().apply_dynamic_traits(world, balls, delta)

        arena_height = 2000.0
        if hasattr(world, 'arena') and hasattr(world.arena, 'height'):
            arena_height = world.arena.height

        if not self.initialized:
            self.lava_y = arena_height
            self.initialized = True

        self.lava_y -= 15.0 * delta

        if hasattr(world, 'arena') and hasattr(world.arena, 'platforms'):
            world.arena.platforms = [p for p in world.arena.platforms if getattr(p, 'y', 0.0) < self.lava_y]

        for b in balls:
            if getattr(b, 'alive', False):
                if getattr(b, 'y', 0.0) > self.lava_y:
                    b.hp -= 50.0 * delta
                    if b.hp <= 0:
                        b.hp = 0
                        b.alive = False
                        b.killer = "lava"

GAME_MODES['vertical_lava_platformer'] = VerticalLavaPlatformerMode()

class AlternatingZoneMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Alternating Zone"
        self.description = "A central zone that alternates between healing players and damaging them every 5 seconds."
        self.zone_x = 500.0
        self.zone_y = 500.0
        self.zone_radius = 150.0
        self.phase_duration = 5.0
        self.phase_timer = 5.0
        self.is_healing_phase = True
        self.heal_rate = 20.0
        self.damage_rate = 20.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        self.zone_x = arena_width / 2.0
        self.zone_y = arena_height / 2.0
        self.phase_timer = self.phase_duration
        self.is_healing_phase = True

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import math
        self.phase_timer -= delta
        if self.phase_timer <= 0:
            self.phase_timer = self.phase_duration
            self.is_healing_phase = not self.is_healing_phase
            phase_name = "Healing" if self.is_healing_phase else "Damaging"
            if hasattr(world, "add_event"):
                world.add_event("alternating_zone_phase", {"message": f"Zone changed to {phase_name} Phase!"})
            elif isinstance(world, dict) and "events" in world:
                world["events"].append({"type": "alternating_zone_phase", "data": {"message": f"Zone changed to {phase_name} Phase!"}})

        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                dist = math.hypot(b.x - self.zone_x, b.y - self.zone_y)
                if dist <= self.zone_radius:
                    if self.is_healing_phase:
                        max_hp = getattr(b, "max_hp", 100.0)
                        b.hp = min(b.hp + self.heal_rate * delta, max_hp)
                        b.in_healing_zone = True
                    else:
                        if hasattr(world, "_deal_damage"):
                            world._deal_damage(None, b, self.damage_rate * delta)
                        else:
                            b.hp -= self.damage_rate * delta

GAME_MODES['alternating_zone'] = AlternatingZoneMode()


class LaserMirrorBordersMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Laser Mirror Borders"
        self.description = "Arena borders are replaced with laser mirrors. Projectiles bounce infinitely but grow stronger with each bounce."

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)

        arena_width = getattr(getattr(world, "arena", None), "width", 1000)
        arena_height = getattr(getattr(world, "arena", None), "height", 1000)

        for proj in getattr(world, "projectiles", []):
            if not getattr(proj, "alive", True) and not getattr(proj, "hp", 1.0) > 0:
                continue

            x = getattr(proj, "x", 0.0)
            y = getattr(proj, "y", 0.0)
            radius = getattr(proj, "radius", 5.0)
            vx = getattr(proj, "vx", 0.0)
            vy = getattr(proj, "vy", 0.0)

            bounced = False
            if x - radius < 0 and vx < 0:
                proj.vx = -vx
                proj.x = radius
                bounced = True
            elif x + radius > arena_width and vx > 0:
                proj.vx = -vx
                proj.x = arena_width - radius
                bounced = True

            if y - radius < 0 and vy < 0:
                proj.vy = -vy
                proj.y = radius
                bounced = True
            elif y + radius > arena_height and vy > 0:
                proj.vy = -vy
                proj.y = arena_height - radius
                bounced = True

            if bounced:
                if hasattr(proj, "bounces_left"):
                    proj.bounces_left += 1
                if hasattr(proj, "damage"):
                    proj.damage *= 1.25



class RoamingBlackHoleMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Roaming Black Hole"
        self.description = "A massive black hole continuously roams and bounces around the arena, pulling players in."
        self.bh_x = 500.0
        self.bh_y = 500.0
        self.bh_vx = 150.0
        self.bh_vy = 100.0
        self.bh_radius = 80.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") else 1000
        self.bh_x = arena_width / 2.0
        self.bh_y = arena_height / 2.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        import math
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") else 1000

        self.bh_x += self.bh_vx * delta
        self.bh_y += self.bh_vy * delta

        if self.bh_x - self.bh_radius < 0:
            self.bh_x = self.bh_radius
            self.bh_vx = -self.bh_vx
        elif self.bh_x + self.bh_radius > arena_width:
            self.bh_x = arena_width - self.bh_radius
            self.bh_vx = -self.bh_vx

        if self.bh_y - self.bh_radius < 0:
            self.bh_y = self.bh_radius
            self.bh_vy = -self.bh_vy
        elif self.bh_y + self.bh_radius > arena_height:
            self.bh_y = arena_height - self.bh_radius
            self.bh_vy = -self.bh_vy

        for b in balls:
            if not getattr(b, "alive", False):
                continue

            if getattr(b, "ball_type", None) == "spectator":
                continue

            dx = self.bh_x - b.x
            dy = self.bh_y - b.y
            dist = math.hypot(dx, dy)

            if dist < self.bh_radius:
                b.hp = 0
                b.alive = False
            elif dist > 0:
                pull_strength = 2000000.0 / (dist * dist)
                pull_strength = min(pull_strength, 500.0)

                multiplier = getattr(b, "gravity_multiplier", 1.0)
                mass = getattr(b, "mass", 1.0)
                if hasattr(b, "vx") and hasattr(b, "vy"):
                    b.vx += (dx / dist) * pull_strength * multiplier / mass * delta
                    b.vy += (dy / dist) * pull_strength * multiplier / mass * delta

GAME_MODES["roaming_black_hole"] = RoamingBlackHoleMode()
