class SuddenDeathEventMode(GameMode):
    """
    An extremely rare late-game event where all balls' cooldowns are permanently reduced by 50%
    but damage taken is doubled, forcing a high-stakes fast-paced ending to the match.
    """
    def __init__(self):
        super().__init__()
        self.name = "Sudden Death Event"
        self.description = "An extremely rare late-game event where all balls' cooldowns are permanently reduced by 50% but damage taken is doubled, forcing a high-stakes fast-paced ending to the match."
        self.applied_to_balls = set()

    def setup(self, world, balls):
        super().setup(world, balls)
        self.applied_to_balls = set()
        for b in balls:
            b_hp = b.get("hp") if isinstance(b, dict) else getattr(b, "hp", 0)
            if isinstance(b, dict):
                b["_sudden_death_last_hp"] = b_hp
            else:
                setattr(b, "_sudden_death_last_hp", b_hp)

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)

        for b in balls:
            b_id = b.get("id") if isinstance(b, dict) else getattr(b, "id", None)

            # Apply permanent 50% cooldown reduction once per ball
            if b_id is not None and b_id not in self.applied_to_balls:
                self.applied_to_balls.add(b_id)
                if isinstance(b, dict):
                    if "skill_cooldown" in b: b["skill_cooldown"] *= 0.5
                    if "SKILL_COOLDOWN" in b: b["SKILL_COOLDOWN"] *= 0.5
                else:
                    if hasattr(b, "skill_cooldown"): b.skill_cooldown *= 0.5
                    if hasattr(b, "SKILL_COOLDOWN"): b.SKILL_COOLDOWN *= 0.5

            # Check for damage taken and double it
            b_hp = b.get("hp") if isinstance(b, dict) else getattr(b, "hp", 0)
            last_hp = b.get("_sudden_death_last_hp", b_hp) if isinstance(b, dict) else getattr(b, "_sudden_death_last_hp", b_hp)

            if b_hp < last_hp:
                # Took damage, subtract the exact same amount again (doubling it)
                damage_taken = last_hp - b_hp
                new_hp = b_hp - damage_taken
                if isinstance(b, dict):
                    b["hp"] = new_hp
                else:
                    b.hp = new_hp

            # Update last hp for next tick
            current_hp = b.get("hp") if isinstance(b, dict) else getattr(b, "hp", 0)
            if isinstance(b, dict):
                b["_sudden_death_last_hp"] = current_hp
            else:
                setattr(b, "_sudden_death_last_hp", current_hp)

GAME_MODES['sudden_death_event'] = SuddenDeathEventMode()



class TugOfWarMultiplePayloadsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Tug of War Multiple Payloads"
        self.description = "Spawn three payloads instead of one. Both teams fight to push/pull the payloads to the opposing team's goal."
        self.payloads = []
        self.red_goal_x = 100.0
        self.blue_goal_x = 900.0
        self.timer = 180.0
        self.mutators = []

    def setup(self, world, balls) -> None:
        super().setup(world, balls)
        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        valid_balls = [b for b in balls if getattr(b, "ball_type", None) != "spectator"]
        mid = len(valid_balls) // 2

        red_team = []
        blue_team = []

        for i, b in enumerate(valid_balls):
            if i < mid:
                b.team = "Red"
                red_team.append(b)
            else:
                b.team = "Blue"
                blue_team.append(b)

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        self.red_goal_x = 100.0
        self.blue_goal_x = arena_width - 100.0

        class PayloadObj:
            pass

        self.payloads = []
        payload_ys = [arena_height * 0.25, arena_height * 0.5, arena_height * 0.75]
        for py in payload_ys:
            payload = PayloadObj()
            payload.ball_type = "payload"
            payload.is_payload = True
            payload.is_invulnerable = True
            payload.speed = 0.0
            payload.vx = 0.0
            payload.vy = 0.0
            payload.base_speed = 0.0
            payload.damage = 0.0
            payload.base_damage = 0.0
            payload.max_hp = 10000.0
            payload.hp = 10000.0
            payload.x = arena_width / 2.0
            payload.y = py
            payload.alive = True
            payload.team = "Neutral"
            payload.radius = 20.0
            balls.append(payload)
            self.payloads.append(payload)

    def tick(self, world, balls, delta: float = 0.016) -> None:
        if getattr(self, "timer", 0) > 0:
            self.timer -= delta

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

        for payload in self.payloads:
            if payload and getattr(payload, "alive", False):
                import math
                if getattr(payload, "hp", 5000.0) < 100.0:
                    payload.hp = 5000.0

                px = getattr(payload, "x", arena_width / 2.0)
                py = getattr(payload, "y", arena_height / 2.0)
                pvx = getattr(payload, "vx", 0.0)
                pvy = getattr(payload, "vy", 0.0)

                for b in balls:
                    if b in self.payloads or not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                        continue

                    dx = getattr(b, "x", 0.0) - px
                    dy = getattr(b, "y", 0.0) - py
                    dist = math.hypot(dx, dy)
                    min_dist = getattr(payload, "radius", 20.0) + getattr(b, "radius", 10.0)

                    if 0 < dist < min_dist:
                        nx = dx / dist
                        ny = dy / dist
                        overlap = min_dist - dist

                        px -= nx * overlap * 0.5
                        b.x += nx * overlap * 0.5

                        b_vx = getattr(b, "vx", 0.0)
                        b_vy = getattr(b, "vy", 0.0)

                        dvx = b_vx - pvx
                        dvy = b_vy - pvy
                        vel_along_normal = dvx * nx + dvy * ny
                        if vel_along_normal < 0:
                            restitution = 1.2
                            speed_mult = 1.0

                            impulse = -(1 + restitution) * vel_along_normal

                            pvx -= nx * impulse * 1.5 * speed_mult
                            pvy -= ny * impulse * 1.5 * speed_mult
                            if hasattr(b, "vx"): b.vx += nx * impulse * 0.5
                            if hasattr(b, "vy"): b.vy += ny * impulse * 0.5

                pvx *= 0.99
                pvy *= 0.99
                px += pvx * delta
                py += pvy * delta

                if px < 50.0:
                    px = 50.0
                    pvx = -pvx * 0.9
                elif px > arena_width - 50.0:
                    px = arena_width - 50.0
                    pvx = -pvx * 0.9

                if py < 50.0:
                    py = 50.0
                    pvy = -pvy * 0.9
                elif py > arena_height - 50.0:
                    py = arena_height - 50.0
                    pvy = -pvy * 0.9
                speed = math.hypot(pvx, pvy)
                max_speed = 1500.0
                if speed > max_speed:
                    pvx = (pvx / speed) * max_speed
                    pvy = (pvy / speed) * max_speed

                payload.x = px
                payload.y = py
                payload.vx = pvx
                payload.vy = pvy

    def check_winner(self, world, balls):
        red_score = sum(1 for p in self.payloads if getattr(p, "x", 500) < self.red_goal_x + 50)
        blue_score = sum(1 for p in self.payloads if getattr(p, "x", 500) > self.blue_goal_x - 50)

        if getattr(self, "timer", 0) <= 0:
            if red_score > blue_score:
                return "Blue" # Blue pushed them left
            elif blue_score > red_score:
                return "Red" # Red pushed them right
            else:
                return "Draw"

        # Check if all 3 are on one side
        if red_score == 3:
            return "Blue"
        elif blue_score == 3:
            return "Red"

        return None


class ElectricDecoyLinkMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Electric Decoy Link"
        self.description = "Generating more than 5 decoys causes them to link together with electricity, damaging enemies that cross the connections."

    def tick(self, world, balls, delta=0.016):
        import math

        # Group decoys by owner
        decoys_by_owner = {}
        for b in balls:
            if getattr(b, "alive", False) and getattr(b, "is_decoy", False):
                owner_id = getattr(b, "owner_id", None)
                if owner_id is not None:
                    if owner_id not in decoys_by_owner:
                        decoys_by_owner[owner_id] = []
                    decoys_by_owner[owner_id].append(b)

        for owner_id, decoys in decoys_by_owner.items():
            if len(decoys) > 5:
                # Find the owner team
                owner_team = "neutral"
                if decoys:
                    owner_team = getattr(decoys[0], "team", "neutral")

                # For every pair of decoys for this owner, check if an enemy crosses the line
                for i in range(len(decoys)):
                    for j in range(i + 1, len(decoys)):
                        d1 = decoys[i]
                        d2 = decoys[j]

                        ax, ay = d1.x, d1.y
                        bx, by = d2.x, d2.y

                        l2 = (bx - ax)**2 + (by - ay)**2

                        for enemy in balls:
                            if not getattr(enemy, "alive", False) or getattr(enemy, "is_decoy", False) or getattr(enemy, "team", "") == owner_team:
                                continue

                            px, py = enemy.x, enemy.y
                            dist = 0.0
                            if l2 == 0:
                                dist = math.hypot(px - ax, py - ay)
                            else:
                                t = max(0, min(1, ((px - ax) * (bx - ax) + (py - ay) * (by - ay)) / l2))
                                proj_x = ax + t * (bx - ax)
                                proj_y = ay + t * (by - ay)
                                dist = math.hypot(px - proj_x, py - proj_y)

                            rad = getattr(enemy, "radius", 10.0)
                            if dist <= rad + 2.0:
                                dmg = 25.0 * delta
                                if hasattr(enemy, "take_damage"):
                                    enemy.take_damage(dmg)
                                else:
                                    enemy.hp -= dmg
                                    if enemy.hp <= 0:
                                        enemy.alive = False

                                if hasattr(world, "events"):
                                    # Create a small lightning effect
                                    if not any(e.get("type") == "electric_link_spark" for e in getattr(world, "events", [])):
                                        world.events.append({
                                            "type": "electric_link_spark",
                                            "data": {"x": px, "y": py, "radius": 5.0}
                                        })

GAME_MODES["tug_of_war_multiple_payloads"] = TugOfWarMultiplePayloadsMode()
GAME_MODES["electric_decoy_link"] = ElectricDecoyLinkMode()

GAME_MODES["fractal_payload"] = FractalPayloadMode()
class ColorSwapTeamMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Color Swap Team"
        self.description = "A team-based mode where balls can only deal damage to enemies of the matching color. Teams periodically swap colors based on a global timer, requiring dynamic positioning and target switching."
        self.kind = "color_swap_team"
        self.colors = ["red", "blue", "green", "yellow"]
        self.swap_interval = 10.0
        self.timer = 0.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        half = len(balls) // 2
        for i, b in enumerate(balls):
            b.team = "Team A" if i < half else "Team B"

        import random as _rnd
        for b in balls:
            b.current_color = _rnd.choice(self.colors)
            b.cosmetic_aura_color = self._get_aura_color(b.current_color)

    def _get_aura_color(self, color_name):
        colors = {
            "red": [1.0, 0.0, 0.0, 1.0],
            "blue": [0.0, 0.0, 1.0, 1.0],
            "green": [0.0, 1.0, 0.0, 1.0],
            "yellow": [1.0, 1.0, 0.0, 1.0]
        }
        return colors.get(color_name, [1.0, 1.0, 1.0, 1.0])

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        self.timer += delta
        if self.timer >= self.swap_interval:
            self.timer = 0.0
            import random as _rnd
            for b in balls:
                available_colors = [c for c in self.colors if c != getattr(b, "current_color", "none")]
                if not available_colors: available_colors = self.colors
                b.current_color = _rnd.choice(available_colors)
                b.cosmetic_aura_color = self._get_aura_color(b.current_color)
            if hasattr(world, "events"):
                world.events.append({"type": "color_swap", "message": "Teams swapped colors!"})

GAME_MODES["color_swap_team"] = ColorSwapTeamMode()

class WindFunnelsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Wind Funnels"
        self.description = "Stationary wind funnels shoot out air constantly in one direction, significantly speeding up balls that enter the stream."
        self.funnels = []

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        import random
        import math
        self.funnels = []
        arena_width = getattr(world.arena, "width", 1500.0)
        arena_height = getattr(world.arena, "height", 1000.0)

        # Create 3-5 funnels
        num_funnels = random.randint(3, 5)
        for _ in range(num_funnels):
            x1 = random.uniform(100, arena_width - 100)
            y1 = random.uniform(100, arena_height - 100)
            angle = random.uniform(0, 2 * math.pi)
            length = random.uniform(300, 600)
            x2 = x1 + math.cos(angle) * length
            y2 = y1 + math.sin(angle) * length

            # width is the radius of the funnel effect
            width = random.uniform(40, 80)
            force = random.uniform(800, 1500)

            self.funnels.append({
                "x1": x1, "y1": y1,
                "x2": x2, "y2": y2,
                "width": width,
                "force": force,
                "dir_x": math.cos(angle),
                "dir_y": math.sin(angle),
                "length_sq": length * length
            })

            if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
                class FallbackFunnelHazard:
                    pass
                f = type('FunnelHazard', (), {})()
                f.id = "funnel_" + str(random.randint(10000, 99999))
                f.kind = "wind_funnel_hazard"
                f.x = x1
                f.y = y1
                f.start_x = x1
                f.start_y = y1
                f.end_x = x2
                f.end_y = y2
                f.radius = width
                f.wind_force = force
                f.wind_dir_x = math.cos(angle)
                f.wind_dir_y = math.sin(angle)
                world.arena.hazards.append(f)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        super().tick(world, balls, delta)
        import math
        import random
        for b in balls:
            if not getattr(b, "alive", False): continue

            # Check if ball is in any funnel
            for f in self.funnels:
                ax, ay = f["x1"], f["y1"]
                bx, by = f["x2"], f["y2"]
                l2 = f["length_sq"]
                if l2 == 0: continue

                # Projection of b onto line AB
                px, py = b.x, b.y
                t = max(0.0, min(1.0, ((px - ax) * (bx - ax) + (py - ay) * (by - ay)) / l2))
                proj_x = ax + t * (bx - ax)
                proj_y = ay + t * (by - ay)

                dist_sq = (px - proj_x)**2 + (py - proj_y)**2
                rad = getattr(b, "radius", 10.0)
                if dist_sq <= (f["width"] + rad)**2:
                    # Inside funnel, apply force
                    # Wind tunnels provide significant speed up
                    if hasattr(b, "vx"): b.vx += f["dir_x"] * f["force"] * delta
                    if hasattr(b, "vy"): b.vy += f["dir_y"] * f["force"] * delta

                    # Optional: apply visual effect event
                    if hasattr(world, "events") and random.random() < 0.1:
                        world.events.append({
                            "type": "wind_funnel_boost",
                            "data": {"x": b.x, "y": b.y}
                        })


class ShiftingMirrorWallsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Shifting Mirror Walls"
        self.description = "Invisible mirror walls periodically shift around the arena, reflecting projectiles and player movement vectors."
        self.walls = []
        self.shift_timer = 0.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        self.walls = []
        self.shift_timer = 0.0
        self._shift_walls(world)

    def _shift_walls(self, world: 'Any') -> None:
        import random
        self.walls = []
        arena = getattr(world, "arena", None)
        arena_width = getattr(arena, "width", 1000.0) if arena else 1000.0
        arena_height = getattr(arena, "height", 1000.0) if arena else 1000.0

        # Create 2-4 random walls
        num_walls = random.randint(2, 4)
        for _ in range(num_walls):
            is_vertical = random.choice([True, False])
            if is_vertical:
                pos = random.uniform(100.0, arena_width - 100.0)
                self.walls.append({"axis": "x", "pos": pos})
            else:
                pos = random.uniform(100.0, arena_height - 100.0)
                self.walls.append({"axis": "y", "pos": pos})

        if hasattr(world, "events"):
            world.events.append({
                "type": "mirrors_shifted",
                "message": "Invisible mirror walls have shifted!"
            })

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        self.shift_timer -= delta
        if self.shift_timer <= 0:
            self._shift_walls(world)
            self.shift_timer = 15.0  # Shift every 15 seconds

        # Reflect balls
        for b in balls:
            if not getattr(b, "alive", False):
                continue
            self._handle_reflection(b, world)

        # Reflect projectiles
        arena = getattr(world, "arena", None)
        projectiles = getattr(world, "projectiles", [])
        hazards = getattr(arena, "hazards", []) if arena else []
        for p in projectiles + hazards:
            if not getattr(p, "alive", True) and not getattr(p, "hp", 1.0) > 0:
                continue
            b_type = getattr(p, "ball_type", getattr(p, "kind", ""))
            is_proj = b_type in ["projectile", "spell", "fireball", "bullet", "snipe", "laser_beam"] or getattr(p, "is_projectile", False) or getattr(p, "is_spell", False)
            if is_proj:
                self._handle_reflection(p, world)

    def _handle_reflection(self, entity: 'Any', world: 'Any') -> None:
        x = getattr(entity, "x", 0.0)
        y = getattr(entity, "y", 0.0)
        radius = getattr(entity, "radius", 15.0)
        vx = getattr(entity, "vx", 0.0)
        vy = getattr(entity, "vy", 0.0)

        bounced = False
        for wall in self.walls:
            if wall["axis"] == "x":
                pos = wall["pos"]
                next_x = x + vx * 0.016
                if (x <= pos and next_x + radius >= pos) or (x >= pos and next_x - radius <= pos) or abs(x - pos) < radius or (x < pos and next_x > pos) or (x > pos and next_x < pos):
                    if vx > 0 and x <= pos + radius:
                        vx = -vx
                        x = pos - radius
                        bounced = True
                    elif vx < 0 and x >= pos - radius:
                        vx = -vx
                        x = pos + radius
                        bounced = True
            else:
                pos = wall["pos"]
                next_y = y + vy * 0.016
                if (y <= pos and next_y + radius >= pos) or (y >= pos and next_y - radius <= pos) or abs(y - pos) < radius or (y < pos and next_y > pos) or (y > pos and next_y < pos):
                    if vy > 0 and y <= pos + radius:
                        vy = -vy
                        y = pos - radius
                        bounced = True
                    elif vy < 0 and y >= pos - radius:
                        vy = -vy
                        y = pos + radius
                        bounced = True

        if bounced:
            entity.x = x
            entity.y = y
            entity.vx = vx
            entity.vy = vy
            if hasattr(world, "events"):
                world.events.append({"type": "mirror_bounce", "x": x, "y": y})

GAME_MODES["shifting_mirror_walls"] = ShiftingMirrorWallsMode()

GAME_MODES["wind_funnels"] = WindFunnelsMode()

class WindTunnelMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Wind Tunnel"
        self.description = "A new hazard 'Wind Tunnel' that generates a narrow, extremely fast wind current across the arena. Any ball entering it gets accelerated to high speeds along the tunnel, allowing for quick escapes or surprise attacks, but making it hard to steer."

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        import random
        import math

        arena_width = getattr(world.arena, "width", 1500.0)
        arena_height = getattr(world.arena, "height", 1000.0)

        # Create one big wind tunnel across the arena
        cx = arena_width / 2.0
        cy = arena_height / 2.0

        angle = random.uniform(0, math.pi * 2)
        length = max(arena_width, arena_height) * 1.5

        start_x = cx - math.cos(angle) * (length / 2.0)
        start_y = cy - math.sin(angle) * (length / 2.0)
        end_x = cx + math.cos(angle) * (length / 2.0)
        end_y = cy + math.sin(angle) * (length / 2.0)

        width = 100.0 # narrow
        force = 2500.0 # extremely fast

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            class FallbackFunnelHazard:
                pass
            f = type('WindTunnelHazard', (), {})()
            f.id = "wind_tunnel_" + str(random.randint(10000, 99999))
            f.kind = "wind_tunnel"
            f.x = cx
            f.y = cy
            f.start_x = start_x
            f.start_y = start_y
            f.end_x = end_x
            f.end_y = end_y
            f.radius = width
            f.wind_force = force
            f.wind_dir_x = math.cos(angle)
            f.wind_dir_y = math.sin(angle)
            f.active = True
            world.arena.hazards.append(f)

GAME_MODES["wind_tunnel"] = WindTunnelMode()


class GhostOrbMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Ghost Orb"
        self.description = "When a ball dies, it leaves behind a ghost orb that chases living players and drains their stamina if touched."
        self.ghost_orbs = []

    class GhostOrb:
        def __init__(self, x, y):
            self.kind = "ghost_orb"
            self.x = x
            self.y = y
            self.radius = 20.0
            self.speed = 100.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.ghost_orbs = []

    def on_ball_died(self, world, ball, killer=None):
        if hasattr(super(), "on_ball_died"):
            super().on_ball_died(world, ball, killer)

        x = getattr(ball, "x", 0.0)
        y = getattr(ball, "y", 0.0)
        orb = self.GhostOrb(x, y)
        self.ghost_orbs.append(orb)
        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            world.arena.hazards.append(orb)

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import math

        living_balls = [b for b in balls if getattr(b, "alive", False) and getattr(b, "ball_type", "") != "spectator"]

        for orb in self.ghost_orbs:
            closest = None
            min_dist = float('inf')
            for b in living_balls:
                dist = math.hypot(b.x - orb.x, b.y - orb.y)
                if dist < min_dist:
                    min_dist = dist
                    closest = b

            if closest and min_dist > 0:
                orb.x += (closest.x - orb.x) / min_dist * orb.speed * delta
                orb.y += (closest.y - orb.y) / min_dist * orb.speed * delta

            for b in living_balls:
                dist = math.hypot(b.x - orb.x, b.y - orb.y)
                if dist <= orb.radius + getattr(b, "radius", 15.0):
                    if hasattr(b, "stamina"):
                        b.stamina = max(0.0, getattr(b, "stamina", 100.0) - 50.0 * delta)

GAME_MODES["ghost_orb"] = GhostOrbMode()


class SuperVortexMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Super Vortex"
        self.description = "Multiple black holes roam the arena and periodically merge into a massive super-vortex at the center."
        self.bhs = []
        self.phase = "split"
        self.phase_timer = 0.0
        self.split_duration = 15.0
        self.merged_duration = 5.0
        self.small_bh_radius = 40.0
        self.super_bh_radius = 120.0
        self.small_pull = 100.0
        self.super_pull = 400.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") else 1000
        self.bhs = [
            {"x": arena_width * 0.25, "y": arena_height * 0.25, "vx": 100.0, "vy": 150.0},
            {"x": arena_width * 0.75, "y": arena_height * 0.25, "vx": -150.0, "vy": 100.0},
            {"x": arena_width * 0.5, "y": arena_height * 0.75, "vx": 120.0, "vy": -120.0},
        ]
        self.phase = "split"
        self.phase_timer = self.split_duration

    def tick(self, world, balls, delta=0.016):
        import math
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") else 1000
        cx = arena_width / 2.0
        cy = arena_height / 2.0

        self.phase_timer -= delta
        if self.phase_timer <= 0:
            if self.phase == "split":
                self.phase = "merged"
                self.phase_timer = self.merged_duration
            else:
                self.phase = "split"
                self.phase_timer = self.split_duration

        if self.phase == "split":
            # Move small black holes
            for bh in self.bhs:
                bh["x"] += bh["vx"] * delta
                bh["y"] += bh["vy"] * delta

                if bh["x"] - self.small_bh_radius < 0:
                    bh["x"] = self.small_bh_radius
                    bh["vx"] *= -1
                elif bh["x"] + self.small_bh_radius > arena_width:
                    bh["x"] = arena_width - self.small_bh_radius
                    bh["vx"] *= -1

                if bh["y"] - self.small_bh_radius < 0:
                    bh["y"] = self.small_bh_radius
                    bh["vy"] *= -1
                elif bh["y"] + self.small_bh_radius > arena_height:
                    bh["y"] = arena_height - self.small_bh_radius
                    bh["vy"] *= -1

            # Pull balls
            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                    continue
                for bh in self.bhs:
                    dx = bh["x"] - b.x
                    dy = bh["y"] - b.y
                    dist = math.hypot(dx, dy)
                    if dist > 0 and dist < 400.0:
                        pull = self.small_pull * (1.0 - dist / 400.0)
                        if not hasattr(b, "vx"): b.vx = 0.0
                        if not hasattr(b, "vy"): b.vy = 0.0
                        b.vx += (dx / dist) * pull * delta
                        b.vy += (dy / dist) * pull * delta

        elif self.phase == "merged":
            # Pull balls to center
            for b in balls:
                if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                    continue
                dx = cx - b.x
                dy = cy - b.y
                dist = math.hypot(dx, dy)
                if dist > 0:
                    pull = self.super_pull * (1.0 - min(dist / 800.0, 1.0))
                    if not hasattr(b, "vx"): b.vx = 0.0
                    if not hasattr(b, "vy"): b.vy = 0.0
                    b.vx += (dx / dist) * pull * delta
                    b.vy += (dy / dist) * pull * delta


class StaticFieldMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Static Field Mutator"
        self.description = "Each time a player uses chain lightning, the leftover electric charge stays in the air, creating a static field that slows down all entities and gradually damages those without electric immunity over time."

    def tick(self, world, balls, delta=0.016):
        import math

        if not hasattr(world, "arena"):
            return

        if not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        if hasattr(world, "events"):
            for event in world.events:
                ev_type = None
                ev_data = None
                if isinstance(event, tuple) and len(event) == 2:
                    ev_type = event[0]
                    ev_data = event[1]
                elif isinstance(event, dict) and "type" in event:
                    ev_type = event["type"]
                    ev_data = event.get("data", {})

                if ev_type == "chain_lightning" and isinstance(ev_data, dict):
                    # Try to find x, y. The event might only have source/target ids.
                    hx, hy = None, None
                    if "x" in ev_data and "y" in ev_data:
                        hx, hy = ev_data["x"], ev_data["y"]
                    elif "target" in ev_data:
                        target_id = ev_data["target"]
                        for b in balls:
                            if getattr(b, "id", None) == target_id:
                                hx, hy = getattr(b, "x", 0.0), getattr(b, "y", 0.0)
                                break
                    elif "source" in ev_data:
                        source_id = ev_data["source"]
                        for b in balls:
                            if getattr(b, "id", None) == source_id:
                                hx, hy = getattr(b, "x", 0.0), getattr(b, "y", 0.0)
                                break

                    if hx is not None and hy is not None:
                        # Append the static field hazard
                        world.arena.hazards.append({
                            "kind": "static_field",
                            "x": hx,
                            "y": hy,
                            "radius": 150.0,
                            "duration": 5.0,
                            "active": True
                        })

        active_hazards = []
        for h in world.arena.hazards:
            if getattr(h, "kind", "") == "static_field" or (isinstance(h, dict) and h.get("kind") == "static_field"):
                # Handle dict or object
                is_dict = isinstance(h, dict)
                dur = h.get("duration", 0.0) if is_dict else getattr(h, "duration", 0.0)
                dur -= delta
                if is_dict:
                    h["duration"] = dur
                else:
                    h.duration = dur

                if dur > 0:
                    active_hazards.append(h)
                    hx = h.get("x", 0.0) if is_dict else getattr(h, "x", 0.0)
                    hy = h.get("y", 0.0) if is_dict else getattr(h, "y", 0.0)
                    hr = h.get("radius", 150.0) if is_dict else getattr(h, "radius", 150.0)
                    hr_sq = hr * hr

                    for b in balls:
                        if not getattr(b, "alive", True):
                            continue

                        # Check distance
                        bx = getattr(b, "x", 0.0)
                        by = getattr(b, "y", 0.0)
                        dist_sq = (bx - hx)**2 + (by - hy)**2
                        if dist_sq <= hr_sq:
                            # Apply slowing effect
                            b.speed_debuff_timer = max(getattr(b, "speed_debuff_timer", 0.0), 0.5)
                            b.speed_debuff_multiplier = 0.5

                            # Check electric immunity
                            is_immune = getattr(b, "electric_immunity", False)

                            # Additional checks from trace for electric/lightning element types
                            b_type = getattr(b, "ball_type", "").lower()
                            traits = getattr(b, "traits", [])
                            if "lightning" in b_type or "lightning" in traits or "electric" in b_type or "electric" in traits:
                                is_immune = True

                            if not is_immune:
                                # Apply damage over time
                                dmg = 10.0 * delta
                                if hasattr(b, "take_damage"):
                                    b.take_damage(dmg)
                                else:
                                    b.hp = getattr(b, "hp", 100.0) - dmg
            else:
                active_hazards.append(h)

        world.arena.hazards = active_hazards


class LowGravityZoneMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Low Gravity Zone"
        self.description = "An area where jumps go much higher and falling is slow."
        self.zone_radius = 250.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        self.apply_dynamic_traits(world, balls, delta)

        if not hasattr(world, 'arena'):
            return

        cx = getattr(world.arena, "width", 1000) / 2.0
        cy = getattr(world.arena, "height", 1000) / 2.0

        for b in balls:
            if not getattr(b, 'alive', False) or getattr(b, 'ball_type', None) == 'spectator':
                continue

            dist = ((getattr(b, "x", 0) - cx)**2 + (getattr(b, "y", 0) - cy)**2)**0.5
            if dist < self.zone_radius:
                if not getattr(b, '_low_gravity_zone_active', False):
                    b._low_gravity_zone_active = True
                    b._base_mass_low_grav = getattr(b, 'mass', 1.0)

                # Apply low gravity effects
                b.mass = getattr(b, '_base_mass_low_grav', 1.0) * 0.2
                if getattr(b, 'vy', 0) > 0:
                    b.vy = max(0.0, b.vy - 1200.0 * delta) # Counteract downward velocity smoothly without jitter
            else:
                if getattr(b, '_low_gravity_zone_active', False):
                    b._low_gravity_zone_active = False
                    if hasattr(b, '_base_mass_low_grav'):
                        b.mass = getattr(b, '_base_mass_low_grav', 1.0)


GAME_MODES['static_field_mutator'] = StaticFieldMutatorMode()

GAME_MODES['super_vortex'] = SuperVortexMode()


class PeriodicLowGravityMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Periodic Low Gravity"
        self.description = "Intermittently turns the gravity extremely low, which makes balls jump much further and halves friction. A chaotic mutator that completely changes pacing every few seconds."
        self.mutators_active = True
        self.mutators = []
        self.timer = 0.0
        self.duration = 10.0
        self.low_grav_active = False

    def setup(self, world, balls):
        super().setup(world, balls)
        self.timer = 0.0
        self.low_grav_active = False
        self.mutators = []

    def apply_dynamic_traits(self, world, balls, delta):
        super().apply_dynamic_traits(world, balls, delta)
        self.timer += delta

        if self.low_grav_active:
            if self.timer >= self.duration:
                self.low_grav_active = False
                self.timer = 0.0
                if "low_gravity" in self.mutators:
                    self.mutators.remove("low_gravity")
                if hasattr(world, "add_event"):
                    world.add_event("gravity_normal", {"message": "Gravity returned to normal!"})

                # Restore state
                for b in balls:
                    if getattr(b, "alive", False):
                        is_applied = getattr(b, "_periodic_low_grav_applied", False)
                        if is_applied:
                            b.is_frictionless = getattr(b, "_orig_frictionless", False)
                            if hasattr(b, "_orig_mass"):
                                b.mass = b._orig_mass
                            b._periodic_low_grav_applied = False
            else:
                if "low_gravity" not in self.mutators:
                    self.mutators.append("low_gravity")

                # Apply state once
                for b in balls:
                    if getattr(b, "alive", False):
                        is_applied = getattr(b, "_periodic_low_grav_applied", False)
                        if not is_applied:
                            b._orig_frictionless = getattr(b, "is_frictionless", False)
                            b._orig_mass = getattr(b, "mass", 1.0)

                            b.is_frictionless = True
                            b.mass = b._orig_mass * 0.5
                            b._periodic_low_grav_applied = True
        else:
            if self.timer >= self.duration:
                self.low_grav_active = True
                self.timer = 0.0
                if hasattr(world, "add_event"):
                    world.add_event("gravity_low", {"message": "Low gravity warning!"})

GAME_MODES['periodic_low_gravity_mutator'] = PeriodicLowGravityMutatorMode()


class MagneticShrinkingFieldMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Magnetic Shrinking Field"
        self.description = "A powerful magnetic field slowly shrinks towards the center. Balls outside the field are pulled violently into walls or hazards, while balls inside must fight for the remaining stable space."
        self.min_x = 0.0
        self.max_x = 1000.0
        self.min_y = 0.0
        self.max_y = 1000.0
        self.shrink_rate = 15.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        self.min_x = 0.0
        self.max_x = arena_width
        self.min_y = 0.0
        self.max_y = arena_height

    def tick(self, world, balls, delta=0.016):
        import math

        # Shrink map boundaries inward
        if self.max_x - self.min_x > 50.0:
            self.min_x += self.shrink_rate * delta
            self.max_x -= self.shrink_rate * delta

        if self.max_y - self.min_y > 50.0:
            self.min_y += self.shrink_rate * delta
            self.max_y -= self.shrink_rate * delta

        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        center_x = arena_width / 2.0
        center_y = arena_height / 2.0

        for b in balls:
            if not getattr(b, "alive", True):
                continue

            bx = getattr(b, "x", 0.0)
            by = getattr(b, "y", 0.0)

            # Check if outside safe zone
            if bx < self.min_x or bx > self.max_x or by < self.min_y or by > self.max_y:
                # Pulled violently into walls (outwards)
                dx = bx - center_x
                dy = by - center_y
                dist = math.sqrt(dx**2 + dy**2)

                if dist > 0.0:
                    dx /= dist
                    dy /= dist
                else:
                    dx = 1.0
                    dy = 0.0

                pull_strength = 2000.0 * delta # Violent pull
                b.x = bx + dx * pull_strength
                b.y = by + dy * pull_strength

                # Apply damage for being outside the zone
                dmg = 20.0 * delta
                if hasattr(b, "take_damage"):
                    b.take_damage(dmg)
                else:
                    b.hp = getattr(b, "hp", 100.0) - dmg

GAME_MODES['magnetic_shrinking_field'] = MagneticShrinkingFieldMode()


class ClanHubMode(GameMode):
    """A non-combat social environment tailored to a single clan where members can hang out, interact with clan-specific NPCs, and view their stash and unlocked decorations."""
    def __init__(self):
        super().__init__()
        self.name = "clan_hub"
        self.desc = "Clan social hub and physical stash."
        self.hub_clan = None

    def setup(self, world: Any, balls: List[Any]) -> None:
        super().setup(world, balls)

        self.hub_clan = getattr(world, "hub_clan", None)
        if not self.hub_clan:
            for b in balls:
                if getattr(b, "clan", None):
                    self.hub_clan = getattr(b, "clan", None)
                    break

        for b in balls:
            b.base_damage = 0.0
            b.damage = 0.0
            b.invulnerable = True

        if not self.hub_clan:
            return

        clan_manager = getattr(world, "clan_manager", None)
        if not clan_manager and hasattr(world, "profile_manager") and hasattr(world.profile_manager, "clan_manager"):
            clan_manager = world.profile_manager.clan_manager

        if not clan_manager:
            return

        clan_data = clan_manager.data.get("clans", {}).get(self.hub_clan, {})

        if not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        for pet in clan_data.get("hub_pets", []):
            pet_name = pet.get("pet", "Unknown")
            x = pet.get("x", 0)
            y = pet.get("y", 0)
            world.arena.hazards.append({
                "kind": "clan_pet",
                "name": pet_name,
                "x": float(x),
                "y": float(y),
                "radius": 25.0
            })

        for dec in clan_data.get("hub", []):
            dec_name = dec.get("decoration", "Unknown")
            x = dec.get("x", 0)
            y = dec.get("y", 0)
            world.arena.hazards.append({
                "kind": "clan_decoration",
                "name": dec_name,
                "x": float(x),
                "y": float(y),
                "radius": 20.0
            })

        stash_x = 200.0
        stash_y = 200.0
        for item_name, amount in clan_data.get("stash", {}).items():
            if amount > 0:
                world.arena.hazards.append({
                    "kind": "clan_stash_pile",
                    "item": item_name,
                    "amount": amount,
                    "x": float(stash_x),
                    "y": float(stash_y),
                    "radius": 15.0
                })
                stash_x += 40.0

        world.arena.hazards.append({
            "kind": "clan_npc",
            "role": "stash_master",
            "x": 400.0,
            "y": 100.0,
            "radius": 30.0
        })
        world.arena.hazards.append({
            "kind": "clan_npc",
            "role": "quest_master",
            "x": 100.0,
            "y": 400.0,
            "radius": 30.0
        })

    def tick(self, world: Any, delta: float) -> None:
        if not self.hub_clan:
            return

        clan_manager = getattr(world, "clan_manager", None)
        if not clan_manager and hasattr(world, "profile_manager") and hasattr(world.profile_manager, "clan_manager"):
            clan_manager = world.profile_manager.clan_manager

        hub_buffs = []
        if clan_manager:
            hub_buffs = clan_manager.get_hub_buffs(self.hub_clan)
            hub_pet_buffs = clan_manager.get_hub_pet_buffs(self.hub_clan) if hasattr(clan_manager, "get_hub_pet_buffs") else []

        balls = getattr(world, "balls", [])

        for b in balls:
            if b.alive:
                for buff in hub_buffs:
                    if buff == "Hub_Speed_Boost":
                        b.speed = getattr(b, "base_speed", 100.0) + 20.0
                    elif buff == "Hub_Health_Regen":
                        if hasattr(b, "hp") and hasattr(b, "max_hp") and b.hp < b.max_hp:
                            b.hp = min(b.max_hp, b.hp + 5.0 * delta)

        hazards = getattr(world.arena, "hazards", []) if hasattr(world, "arena") else []
        for h in hazards:
            kind = h.get("kind", "") if isinstance(h, dict) else getattr(h, "kind", "")
            if kind == "clan_pet":
                hx = h.get("x", 0) if isinstance(h, dict) else getattr(h, "x", 0)
                hy = h.get("y", 0) if isinstance(h, dict) else getattr(h, "y", 0)
                h_radius = h.get("radius", 25.0) if isinstance(h, dict) else getattr(h, "radius", 25.0)

                for b in balls:
                    if not b.alive: continue
                    bx = getattr(b, "x", 0)
                    by = getattr(b, "y", 0)
                    br = getattr(b, "radius", 10.0)
                    dist = ((bx - hx)**2 + (by - hy)**2)**0.5

                    if dist < (br + h_radius + 20.0):
                        pet_buffs = hub_pet_buffs
                        for buff in pet_buffs:
                            if buff == "Pet_Speed_Boost":
                                b.speed = getattr(b, "base_speed", 100.0) + 15.0
                            elif buff == "Pet_Health_Regen":
                                if hasattr(b, "hp") and hasattr(b, "max_hp") and b.hp < b.max_hp:
                                    b.hp = min(b.max_hp, b.hp + 3.0 * delta)
                            elif buff == "Pet_Golden_Aura":
                                b.gold = getattr(b, "gold", 0) # Just a passive check or logic if needed, maybe we don't modify gold actively here, just a buff aura

            if kind == "clan_npc":
                hx = h.get("x", 0) if isinstance(h, dict) else getattr(h, "x", 0)
                hy = h.get("y", 0) if isinstance(h, dict) else getattr(h, "y", 0)
                h_radius = h.get("radius", 30.0) if isinstance(h, dict) else getattr(h, "radius", 30.0)
                role = h.get("role", "npc") if isinstance(h, dict) else getattr(h, "role", "npc")

                for b in balls:
                    if not b.alive:
                        continue
                    bx = getattr(b, "x", 0)
                    by = getattr(b, "y", 0)
                    br = getattr(b, "radius", 10.0)
                    dist = ((bx - hx)**2 + (by - hy)**2)**0.5
                    if dist < (br + h_radius + 10.0):
                        last_interaction = getattr(b, "last_npc_interaction", 0)
                        current_time = getattr(world, "time", 0)
                        if current_time - last_interaction > 1.0:
                            world.add_event("npc_interaction", {"npc": role, "player": getattr(b, "id", "")})
                            b.last_npc_interaction = current_time


class OrbitalBlackHoleEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Orbital Black Hole Event"
        self.description = "A massive central black hole occasionally spawns, heavily modifying the trajectory of all projectiles and slightly pulling balls inward while providing an orbit-like speed boost to tangential movement."
        self.active = False
        self.timer = 0.0
        self.pull_strength = 50.0
        self.tangential_boost = 150.0
        self.projectile_pull = 500.0

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random
        import math

        if not self.active:
            if random.random() < 0.02 * delta:
                self.active = True
                self.timer = 15.0
                if hasattr(world, "add_event"):
                    world.add_event("orbital_black_hole", {"message": "An orbital black hole has appeared!"})
        else:
            self.timer -= delta
            if self.timer <= 0:
                self.active = False
                if hasattr(world, "add_event"):
                    world.add_event("orbital_black_hole_end", {"message": "The orbital black hole has vanished."})
                return

            arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
            arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000

            cx = arena_width / 2.0
            cy = arena_height / 2.0

            for b in balls:
                if not getattr(b, "alive", False): continue
                if getattr(b, "ball_type", "") == "spectator": continue

                dx = cx - getattr(b, "x", 0)
                dy = cy - getattr(b, "y", 0)
                dist = math.hypot(dx, dy)

                if dist > 0:
                    b.x += (dx / dist) * self.pull_strength * delta
                    b.y += (dy / dist) * self.pull_strength * delta

                    tangent_x = -dy / dist
                    tangent_y = dx / dist

                    vx = getattr(b, "vx", 0)
                    vy = getattr(b, "vy", 0)
                    dot1 = vx * tangent_x + vy * tangent_y
                    dot2 = vx * (-tangent_x) + vy * (-tangent_y)

                    if dot2 > dot1:
                        tangent_x = -tangent_x
                        tangent_y = -tangent_y

                    b.x += tangent_x * self.tangential_boost * delta
                    b.y += tangent_y * self.tangential_boost * delta

            if hasattr(world, "projectiles"):
                for proj in world.projectiles:
                    dx = cx - getattr(proj, "x", 0)
                    dy = cy - getattr(proj, "y", 0)
                    dist = math.hypot(dx, dy)
                    if dist > 0:
                        if hasattr(proj, "vx") and hasattr(proj, "vy"):
                            proj.vx += (dx / dist) * self.projectile_pull * delta
                            proj.vy += (dy / dist) * self.projectile_pull * delta

GAME_MODES["clan_hub"] = ClanHubMode()
GAME_MODES["orbital_black_hole_event"] = OrbitalBlackHoleEventMode()

class PeriodicGhostMutatorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Periodic Ghost"
        self.description = "Players periodically become ghosts and can pass through walls."
        self.mutators_active = True
        self.mutators = []
        self.timer = 0.0
        self.duration = 10.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.timer = 0.0
        self.mutators = []

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)
        self.timer += delta

        if self.timer >= self.duration:
            self.timer = 0.0
            if hasattr(world, "add_event"):
                world.add_event("ghost_mode", {"message": "Ghost mode activated!"})

            for b in balls:
                if getattr(b, "alive", False) and getattr(b, "ball_type", None) != "spectator":
                    b.intangible = True
                    b.intangible_timer = 3.0
                    b.ghost_mode_active = True
                    b.ghost_mode_timer = 3.0

GAME_MODES['periodic_ghost_mutator'] = PeriodicGhostMutatorMode()

class ConfettiCelebrationMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Confetti Celebration"
        self.description = "When a ball is eliminated, instead of just disappearing, it triggers a massive confetti explosion that momentarily blinds nearby players and applies a small speed buff to everyone caught in it, simulating a chaotic celebration."

    def on_ball_died(self, world, ball, killer=None):
        if hasattr(super(), "on_ball_died"):
            super().on_ball_died(world, ball, killer)

        if isinstance(ball, dict):
            ex_x = ball.get("x", 0.0)
            ex_y = ball.get("y", 0.0)
        else:
            ex_x = getattr(ball, "x", 0.0)
            ex_y = getattr(ball, "y", 0.0)

        # Trigger event for visual effect
        if hasattr(world, "add_event"):
            world.add_event("confetti_explosion", {"x": ex_x, "y": ex_y, "radius": 400.0})
        elif isinstance(world, dict) and "events" in world:
            world["events"].append({"type": "confetti_explosion", "data": {"x": ex_x, "y": ex_y, "radius": 400.0}})

        balls = []
        if isinstance(world, dict):
            balls = world.get("balls", [])
        else:
            balls = getattr(world, "balls", getattr(world, "entities", []))

        for b in balls:
            is_b_dict = isinstance(b, dict)
            is_alive = b.get("alive", False) if is_b_dict else getattr(b, "alive", False)
            if not is_alive: continue

            b_type = b.get("ball_type", "") if is_b_dict else getattr(b, "ball_type", "")
            if b_type == "spectator": continue

            b_x = b.get("x", 0.0) if is_b_dict else getattr(b, "x", 0.0)
            b_y = b.get("y", 0.0) if is_b_dict else getattr(b, "y", 0.0)

            dist_sq = (b_x - ex_x)**2 + (b_y - ex_y)**2
            if dist_sq <= 400.0**2:
                # Apply blindness and speed buff
                if is_b_dict:
                    b["is_blinded"] = True
                    b["blindness_timer"] = max(b.get("blindness_timer", 0.0), 2.0)
                    b["speed_boost_timer"] = max(b.get("speed_boost_timer", 0.0), 3.0)
                else:
                    b.is_blinded = True
                    b.blindness_timer = max(getattr(b, "blindness_timer", 0.0), 2.0)
                    b.speed_boost_timer = max(getattr(b, "speed_boost_timer", 0.0), 3.0)

GAME_MODES['confetti_celebration'] = ConfettiCelebrationMode()

class ConvergingSafeZonesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Converging Safe Zones"
        self.description = "Multiple safe zones slowly converge and combine into one at the center, forcing different groups to travel and meet."
        self.zones = []
        self.center_x = 500.0
        self.center_y = 500.0

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_width = getattr(world.arena, "width", 1000) if hasattr(world, "arena") and world.arena else 1000
        arena_height = getattr(world.arena, "height", 1000) if hasattr(world, "arena") and world.arena else 1000
        self.center_x = arena_width / 2.0
        self.center_y = arena_height / 2.0
        self.zones = []

        # Spawn initial zones near corners
        corners = [
            (200, 200), (arena_width - 200, 200),
            (200, arena_height - 200), (arena_width - 200, arena_height - 200)
        ]

        for cx, cy in corners:
            self.zones.append({
                "x": cx,
                "y": cy,
                "radius": 200.0
            })

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import math

        if not hasattr(world, "dead_balls"):
            world.dead_balls = []

        # move zones towards center
        converge_speed = 15.0
        active_zones = []
        for z in self.zones:
            dx = self.center_x - z["x"]
            dy = self.center_y - z["y"]
            dist = math.sqrt(dx*dx + dy*dy)

            if dist > 5.0:
                z["x"] += (dx / dist) * converge_speed * delta
                z["y"] += (dy / dist) * converge_speed * delta

            active_zones.append(z)

        self.zones = active_zones

        # check player bounds
        for ball in balls:
            w_timer = getattr(ball, 'weather_immunity_timer', 0.0)
            is_immune = (w_timer > 0.0) if isinstance(w_timer, (int, float)) else False
            if not getattr(ball, "alive", False):
                continue
            if is_immune:
                continue

            in_zone = False
            for z in self.zones:
                dx = ball.x - z["x"]
                dy = ball.y - z["y"]
                if math.sqrt(dx*dx + dy*dy) <= z["radius"]:
                    in_zone = True
                    break

            if not in_zone:
                damage = 25.0 * delta
                if hasattr(ball, "take_damage"):
                    ball.take_damage(damage)
                else:
                    ball.hp -= damage
                    if ball.hp <= 0:
                        ball.hp = 0
                        ball.alive = False
                        if hasattr(ball, "id") and ball.id not in world.dead_balls:
                            world.dead_balls.append(ball.id)
                            if hasattr(world, "add_event"):
                                world.add_event("ball_died", {"id": ball.id, "reason": "outside_zone", "killer_id": -1})
GAME_MODES['converging_safe_zones'] = ConvergingSafeZonesMode()

class BoundaryBuilderMode(ShrinkingArenaMode):
    def __init__(self):
        super().__init__()
        self.name = "Boundary Builder"
        self.description = "Players collect resource blocks to rebuild the shrinking arena boundary and create defensive bunkers."
        self.resource_timer = 0.0
        self.bunkers = []

    class ResourceBlock:
        def __init__(self, id_val, x, y):
            self.id = id_val
            self.x = x
            self.y = y
            self.radius = 15.0
            self.kind = "resource_block"
            self.active = True

    class Bunker:
        def __init__(self, id_val, team, x, y):
            self.id = id_val
            self.team = team
            self.x = x
            self.y = y
            self.radius = 40.0
            self.hp = 500.0
            self.max_hp = 500.0
            self.kind = "bunker"
            self.active = True

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        self.resource_timer += delta
        if self.resource_timer >= 5.0:
            self.resource_timer -= 5.0
            if hasattr(world, "arena"):
                import random
                aw = getattr(world.arena, "width", 1000.0)
                ah = getattr(world.arena, "height", 1000.0)
                if not hasattr(self, "next_block_id"):
                    self.next_block_id = 1000
                new_block = self.ResourceBlock(
                    self.next_block_id,
                    random.uniform(50, aw - 50),
                    random.uniform(50, ah - 50)
                )
                self.next_block_id += 1
                if not hasattr(world.arena, "hazards"):
                    world.arena.hazards = []
                world.arena.hazards.append(new_block)

        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            for h in list(world.arena.hazards):
                if getattr(h, "kind", "") == "resource_block" and getattr(h, "active", True):
                    for b in balls:
                        if not getattr(b, "alive", True):
                            continue
                        import math
                        bx = getattr(b, "x", 0.0)
                        by = getattr(b, "y", 0.0)
                        br = getattr(b, "radius", 15.0)
                        hx = getattr(h, "x", 0.0)
                        hy = getattr(h, "y", 0.0)
                        hr = getattr(h, "radius", 15.0)
                        dist = math.hypot(bx - hx, by - hy)
                        if dist < br + hr:
                            h.active = False
                            world.arena.hazards.remove(h)
                            b_res = getattr(b, "blocks_collected", 0) + 1
                            b.blocks_collected = b_res

                            if b_res >= 3:
                                b.blocks_collected -= 3
                                # Rebuild boundary by expanding it slightly
                                ow = getattr(world.arena, "width", 1000.0)
                                oh = getattr(world.arena, "height", 1000.0)
                                nw = min(2000.0, ow + 50.0)
                                nh = min(2000.0, oh + 50.0)
                                world.arena.width = nw
                                world.arena.height = nh

                                # And build a bunker
                                if not hasattr(self, "next_bunker_id"):
                                    self.next_bunker_id = 2000
                                bunker = self.Bunker(self.next_bunker_id, getattr(b, "team", "neutral"), bx, by)
                                self.next_bunker_id += 1
                                self.bunkers.append(bunker)
                                world.arena.hazards.append(bunker)
                            break

            for h in list(world.arena.hazards):
                if getattr(h, "kind", "") == "bunker" and getattr(h, "active", True):
                    for b in balls:
                        if not getattr(b, "alive", True):
                            continue
                        import math
                        bx = getattr(b, "x", 0.0)
                        by = getattr(b, "y", 0.0)
                        br = getattr(b, "radius", 15.0)
                        hx = getattr(h, "x", 0.0)
                        hy = getattr(h, "y", 0.0)
                        hr = getattr(h, "radius", 40.0)
                        team = getattr(h, "team", "neutral")
                        dist = math.hypot(bx - hx, by - hy)

                        if dist < br + hr:
                            if getattr(b, "team", "") != team:
                                # push back enemy
                                overlap = (br + hr) - dist
                                if dist > 0:
                                    nx = (bx - hx) / dist
                                    ny = (by - hy) / dist
                                    b.x += nx * overlap
                                    b.y += ny * overlap

                                h.hp -= 10.0 * delta
                                if h.hp <= 0:
                                    h.active = False
                                    if h in world.arena.hazards:
                                        world.arena.hazards.remove(h)

GAME_MODES['boundary_builder'] = BoundaryBuilderMode()


class SwapLowestHPMutator(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Low HP Swap Mutator"
        self.description = "Any ball dropping below 30% HP instantly swaps positions with the highest HP enemy in the arena."

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        for b in balls:
            if not getattr(b, "alive", True) or getattr(b, "ball_type", "") == "spectator":
                continue

            hp = getattr(b, "hp", 0.0)
            max_hp = getattr(b, "max_hp", 1.0)
            if max_hp <= 0:
                continue

            hp_percent = hp / max_hp

            # Check if dropped below 30%
            if hp_percent < 0.3:
                # Only trigger if not already triggered this drop
                if not getattr(b, "low_hp_swap_triggered", False):
                    b.low_hp_swap_triggered = True

                    # Find highest HP enemy
                    best_enemy = None
                    best_enemy_hp = -1.0
                    b_team = getattr(b, "team", "")

                    for enemy in balls:
                        if not getattr(enemy, "alive", True) or getattr(enemy, "ball_type", "") == "spectator":
                            continue
                        if getattr(enemy, "team", "") == b_team:
                            continue

                        enemy_hp = getattr(enemy, "hp", 0.0)
                        if enemy_hp > best_enemy_hp:
                            best_enemy_hp = enemy_hp
                            best_enemy = enemy

                    if best_enemy:
                        # Swap positions
                        bx, by = b.x, b.y
                        ex, ey = best_enemy.x, best_enemy.y

                        b.x, b.y = ex, ey
                        best_enemy.x, best_enemy.y = bx, by

                        if hasattr(world, "add_event"):
                            world.add_event("teleport_effect", {"x": bx, "y": by})
                            world.add_event("teleport_effect", {"x": ex, "y": ey})
                            world.add_event("message", {"text": f"{getattr(b, 'name', 'Entity')} swapped with {getattr(best_enemy, 'name', 'Enemy')}!"})
            else:
                # Reset trigger if hp >= 30%
                b.low_hp_swap_triggered = False

GAME_MODES['low_hp_swap_mutator'] = SwapLowestHPMutator()

class ReviveAltarMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Revive Altar"
        self.description = "Living players can bring a specific item to designated altars on the map to revive ghost teammates, but doing so takes time and makes them vulnerable."
        self.token_spawn_timer = 0.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        world.revive_altars = []
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") else 1000.0

        world.revive_altars.append({
            "x": arena_width / 2,
            "y": arena_height / 2,
            "radius": 100.0,
            "channeling_ball": None,
            "progress": 0.0
        })

        if hasattr(world, "arena") and not hasattr(world.arena, "items"):
            world.arena.items = []

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random
        if not hasattr(world, "revive_altars"):
            return

        self.token_spawn_timer -= delta
        if self.token_spawn_timer <= 0:
            self.token_spawn_timer = 10.0
            if hasattr(world, "arena") and hasattr(world.arena, "items"):
                arena_w = getattr(world.arena, "width", 1000.0)
                arena_h = getattr(world.arena, "height", 1000.0)

                # Check for existing tokens to avoid spawning too many
                tokens = []
                for item in getattr(world.arena, "items", []):
                    if isinstance(item, dict) and item.get("kind") == "revive_token":
                        tokens.append(item)
                    elif hasattr(item, "kind") and getattr(item, "kind") == "revive_token":
                        tokens.append(item)

                if len(tokens) < 5:
                    world.arena.items.append({
                        "kind": "revive_token",
                        "x": random.uniform(100.0, arena_w - 100.0),
                        "y": random.uniform(100.0, arena_h - 100.0),
                        "radius": 15.0,
                        "active": True
                    })

        if hasattr(world, "arena") and hasattr(world.arena, "items"):
            for b in balls:
                if not getattr(b, "alive", False):
                    continue
                bx = getattr(b, "x", 0.0)
                by = getattr(b, "y", 0.0)
                br = getattr(b, "radius", 10.0)
                for item in world.arena.items:
                    is_dict = isinstance(item, dict)
                    kind = item.get("kind") if is_dict else getattr(item, "kind", None)
                    active = item.get("active", True) if is_dict else getattr(item, "active", True)

                    if kind == "revive_token" and active:
                        ix = item.get("x", 0.0) if is_dict else getattr(item, "x", 0.0)
                        iy = item.get("y", 0.0) if is_dict else getattr(item, "y", 0.0)
                        ir = item.get("radius", 15.0) if is_dict else getattr(item, "radius", 15.0)
                        dist_sq = (bx - ix)**2 + (by - iy)**2
                        if dist_sq <= (br + ir)**2:
                            if is_dict:
                                item["active"] = False
                            else:
                                item.active = False
                            b.has_revive_token = True

            # Remove inactive
            filtered_items = []
            for i in world.arena.items:
                is_active = i.get("active", True) if isinstance(i, dict) else getattr(i, "active", True)
                if is_active:
                    filtered_items.append(i)
            world.arena.items = filtered_items

        for altar in world.revive_altars:
            ax = altar.get("x", 0.0)
            ay = altar.get("y", 0.0)
            ar = altar.get("radius", 100.0)

            channeling_ball = None
            for b in balls:
                if not getattr(b, "alive", False) or not getattr(b, "has_revive_token", False):
                    continue
                bx = getattr(b, "x", 0.0)
                by = getattr(b, "y", 0.0)
                dist_sq = (bx - ax)**2 + (by - ay)**2
                if dist_sq <= ar**2:
                    channeling_ball = b
                    break

            if channeling_ball:
                channeling_ball.silence_timer = max(getattr(channeling_ball, "silence_timer", 0.0), 0.5)
                if hasattr(channeling_ball, "vx"):
                    channeling_ball.vx *= 0.5
                if hasattr(channeling_ball, "vy"):
                    channeling_ball.vy *= 0.5

                if altar.get("channeling_ball") == id(channeling_ball):
                    altar["progress"] += delta
                else:
                    altar["channeling_ball"] = id(channeling_ball)
                    altar["progress"] = delta

                if altar["progress"] >= 3.0:
                    revived_any = False
                    team = getattr(channeling_ball, "team", None)
                    if team:
                        for b in balls:
                            if not getattr(b, "alive", False) and getattr(b, "team") == team:
                                b.alive = True
                                b.hp = getattr(b, "max_hp", 100.0) * 0.5
                                b.x = ax
                                b.y = ay
                                b.intangible_timer = 2.0
                                b.intangible = True
                                revived_any = True

                    if revived_any:
                        channeling_ball.has_revive_token = False
                        if hasattr(world, "add_event"):
                            world.add_event("teammate_revived", {"team": team, "reviver": channeling_ball})

                    altar["progress"] = 0.0
                    altar["channeling_ball"] = None
            else:
                altar["progress"] = max(0.0, altar.get("progress", 0.0) - delta)
                if altar["progress"] == 0.0:
                    altar["channeling_ball"] = None

GAME_MODES['revive_altar'] = ReviveAltarMode()


class AuraWellHazardMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Aura Well Hazard"
        self.description = "A new hazard that absorbs the aura color of the first ball that touches it. Once charged, it pulses in waves, healing players with the matching aura and damaging those with different auras, encouraging territory control."

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        import random
        # Spawn some aura wells
        if hasattr(world, "arena") and hasattr(world.arena, "hazards"):
            try:
                from arena.procedural_arena import Hazard
                hazard_class = Hazard
            except ImportError:
                class FallbackHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                        self.active = True
                hazard_class = FallbackHazard

            arena_width = getattr(world.arena, "width", 2000.0)
            arena_height = getattr(world.arena, "height", 2000.0)

            for _ in range(3):
                x = random.uniform(200.0, arena_width - 200.0)
                y = random.uniform(200.0, arena_height - 200.0)
                well_id = 93000 + len(world.arena.hazards)
                well = hazard_class(id=well_id, x=x, y=y, radius=60.0, kind="aura_well", damage=0.0)
                setattr(well, "absorbed_aura", None)
                setattr(well, "pulse_timer", 0.0)
                setattr(well, "pulse_interval", 3.0)
                setattr(well, "pulse_radius", 250.0)
                world.arena.hazards.append(well)

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)

        if not hasattr(world, "arena") or not hasattr(world.arena, "hazards"):
            return

        for hazard in world.arena.hazards:
            if getattr(hazard, "kind", "") != "aura_well" or not getattr(hazard, "active", True):
                continue

            hx = getattr(hazard, "x", 0.0)
            hy = getattr(hazard, "y", 0.0)
            hradius = getattr(hazard, "radius", 60.0)

            absorbed_aura = getattr(hazard, "absorbed_aura", None)

            if absorbed_aura is None:
                # Check for first ball to touch
                for b in balls:
                    if not getattr(b, "alive", False):
                        continue
                    bx = getattr(b, "x", 0.0)
                    by = getattr(b, "y", 0.0)
                    bradius = getattr(b, "radius", 20.0)

                    dist = ((bx - hx)**2 + (by - hy)**2)**0.5
                    if dist < (hradius + bradius):
                        b_aura = getattr(b, "aura_color", getattr(b, "team", "neutral"))
                        setattr(hazard, "absorbed_aura", b_aura)
                        if hasattr(world, "add_event"):
                            world.add_event("aura_well_charged", {"hazard_id": getattr(hazard, "id", -1), "aura": b_aura})
                        break
            else:
                # Charged, pulse
                timer = getattr(hazard, "pulse_timer", 0.0)
                timer -= delta
                if timer <= 0:
                    timer = getattr(hazard, "pulse_interval", 3.0)
                    if hasattr(world, "add_event"):
                        world.add_event("aura_well_pulse", {"hazard_id": getattr(hazard, "id", -1), "aura": absorbed_aura})

                    pulse_radius = getattr(hazard, "pulse_radius", 250.0)

                    for b in balls:
                        if not getattr(b, "alive", False):
                            continue
                        bx = getattr(b, "x", 0.0)
                        by = getattr(b, "y", 0.0)

                        dist = ((bx - hx)**2 + (by - hy)**2)**0.5
                        if dist <= pulse_radius:
                            b_aura = getattr(b, "aura_color", getattr(b, "team", "neutral"))
                            if b_aura == absorbed_aura:
                                # Heal
                                if hasattr(b, "hp") and hasattr(b, "max_hp"):
                                    b.hp = min(getattr(b, "max_hp", 100.0), b.hp + 20.0)
                                # Speed and damage increase by 50%
                                setattr(b, "aura_well_buff_timer", 3.0)
                            else:
                                # Damage
                                if hasattr(b, "take_damage"):
                                    b.take_damage(20.0)
                                else:
                                    if hasattr(b, "hp"):
                                        b.hp -= 20.0
                                        if b.hp <= 0:
                                            b.alive = False
                                            if hasattr(world, "add_event"):
                                                world.add_event("ball_died", {"id": getattr(b, "id", -1), "killer_id": -1, "reason": "aura_well_pulse"})

                setattr(hazard, "pulse_timer", timer)

GAME_MODES['aura_well_hazard'] = AuraWellHazardMode()

class SplitScreenMirrorMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Split Screen Mirror"
        self.description = "An arena mode where the screen is split down the middle. Passing through the central divide mirrors all properties (speed, health changes) until returning to the original side."

    def setup(self, world, balls):
        super().setup(world, balls)
        arena_left = world.arena.get("left", -1000) if hasattr(world, "arena") and isinstance(world.arena, dict) else -1000
        arena_right = world.arena.get("right", 1000) if hasattr(world, "arena") and isinstance(world.arena, dict) else 1000

        if hasattr(world, "arena") and not isinstance(world.arena, dict):
            arena_left = getattr(world.arena, "left", -1000)
            arena_right = getattr(world.arena, "right", 1000)

        self.mid_x = (arena_left + arena_right) / 2.0

        for b in balls:
            b._original_side = "left" if getattr(b, "x", 0.0) < self.mid_x else "right"
            b._prev_tick_hp = getattr(b, "hp", 100.0)
            b._mirror_inverted = False
            b._orig_speed_multiplier = getattr(b, "speed_multiplier", 1.0)

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        for b in balls:
            if not getattr(b, "alive", True):
                continue

            current_side = "left" if getattr(b, "x", 0.0) < self.mid_x else "right"
            is_inverted = (current_side != getattr(b, "_original_side", current_side))

            b_prev_hp = getattr(b, "_prev_tick_hp", getattr(b, "hp", 100.0))
            current_hp = getattr(b, "hp", 100.0)
            hp_diff = current_hp - b_prev_hp

            if is_inverted:
                if not getattr(b, "_mirror_inverted", False):
                    b._mirror_inverted = True
                    b._orig_speed_multiplier = getattr(b, "speed_multiplier", 1.0)
                    b.speed_multiplier = b._orig_speed_multiplier * -1.0

                if hp_diff != 0:
                    inverted_hp = b_prev_hp - hp_diff
                    max_hp = getattr(b, "max_hp", 100.0)
                    b.hp = min(inverted_hp, max_hp)
            else:
                if getattr(b, "_mirror_inverted", False):
                    b._mirror_inverted = False
                    b.speed_multiplier = getattr(b, "_orig_speed_multiplier", 1.0)

            b._prev_tick_hp = getattr(b, "hp", 100.0)

GAME_MODES["split_screen_mirror"] = SplitScreenMirrorMode()

class InvertControlsMutator(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Invert Controls Mutator"
        self.description = "A mutator that periodically inverts all players' movement controls for a short duration."
        self.trigger_timer = 0.0

    def apply_dynamic_traits(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        self.trigger_timer += delta
        if self.trigger_timer >= 15.0:
            self.trigger_timer -= 15.0
            for b in balls:
                if not getattr(b, "is_ghost", False):
                    b.invert_timer = max(getattr(b, "invert_timer", 0.0), 3.0)

GAME_MODES['invert_controls_mutator'] = InvertControlsMutator()
