class OccasionalMirrorWallsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Occasional Mirror Walls"
        self.description = "Walls around the map occasionally become mirrors for a few seconds. Lasers and projectiles shot at them bounce directly back at the attacker, making players careful where they shoot."
        self.timer = 0.0
        self.active = False
        self.active_timer = 0.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        import random
        self.timer = random.uniform(10.0, 20.0)
        self.active = False
        self.active_timer = 0.0

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import random

        if not self.active:
            self.timer -= delta
            if self.timer <= 0:
                self.active = True
                self.active_timer = random.uniform(3.0, 6.0)
                if hasattr(world, "events"):
                    world.events.append({
                        "type": "mirror_walls_active",
                        "message": "Walls are now mirrors!"
                    })
        else:
            self.active_timer -= delta
            if self.active_timer <= 0:
                self.active = False
                self.timer = random.uniform(10.0, 20.0)
                if hasattr(world, "events"):
                    world.events.append({
                        "type": "mirror_walls_inactive",
                        "message": "Walls returned to normal."
                    })
            else:
                arena = getattr(world, "arena", None)
                arena_width = getattr(arena, "width", 1000) if arena else 1000
                arena_height = getattr(arena, "height", 1000) if arena else 1000

                projectiles = getattr(world, "projectiles", [])
                hazards = getattr(arena, "hazards", []) if arena else []

                for proj in projectiles + hazards:
                    if not getattr(proj, "alive", True) and not getattr(proj, "hp", 1.0) > 0:
                        continue

                    b_type = getattr(proj, "ball_type", getattr(proj, "kind", ""))
                    is_proj = b_type in ["projectile", "spell", "fireball", "bullet", "snipe", "laser_beam"] or getattr(proj, "is_projectile", False) or getattr(proj, "is_spell", False)

                    if not is_proj:
                        continue

                    x = getattr(proj, "x", 0)
                    y = getattr(proj, "y", 0)
                    radius = getattr(proj, "radius", 5.0)
                    vx = getattr(proj, "vx", 0)
                    vy = getattr(proj, "vy", 0)

                    bounced = False
                    if x - radius <= 0 and vx < 0:
                        proj.vx = -vx
                        proj.vy = -vy
                        proj.x = radius + 1
                        bounced = True
                    elif x + radius >= arena_width and vx > 0:
                        proj.vx = -vx
                        proj.vy = -vy
                        proj.x = arena_width - radius - 1
                        bounced = True
                    elif y - radius <= 0 and vy < 0:
                        proj.vx = -vx
                        proj.vy = -vy
                        proj.y = radius + 1
                        bounced = True
                    elif y + radius >= arena_height and vy > 0:
                        proj.vx = -vx
                        proj.vy = -vy
                        proj.y = arena_height - radius - 1
                        bounced = True


GAME_MODES["occasional_mirror_walls"] = OccasionalMirrorWallsMode()

GAME_MODES['quantum_tunnel_safe_zone'] = QuantumTunnelSafeZoneMode()
GAME_MODES['bone_prison_trap'] = __import__('ai.bone_prison_trap', fromlist=['']).BonePrisonTrapMode()


class VolcanoBossMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Volcano Boss"
        self.description = "A massive volcano in the center of the arena continuously spawns lava geysers and throws fireballs. Players must dodge the hazards and use water-based items to cool down the boss to defeat it."
        self.boss_id = None
        self.attack_timer = 0.0
        self.geyser_timer = 0.0
        self.item_timer = 0.0
        self.volcano_heat = 100.0

    def setup(self, world, balls):
        import random
        super().setup(world, balls)
        arena_w = getattr(world.arena, "width", 1000)
        arena_h = getattr(world.arena, "height", 1000)

        # Spawn Volcano Boss
        boss_id = getattr(world, "next_id", random.randint(100000, 999999))
        if hasattr(world, "next_id"):
            world.next_id += 1

        self.boss_id = boss_id

        boss_class = type('VolcanoBoss', (object,), {})
        boss = boss_class()
        boss.id = boss_id
        boss.ball_type = "volcano_boss"
        boss.name = "Mount Doom"
        boss.x = arena_w / 2.0
        boss.y = arena_h / 2.0
        boss.vx = 0.0
        boss.vy = 0.0
        boss.radius = 120.0
        boss.hp = 5000.0
        boss.max_hp = 5000.0
        boss.damage = 50.0
        boss.speed = 0.0
        boss.alive = True
        boss.team = "boss"
        boss.invulnerable = True # Take damage only from water items

        if hasattr(world, "balls"):
            world.balls.append(boss)

        if hasattr(world, "add_event"):
            world.add_event("boss_spawn", {"message": "A massive Volcano has emerged! Use water items to cool it down!"})

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        import random
        import math

        if not hasattr(world, "arena"):
            return

        arena_w = getattr(world.arena, "width", 1000)
        arena_h = getattr(world.arena, "height", 1000)

        boss = next((b for b in balls if getattr(b, "id", None) == self.boss_id and getattr(b, "alive", False)), None)
        if not boss:
            return

        # Volcano is stationary
        boss.vx = 0.0
        boss.vy = 0.0
        boss.x = arena_w / 2.0
        boss.y = arena_h / 2.0

        # Ensure invulnerable to normal attacks
        boss.invulnerable = True

        self.attack_timer += delta
        self.geyser_timer += delta
        self.item_timer += delta

        heat_multiplier = max(0.5, boss.hp / boss.max_hp)

        # Fireballs
        if self.attack_timer >= 2.0 * heat_multiplier:
            self.attack_timer -= 2.0 * heat_multiplier
            try:
                from arena.procedural_arena import Hazard
                for _ in range(random.randint(1, 3)):
                    target_x = random.uniform(100.0, arena_w - 100.0)
                    target_y = random.uniform(100.0, arena_h - 100.0)

                    fireball = Hazard(random.randint(10000, 99999), boss.x, boss.y, 25.0, "lava_projectile", damage=40.0)
                    angle = math.atan2(target_y - boss.y, target_x - boss.x)
                    speed = 300.0
                    setattr(fireball, 'vx', math.cos(angle) * speed)
                    setattr(fireball, 'vy', math.sin(angle) * speed)
                    dist = math.hypot(target_x - boss.x, target_y - boss.y)
                    setattr(fireball, 'duration', dist / speed)
                    setattr(fireball, 'spawn_magma', True)

                    if not hasattr(world.arena, "hazards"):
                        world.arena.hazards = []
                    world.arena.hazards.append(fireball)
            except ImportError:
                class DummyHazard:
                    def __init__(self, hid, x, y, r, k, damage):
                        self.id = hid; self.x = x; self.y = y; self.radius = r; self.kind = k; self.damage = damage
                        self.active = True
                fireball = DummyHazard(random.randint(10000, 99999), boss.x, boss.y, 25.0, "lava_projectile", 40.0)
                angle = math.atan2(random.uniform(100, arena_w-100) - boss.y, random.uniform(100, arena_h-100) - boss.x)
                setattr(fireball, 'vx', math.cos(angle) * 300)
                setattr(fireball, 'vy', math.sin(angle) * 300)
                setattr(fireball, 'duration', 2.0)
                setattr(fireball, 'spawn_magma', True)
                if not hasattr(world.arena, "hazards"):
                    world.arena.hazards = []
                world.arena.hazards.append(fireball)

            if hasattr(world, "add_event"):
                world.add_event("volcano_eruption", {"x": boss.x, "y": boss.y})

        # Lava Geysers
        if self.geyser_timer >= 5.0 * heat_multiplier:
            self.geyser_timer -= 5.0 * heat_multiplier
            try:
                from arena.procedural_arena import Hazard
                for _ in range(random.randint(2, 5)):
                    gx = random.uniform(50.0, arena_w - 50.0)
                    gy = random.uniform(50.0, arena_h - 50.0)
                    # Don't spawn under boss
                    if math.hypot(gx - boss.x, gy - boss.y) > 150:
                        geyser = Hazard(random.randint(10000, 99999), gx, gy, 40.0, "lava_geyser", damage=60.0)
                        setattr(geyser, "duration", 4.0)
                        setattr(geyser, "active", True)
                        if not hasattr(world.arena, "hazards"):
                            world.arena.hazards = []
                        world.arena.hazards.append(geyser)
            except ImportError:
                class DummyHazard:
                    def __init__(self, hid, x, y, r, k, damage):
                        self.id = hid; self.x = x; self.y = y; self.radius = r; self.kind = k; self.damage = damage
                        self.active = True
                for _ in range(3):
                    gx = random.uniform(50.0, arena_w - 50.0)
                    gy = random.uniform(50.0, arena_h - 50.0)
                    if math.hypot(gx - boss.x, gy - boss.y) > 150:
                        geyser = DummyHazard(random.randint(10000, 99999), gx, gy, 40.0, "lava_geyser", 60.0)
                        setattr(geyser, "duration", 4.0)
                        if not hasattr(world.arena, "hazards"):
                            world.arena.hazards = []
                        world.arena.hazards.append(geyser)

        # Spawn Water items
        if self.item_timer >= 4.0:
            self.item_timer -= 4.0
            if not hasattr(world, "boosters"):
                world.boosters = []

            water_item = {
                "id": getattr(world, "next_id", random.randint(100000, 999999)),
                "x": random.uniform(100.0, arena_w - 100.0),
                "y": random.uniform(100.0, arena_h - 100.0),
                "kind": "water_orb",
                "radius": 15.0,
                "color": "blue",
                "duration": 10.0
            }
            if hasattr(world, "next_id"):
                world.next_id += 1

            # Avoid spawning under boss
            if math.hypot(water_item["x"] - boss.x, water_item["y"] - boss.y) > 200:
                world.boosters.append(water_item)

        # Handle Water Orb pickups and boss damage
        if hasattr(world, "boosters"):
            boosters_to_remove = []
            for b in world.boosters:
                b_kind = b.get("kind", "") if isinstance(b, dict) else getattr(b, "kind", "")
                if b_kind == "water_orb":
                    bx = b.get("x", 0) if isinstance(b, dict) else getattr(b, "x", 0)
                    by = b.get("y", 0) if isinstance(b, dict) else getattr(b, "y", 0)
                    br = b.get("radius", 15) if isinstance(b, dict) else getattr(b, "radius", 15)

                    for ball in balls:
                        if getattr(ball, "alive", False) and getattr(ball, "team", "") != "boss":
                            dist = math.hypot(ball.x - bx, ball.y - by)
                            if dist < ball.radius + br:
                                # Picked up water orb
                                boosters_to_remove.append(b)
                                # Damage boss
                                damage_amount = 500.0
                                boss.hp -= damage_amount
                                if hasattr(world, "add_event"):
                                    world.add_event("boss_cooled", {"damage": damage_amount, "boss_hp": boss.hp})
                                break

            for b in boosters_to_remove:
                if b in world.boosters:
                    world.boosters.remove(b)

        # Check if boss died
        if boss.hp <= 0 and getattr(boss, "alive", True):
            boss.alive = False
            boss.hp = 0
            if hasattr(world, "add_event"):
                world.add_event("boss_defeated", {"message": "The Volcano Boss has been extinguished!"})


class CorruptedCapturePointsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Corrupted Capture Points"
        self.description = "Special corrupted capture points appear randomly in the arena. If successfully captured, the capturing team gains a massive temporary damage boost but starts constantly losing health until they eliminate an enemy player."
        self.capture_points = []
        self.spawn_timer = 0.0
        import random
        self.random = random

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import math

        arena_w = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") else 1000.0
        arena_h = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") else 1000.0

        self.spawn_timer += delta
        if not self.capture_points and self.spawn_timer > 10.0:
            self.spawn_timer = 0.0
            self.capture_points.append({
                "x": self.random.uniform(200.0, arena_w - 200.0),
                "y": self.random.uniform(200.0, arena_h - 200.0),
                "radius": 150.0,
                "capture_progress": 0.0,
                "owner_team": None
            })
            if hasattr(world, "add_event"):
                world.add_event("corrupted_point_spawned", {"x": self.capture_points[-1]["x"], "y": self.capture_points[-1]["y"]})

        points_to_remove = []
        for cp in self.capture_points:
            teams_in_radius = {}
            for b in balls:
                if not getattr(b, "alive", True):
                    continue
                bx = getattr(b, "x", 0.0)
                by = getattr(b, "y", 0.0)
                br = getattr(b, "radius", 15.0)
                b_team = getattr(b, "team", -1)

                if math.hypot(bx - cp["x"], by - cp["y"]) < cp["radius"] + br:
                    if b_team not in teams_in_radius:
                        teams_in_radius[b_team] = []
                    teams_in_radius[b_team].append(b)

            if cp["owner_team"] is None:
                if len(teams_in_radius) == 1:
                    capturing_team = list(teams_in_radius.keys())[0]
                    cp["capture_progress"] += 20.0 * delta
                    if cp["capture_progress"] >= 100.0:
                        cp["capture_progress"] = 100.0
                        cp["owner_team"] = capturing_team
                        if hasattr(world, "add_event"):
                            world.add_event("corrupted_point_captured", {"team": capturing_team})

                        # Apply initial buff to all living players in that team
                        for b in balls:
                            if getattr(b, "team", -1) == capturing_team and getattr(b, "alive", True):
                                b.has_corrupted_buff = True
                                b.corrupted_buff_kills_base = getattr(b, "kills", 0)
                                if not hasattr(b, "base_damage_multiplier"):
                                    b.base_damage_multiplier = getattr(b, "damage_multiplier", 1.0)
                                b.damage_multiplier = b.base_damage_multiplier * 3.0

                        cp["to_remove"] = True
                elif len(teams_in_radius) == 0:
                    cp["capture_progress"] -= 10.0 * delta
                    if cp["capture_progress"] < 0:
                        cp["capture_progress"] = 0.0
            else:
                pass

            if cp.get("to_remove", False):
                points_to_remove.append(cp)

        for cp in points_to_remove:
            self.capture_points.remove(cp)

        # Apply continuous health drain and check for kills
        for b in balls:
            if getattr(b, "alive", True) and getattr(b, "has_corrupted_buff", False):
                current_kills = getattr(b, "kills", 0)
                base_kills = getattr(b, "corrupted_buff_kills_base", 0)

                if current_kills > base_kills:
                    # Enemy player eliminated
                    b.has_corrupted_buff = False
                    if hasattr(b, "base_damage_multiplier"):
                        b.damage_multiplier = b.base_damage_multiplier
                    if hasattr(world, "add_event"):
                        world.add_event("corrupted_buff_cleared", {"ball_id": getattr(b, "id", -1)})
                else:
                    # Drain health constantly
                    b.hp = getattr(b, "hp", 100.0) - (20.0 * delta)
                    if b.hp <= 0:
                        b.hp = 0
                        b.alive = False
                        if hasattr(world, "add_event"):
                            world.add_event("ball_died", {"ball_id": getattr(b, "id", -1), "reason": "corrupted_drain"})
                        # If died, remove buff state so it doesn't try to revert later
                        b.has_corrupted_buff = False
                        if hasattr(b, "base_damage_multiplier"):
                            b.damage_multiplier = b.base_damage_multiplier

GAME_MODES['volcano_boss_mode'] = VolcanoBossMode()
GAME_MODES['corrupted_capture_points'] = CorruptedCapturePointsMode()


class HealthyGravityWellMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Healthy Gravity Well"
        self.description = "A gravity well that pulls players with hp > 75 towards the center."
        self.cgw_id = 2000000
        self.pull_strength_base = 5000000.0  # Constant for inverse square law
        self.horizon_radius = 50.0
        self.pull_radius = 2000.0
        self.damage = 25.0

    def setup(self, world: 'Any', balls: 'List[Any]') -> None:
        super().setup(world, balls)
        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            world.arena.hazards = []

        # Center coordinates
        cx = getattr(world.arena, "width", 1000.0) / 2.0 if hasattr(world, "arena") else 500.0
        cy = getattr(world.arena, "height", 1000.0) / 2.0 if hasattr(world, "arena") else 500.0

        existing = next((h for h in getattr(world, "arena", type("dummy", (), {"hazards": []})).hazards if getattr(h, "kind", "") == "healthy_gravity_well" and getattr(h, "id", None) == self.cgw_id), None)
        if not existing and hasattr(world, "arena"):
            try:
                from arena.procedural_arena import Hazard
                bh = Hazard(
                    id=self.cgw_id,
                    x=cx,
                    y=cy,
                    radius=self.horizon_radius,
                    kind="healthy_gravity_well",
                    damage=self.damage
                )
                world.arena.hazards.append(bh)
            except ImportError:
                class DummyHazard:
                    def __init__(self, id, x, y, radius, kind, damage):
                        self.id = id
                        self.x = x
                        self.y = y
                        self.radius = radius
                        self.kind = kind
                        self.damage = damage
                world.arena.hazards.append(DummyHazard(self.cgw_id, cx, cy, self.horizon_radius, "healthy_gravity_well", self.damage))

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float = 0.016) -> None:
        super().tick(world, balls, delta)
        import math

        if hasattr(world, "arena") and not hasattr(world.arena, "hazards"):
            return

        cgw = next((h for h in getattr(world, "arena", type("dummy", (), {"hazards": []})).hazards if getattr(h, "kind", "") == "healthy_gravity_well" and getattr(h, "id", None) == self.cgw_id), None)
        if not cgw:
            return

        cx = cgw.x
        cy = cgw.y

        # Pull players
        for b in balls:
            if not getattr(b, "alive", False):
                continue

            if getattr(b, "ball_type", None) == "spectator":
                continue

            hp = getattr(b, "hp", 0)
            if hp <= 75:
                continue

            dx = cx - b.x
            dy = cy - b.y
            dist = math.hypot(dx, dy)

            if dist < self.horizon_radius:
                # Inside the event horizon, take heavy damage
                if hasattr(b, "hp"):
                    b.hp -= self.damage * delta
                    if b.hp <= 0:
                        b.hp = 0
                        b.alive = False
            elif dist > 0 and dist < self.pull_radius:
                # Pull strength is inversely proportional to square of distance (gravity)
                pull_strength = self.pull_strength_base / (dist * dist)
                # Cap max pull force right at the edge of the event horizon
                max_pull = self.pull_strength_base / (self.horizon_radius * self.horizon_radius)
                pull_strength = min(pull_strength, max_pull)

                if hasattr(b, "vx") and hasattr(b, "vy"):
                    b.vx += (dx / dist) * pull_strength * delta
                    b.vy += (dy / dist) * pull_strength * delta
                else:
                    # Direct position update if no velocity
                    b.x += (dx / dist) * pull_strength * delta * delta
                    b.y += (dy / dist) * pull_strength * delta * delta

GAME_MODES['healthy_gravity_well'] = HealthyGravityWellMode()


class OutsideInFallingTilesMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Outside-In Falling Tiles"
        self.description = "Tiles fall from the outside in, slowly making the arena smaller in a grid-like fashion."
        self.grid_size = 50.0
        self.tiles = {}
        self.timer = 0.0
        self.phase = "wait"
        self.warning_duration = 2.0
        self.fall_duration = 3.0
        self.falling_tiles = []
        self.is_falling_tiles_royale = True
        self.current_ring = 0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.tiles = {}
        arena_width = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0
        arena_height = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") and world.arena else 1000.0

        self.cols = int(arena_width / self.grid_size)
        self.rows = int(arena_height / self.grid_size)

        for c in range(self.cols):
            for r in range(self.rows):
                self.tiles[(c, r)] = {"state": "normal"}

        self.timer = 5.0
        self.phase = "wait"
        self.current_ring = 0
        self.falling_tiles = []

    def tick(self, world, balls, delta=0.016):
        super().tick(world, balls, delta)
        self.timer -= delta

        if self.phase == "wait":
            if self.timer <= 0:
                normal_tiles = [k for k, v in self.tiles.items() if v["state"] == "normal"]
                if len(normal_tiles) > 4:
                    self.phase = "warning"
                    self.timer = self.warning_duration

                    ring_tiles = []
                    while self.current_ring <= max(self.cols, self.rows) / 2:
                        for c in range(self.cols):
                            for r in range(self.rows):
                                if (c, r) in self.tiles and self.tiles[(c, r)]["state"] == "normal":
                                    ring_index = min(c, r, self.cols - 1 - c, self.rows - 1 - r)
                                    if ring_index == self.current_ring:
                                        ring_tiles.append((c, r))
                        if ring_tiles:
                            break
                        self.current_ring += 1

                    if len(normal_tiles) - len(ring_tiles) < 4:
                        tiles_to_keep = 4 - (len(normal_tiles) - len(ring_tiles))
                        if len(ring_tiles) > tiles_to_keep:
                            ring_tiles = ring_tiles[:-tiles_to_keep]

                    self.falling_tiles = ring_tiles
                    for k in self.falling_tiles:
                        self.tiles[k]["state"] = "warning"

                    if hasattr(world, "add_event") and self.falling_tiles:
                        world.add_event("tiles_warning", {"message": "Outer tiles are lighting up!", "tiles": self.falling_tiles})
                else:
                    self.timer = 5.0

        elif self.phase == "warning":
            if self.timer <= 0:
                self.phase = "falling"
                self.timer = self.fall_duration
                for k in self.falling_tiles:
                    self.tiles[k]["state"] = "falling"
                if hasattr(world, "add_event") and self.falling_tiles:
                    world.add_event("tiles_falling", {"message": "Outer tiles are falling!", "tiles": self.falling_tiles})

        elif self.phase == "falling":
            if self.timer <= 0:
                self.phase = "wait"
                self.timer = 5.0
                if hasattr(world, "add_event") and self.falling_tiles:
                    world.add_event("tiles_pit", {"message": "Outer tiles have fallen!", "tiles": self.falling_tiles})
                for k in self.falling_tiles:
                    self.tiles[k]["state"] = "pit"
                self.falling_tiles = []
                self.current_ring += 1

        for b in balls:
            if not getattr(b, "alive", False) or getattr(b, "ball_type", None) == "spectator":
                continue

            bx, by = getattr(b, "x", 0.0), getattr(b, "y", 0.0)
            c = int(bx / self.grid_size)
            r = int(by / self.grid_size)

            if (c, r) in self.tiles:
                state = self.tiles[(c, r)]["state"]
                if state == "pit":
                    if hasattr(b, "take_damage"):
                        b.take_damage(9999.0)
                    else:
                        b.hp = 0.0
                        b.alive = False

                    if not getattr(b, "alive", False) and hasattr(world, "add_event"):
                        world.add_event("ball_fell", {"id": getattr(b, "id", None)})

GAME_MODES['outside_in_falling_tiles'] = OutsideInFallingTilesMode()

