class LaserTagMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Laser Tag"
        self.description = "Players shoot non-lethal lasers that bounce off walls. If hit, you are disabled for 3 seconds. The last player remaining without being hit wins."
        self.laser_cooldown = 1.0
        self.laser_speed = 600.0

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)

        # We need to spawn lasers for alive players
        for b in balls:
            if not getattr(b, "alive", True) or getattr(b, "ball_type", "") == "spectator":
                continue

            # Decrease laser cooldown
            cd = getattr(b, "laser_tag_cd", 0.0)
            if cd > 0:
                setattr(b, "laser_tag_cd", cd - delta)

            # If cooldown is up, fire a laser at nearest enemy
            if getattr(b, "laser_tag_cd", 0.0) <= 0:
                # Find nearest enemy
                nearest_enemy = None
                min_dist = 999999.0
                for e in balls:
                    if e == b or not getattr(e, "alive", True) or getattr(e, "ball_type", "") == "spectator":
                        continue
                    if getattr(e, "team", None) == getattr(b, "team", None) and getattr(b, "team", None) is not None:
                        continue

                    dx = e.x - b.x
                    dy = e.y - b.y
                    dist = (dx**2 + dy**2)**0.5
                    if dist < min_dist:
                        min_dist = dist
                        nearest_enemy = e

                if nearest_enemy:
                    # Shoot a laser towards nearest enemy
                    dx = nearest_enemy.x - b.x
                    dy = nearest_enemy.y - b.y
                    import math
                    angle = math.atan2(dy, dx)

                    try:
                        from arena.procedural_arena import Hazard
                        laser = Hazard(getattr(world, "next_id", 99999) + 100, b.x + math.cos(angle)*25, b.y + math.sin(angle)*25, 10.0, "laser_beam", 0.0)
                    except:
                        class FallbackLaser:
                            def __init__(self, id, x, y, radius, kind, damage):
                                self.id = id; self.x = x; self.y = y; self.radius = radius; self.kind = kind; self.damage = damage
                        laser = FallbackLaser(getattr(world, "next_id", 99999) + 100, b.x + math.cos(angle)*25, b.y + math.sin(angle)*25, 10.0, "laser_beam", 0.0)

                    setattr(laser, "vx", math.cos(angle) * self.laser_speed)
                    setattr(laser, "vy", math.sin(angle) * self.laser_speed)
                    setattr(laser, "is_projectile", True)
                    setattr(laser, "bounces", 10)
                    setattr(laser, "owner_id", getattr(b, "id", None))
                    setattr(laser, "alive", True)
                    setattr(laser, "duration", 5.0)

                    if not hasattr(world, "projectiles"):
                        world.projectiles = []
                    world.projectiles.append(laser)

                    setattr(b, "laser_tag_cd", self.laser_cooldown)

        # Handle projectile collisions manually if needed,
        # or normally game mode handles it.
        # Let's handle it manually to be safe.
        if hasattr(world, "projectiles"):
            projs_to_remove = []
            for p in world.projectiles:
                if getattr(p, "kind", "") != "laser_beam":
                    continue

                # Update position and bounce
                p.duration -= delta
                if p.duration <= 0:
                    projs_to_remove.append(p)
                    continue

                p.x += getattr(p, "vx", 0) * delta
                p.y += getattr(p, "vy", 0) * delta

                aw = getattr(world.arena, "width", 1000)
                ah = getattr(world.arena, "height", 1000)
                bounced = False
                if p.x - p.radius < 0:
                    p.x = p.radius
                    p.vx = abs(p.vx)
                    bounced = True
                elif p.x + p.radius > aw:
                    p.x = aw - p.radius
                    p.vx = -abs(p.vx)
                    bounced = True

                if p.y - p.radius < 0:
                    p.y = p.radius
                    p.vy = abs(p.vy)
                    bounced = True
                elif p.y + p.radius > ah:
                    p.y = ah - p.radius
                    p.vy = -abs(p.vy)
                    bounced = True

                if bounced:
                    p.bounces -= 1
                    if p.bounces <= 0:
                        projs_to_remove.append(p)
                        continue

                # Check collision with balls
                for b in balls:
                    if not getattr(b, "alive", True) or getattr(b, "ball_type", "") == "spectator":
                        continue
                    if getattr(p, "owner_id", None) == getattr(b, "id", None):
                        continue

                    dx = b.x - p.x
                    dy = b.y - p.y
                    dist = (dx**2 + dy**2)**0.5
                    if dist <= b.radius + p.radius:
                        # Hit!
                        # Disable for 3 seconds
                        b.silence_timer = max(getattr(b, "silence_timer", 0.0), 3.0)
                        b.stun_timer = max(getattr(b, "stun_timer", 0.0), 3.0)
                        # Eliminates the player from winning?
                        # 'The last player remaining without being hit wins'
                        # Thus we mark them as hit.
                        setattr(b, "has_been_hit", True)

                        projs_to_remove.append(p)

                        # Apply elimination condition: if everyone else is hit, the remaining player wins.
                        # Wait, what if they get eliminated on hit instead of just 'has_been_hit'?
                        # Let's eliminate them if we want standard BR, but 'disabled for 3 seconds' implies they stay alive.
                        break


            # Filter unique list without set since Hazard may be unhashable
            unique_projs = []
            for p in projs_to_remove:
                if p not in unique_projs:
                    unique_projs.append(p)
            for p in unique_projs:

                if p in world.projectiles:
                    world.projectiles.remove(p)

        # Check win condition:
        # If there is exactly one player who hasn't been hit, they win.
        # Or if everyone but one is eliminated.
        # But how to trigger win? Normally BR mode handles wins when 1 player is alive.
        # Should we kill players who have been hit?
        # If they are just "disabled for 3 seconds", then they eventually take damage from the zone and die.
        # Wait, the task says: 'The last player remaining without being hit wins.'
        # That means if you get hit, you are OUT (eliminated from winning).
        # Maybe we should set hp to 0 if they get hit? But then why 'disabled for 3 seconds'?
        # Oh, maybe getting hit disables them, AND they are disqualified. So they wander as zombies?
        # Let's just set hp = 0 after 3 seconds, or maybe they just lose HP.
        # Actually, maybe the simplest thing is:
        # You are disabled for 3 seconds. The last player remaining without being hit wins.
        # If they are disabled for 3 seconds, they can't move or shoot.
        # We can just check how many players have NOT been hit.
        not_hit_count = sum(1 for b in balls if getattr(b, "alive", True) and not getattr(b, "has_been_hit", False) and getattr(b, "ball_type", "") != "spectator")
        if not_hit_count == 1:
            # We have a winner! We should kill everyone else.
            for b in balls:
                if getattr(b, "has_been_hit", False) and getattr(b, "alive", True):
                    b.hp = 0
                    b.alive = False
                    if hasattr(world, "add_event"):
                        world.add_event("death", {"id": getattr(b, "id", None), "reason": "laser_tag_elimination"})

GAME_MODES['laser_tag'] = LaserTagMode()
GAME_MODES['gold_rush'] = __import__('ai.gold_rush', fromlist=['']).GoldRushMode()


class OrbitalStrikeEventMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Orbital Strike Event"
        self.description = "Random orbital strikes target the arena. A warning circle appears, followed by a devastating laser blast."
        self.strikes = []
        self.spawn_timer = 0.0
        self.spawn_interval = 10.0
        self.warning_duration = 3.0
        self.strike_radius = 80.0
        self.strike_damage = 500.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.strikes = []
        self.spawn_timer = 5.0

    def tick(self, world, balls, delta=0.016):
        import random
        import math
        super().tick(world, balls, delta)

        active_strikes = []
        for strike in self.strikes:
            strike["timer"] -= delta
            if strike["state"] == "warning":
                if strike["timer"] <= 0:
                    strike["state"] = "firing"
                    strike["timer"] = 1.0 # Duration of the visual/damage blast

                    if hasattr(world, "add_event"):
                        world.add_event("orbital_strike_fired", {"x": strike["x"], "y": strike["y"], "radius": self.strike_radius, "message": "Orbital strike fired!"})

                    # Deal damage
                    for b in balls:
                        if not getattr(b, "alive", False) or getattr(b, "ball_type", "") == "spectator":
                            continue
                        dist = math.hypot(b.x - strike["x"], b.y - strike["y"])
                        if dist <= self.strike_radius + getattr(b, "radius", 10.0):
                            if hasattr(b, "take_damage"):
                                b.take_damage(self.strike_damage, source="orbital_strike")
                            else:
                                b.hp -= self.strike_damage
                                if b.hp <= 0:
                                    b.hp = 0
                                    b.alive = False
                    active_strikes.append(strike)
                else:
                    active_strikes.append(strike)
            elif strike["state"] == "firing":
                if strike["timer"] > 0:
                    active_strikes.append(strike)

        self.strikes = active_strikes

        self.spawn_timer -= delta
        if self.spawn_timer <= 0:
            self.spawn_timer = self.spawn_interval
            arena_w = getattr(world.arena, "width", 1000.0) if hasattr(world, "arena") else 1000.0
            arena_h = getattr(world.arena, "height", 1000.0) if hasattr(world, "arena") else 1000.0

            x = random.uniform(self.strike_radius, arena_w - self.strike_radius)
            y = random.uniform(self.strike_radius, arena_h - self.strike_radius)

            self.strikes.append({
                "x": x,
                "y": y,
                "state": "warning",
                "timer": self.warning_duration
            })
            if hasattr(world, "add_event"):
                world.add_event("orbital_strike_warning", {"x": x, "y": y, "radius": self.strike_radius, "message": "Orbital strike incoming!"})

GAME_MODES['orbital_strike_event'] = OrbitalStrikeEventMode()


class GuildObstacleCourseMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Guild Obstacle Course"
        self.description = "Players race through a custom obstacle course within their guild HQ layout using unlocked defenses and traps, competing for the best time."
        self.course_active = False
        self.start_x = 0.0
        self.start_y = 0.0
        self.finish_x = 0.0
        self.finish_y = 0.0
        self.player_timers = {}
        self.finished_players = set()

    def setup(self, world, balls):
        super().setup(world, balls)
        self.course_active = True
        self.player_timers = {}
        self.finished_players = set()

        # In a real scenario, these would be loaded from the guild's layout
        # We set default values if they are not initialized
        arena_w = getattr(world.arena, "width", 2000.0)
        arena_h = getattr(world.arena, "height", 2000.0)

        self.start_x = 100.0
        self.start_y = 100.0
        self.finish_x = arena_w - 100.0
        self.finish_y = arena_h - 100.0

        # Load custom defenses and traps from guild layout as hazards
        # This assumes the world has a reference to the active guild's layout
        if hasattr(world, 'guild_manager') and hasattr(world, 'active_guild_name'):
            guild_name = world.active_guild_name
            layout = world.guild_manager.get_hq_status(guild_name).get("layout", {})
            defenses = layout.get("defenses", {})

            try:
                from arena.procedural_arena import Hazard
                for trap_id, trap_info in defenses.items():
                    # Create hazards based on placed traps
                    x = trap_info.get("x", arena_w / 2.0)
                    y = trap_info.get("y", arena_h / 2.0)
                    world.arena.hazards.append(Hazard(getattr(world, "next_id", 99999), x, y, 30.0, "trap", 20.0))
            except ImportError:
                class DummyHazard:
                    def __init__(self, hid, x, y, r, k, damage):
                        self.id = hid; self.x = x; self.y = y; self.radius = r; self.kind = k; self.damage = damage
                        self.active = True
                for trap_id, trap_info in defenses.items():
                    x = trap_info.get("x", arena_w / 2.0)
                    y = trap_info.get("y", arena_h / 2.0)
                    world.arena.hazards.append(DummyHazard(getattr(world, "next_id", 99999), x, y, 30.0, "trap", 20.0))

        for b in balls:
            b.x = self.start_x
            b.y = self.start_y
            self.player_timers[b.id] = 0.0

    def tick(self, world, balls, delta):
        if not self.course_active:
            return

        for b in balls:
            if b.id in self.finished_players:
                continue

            self.player_timers[b.id] += delta

            # Check if reached finish line
            dist_sq = (b.x - self.finish_x)**2 + (b.y - self.finish_y)**2
            # Assume finish zone has radius 50
            if dist_sq < 2500.0:
                self.finished_players.add(b.id)
                completion_time = self.player_timers[b.id]

                # Record score (lower is better, but leaderboard might sort high to low,
                # so we can use a negative or inverse time, or assume UI handles it.
                # For simplicity, we store the time.)
                if hasattr(world, 'guild_manager') and hasattr(world, 'active_guild_name'):
                    world.guild_manager.record_mini_game_score(
                        world.active_guild_name,
                        "obstacle_course",
                        str(b.id),
                        completion_time
                    )
                world.add_event("obstacle_course_finish", {"ball_id": b.id, "time": completion_time})

GAME_MODES['guild_obstacle_course'] = GuildObstacleCourseMode()

class DisorientationBrushMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Disorientation Brush"
        self.description = "A deployed area that acts like a large brush. Enemies entering the area have their minimap filled with fake player icons and random shooting sounds, disorienting them while they remain inside the zone."

        class BrushHazard:
            def __init__(self, h_id, x, y, radius, kind, duration):
                self.id = h_id
                self.x = x
                self.y = y
                self.radius = radius
                self.kind = kind
                self.duration = duration

        self.hazard_class = BrushHazard

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        super().tick(world, balls, delta)

        for hazard in getattr(world.arena, "hazards", []):
            if hazard.kind == "disorientation_brush":
                for ball in balls:
                    if getattr(ball, "hp", 0) <= 0:
                        continue

                    dx = hazard.x - ball.x
                    dy = hazard.y - ball.y
                    dist_sq = dx**2 + dy**2

                    if dist_sq < (hazard.radius + ball.radius)**2:
                        # Ball is inside the brush area
                        # Give them fake minimap pings
                        h_owner_id = getattr(hazard, "owner_id", None)
                        h_team = getattr(hazard, "owner_team", None)
                        b_team = getattr(ball, "team", None)

                        # Only affect enemies
                        if (h_owner_id and ball.id == h_owner_id) or (h_team and b_team and h_team == b_team):
                            continue

                        if getattr(ball, "disorientation_ping_timer", 0) <= 0:
                            # Generate a random position around the ball
                            angle = random.random() * 2 * math.pi
                            dist = random.random() * 300
                            fake_x = ball.x + math.cos(angle) * dist
                            fake_y = ball.y + math.sin(angle) * dist

                            # Add fake ping targeted only at this ball's client
                            world.add_event("minimap_ping", {
                                "x": fake_x,
                                "y": fake_y,
                                "color": "red",
                                "duration": 0.5,
                                "target_id": ball.id
                            })

                            # Add fake sound targeted only at this ball's client
                            world.add_event("play_sound", {
                                "sound": "shoot_random",
                                "x": fake_x,
                                "y": fake_y,
                                "target_id": ball.id
                            })

                            # Fire rapidly to "fill" the minimap
                            ball.disorientation_ping_timer = 0.1
                        else:
                            ball.disorientation_ping_timer -= delta

GAME_MODES["disorientation_brush"] = DisorientationBrushMode()

class ElasticWallsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Elastic Walls"
        self.description = "A new arena modifier where hitting the arena walls applies an elastic bounce that temporarily increases the ball's max speed beyond the normal cap for 2 seconds. This encourages risky play where players intentionally bounce off walls to gain an edge in speed during pursuits or evasions."

    def tick(self, world, balls, delta=0.016):
        for b in balls:
            timer = getattr(b, "elastic_bounce_timer", 0.0)
            if timer > 0.0:
                timer -= delta
                b.elastic_bounce_timer = timer
                if timer > 0.0:
                    b.max_speed = getattr(b, "base_max_speed", 200.0) * 1.5
                else:
                    base = getattr(b, "base_max_speed", 200.0)
                    b.max_speed = base
            else:
                if hasattr(b, "max_speed") or hasattr(b, "base_max_speed"):
                    base = getattr(b, "base_max_speed", 200.0)
                    b.max_speed = base

GAME_MODES['elastic_walls'] = ElasticWallsMode()

class QuantumDetonatorsMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Quantum Detonators"
        self.description = "Randomly spawned Quantum Detonators explode into chaotic zones. These zones randomly teleport players who enter them to another active zone on the map, reversing their current momentum."

    def setup(self, world, balls):
        world.quantum_detonators = getattr(world, 'quantum_detonators', [])
        world.chaotic_zones = getattr(world, 'chaotic_zones', [])
        super().setup(world, balls)

    def tick(self, world, balls, delta=0.016):
        import random as _rnd
        import math

        if not hasattr(world, 'quantum_detonators'):
            world.quantum_detonators = []
        if not hasattr(world, 'chaotic_zones'):
            world.chaotic_zones = []

        # Spawn logic
        if _rnd.random() < delta * 0.1:
            try:
                arena_width = getattr(world.arena, 'width', 1000)
                arena_height = getattr(world.arena, 'height', 1000)
            except Exception:
                arena_width = 1000
                arena_height = 1000
            world.quantum_detonators.append({
                "x": _rnd.random() * arena_width,
                "y": _rnd.random() * arena_height,
                "timer": 3.0,
                "radius": 30.0
            })

        # Process detonators
        active_detonators = []
        for det in world.quantum_detonators:
            det["timer"] -= delta
            if det["timer"] <= 0:
                world.chaotic_zones.append({
                    "x": det["x"],
                    "y": det["y"],
                    "radius": 60.0,
                    "duration": 5.0
                })
            else:
                active_detonators.append(det)
        world.quantum_detonators = active_detonators

        # Process chaotic zones
        active_zones = []
        for zone in world.chaotic_zones:
            zone["duration"] -= delta
            if zone["duration"] > 0:
                active_zones.append(zone)
        world.chaotic_zones = active_zones

        # Teleport logic
        for b in balls:
            cooldown = getattr(b, "quantum_teleport_cooldown", 0.0)
            if cooldown > 0.0:
                b.quantum_teleport_cooldown = cooldown - delta
                continue

            bx = getattr(b, "x", 0.0)
            by = getattr(b, "y", 0.0)
            brad = getattr(b, "radius", 15.0)

            # Check distance to any zone
            for current_zone in world.chaotic_zones:
                zx = current_zone["x"]
                zy = current_zone["y"]
                zrad = current_zone["radius"]

                dx = bx - zx
                dy = by - zy
                dist_sq = dx * dx + dy * dy
                if dist_sq < (brad + zrad) ** 2:
                    # Collided with a zone. Find a different one to teleport to.
                    other_zones = [z for z in world.chaotic_zones if z != current_zone]
                    if other_zones:
                        target_zone = _rnd.choice(other_zones)
                        b.x = target_zone["x"]
                        b.y = target_zone["y"]
                        # Reverse momentum
                        b.vx = -getattr(b, "vx", 0.0)
                        b.vy = -getattr(b, "vy", 0.0)
                        b.quantum_teleport_cooldown = 1.0
                    break

GAME_MODES["quantum_detonators"] = QuantumDetonatorsMode()

class DarkMatterVoidMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Dark Matter Void"
        self.description = "Center slowly becomes a dark matter void that eliminates players. Edge grants buffs."
        self.void_radius = 0.0
        self.void_growth_rate = 10.0 # pixels per second
        self.edge_buffer = 150.0

    def setup(self, world, balls):
        super().setup(world, balls)
        self.void_radius = 0.0

    def tick(self, world, balls, delta):
        super().tick(world, balls, delta)
        self.void_radius += self.void_growth_rate * delta

        import math
        cx = getattr(world.arena, "width", 1000) / 2.0
        cy = getattr(world.arena, "height", 1000) / 2.0

        for b in balls:
            if not getattr(b, "alive", True):
                continue

            bx = getattr(b, "x", 0.0)
            by = getattr(b, "y", 0.0)

            if not isinstance(bx, (int, float)): bx = 0.0
            if not isinstance(by, (int, float)): by = 0.0

            dist = math.hypot(bx - cx, by - cy)

            if dist < self.void_radius:
                # Instant eliminate
                if hasattr(b, 'hp'):
                    b.hp = 0
                else:
                    b.alive = False
            elif dist < self.void_radius + self.edge_buffer:
                # Edge buffer - speed buff and skill recharge
                b.speed = getattr(b, "base_speed", 100.0) * 2.5
                if hasattr(b, 'skill_cooldown'):
                    b.skill_cooldown = max(0.0, getattr(b, 'skill_cooldown', 0.0) - delta * 5.0)
            else:
                # Normal speed
                if hasattr(b, "base_speed") and hasattr(b, "speed"):
                    speed_val = getattr(b, 'speed', None)
                    if isinstance(speed_val, (int, float)) and speed_val != 0.0:
                        b.speed = getattr(b, "base_speed", 100.0)

GAME_MODES["dark_matter_void"] = DarkMatterVoidMode()


class DangerBeaconMode(GameMode):
    def __init__(self):
        super().__init__()
        self.name = "Danger Beacon"
        self.description = "A placed beacon that reveals enemies within its radius on the minimap."

    def tick(self, world: 'Any', balls: 'List[Any]', delta: float) -> None:
        super().tick(world, balls, delta)

        if not hasattr(world, "arena") or not hasattr(world.arena, "hazards"):
            return
        # Let players pick up danger beacons
        for b in balls:
            if getattr(b, "hp", 0) <= 0:
                continue
            b_x = getattr(b, "x", 0.0) if not isinstance(b, dict) else b.get("x", 0.0)
            b_y = getattr(b, "y", 0.0) if not isinstance(b, dict) else b.get("y", 0.0)
            b_rad = getattr(b, "radius", 20.0) if not isinstance(b, dict) else b.get("radius", 20.0)

            for h in world.arena.hazards:
                h_kind = getattr(h, "kind", "") if not isinstance(h, dict) else h.get("kind", "")
                if h_kind == "danger_beacon_pickup":
                    h_x = getattr(h, "x", 0.0) if not isinstance(h, dict) else h.get("x", 0.0)
                    h_y = getattr(h, "y", 0.0) if not isinstance(h, dict) else h.get("y", 0.0)
                    h_rad = getattr(h, "radius", 10.0) if not isinstance(h, dict) else h.get("radius", 10.0)

                    dist_sq = (b_x - h_x)**2 + (b_y - h_y)**2
                    if dist_sq < (b_rad + h_rad)**2:
                        # Pickup
                        if isinstance(b, dict):
                            b["danger_beacon_count"] = b.get("danger_beacon_count", 0) + 1
                        else:
                            b.danger_beacon_count = getattr(b, "danger_beacon_count", 0) + 1

                        if hasattr(world.arena.hazards, "remove"):
                            world.arena.hazards.remove(h)
                        break



        for h in world.arena.hazards:
            h_kind = h.get("kind", "") if isinstance(h, dict) else getattr(h, "kind", "")
            if h_kind == "danger_beacon":
                h_x = h.get("x", 0.0) if isinstance(h, dict) else getattr(h, "x", 0.0)
                h_y = h.get("y", 0.0) if isinstance(h, dict) else getattr(h, "y", 0.0)
                h_radius = h.get("radius", 0.0) if isinstance(h, dict) else getattr(h, "radius", 0.0)
                h_owner_id = h.get("owner_id", None) if isinstance(h, dict) else getattr(h, "owner_id", None)
                h_team = h.get("owner_team", None) if isinstance(h, dict) else getattr(h, "owner_team", None)

                for b in balls:
                    b_hp = b.get("hp", 0) if isinstance(b, dict) else getattr(b, "hp", 0)
                    if b_hp <= 0:
                        continue

                    # Check if enemy
                    is_enemy = False
                    b_team = b.get("team", None) if isinstance(b, dict) else getattr(b, "team", None)
                    b_id = b.get("id", None) if isinstance(b, dict) else getattr(b, "id", None)

                    if b_team is not None and h_team is not None:
                        if str(b_team) != str(h_team):
                            is_enemy = True
                    else:
                        if str(b_id) != str(h_owner_id):
                            is_enemy = True

                    if not is_enemy:
                        continue

                    b_x = b.get("x", 0.0) if isinstance(b, dict) else getattr(b, "x", 0.0)
                    b_y = b.get("y", 0.0) if isinstance(b, dict) else getattr(b, "y", 0.0)
                    b_radius = b.get("radius", 20.0) if isinstance(b, dict) else getattr(b, "radius", 20.0)

                    dx = b_x - h_x
                    dy = b_y - h_y
                    dist_sq = dx**2 + dy**2

                    if dist_sq < (h_radius + b_radius)**2:
                        ping_timer = b.get("minimap_ping_timer", 0.0) if isinstance(b, dict) else getattr(b, "minimap_ping_timer", 0.0)
                        if ping_timer <= 1e-5:
                            if hasattr(world, "add_event"):
                                world.add_event("minimap_ping", {"x": b_x, "y": b_y, "color": "red", "duration": 0.5})
                            elif hasattr(world, "events"):
                                world.events.append({'type': 'minimap_ping', 'data': {"x": b_x, "y": b_y, "color": "red", "duration": 0.5}})

                            if isinstance(b, dict):
                                b["minimap_ping_timer"] = 1.0
                            else:
                                b.minimap_ping_timer = 1.0
                        else:
                            if isinstance(b, dict):
                                b["minimap_ping_timer"] = ping_timer - delta
                            else:
                                b.minimap_ping_timer = ping_timer - delta

GAME_MODES["danger_beacon"] = DangerBeaconMode()


